/* =======================================================================
   vocab-notes.js — "why it is that word" mini-lessons and example sentences
   for Vocab Flip's slideshow (Genki lessons 1–16, 788 words).
   Keyed by "kana|kanji" (kanji left empty for kana-only words), same as Vocab Flip.
     explain: English, with Japanese inside 「」 — 「かな」 or 「漢字|かな」 (shown as kanji, spoken as kana)
     ja:      example sentence in Story-time markup ([word], {other word|reading}, plain kana)
     en:      its English translation
   ======================================================================= */
window.VOCAB_NOTES = window.VOCAB_NOTES || {};
Object.assign(window.VOCAB_NOTES, {
  "せんせい|先生": {
    explain: "Let's take it apart. The first kanji, 「先|せん」, means ahead, or before. The second, 「生|せい」, means life, or to be born. Both use their Chinese-origin readings here. Put them together and you get someone born before you. In other words, a person who went down the road first and can now show you the way. You already know 「先|せん」 from 「先週|せんしゅう」, last week, the week that came before. And 「生|せい」 is everywhere in school words, like 「学生|がくせい」, student, and 「留学生|りゅうがくせい」, international student. Here's something English speakers find surprising. 「せんせい」 isn't only for school teachers. Doctors, lawyers, politicians, and masters of an art are all called 「せんせい」 too. It's a title of respect for anyone with expert knowledge. You also attach it to a name, like 「やましたせんせい」, and you never use it about yourself. So to recap, a teacher is the one born ahead of you, who walks the path first.",
    ja: "[先生|せんせい]は{日本人|にほんじん}です。",
    en: "The teacher is Japanese." },
  "がくせい|学生": {
    explain: "Two kanji, both with their Chinese-origin readings. 「学|がく」 means learning or study. 「生|せい」 means life, or a living person. So a student is a person whose life right now is about learning. Look at the bottom of 「学|がく」 and you'll find the kanji for child, 「子|こ」. A way to remember it: picture a child sitting under a roof, busy studying. 「学|がく」 is one of the most useful kanji you'll meet. It's in 「大学|だいがく」, college, in 「学校|がっこう」, school, where the sound shrinks a little to 「がっ」, and in 「留学生|りゅうがくせい」, a student studying abroad. And 「生|せい」 shows up in 「先生|せんせい」, the teacher, so the teacher and the student share the same second kanji. In Japan, 「がくせい」 often points to college students in particular, while younger kids are more often called 「せいと」 or 「じどう」. To recap, learning plus person gives you a student.",
    ja: "わたしは[学生|がくせい]です。",
    en: "I am a student." },
  "だいがく|大学": {
    explain: "「大|だい」 means big, and 「学|がく」 means learning. A big place of learning. Both kanji use their Chinese-origin readings in this word. The shape of 「大|だい」 is a person standing with arms and legs stretched out wide, as if to say, this big! On its own as an adjective, it takes the native reading, 「大きい|おおきい」. But in compounds like this one it's usually 「だい」, as in 「大好き|だいすき」, to love, and 「大丈夫|だいじょうぶ」, it's okay. 「学|がく」 is the same learning you see in 「学生|がくせい」 and 「学校|がっこう」. Add one more kanji, 「院|いん」, institution, and you get 「大学院|だいがくいん」, graduate school. A note on meaning. Japanese doesn't split college and university the way English sometimes does. A four-year school of any size is a 「だいがく」. Students are 「だいがくせい」, and first-years say 「いちねんせい」. To recap, a big school of learning.",
    ja: "わたしは[大学|だいがく]の{一年生|いちねんせい}です。",
    en: "I'm a first-year student at college." },
  "ともだち|友だち": {
    explain: "The first part, 「友|とも」, is the kanji for friend, read here with its native Japanese reading. The second part, 「だち」, is a sound-softened form of 「たち」, the ending that makes groups of people. You know it from 「わたしたち」, we. So the word originally meant friends, plural, a group of companions. Over time the plural feeling faded, and now 「ともだち」 works perfectly well for just one friend. That's why you can even say 「ともだちたち」, friends, without it sounding too odd, though most people just say 「ともだち」 for one or many. In textbooks you'll often see it written with the first part in kanji and the rest in kana, exactly like this word. A small culture note. Japanese makes a clear difference between a friend and a boyfriend or girlfriend, so 「ともだち」 never hints at romance. To recap, 「とも」 means friend, and 「だち」 is an old group ending that stuck.",
    ja: "メアリーさんは[友だち|ともだち]です。",
    en: "Mary is my friend." },
  "にほん|日本": {
    explain: "「日|に」 is the sun, and 「本|ほん」 means root or origin. So the name means the origin of the sun. Seen from China, Japan lies to the east, where the sun comes up, which is why it's called the land of the rising sun. The shapes help here. 「日|に」 began as a picture of the sun, a circle with a dot in the middle, later squared off. 「本|ほん」 is the tree kanji, 「木|き」, with an extra line marking its base, the root. Notice that 「日|に」 is a shortened reading. It's normally 「にち」, as in 「毎日|まいにち」, every day, and 「日曜日|にちようび」, Sunday. And 「本|ほん」 is the same kanji as book, 「本|ほん」, and bookstore, 「本屋|ほんや」. You may also hear the country called 「にっぽん」. Both are correct. 「にっぽん」 sounds a bit stronger and shows up on stamps, money, and at sports events. To recap, the root of the sun, the land where the sun rises.",
    ja: "たけしさんは[日本|にほん]の{学生|がくせい}です。",
    en: "Takeshi is a student in Japan." },
  "りゅうがくせい|留学生": {
    explain: "This one is built from a word you already know. 「留|りゅう」 means to stay, or to remain somewhere, and here it uses its Chinese-origin reading. Then comes 「学生|がくせい」, student. So it's a student who stays in another country in order to learn. Drop the last kanji and add the verb ending, and you get 「留学する|りゅうがくする」, to study abroad. So if you go to Japan for a year of school, you are doing 「りゅうがく」, and you are a 「りゅうがくせい」. Inside the word, the 「学|がく」 is the same learning as in 「大学|だいがく」 and 「学校|がっこう」, and the 「生|せい」 is the same person as in 「先生|せんせい」. Japanese universities have international student offices and dorms just for 「りゅうがくせい」. In Genki, Mary is one. When you introduce yourself in Japan, this might be the word that describes you. To recap, stay plus student, the student who stays abroad to study.",
    ja: "メアリーさんはアメリカの[留学生|りゅうがくせい]です。",
    en: "Mary is an international student from America." },
  "とけい|時計": {
    explain: "「時|と」 is the kanji for time, and 「計|けい」 means to measure or count. So a clock or a watch is a time measurer. The reading is the unusual part. On its own, this kanji is normally read 「じ」, as in 「時間|じかん」, time, or 「とき」, as in 「時々|ときどき」, sometimes. It is never 「と」 except in this word. That's because the word 「とけい」 is older than this spelling. The kanji were picked later because their meanings fit, so treat the whole word as one special reading. 「計|けい」 itself has its normal Chinese-origin reading. It's the same idea as measuring or calculating. One more point. Japanese uses one word for both a clock on the wall and a watch on your wrist. If you need to be specific, a wristwatch is 「うでどけい」, an arm clock, where the sound softens to 「ど」. To recap, the time measurer, with a special reading you just have to learn.",
    ja: "わたしの[時計|とけい]はセイコーです。",
    en: "My watch is a Seiko." },
  "でんわ|電話": {
    explain: "「電|でん」 means electricity. The top of the kanji is the rain kanji, 「雨|あめ」, because 「電|でん」 started out meaning lightning, the electricity in a storm. 「話|わ」 means talk. Both are Chinese-origin readings here. So a telephone is electric talk. Very logical. 「電|でん」 leads a big family of modern words. 「電車|でんしゃ」 is a train, an electric car. 「電気|でんき」 is electricity, or the lights. 「電池|でんち」 is a battery, an electric pond. And 「話|わ」 is the same kanji as the verb 「話す|はなす」, to talk, where it takes its native reading. To make a phone call, add the verb ending to get 「電話する|でんわする」. Or say 「でんわをかけます」. Your phone number is 「でんわばんごう」. A note for today: people say 「けいたい」 or 「スマホ」 for a cell phone, but 「でんわ」 is still the general word for a phone call. To recap, electricity plus talk gives you the telephone.",
    ja: "[電話|でんわ]{番号|ばんごう}はなんですか。",
    en: "What is your phone number?" },
  "ほん|本": {
    explain: "This kanji is a nice one to picture. Start with the tree kanji, 「木|き」. Add a short line across the bottom of the trunk, marking the base. That gives you 「本|ほん」, which first meant root or origin. From there it grew other meanings, including the real thing and book. The reading here is the Chinese-origin one, 「ほん」. You've already seen the root meaning in 「日本|にほん」, the origin of the sun. The real thing meaning shows up in 「本当|ほんとう」, truth, as in 「本当ですか|ほんとうですか」, really? A bookstore is 「本屋|ほんや」, a book shop. And later you'll use 「本|ほん」 as a counter for long thin things like pens, bottles, and umbrellas. That use goes back to the tree trunk shape. A way to remember it: books are made of paper, and paper comes from trees. To recap, a tree with its root marked, which became the word for book.",
    ja: "これはわたしの[本|ほん]です。",
    en: "This is my book." },
  "いま|": {
    explain: "This is a native Japanese word, written with the kanji 「今|いま」. It's one of the most useful time words you'll have. The same kanji appears in lots of words about the present. 「今日|きょう」 is today, 「今晩|こんばん」 is tonight, 「今週|こんしゅう」 is this week, and 「今年|ことし」 is this year. Notice how the reading changes from word to word, but the meaning of this, or now, stays. A common mistake for English speakers is to add a particle. With times like three o'clock you say 「さんじに」, but with 「いま」 you don't add 「に」. Just say 「いま、なんじですか」, what time is it now? 「いま」 can also mean just now or right away, as in 「いまいきます」, I'm coming now. A way to remember it: picture someone tapping a watch and saying, it's time, mate, the time is now. To recap, the plain word for now, used without a particle.",
    ja: "[いま]、{何時|なんじ}ですか。",
    en: "What time is it now?" },
  "えいご|": {
    explain: "Usually written 「英語|えいご」. 「英|えい」 stands for England, and 「語|ご」 means language or word. Both use Chinese-origin readings. Why does 「英|えい」 stand for England? Long ago, foreign names were spelled with kanji chosen for their sounds, and the spelling for England began with 「英|えい」. That first kanji became the short name, so Britain is also called 「英国|えいこく」. The kanji itself means something like excellent or flower, which is a nice bonus. 「語|ご」 is the real workhorse here. Add it to a country name and you get that country's language. 「にほんご」 is Japanese, 「ちゅうごくご」 is Chinese, and 「がいこくご」 is a foreign language. A common mistake: 「えいご」 is only the language. An English person is 「イギリスじん」, and an American is 「アメリカじん」. Both of them speak 「えいご」, of course. To recap, England plus language gives you English.",
    ja: "わたしの{専攻|せんこう}は[えいご]です。",
    en: "My major is English." },
  "にほんご|": {
    explain: "This word is a perfect example of the country plus 「語|ご」 pattern. Start with 「日本|にほん」, Japan, the origin of the sun. Add 「語|ご」, language, read with its Chinese-origin reading. Japan's language. Once you know this pattern, you can make many languages yourself. 「えいご」 is English, 「ちゅうごくご」 is Chinese, 「かんこくご」 is Korean, and 「がいこくご」 is any foreign language. The same 「日本|にほん」 starts other words too. 「にほんじん」 is a Japanese person, using 「じん」, person, instead of 「ご」, language. So keep these two endings straight. 「ご」 is the language, 「じん」 is the people. Inside Japan, schools often call the subject 「こくご」, the national language, rather than 「にほんご」. 「にほんご」 is the name used when it's taught as a foreign language, which is exactly what you're doing. To recap, Japan plus language gives you Japanese.",
    ja: "わたしは[にほんご]の{学生|がくせい}です。",
    en: "I'm a student of Japanese." },
  "こうこう|": {
    explain: "Usually written 「高校|こうこう」. 「高|こう」 means high or tall, and 「校|こう」 means school. Both kanji use their Chinese-origin readings, and they happen to sound the same, which is why the word sounds like an echo. It really is high school, just as in English. The word is actually a short form of a longer official name, 「こうとうがっこう」, which means higher level school. People almost always use the short version. You know 「校|こう」 already from 「学校|がっこう」, school. And 「高|こう」 has a native reading, 「高い|たかい」, which means tall or expensive, as in 「背が高い|せがたかい」, to be tall. Add 「生|せい」, person, and you get 「こうこうせい」, a high school student. A culture note: Japanese high school takes three years and usually requires an entrance exam, unlike many American schools. To recap, high plus school, an easy one.",
    ja: "{兄|あに}は[こうこう]の{先生|せんせい}です。",
    en: "My older brother is a high school teacher." },
  "ごご|": {
    explain: "Usually written 「午後|ごご」. The first kanji, 「午|ご」, refers to noon. The second, 「後|ご」, means after. Both use Chinese-origin readings. So the word is literally after noon, exactly the same idea as P.M. Why does 「午|ご」 mean noon? In the old system, the day was split into twelve two-hour blocks named after the twelve zodiac animals. The block of the horse, written with this kanji, was centered on midday. So noon became the hour of the horse. The second kanji, 「後|ご」, is the same one as in 「あとで」, later on. And you'll meet it as an ending that means later, as in 「三日後|みっかご」, three days later. The big grammar point is word order. In English, P.M. comes after the time. In Japanese, 「ごご」 comes first. So three P.M. is 「ごごさんじ」. Its partner is 「ごぜん」, A.M., before noon. To recap, after the hour of the horse, that is, after noon.",
    ja: "いま[ごご]{三時|さんじ}です。",
    en: "It's three P.M. now." },
  "ごぜん|": {
    explain: "Usually written 「午前|ごぜん」. The first kanji, 「午|ご」, refers to noon, and the second, 「前|ぜん」, means before. Both are Chinese-origin readings here. So it's literally before noon, the same idea as A.M. The noon kanji has a story. In the old Japanese way of telling time, the day was divided into twelve two-hour blocks, each named for one of the zodiac animals. The horse's block sat right around midday, and this is the horse's kanji. So 「ごぜん」 is before the hour of the horse. The second kanji, 「前|ぜん」, also has a native reading, 「まえ」, which means front or before. You'll see that one in 「なまえ」, name. As with 「ごご」, the word order flips compared to English. You put 「ごぜん」 first, then the time. So nine A.M. is 「ごぜんくじ」. Keep the pair together in your head: 「ごぜん」 is before noon, 「ごご」 is after noon. To recap, before the horse hour, that is, the morning.",
    ja: "いま[ごぜん]{九時|くじ}です。",
    en: "It's nine A.M. now." },
  "せんこう|専攻": {
    explain: "Two kanji, both with Chinese-origin readings. 「専|せん」 means exclusive, or to specialize, to give yourself to one thing only. 「攻|こう」 means to attack, and by extension to work hard at something or to study it closely. Put them together and your major is the one subject you specialize in and go after with full force. A way to remember it: picture yourself charging at one subject on the battlefield, while all the other subjects watch from the side. This word is a key part of the Genki self-introduction. You'll ask 「せんこうはなんですか」, what's your major? And you'll answer with 「わたしのせんこうは」 plus a subject, like 「けいざい」, economics, 「れきし」, history, or 「にほんご」. Note that it's a noun, not a verb, so you say what your major is, using 「です」. In casual conversation, people may also ask what department or faculty you belong to. To recap, specialize plus attack, the subject you charge at.",
    ja: "わたしの[専攻|せんこう]はれきしです。",
    en: "My major is history." },
  "なまえ|": {
    explain: "Usually written 「名前|なまえ」. Both kanji use native Japanese readings here. 「名|な」 means name, and 「前|まえ」 means front or before. Rather than tell a history for why front was added, here's a hook. A way to remember it: your name is what you put out in front of you. It's the first thing people learn when you step forward. The kanji 「名|な」 has a Chinese-origin reading too, 「めい」, which you'll see in 「有名|ゆうめい」, famous, literally having a name, and 「有名人|ゆうめいじん」, a celebrity. And 「前|まえ」 is the same front as in 「ごぜん」, before noon, where it's read 「ぜん」. When you ask someone else's name, it's polite to add 「お」 to the front, 「おなまえは」. You never add 「お」 to your own name. So you say 「わたしのなまえは」, my name is, and then your name. To recap, the name you carry out in front of you.",
    ja: "わたしの[なまえ]はメアリーです。",
    en: "My name is Mary." },
  "なん|": {
    explain: "This is a sound-changed form of 「なに」, what. Both are written with the kanji 「何|なに」. The question is when to use which. You use 「なん」 when the next sound is a d, t, or n sound, as in 「なんですか」, what is it? You also use it in front of counters, words that count things. 「なんじ」 is what time, 「なんさい」 is how old, and 「なんねんせい」 is what year in school. You use 「なに」 before most other sounds, especially particles like 「を」 and 「が」, as in 「なにをたべますか」, what will you eat? Later you'll meet 「なにか」, something, and 「なにも」, not anything. A common mistake is saying 「なにですか」. It sounds off to Japanese ears. The reason is just smoothness. 「なんです」 rolls off the tongue more easily. A way to remember it: when the next sound is d, t, or n, the word clips itself short to 「なん」. To recap, 「なん」 is 「なに」 shortened before those sounds and counters.",
    ja: "{専攻|せんこう}は[なん]ですか。",
    en: "What is your major?" },
  "にほんじん|": {
    explain: "This is 「日本|にほん」, Japan, plus 「人|じん」, person. The kanji 「人|じん」 is a simple picture of a person walking, two legs striding apart. It has three readings you'll keep meeting, and the choice matters. The native reading, 「ひと」, is the word for person on its own. The reading 「じん」 attaches to a place to mean a person from there, like 「アメリカじん」 or 「がいこくじん」, a foreigner. And 「にん」 is used for counting people, as in 「さんにん」, three people. Watch out for the language versus people mix-up. 「にほんご」 is the Japanese language, and 「にほんじん」 is a Japanese person. A common slip is saying 「にほんじん」 when you mean the language, or the other way round. The 「じん」 ending also shows up in 「有名人|ゆうめいじん」, a celebrity, literally a famous person. To recap, Japan plus person, with 「じん」 as the person from a place.",
    ja: "たけしさんは[にほんじん]です。",
    en: "Takeshi is Japanese." },
  "はん|": {
    explain: "Usually written 「半|はん」, meaning half. The Chinese-origin reading is used here. You put it straight after an hour to mean half past. 「さんじはん」 is half past three, or three thirty. 「ごごしちじはん」 is seven thirty P.M. That's really all there is to the grammar. Here are some things to watch out for. It only works for thirty minutes. For other minutes, you use 「ふん」 or 「ぷん」, minutes. Also, English has phrases like half to four, or quarter past. Japanese doesn't use those in everyday speech. Just state the hour and add 「はん」. And remember that 「はん」 comes after 「じ」, never before. The same kanji appears in other half words you'll meet later, like a half, or half price. A way to remember it: think of a clock face split in half by the minute hand pointing straight down. When the hand reaches the bottom, it's 「はん」. To recap, put 「はん」 after the hour for half past.",
    ja: "いま{三時|さんじ}[はん]です。",
    en: "It's three thirty now." },
  "ばんごう|": {
    explain: "Usually written 「番号|ばんごう」. Both kanji use their Chinese-origin readings. 「番|ばん」 means a turn, or a place in order, like taking your turn in line. 「号|ごう」 means a number or a sign, like an issue number on a magazine or a train's name number. So a 「ばんごう」 is a number that marks something's place in an order. The kanji 「番|ばん」 shows up in 「一番|いちばん」, number one, or the best, which you'll learn later. In Genki's first lesson, the main use is 「でんわばんごう」, telephone number. You ask 「でんわばんごうはなんですか」, what is your phone number? When reading a phone number out loud, Japanese people often say the dash as 「の」. The number zero is 「ゼロ」 or 「れい」, and four and seven are usually 「よん」 and 「なな」 to avoid confusion. To recap, turn plus number, the number that gives something its place.",
    ja: "{電話|でんわ}[ばんごう]はなんですか。",
    en: "What's your phone number?" },
  "わたし|": {
    explain: "This is the standard, safe word for I. It works for everyone, man or woman, young or old, in almost any setting. That's why Genki teaches it first. The kanji is 「私|わたし」, which also carries the meaning private, as in a private school. There's an even more formal version, 「わたくし」, used in business or very polite speech. Men often use 「ぼく」 in casual talk, which feels softer and more boyish. And 「わたし」 plus 「たち」 makes 「わたしたち」, we. Here is the most common mistake English speakers make. They say 「わたしは」 at the start of every sentence. In Japanese, once it's clear you're talking about yourself, you usually drop it. Saying it too often sounds stiff, or as if you're stressing yourself on purpose. A way to remember it: think of saying, what about me, to point at yourself. To recap, the all-purpose polite I, used less often than you'd expect.",
    ja: "[わたし]はアメリカじんです。",
    en: "I am American." },
  "アメリカ|": {
    explain: "A loanword from America, so it's written in katakana. The sounds map over very neatly. English a becomes 「ア」, then 「メ」, then the r becomes 「リ」, and the final a becomes 「カ」. Unlike some country names, there's no extra vowel or long vowel to worry about. Notice that in Japanese, 「アメリカ」 usually means the United States, not the whole of the Americas. A fun extra fact. Long ago, foreign names were written with kanji chosen for their sound, and the spelling for America used the kanji for rice as its second character. That's why, in newspapers, you'll see the U.S. called 「米国|べいこく」, the rice country, even though it has nothing to do with rice. To make an American, add 「じん」, person, to get 「アメリカじん」. The English language is still 「えいご」, though, not a version of 「アメリカ」. To recap, America squeezed straight into katakana, meaning the U.S.",
    ja: "[アメリカ]の{大学|だいがく}の{学生|がくせい}です。",
    en: "I'm a student at an American college." },
  "イギリス|": {
    explain: "This one surprises people. It doesn't come from the word Britain at all. When Portuguese traders reached Japan in the fifteen hundreds, they brought their word for English, which sounds roughly like ing-lesh. Japanese squeezed those sounds into 「イギリス」. The n sound softened away, the l became an r sound, and an extra vowel was added at the end, as Japanese needs. That's why the word sounds a bit like English rather than Britain. In everyday use, 「イギリス」 covers the whole United Kingdom, even though it comes from a word for England. There's also a kanji name, 「英国|えいこく」, which you'll see in news writing, and it shares 「英|えい」 with 「えいご」, English. So a British person is 「イギリスじん」, and the language they speak is 「えいご」. A way to remember it: think of an English person introducing themself as English, with a Japanese accent. To recap, from the Portuguese word for English, used for all of Britain.",
    ja: "ロバートさんは[イギリス]じんです。",
    en: "Robert is British." },
  "オーストラリア|": {
    explain: "A loanword from English Australia, so it's written in katakana. Watch how the sounds were fitted into Japanese. The opening sound, written au in English, becomes a long 「オー」, shown by the dash. Then s and t get their own syllables, 「ス」 and 「ト」, because Japanese can't stack consonants together. The l becomes an r sound, 「ラ」, since Japanese has no separate l. And the ending becomes 「リア」. The English name itself comes from Latin, meaning the southern land. So the whole name, read in Japanese, means the southern land too, just as it does in English. Japan and Australia have close ties. Many Japanese students go there for working holidays and language study, and lots of Australians ski in Hokkaido every winter. An Australian is 「オーストラリアじん」. To recap, Australia stretched into Japanese sounds, with a long 「オー」 at the start and an r sound instead of l.",
    ja: "{友だち|ともだち}は[オーストラリア]じんです。",
    en: "My friend is Australian." },
  "かんこく|": {
    explain: "Usually written 「韓国|かんこく」. 「韓|かん」 is the Han in Korea's own name for itself, the same sound you hear in Korean words about the country. 「国|こく」 means country, and both use Chinese-origin readings. So the name is simply the Han country. The kanji 「国|こく」 is worth learning well. The outer box is a boundary, a border around the land, and the piece inside is the jewel kanji, so you can picture a precious land within borders. Its native reading is 「くに」, country, and it shows up in 「がいこく」, a foreign country, and 「がいこくじん」, a foreigner. You'll also find it in 「ちゅうごく」, China, where the sound softens to 「ごく」. The usual patterns apply. 「かんこくじん」 is a Korean person, and 「かんこくご」 is the Korean language. Korean food, dramas, and music are hugely popular in Japan, so you'll hear this word often. To recap, the Han country, with the same country kanji you'll see everywhere.",
    ja: "スーさんは[かんこく]の{留学生|りゅうがくせい}です。",
    en: "Sue is an international student from Korea." },
  "ちゅうごく|": {
    explain: "Usually written 「中国|ちゅうごく」. 「中|ちゅう」 means middle or center. Its shape is easy: a box with a line running straight through the middle. 「国|ごく」 means country, softened here from 「こく」 to 「ごく」. Both are Chinese-origin readings. So the name means the middle country, often translated as the Middle Kingdom. That's how China has long seen itself, as the center of the world. 「中|ちゅう」 also shows up in words like 「授業中に|じゅぎょうちゅうに」, during class, where it means in the middle of something. And it can be read 「じゅう」, as in 「一日中|いちにちじゅう」, all day long. Watch out for one thing. In Japan, the same name can also refer to the 「ちゅうごく」 region in western Japan, around Hiroshima, so context matters. A Chinese person is 「ちゅうごくじん」, and the language is 「ちゅうごくご」. To recap, the middle country, with a line through the center of a box.",
    ja: "リーさんは[ちゅうごく]じんです。",
    en: "Lee is Chinese." },
  "けいざい|": {
    explain: "Usually written 「経済|けいざい」. Both kanji use their Chinese-origin readings. 「経|けい」 means to manage or govern, and 「済|ざい」 means to rescue or help, or to settle something. The word is a shortened form of an old four-character phrase that meant governing the world and saving the people. That's a pretty grand idea, and it was the original sense of economics. In the late eighteen hundreds, when Japan was taking in Western learning, scholars chose this old phrase to translate the Western word economy, and it stuck. So the subject of money, markets, and trade carries the idea of running society well so people can live. You'll use it in self-introductions, as in 「せんこうはけいざいです」, my major is economics. You'll also hear 「にほんのけいざい」, the Japanese economy, on the news. A way to remember it: an economist's job is to keep the world working and help the people. To recap, govern plus rescue, managing society for its people.",
    ja: "{専攻|せんこう}は[けいざい]です。",
    en: "My major is economics." },
  "コンピューター|": {
    explain: "A loanword from English computer, so it's in katakana. Look at how the sounds were squeezed in. Japanese can't end a syllable on a hard m or p, so com becomes 「コン」, using the only consonant that can close a syllable, the n sound. Then pu becomes 「ピュー」, with a small 「ュ」 to make the y glide and a long mark for the stretched vowel. The ending er becomes 「ター」, a long a sound, because Japanese turns the English er ending into a long vowel. You'll see that same pattern in lots of loanwords, like 「コーヒー」 and 「スーパー」. A small spelling note. In technical writing, you'll sometimes see it without the final long mark, 「コンピュータ」. Both are correct, and the long version is now more common. In daily life, people often just say 「パソコン」, short for personal computer. To recap, computer with its er turned into a long 「ター」.",
    ja: "{専攻|せんこう}は[コンピューター]です。",
    en: "My major is computers." },
  "ビジネス|": {
    explain: "A loanword from English business, written in katakana. The English spelling is strange, but the sound is something like biz-nis, and Japanese follows the sound, not the spelling. So the first part becomes 「ビ」. The z sound needs a vowel after it, and Japanese uses 「ジ」 for that, giving 「ビジ」. The ending ness becomes 「ネス」, with a vowel tucked onto the final s. The result is 「ビジネス」. In Genki it appears as a major, business studies. But you'll also hear it in many compound words. A business hotel is a small, simple hotel for people on work trips, which is a very Japanese kind of place. Business class on a plane is the same idea as in English. A way to remember it: say business fast, then add a little vowel to every consonant. To recap, business, squeezed into four katakana by following its sound, not its spelling.",
    ja: "{兄|あに}の{専攻|せんこう}は[ビジネス]です。",
    en: "My older brother's major is business." },
  "れきし|": {
    explain: "Usually written 「歴史|れきし」. Both kanji use their Chinese-origin readings. 「歴|れき」 means to pass through, one after another, like the long line of years going by. 「史|し」 means a record or chronicle, the written account of events. Put them together and history is the record of everything that has passed through time. A way to remember it: picture an old scroll unrolling, with year after year written along it. You'll use it in self-introductions, as in 「せんこうはれきしです」, my major is history. And you can talk about 「にほんのれきし」, Japanese history, which is a big topic that draws many students to Japan. Japanese history is often divided by periods named after cities or capitals, such as the Edo period, when the capital was Edo, now Tokyo. Those period names come up all the time in museums and travel. To recap, passing through plus record, the record of what has passed.",
    ja: "[れきし]の{先生|せんせい}です。",
    en: "She's a history teacher." },
  "しごと|": {
    explain: "Usually written 「仕事|しごと」. Both parts use native readings. 「仕|し」 means to serve or attend, and 「事|ごと」 means thing or matter. Notice the sound change. On its own, 「事|こと」 starts with a k sound, but after another word it softens into 「ごと」. This softening happens all the time in Japanese compounds. So a job is the matters you attend to in service. The kanji 「事|じ」 also has a Chinese-origin reading, which you'll see in 「用事|ようじ」, an errand, and 「返事|へんじ」, a reply. All of them are about things to do or deal with. When asking about someone else's job, add 「お」 for politeness, as in 「おしごとはなんですか」, what do you do? Note that 「しごと」 can mean both your occupation and the work you're doing today. So 「しごとにいきます」 means going to work. To recap, serve plus matter, the things you take care of.",
    ja: "お[しごと]はなんですか。",
    en: "What is your job?" },
  "かいしゃいん|": {
    explain: "Usually written 「会社員|かいしゃいん」. All three kanji use Chinese-origin readings. 「会|かい」 means to meet or gather, the same kanji as the verb 「会う|あう」, to meet. 「社|しゃ」 means a society, a group of people, and also a shrine. Together, 「会社|かいしゃ」 means a company, a group that gathers to do business. The last kanji, 「員|いん」, means a member. So an office worker is a company member. 「社|しゃ」 is in other words too. 「社長|しゃちょう」 is a company president, and 「神社|じんじゃ」 is a shrine, a place for the gods, where the sound changes to 「じゃ」. In Japan, 「かいしゃいん」 is how many people describe themselves at work, especially salaried office staff. Rather than giving a specific job title, people often say which company they work for and that they are a company member. To recap, gathering plus society plus member, a member of a company.",
    ja: "{父|ちち}は[かいしゃいん]です。",
    en: "My father is an office worker." },
  "こうこうせい|": {
    explain: "This is three pieces you already know. 「高|こう」 means high, 「校|こう」 means school, and together 「こうこう」 is high school. Add 「生|せい」, a person, often a student, and you have a high school student. All three are Chinese-origin readings. The 「生|せい」 ending is the same one you saw in 「学生|がくせい」, student, 「先生|せんせい」, teacher, and 「留学生|りゅうがくせい」, international student. Japanese builds school level words in this neat, regular way. A 「だいがくせい」 is a college student, made from 「だいがく」 plus 「せい」, and you'll also hear the shorter forms for younger students later on. A culture note: Japanese high school students usually wear uniforms, and many join a club after classes. To say what year someone is in, use 「いちねんせい」, first year, and so on. To recap, high school plus person, the high school student.",
    ja: "{妹|いもうと}は[こうこうせい]です。",
    en: "My younger sister is a high school student." },
  "しゅふ|": {
    explain: "Usually written 「主婦|しゅふ」. Both kanji use Chinese-origin readings. 「主|しゅ」 means main, or master, the person in charge. 「婦|ふ」 means woman or wife, and you can see the woman kanji, 「女|おんな」, on its left side. So the word means the woman in charge of the home. The kanji 「主|しゅ」 appears in 「ご主人|ごしゅじん」, someone's husband, literally the main person of the house. A cultural note. These words come from a time when roles in the home were very fixed. They're still common, but there's also a male form, 「しゅふ」 written with a different second kanji meaning husband, and many people now use more neutral wording. Genki uses it when describing family members, as in 「はははしゅふです」, my mother is a housewife. To recap, the main woman of the household, the housewife.",
    ja: "{母|はは}は[しゅふ]です。",
    en: "My mother is a housewife." },
  "だいがくいんせい|": {
    explain: "This long word is built from pieces you already have. Start with 「大学|だいがく」, college, a big place of learning. Add 「院|いん」, which means an institution or a building of a certain kind. That gives 「大学院|だいがくいん」, graduate school. Then add 「生|せい」, a person or student, to get a graduate student. All readings are Chinese-origin. 「院|いん」 is worth noticing because it appears in other building words. 「病院|びょういん」 is a hospital, an institution for illness, and 「美容院|びよういん」 is a beauty salon, an institution for beauty. Be careful, those two sound almost the same, so the vowel length matters. Japanese graduate students are often in a master's course or a doctoral course. Many international students come to Japan as 「だいがくいんせい」 rather than as undergraduates. To recap, college plus institution plus person, the graduate student.",
    ja: "{兄|あに}は[だいがくいんせい]です。",
    en: "My older brother is a graduate student." },
  "だいがくせい|": {
    explain: "This is 「大学|だいがく」, college, plus 「生|せい」, student, all with Chinese-origin readings. It's the clearest example of a pattern Japanese loves. Take a school level and add 「せい」, and you get the student at that level. So 「こうこう」 becomes 「こうこうせい」, a high school student, and 「だいがくいん」 becomes 「だいがくいんせい」, a graduate student. You might wonder how this differs from 「がくせい」, student. They overlap a lot. 「がくせい」 is the general word, and in everyday speech it often means a college student anyway. 「だいがくせい」 is more precise, and it's what you use when you want to make clear you're at college. To say your year, add 「いちねんせい」 for first year, 「にねんせい」 for second, and so on. A culture note: Japanese college entrance exams are famously hard, but many students find the college years more relaxed. To recap, college plus person, the college student.",
    ja: "{姉|あね}は[だいがくせい]です。",
    en: "My older sister is a college student." },
  "べんごし|": {
    explain: "Usually written 「弁護士|べんごし」. All three kanji use Chinese-origin readings. 「弁|べん」 means to speak or argue, to make a case. 「護|ご」 means to protect or guard. Together, 「弁護|べんご」 means to defend someone by speaking for them, which is exactly what a defense lawyer does in court. The last kanji, 「士|し」, means a trained professional, someone with a qualification. So a lawyer is a qualified professional who protects people by arguing for them. The protect kanji also appears in 「看護師|かんごし」, a nurse, someone who watches over and protects patients. Notice that the endings differ, though. A nurse ends in a different kanji for professional, so the two words share 「護|ご」, protect, but not their last kanji. In Japan, passing the bar exam is famously difficult, and lawyers are often called 「せんせい」, like teachers and doctors. To recap, speak plus protect plus professional, the lawyer.",
    ja: "メアリーさんのおとうさんは[べんごし]です。",
    en: "Mary's father is a lawyer." },
  "おかあさん|": {
    explain: "Written 「お母さん|おかあさん」. The center is 「かあ」, from the mother kanji, 「母|かあ」. Around it you have a polite 「お」 on the front and the respectful 「さん」 on the end. So it's a respectful way to say mother. Here's the key rule, and English speakers trip over it all the time. When you talk about someone else's mother, you use 「おかあさん」. When you talk about your own mother to someone outside the family, you use the humble word 「はは」, written with the same kanji. Inside your own family, though, you can call your mother 「おかあさん」 to her face. This inside versus outside idea runs through all the family words. 「おとうさん」 and 「ちち」 work the same way for father, and 「おねえさん」 and 「あね」 for an older sister. A way to remember it: honor other people's family, and stay humble about your own. To recap, the respectful mother, for other people's moms.",
    ja: "[おかあさん]は{先生|せんせい}ですか。",
    en: "Is your mother a teacher?" },
  "おとうさん|": {
    explain: "Written 「お父さん|おとうさん」. In the middle is 「とう」, from the father kanji, 「父|とう」. It's wrapped with the polite 「お」 in front and the respectful 「さん」 at the end. So this is the respectful word for father. It follows the same rule as 「おかあさん」. When you talk about someone else's father, say 「おとうさん」, as in 「たけしさんのおとうさん」, Takeshi's father. When you talk about your own father to people outside your family, switch to the humble word 「ちち」, written with the same kanji. At home, you can call your own father 「おとうさん」 directly. Kids often shorten it to 「とうさん」 or say the casual 「パパ」. A common mistake is introducing your own dad as 「おとうさん」 in a self-introduction. Japanese listeners will understand, but it sounds a little childish. To recap, the respectful father, with 「ちち」 for your own dad when speaking to others.",
    ja: "[おとうさん]は{会社員|かいしゃいん}ですか。",
    en: "Is your father an office worker?" },
  "おねえさん|": {
    explain: "Written 「お姉さん|おねえさん」. The core is 「ねえ」, from the older sister kanji, 「姉|ねえ」, which has the woman kanji, 「女|おんな」, on its left. Around it are the polite 「お」 and the respectful 「さん」. Like the other family words, it has two sides. You use 「おねえさん」 for someone else's older sister, or to talk to your own older sister directly. When talking about your own older sister to outsiders, use the humble word 「あね」. The older brother pair works the same way, 「おにいさん」 and 「あに」. Younger siblings don't usually get the polite wrap. You just say 「いもうと」 or 「おとうと」. There's a fun extra use. People also call a young woman they don't know 「おねえさん」, for example a shop clerk or a waitress, as a friendly way to get her attention. To recap, the respectful older sister, with 「あね」 for your own when talking to others.",
    ja: "[おねえさん]は{大学生|だいがくせい}ですか。",
    en: "Is your older sister a college student?" },
  "おにいさん|": {
    explain: "In kanji it's 「お兄さん|おにいさん」. The middle piece, 「兄|にい」, is the kanji for older brother, and in this word it has a special reading that only shows up here. Around it sit two polite wrappers: 「お」 at the front and 「さん」 at the back, the same 「さん」 you put after people's names. Because it's wrapped in politeness, this is the word for someone else's older brother, or for calling out to your own big brother at home. When you talk about your own older brother to other people, you drop the wrapping and use the humble word 「兄|あに」, the same kanji with its native reading. The same pattern runs through the whole family. 「おねえさん」 is someone's older sister, and 「姉|あね」 is your own. 「おかあさん」 and 「おとうさん」 work the same way for mother and father. You'll also hear 「おにいさん」 used for any young man, for example a shopkeeper calling out to a guy in his twenties. A way to remember the shape: 「兄|にい」 is a big mouth 「口|くち」 sitting on two legs, the big brother who does all the talking. That's a hook, not a history lesson. The kanji also hides in 「兄弟|きょうだい」, brothers and sisters. In short, polite wrapper plus brother: your friend's big brother, or yours when you call him.",
    ja: "[おにいさん]は{何歳|なんさい}ですか。",
    en: "How old is your older brother?" },
  "いもうと|": {
    explain: "In kanji it's 「妹|いもうと」, read with its native reading. On the left is 「女|おんな」, woman, the same piece you see in 「女の人|おんなのひと」 and in 「姉|あね」, older sister. On the right is a piece that on its own means not yet. A way to remember it: the girl in the family who isn't grown up yet. Treat that as a hook. Unlike 「おねえさん」 and 「おにいさん」, this word has no polite 「お」 and 「さん」 built in, because younger siblings sit lower in the family order. So plain 「いもうと」 is how you talk about your own younger sister. For someone else's younger sister, you add 「さん」 and say 「いもうとさん」. Its partner is 「おとうと」, younger brother, which works the same way. Together the four sibling words make a little set: older brother and older sister get the respectful forms, younger brother and younger sister stay plain. A common slip for English speakers is to just say sister. Japanese almost always tells you whether she's older or younger, so you have to choose. Quick recap: woman plus not yet, your little sister, plain for yours and 「さん」 for someone else's.",
    ja: "[いもうと]は{十六歳|じゅうろくさい}です。",
    en: "My younger sister is sixteen." },
  "おとうと|": {
    explain: "In kanji it's 「弟|おとうと」, read with its native reading. Be careful with the sound, because it sits very close to 「おとうさん」, father. The difference is just the ending. 「おとうと」 stops short with 「と」, while father stretches out into 「おとうさん」. A way to remember it: the little brother wants to be just like dad, so his name is almost dad's name, only shorter and without the grown up 「さん」. Like 「いもうと」, younger sister, this word has no polite wrapping built in. You use plain 「おとうと」 for your own younger brother, and 「おとうとさん」 for someone else's. The same kanji also appears in 「兄弟|きょうだい」, siblings, where 「兄|きょう」 is older brother and 「弟|だい」 is younger brother, both with their Chinese-origin readings. So the word for brothers and sisters is literally older brother plus younger brother. Japanese cares a lot about who is older, so instead of just saying brother, you'll nearly always pick older or younger. Recap: 「弟|おとうと」, the little brother whose name is almost father's, plain for yours and with 「さん」 for someone else's.",
    ja: "[おとうと]は{高校生|こうこうせい}です。",
    en: "My younger brother is a high school student." },
  "かがく|": {
    explain: "In kanji it's 「科学|かがく」, two kanji with their Chinese-origin readings. 「科|か」 means a branch, a department or a course of study. You can find it in 「教科書|きょうかしょ」, textbook, a book for a school subject. 「学|がく」 means learning or study, the same piece you already know from 「学生|がくせい」, student, 「大学|だいがく」, college, and 「学校|がっこう」, school. Put them together and science is the branches of learning, all the organised fields of knowledge. Here's a fun trap. Japanese has another word pronounced exactly the same way, 「化学|かがく」, which means chemistry. The first kanji there is different, but the sound is identical. Because that gets confusing in speech, people sometimes call chemistry 「ばけがく」 to keep the two apart, using the native reading of its first kanji. You don't need that word yet, but it's a good reminder that Japanese has many sound-alike words that only kanji can tell apart. You'll meet 「かがく」 as a college major, alongside 「けいざい」, economics, and 「れきし」, history. Recap: branch plus learning, the branches of knowledge, science.",
    ja: "[かがく]の{先生|せんせい}はアメリカじんです。",
    en: "The science teacher is American." },
  "せいじ|": {
    explain: "In kanji it's 「政治|せいじ」, two kanji with their Chinese-origin readings. 「政|せい」 means government or administration, the business of running the state. 「治|じ」 means to govern, to rule, or to set things in order. The same kanji is also used in words about calming things down or healing, so think of it as putting things right. Together they make governing and setting the country in order, which is politics. It's a fairly formal, serious word. You'll hear it on the news and use it to talk about a field of study, as in someone's major. Grouping it with the other majors in this lesson helps. 「けいざい」 is economics, 「れきし」 is history, 「ぶんがく」 is literature, and 「かがく」 is science. To say your major, you use 「せんこう」, so a student might say 「せんこうはせいじです」, my major is politics. A way to remember the sound: picture a politician saying, say, gee, I'll fix everything. That's just a sound hook. Recap: government plus setting in order, the work of running a country, politics.",
    ja: "{兄|あに}の{専攻|せんこう}は[せいじ]です。",
    en: "My older brother's major is politics." },
  "ぶんがく|": {
    explain: "In kanji it's 「文学|ぶんがく」, two kanji with their Chinese-origin readings. 「文|ぶん」 means writing, text or sentences. You'll see the same kanji in 「文法|ぶんぽう」, grammar, the rules of sentences, and in 「文化|ぶんか」, culture, the written and civilised side of life. 「学|がく」 means learning or study, the same kanji as in 「学生|がくせい」, student, 「大学|だいがく」, college, and 「科学|かがく」, science. So literature is the study of writing. Notice how English does something similar: literature comes from a Latin word for letters. Both languages built the word out of writing. Japan has a long literary tradition. One of the world's earliest novels, The Tale of Genji, was written by a woman at the Japanese court about a thousand years ago. If you study Japanese literature, that's often where the story starts. Like the other majors in this lesson, you can say 「せんこうはぶんがくです」, my major is literature. Recap: writing plus learning, the study of written works, literature.",
    ja: "{日本|にほん}の[ぶんがく]の{先生|せんせい}です。",
    en: "She's a teacher of Japanese literature." },
  "かさ|傘": {
    explain: "「傘|かさ」 uses its native reading here. This kanji is one of the easiest to picture. Look at its shape: a wide roof on top, like the canopy of an umbrella, and underneath it, little 「人|ひと」 shapes, people, huddled together. In the middle runs a straight line like the handle. So the kanji is drawn as an open umbrella with people sheltering under it. Some cultural notes help it stick. In Japan it rains a lot, especially in the rainy season in early summer, so umbrellas are everywhere. Convenience stores sell cheap clear plastic umbrellas, and when it suddenly pours, everyone buys one. Shops and offices often have an umbrella stand or plastic sleeves at the door so you don't drip on the floor. Sadly, those identical clear umbrellas also go missing a lot, because they're easy to mix up. Pair it with 「あめ」, rain, which you'll meet a little later. A typical question you can already ask: 「わたしのかさはどれですか」, which one is my umbrella? Recap: a roof with people under it, the umbrella.",
    ja: "[傘|かさ]はどこですか。",
    en: "Where is the umbrella?" },
  "くつ|靴": {
    explain: "「靴|くつ」 uses its native reading. The left side of the kanji is 「革|かわ」, which means leather or animal hide, and it shows up in many kanji for things made of leather. The right side mainly hints at the sound in Chinese, so you don't need to find a meaning there. Leather plus a sound hint gives you shoes, which for most of history were made of leather. The same leather piece appears in another word from this lesson, 「鞄|かばん」, bag. That's a nice pair: both things were made of leather. One very important cultural note goes with shoes. In Japan you take your shoes off when you enter a home, and often in some schools, temples and traditional restaurants too. There's a small entrance area just inside the door where shoes are left, and slippers are often waiting for you. Later you'll learn the verb 「はく」, to put on clothes below the waist, and that's the verb Japanese uses for putting on shoes too. A question you can already ask: 「これはだれのくつですか」, whose shoes are these? Recap: leather on the left, shoes, and take them off at the door.",
    ja: "これはだれの[靴|くつ]ですか。",
    en: "Whose shoes are these?" },
  "さかな|魚": {
    explain: "「魚|さかな」 uses its native reading here. This kanji started as a picture of a fish, set upright. At the top is the head, in the middle a square with a cross that looks like a scaly body, and the four dots along the bottom were once the tail fins. Those four dots look like the dots meaning fire in some other kanji, but here they come from the tail, so don't let them fool you. Once you see the fish standing on its nose, you won't forget it. The kanji also has a Chinese-origin reading, 「ぎょ」, used in compound words, and it appears as a part in the kanji for many individual kinds of fish. Sushi restaurants sometimes have big cups covered in those fish kanji. A small extra: the word 「さかな」 is also used for snacks eaten with drinks, and in that sense it's traditionally explained as coming from words for sake plus side dish. Fish is central to Japanese food, from sushi and grilled fish at breakfast to fish markets in every city. You'll often hear 「さかな」 next to 「にく」, meat, when choosing a meal. Recap: a picture of a fish, head up, tail fins as four dots.",
    ja: "あれは{日本|にほん}の[魚|さかな]です。",
    en: "That is a Japanese fish." },
  "しんぶん|新聞": {
    explain: "「新聞|しんぶん」 is two kanji with their Chinese-origin readings. 「新|しん」 means new. You'll recognise it from 「新しい|あたらしい」, new, where it takes its native reading, and from 「新幹線|しんかんせん」, the bullet train, the new trunk line. 「聞|ぶん」 means to hear. Look at its shape: it's a gate, 「門|もん」, with an ear, 「耳|みみ」, inside it, like someone listening at a gate. The same kanji is the verb 「聞く|きく」, to listen or to hear, with its native reading. So a newspaper is literally new things heard, the latest news that's going around. Back before mass printing, news really did travel by word of mouth, so the idea of hearing fits. Newspapers are still big in Japan. Some of the largest papers in the world by circulation are Japanese, and many homes get a morning paper delivered. A useful sentence: 「これはにほんのしんぶんです」, this is a Japanese newspaper. Recap: new plus hear, the new things you hear about, the newspaper.",
    ja: "これは{日本|にほん}の[新聞|しんぶん]です。",
    en: "This is a Japanese newspaper." },
  "じてんしゃ|自転車": {
    explain: "「自転車|じてんしゃ」 is three kanji, all with Chinese-origin readings. 「自|じ」 means self, one's own. You've got it in 「自分で|じぶんで」, by oneself. 「転|てん」 means to turn or to roll. Notice it has 「車|くるま」, vehicle, on its left side, because wheels turn. You'll meet it again in 「運転する|うんてんする」, to drive, literally to move and turn. 「車|しゃ」 means vehicle or car. With its native reading it's 「車|くるま」, car, and with this Chinese-origin reading it's the end of 「電車|でんしゃ」, train, the electric vehicle. So a bicycle is a self turning vehicle, a vehicle whose wheels you turn with your own power. Each piece is doing honest work, which makes it easy to rebuild the word if you forget it. Bicycles are everywhere in Japan. People ride to the station, to school and to the supermarket, often with a basket on the front, and there are huge bicycle parking areas near train stations. In casual speech people also say 「チャリ」 for a bike. Recap: self plus turn plus vehicle, the bike you power yourself.",
    ja: "あれはだれの[自転車|じてんしゃ]ですか。",
    en: "Whose bicycle is that over there?" },
  "さいふ|財布": {
    explain: "「財布|さいふ」 is two kanji with their Chinese-origin readings. 「財|さい」 means money, wealth or property. On its own this kanji is usually read 「ざい」, but in this word it softens to 「さい」. Look at the left side: it's 「貝|かい」, shell. In ancient China, cowrie shells were used as money, so many kanji about money, buying and value have a shell on the left. That's a real piece of history, and it makes the kanji easy to read: shell means money. 「布|ふ」 means cloth. Its native reading is 「ぬの」, but here it's the Chinese-origin reading. Put them together and a wallet is a money cloth, a cloth pouch for your wealth. Before leather wallets, people carried coins in cloth pouches, so the name fits. A cultural note: Japan was long known as a cash society, and coins are used a lot, so many wallets have a proper coin pocket. Lost wallets are also famously often handed in to the police box. A sentence you can already say: 「それはわたしのさいふです」, that's my wallet. Recap: shell for money plus cloth, a money pouch, your wallet.",
    ja: "それはわたしの[財布|さいふ]です。",
    en: "That is my wallet." },
  "やさい|野菜": {
    explain: "「野菜|やさい」 is two kanji with their Chinese-origin readings. 「野|や」 means field, open country, or wild. You'll find it in 「野球|やきゅう」, baseball, which is literally field ball. 「菜|さい」 means greens or vegetables. Look at the top: that's the grass shape, which appears in kanji for plants. Underneath is a piece showing a hand reaching over a tree, the idea of picking. So 「菜|さい」 is plants you pick to eat. Put them together and vegetables are greens from the field. That makes it easy to remember: baseball is played in a field, and vegetables are grown in one. A couple of uses help. 「やさい」 covers all kinds of vegetables, whether one or many, since Japanese nouns don't change for plural. Shops often sell vegetables individually or in small bags, and some prices can surprise visitors because good produce in Japan can be expensive. That matches the example sentence about vegetables being 「たかい」. Recap: field plus greens, plants from the field, vegetables.",
    ja: "この[野菜|やさい]はたかいです。",
    en: "These vegetables are expensive." },
  "いす|": {
    explain: "Usually written in kana, but the kanji is 「椅子|いす」. The first kanji has 「木|き」, tree or wood, on its left side, a hint that chairs were made of wood. The second kanji, 「子|す」, normally means child, but here it's used in an old, less common reading as a little suffix for objects. You'll see 「子|し」 doing that same job in 「帽子|ぼうし」, hat, also from this lesson, where it's read 「し」. It's a sort of thing-maker on the end of a word. Chairs pair naturally with 「机|つくえ」, desk, which also has the tree shape on its left. Desk and chair, both made of wood, both with a tree in their kanji. Later you'll learn the verb 「すわる」, to sit, and you'll say 「いすにすわります」, I sit on the chair. A cultural note: traditional Japanese rooms with straw mats were built for sitting on the floor, so chairs came into everyday homes more recently. A way to remember the sound: it sounds a bit like easy, as in take it easy and sit down. That's just a hook. Recap: wood plus a little object ending, the chair.",
    ja: "その[いす]は{先生|せんせい}のです。",
    en: "That chair is the teacher's." },
  "つくえ|机": {
    explain: "「机|つくえ」 uses its native reading. The kanji has two parts. On the left is 「木|き」, tree or wood, the same piece you see in 「木曜日|もくようび」, Thursday, where it's read 「もく」. On the right is a small shape that on its own means a little table or stand. It even looks like one, a flat top on two short legs. So wood plus little table gives you a desk. This kanji is one of the friendliest to break apart, because both halves point straight at the meaning. A desk naturally goes with 「いす」, chair, whose kanji also starts with the tree shape. Learn them together as the wooden pair in the classroom. In Japanese schools, students usually stay in one classroom and the teachers come to them, so each student has their own desk and chair. Students even clean the classroom themselves at the end of the day, moving the desks to sweep. Useful sentences: 「これはわたしのつくえです」, this is my desk, or with a location word, the pen is on the desk. Recap: wood plus a little table, the desk.",
    ja: "これはわたしの[机|つくえ]です。",
    en: "This is my desk." },
  "ぼうし|帽子": {
    explain: "「帽子|ぼうし」 is two kanji with Chinese-origin readings. 「帽|ぼう」 means head covering or cap. On its left side is a piece that means cloth, which shows up in kanji for fabric things. That's a solid clue: a cloth thing for your head. 「子|し」 normally means child, but here it's just a little suffix that makes an everyday object. You see the same job in 「椅子|いす」, chair, where it's read 「す」. So 「帽子|ぼうし」 is basically head covering thing, and the 「子|し」 doesn't mean child at all. That's a common trap: don't try to find a child in the hat. A useful verb to go with it is 「かぶる」, to put on something on your head, which you'll learn later. Japanese uses different verbs for wearing depending on the body part, so a hat gets 「かぶる」 while shoes and jeans get 「はく」. In Japan you'll see a lot of hats in summer, and young school kids often wear brightly coloured caps so drivers can see them. A question you can already ask: 「あのぼうしはいくらですか」, how much is that hat? Recap: cloth head covering plus a little object ending, the hat.",
    ja: "あの[帽子|ぼうし]はいくらですか。",
    en: "How much is that hat?" },
  "これ|": {
    explain: "This is the first word of the famous 「こ」, 「そ」, 「あ」, 「ど」 system. Japanese builds its pointing words from four starting sounds. Words starting with 「こ」 mean near me, the speaker. Words with 「そ」 mean near you, the listener. Words with 「あ」 mean away from both of us. And words with 「ど」 ask a question. Then the endings tell you what kind of word it is. 「れ」 makes a thing, so 「これ」, 「それ」, 「あれ」 and 「どれ」 are this one, that one, that one over there, and which one. 「こ」 plus 「こ」 makes a place, 「ここ」, here. And 「の」 makes a word that sits before a noun, so 「このペン」 is this pen. A common mistake for English speakers is putting a noun after 「これ」. You can't say this pen with 「これ」. Use 「これ」 alone, as in 「これはペンです」, this is a pen, or use 「この」 before a noun. Polite level: it's neutral and fine anywhere. A way to remember it: 「こ」 is close, both start with a k sound. Recap: near me plus thing, this one.",
    ja: "[これ]はわたしのペンです。",
    en: "This is my pen." },
  "それ|": {
    explain: "This belongs to the 「こ」, 「そ」, 「あ」, 「ど」 set of pointing words. The 「そ」 words mean near you, the person I'm talking to. So 「それ」 is the thing close to the listener: something in their hand, on their desk, or right next to them. English just says that, so it's easy to mix up 「それ」 and 「あれ」. Here's the test. If it's near the other person, use 「それ」. If it's far from both of you, use 「あれ」. The same 「そ」 starts the other words in the group. 「そこ」 means there, near you, and 「その」 goes before a noun, as in 「そのかばん」, that bag by you. In conversation, 「それ」 also points back to something the other person just said, a bit like English that, as in that's great. A common mistake: putting a noun right after it. You say 「それはなんですか」, what is that, but for that bag you need 「その」. The answer usually switches sides. If I ask about 「それ」, near you, you answer with 「これ」, because it's near you, the speaker, now. A way to remember it: 「そ」 is so close to you. Recap: near the listener plus thing, that one by you.",
    ja: "[それ]はなんですか。",
    en: "What is that?" },
  "あれ|": {
    explain: "This is the far member of the 「こ」, 「そ」, 「あ」, 「ど」 set of pointing words. The 「あ」 words mean far from both the speaker and the listener. So 「あれ」 is that thing over there, like a building across the street or a bag on a far shelf. The rest of the 「あ」 family follows the same idea. 「あそこ」 is over there, the place, and 「あの」 goes before a noun, as in 「あのひと」, that person over there. When both people are talking about something neither of them is near, 「あれ」 is the right choice. In conversation it has one more use. When you and a friend both know what you mean, 「あれ」 can point to a shared memory, like that thing we talked about. And on its own, said with surprise, 「あれ」 is also an exclamation like huh, what? when something isn't where you expected. A common mistake is using 「それ」 for something far away just because English says that for both. Ask yourself, is it near the listener or far from us both? A way to remember it: the 「あ」 sound is like away, so 「あれ」 is the thing way over there. Recap: far from us both plus thing, that one over there.",
    ja: "[あれ]はだれのかばんですか。",
    en: "Whose bag is that over there?" },
  "どれ|": {
    explain: "This is the question member of the 「こ」, 「そ」, 「あ」, 「ど」 pointing words. The 「ど」 words always ask. 「どれ」 is which one, 「どこ」 is where, and 「どの」 is which, used before a noun, as in 「どのかばん」, which bag. Use 「どれ」 when you're choosing one thing out of three or more. Pointing at a row of umbrellas, you'd ask 「あなたのかさはどれですか」, which one is your umbrella? When there are only two choices, Japanese prefers a different word, 「どちら」, which you'll learn later. One grammar point matters a lot. Question words like 「どれ」 can't take 「は」 as the topic. If 「どれ」 is the subject, use 「が」 instead, as in 「どれがいいですか」, which one is good? That's a common mistake for beginners, who are used to putting 「は」 everywhere. To answer, you just swap in one of the other pointing words, like 「これです」, it's this one. A way to remember it: the 「ど」 words are the doubtful ones, always asking. Recap: question plus thing, which one, and pair it with 「が」 not 「は」.",
    ja: "あなたのかさは[どれ]ですか。",
    en: "Which one is your umbrella?" },
  "あそこ|": {
    explain: "This is the far place word in the 「こ」, 「そ」, 「あ」, 「ど」 set. The place words are 「ここ」, here, near me, 「そこ」, there, near you, 「あそこ」, over there, away from both of us, and 「どこ」, where. Notice that 「あそこ」 is a little irregular. You might expect it to be just 「あこ」, following the pattern, but the real word has an extra 「そ」 in the middle. That's worth a moment of attention, because it's the one place word that breaks the rhythm. Use 「あそこ」 for a place you could point to across the room or down the street. A very useful sentence is 「おてあらいはあそこです」, the restroom is over there. In Japan, someone giving directions will often just point and say 「あそこです」, so it's a word you'll hear a lot when asking the way. You can also make it more specific by adding a noun, as in over there by the bank, later on. A way to remember the extra syllable: over there is further away, so the word stretches a little longer. That's just a hook. Recap: the far place word, a little longer than the pattern, over there.",
    ja: "おてあらいは[あそこ]です。",
    en: "The restroom is over there." },
  "どこ|": {
    explain: "This is the question place word in the 「こ」, 「そ」, 「あ」, 「ど」 set. It sits with 「ここ」, here, 「そこ」, there near you, and 「あそこ」, over there. The 「ど」 at the start marks a question, just like in 「どれ」, which one, and 「どの」, which. The basic pattern is simple: put the thing you're looking for first, then 「は」, then 「どこですか」. So 「おてあらいはどこですか」 is where is the restroom, and 「ぎんこうはどこですか」 is where is the bank. Start with 「すみません」 to be polite, and you have a complete sentence for asking the way. The answer usually swaps 「どこ」 for one of the place words, like 「あそこです」, it's over there. 「どこ」 can also ask where someone is from: 「どこからきましたか」, where did you come from? A common mistake is putting 「どこ」 at the start like English does. In Japanese the question word sits where the answer would go, so the word order doesn't change. A way to remember the sound: picture a dog sniffing around asking where, where? That's just a hook. Recap: question plus place, where.",
    ja: "{銀行|ぎんこう}は[どこ]ですか。",
    en: "Where is the bank?" },
  "だれ|": {
    explain: "This is the question word for people. It has a kanji, 「誰|だれ」, but it's almost always written in kana. The basic pattern is the same as the other question words: put it where the answer would go and end with 「ですか」. So 「あのひとはだれですか」 is who is that person? Add 「の」 and it becomes whose. 「だれのかさですか」 is whose umbrella is it, and 「これはだれのですか」 is whose is this? That's useful in a classroom full of lost umbrellas and pencils. There's a politeness point to know. 「だれ」 is fine with friends, but if you're asking about someone in a polite setting, like a guest or a superior, Japanese uses the more respectful word 「どなた」. Another grammar point: as a subject, 「だれ」 takes 「が」, not 「は」, the same rule as other question words. For example, who came would use 「だれが」. A common mistake is using 「なん」, what, for people. Japanese keeps them separate: 「なん」 for things, 「だれ」 for people. A way to remember it: who dares? The word sounds a bit like dare. Recap: the who word, add 「の」 for whose.",
    ja: "あの{人|ひと}は[だれ]ですか。",
    en: "Who is that person?" },
  "とんかつ|": {
    explain: "This word is a fusion of Japanese and English. 「とん」 is the Chinese-origin reading of 「豚|ぶた」, pig or pork. You'll later see the native reading in 「豚肉|ぶたにく」, pork. 「かつ」 is short for 「カツレツ」, which comes from the English word cutlet. In that loanword, the sounds got squeezed: cutlet became 「カツレツ」, with the l turning into an r sound and extra vowels added. Then Japanese clipped it down to just 「かつ」. Put them together and you get pork cutlet. The dish itself is a thick pork cutlet, coated in breadcrumbs and deep fried, usually served sliced with shredded cabbage, rice, miso soup and a thick brown sauce. It started out as a Western style dish in the late eighteen hundreds and became thoroughly Japanese. There's a fun cultural note. 「かつ」 sounds the same as the verb 「勝つ|かつ」, to win. So students often eat 「とんかつ」 or 「かつどん」, a cutlet on rice, the night before a big exam for luck. At a restaurant you can say 「とんかつをください」, pork cutlet, please. Recap: pig plus cutlet, the deep fried pork cutlet that brings luck.",
    ja: "[とんかつ]をください。",
    en: "Pork cutlet, please." },
  "にく|": {
    explain: "In kanji it's 「肉|にく」, and the shape is often described as a slab of meat with streaks of fat or ribs inside. Here's a surprise: 「にく」 is actually the Chinese-origin reading. It's been used for so long that it feels like a native word, and it's the reading you'll hear every day. The kanji goes on the end of words for different meats. Pork is 「豚肉|ぶたにく」, pig meat. Beef is 「牛肉|ぎゅうにく」, cow meat. And chicken is 「とりにく」, bird meat. The 「牛|ぎゅう」 in beef is the same one in 「牛乳|ぎゅうにゅう」, milk, cow milk. Once you know 「にく」, you can recognise all of them. A bit of history makes it more interesting. For over a thousand years, eating meat from animals like cows was officially discouraged in Japan, partly for Buddhist reasons, and fish was the main protein. Meat eating became popular in the late eighteen hundreds when Japan opened up to the West, which is when dishes like 「とんかつ」 and beef hot pots appeared. A useful question: 「これはにくですか」, is this meat? Recap: the meat kanji, added to animals to make pork, beef and chicken.",
    ja: "これは[にく]ですか。",
    en: "Is this meat?" },
  "メニュー|": {
    explain: "This comes from the French word menu, and it reached Japanese through English. Look at how the sounds were squeezed in. The first syllable stays 「メ」. Then the second part becomes 「ニュー」, using a small 「ュ」 to make a combined sound, and the long vowel mark at the end stretches it out, a bit like the English word new. Japanese doesn't have the exact French vowel, so it uses the closest thing. The meaning hasn't shifted: it's a list of food and drink at a restaurant. It's also used for menus in apps and on computers, just like in English. A typical way to ask for one is 「メニューをください」 or the slightly more polite 「メニューをおねがいします」, the menu, please. A cultural note helps here. Many Japanese restaurants display realistic plastic models of their dishes in the front window. These food models help you choose, and if you can't read the menu, you can just take the server outside and point. Many menus also have lots of photos for the same reason. Recap: a French word through English, squeezed into Japanese sounds, the restaurant menu.",
    ja: "[メニュー]をおねがいします。",
    en: "The menu, please." },
  "えんぴつ|": {
    explain: "In kanji it's 「鉛筆|えんぴつ」, two kanji with their Chinese-origin readings. 「鉛|えん」 means lead, the metal. On its left side is 「金|かね」, metal or money, which marks lots of kanji for metals. 「筆|ぴつ」 means writing brush. Look at its top: it has the bamboo shape, because traditional brushes have bamboo handles. On its own the reading is 「ひつ」, but after 「ん」 it changes to 「ぴつ」. That sound change happens in many words, so it's worth noticing. Put them together and a pencil is a lead brush. Funnily enough, pencils don't contain lead at all. They use graphite, but people once thought graphite was a kind of lead, and English calls it pencil lead to this day. Japanese kept that same old idea in the kanji. Brushes were the normal writing tool in Japan for centuries, so a new writing tool got named after a brush. Japanese students still use pencils a lot, even at college, and many children practice kanji with pencils that are softer and darker than usual. It goes on the desk with 「けしゴム」, eraser, and 「ペン」, pen. Recap: lead plus brush, the pencil.",
    ja: "その[えんぴつ]はだれのですか。",
    en: "Whose pencil is that?" },
  "かばん|": {
    explain: "It's usually written in kana, but there's a kanji, 「鞄|かばん」, and it's a great one to notice. On its left side is 「革|かわ」, leather, the same piece that's on the left of 「靴|くつ」, shoes. On its right side is a shape meaning to wrap. So the kanji is leather that wraps your things. Shoes and bags, both leather goods, share the same left side. That's a neat pair from the same lesson. The word itself covers almost any bag you carry: a school bag, a briefcase, a handbag or a backpack. Japanese elementary school children famously carry a sturdy leather backpack, and many families buy one as a special present when their child starts school. In daily life, Japanese also uses the loanword 「バッグ」, from English bag, especially for fashion bags. A simple sentence: 「あれはわたしのかばんです」, that over there is my bag. A way to remember the sound: picture tossing your bag onto the desk and it lands with a loud ka-ban! That's just a hook. Recap: leather plus wrap, any bag you carry.",
    ja: "あれはわたしの[かばん]です。",
    en: "That over there is my bag." },
  "ジーンズ|": {
    explain: "This comes from the English word jeans. Look at how the sounds were squeezed into Japanese. The j sound becomes 「ジ」, and the long ee is shown with the long vowel mark, 「ジー」. Then the n becomes 「ン」. The final s in jeans actually sounds like a z in English, so Japanese uses 「ズ」, with the extra u vowel tacked on because Japanese syllables like to end in a vowel. That ending keeps the plural feel of the English word, since in English jeans are always plural. Japanese doesn't really do plurals, so here the 「ズ」 is just part of the word. There's also an older Japanese made word, 「ジーパン」, which squeezes jeans and pants together. You'll hear it from older people, while 「ジーンズ」 is the standard word now. Later you'll learn the verb 「はく」, which is used for putting on things below the waist, so you say 「ジーンズをはきます」, I put on jeans. That's a different verb from the one for shirts, and English speakers often mix them up. A useful shopping sentence: 「このジーンズはいくらですか」, how much are these jeans? Recap: English jeans with a 「ズ」 for the s, worn with 「はく」.",
    ja: "この[ジーンズ]はいくらですか。",
    en: "How much are these jeans?" },
  "じしょ|": {
    explain: "In kanji it's 「辞書|じしょ」, two kanji with their Chinese-origin readings. 「辞|じ」 means words or expressions. In other words it can also mean to resign or step down, but here it's about words. 「書|しょ」 means writing or a book. That's a very busy kanji you'll see everywhere. With its native reading it's the verb 「書く|かく」, to write. With this reading it's in 「図書館|としょかん」, library, 「教科書|きょうかしょ」, textbook, and 「りれきしょ」, résumé. So a dictionary is a book of words. Notice how many book and writing words end in 「しょ」. Once you know 「書|しょ」 means written thing, you can guess the meaning of new words more easily. Most students today use electronic dictionaries or apps, and in Japan dedicated electronic dictionary devices were very popular with students for years. Paper dictionaries are still used in schools, though. A useful sentence: 「これはにほんごのじしょです」, this is a Japanese dictionary. To say an English to Japanese dictionary, you'd use the language names, which you'll learn later. Recap: words plus book, the dictionary.",
    ja: "これは{日本語|にほんご}の[じしょ]です。",
    en: "This is a Japanese dictionary." },
  "テープ|": {
    explain: "This comes from the English word tape. The t becomes 「テ」, the long a sound is shown with the long vowel mark, 「テー」, and the final p becomes 「プ」, with an extra u vowel added because Japanese syllables end in vowels. So a one syllable English word turns into a three beat Japanese word. That vowel stretching and adding is the most common thing that happens to English loanwords. In older textbooks, 「テープ」 usually means a cassette tape for listening practice, which is why it appears in a lesson full of classroom items. Today it more often means sticky tape or tape for wrapping. Clear sticky tape has its own common name in Japan, a brand name that became the everyday word, a bit like how English speakers say Scotch tape. You'll also see it in words like video tape. If you need some tape in a shop or office, you can say 「テープはどこですか」, where is the tape? A way to remember the meaning shift: in the classroom of the past, tape meant sound, today it means sticking. Recap: English tape with the vowel stretched, cassette tape in older books, sticky tape today.",
    ja: "[テープ]はどこですか。",
    en: "Where is the tape?" },
  "トレーナー|": {
    explain: "This comes from the English word trainer, but in Japan it means a sweatshirt. Look at the sounds first. The tr becomes 「ト」 plus 「レ」, because Japanese can't put two consonants together, so it adds a vowel. The long ai sound becomes a stretched 「レー」. The n is 「ナ」, and the er at the end becomes another long vowel, 「ナー」, because the r sound is dropped. Now the meaning. In English, a trainer is a coach, or in Britain a sneaker. Japan took the word and used it for the cotton pullover top you'd wear while training. This is a word made in Japan from English parts, so don't use it that way in English, or people will think you mean a coach. Japanese still also uses 「トレーナー」 for a fitness trainer or coach, depending on context. In fashion, younger people often say 「スウェット」, from sweat, for the same kind of top. A good shopping sentence: 「そのトレーナーはいくらですか」, how much is that sweatshirt? Recap: English trainer, the top you train in, the sweatshirt.",
    ja: "その[トレーナー]はいくらですか。",
    en: "How much is that sweatshirt?" },
  "ノート|": {
    explain: "This is short for the English word notebook. Japanese often clips long loanwords, keeping just the first part. Here only note made it in. The sounds change a little: the n plus long o becomes 「ノー」, with the long vowel mark, and the final t becomes 「ト」, with an extra o vowel because Japanese syllables end in vowels. Here's the key point for English speakers. 「ノート」 means the notebook itself, the thing you write in. It doesn't mean a short written message. For a quick note or memo, Japanese uses a different loanword, 「メモ」. Mixing these up is a very common mistake. The word also shows up in 「ノートパソコン」, a laptop, literally a notebook personal computer. Japan loves stationery, and shops are full of beautiful notebooks, often with grid lines to help you write kanji neatly. Students usually have one notebook for each subject. A useful question: 「これはだれのノートですか」, whose notebook is this? Recap: notebook clipped to note, always the book, never the message.",
    ja: "これはだれの[ノート]ですか。",
    en: "Whose notebook is this?" },
  "ペン|": {
    explain: "This comes from the English word pen. It's one of the simplest loanwords. The p and e stay as 「ペ」, and the final n becomes 「ン」, the one Japanese sound that can end a syllable without a vowel. So it's a nearly perfect copy of the English word, just two beats long. Notice the little circle on 「ペ」. That small circle turns the h sounds into p sounds in Japanese. It's how you know this is a p and not a b. The word builds into other everyday words. A ballpoint pen is 「ボールペン」, ball pen. A felt tip marker is often called a sign pen, a Japanese made compound. In a classroom it sits on your desk next to 「えんぴつ」, pencil, and 「けしゴム」, eraser. In Japan, official documents and forms are usually filled in with pen, often in black ink, and many pens have erasable ink that students love. Useful sentences: 「これはわたしのペンです」, this is my pen, or 「ペンをかしてください」, please lend me a pen, which you'll be able to say later. Recap: English pen, almost unchanged, the little circle makes it a p.",
    ja: "この[ペン]は{千円|せんえん}です。",
    en: "This pen is a thousand yen." },
  "おてあらい|": {
    explain: "In kanji it's 「お手洗い|おてあらい」. It's made of three pieces. The front 「お」 is the polite prefix that softens a word. Then 「手|て」, hand, with its native reading. You know it from 「手紙|てがみ」, letter, and 「手伝う|てつだう」, to help, lending a hand. Then 「洗い|あらい」, washing, from the verb 「洗う|あらう」, to wash. So literally it's the honourable hand washing, the place where you wash your hands. That's a polite, indirect way to name the room, just like English washroom or restroom. Japanese has a few words for it. 「トイレ」, from English toilet, is the most common everyday word and is fine almost anywhere. 「おてあらい」 is softer and more polite, and you'll see it on signs in stores and stations. A cultural note: Japanese toilets are famous for high tech seats with heated seats and built in washing, and many have a button that plays a flushing sound for privacy. Asking the way is easy: 「すみません、おてあらいはどこですか」, excuse me, where is the restroom? Recap: polite plus hand plus washing, the restroom.",
    ja: "すみません、[おてあらい]はどこですか。",
    en: "Excuse me, where is the restroom?" },
  "たかい|": {
    explain: "In kanji it's 「高い|たかい」, with its native reading. The main meaning of this word is high or tall, and expensive comes from that: a high price. English does the same thing when it says prices are high. The kanji is often described as a picture of a tall building, a tower with a roof on top. You already know this kanji with its Chinese-origin reading, 「こう」, in 「高校|こうこう」, high school, and 「高校生|こうこうせい」, high school student. Later you'll also learn 「背が高い|せがたかい」, which means tall, literally one's height is high. So one word covers both things. Context tells you which one is meant. A building that's 「たかい」 is tall, and a watch that's 「たかい」 is expensive. Its opposites split apart, though. Cheap is 「やすい」, and low is 「ひくい」, so be careful to choose the right one. This is an i adjective, so you can put it straight before a noun, as in 「たかいとけい」, an expensive watch, or end a sentence with it, as in 「このとけいはたかいです」. Recap: the high kanji, a high price, expensive.",
    ja: "この{時計|とけい}は[たかい]です。",
    en: "This watch is expensive." },
  "こくばん|": {
    explain: "In kanji it's 「黒板|こくばん」, two kanji with their Chinese-origin readings. 「黒|こく」 means black. With its native reading it's the adjective 「黒い|くろい」, black, which you'll learn soon. 「板|ばん」 means board or plank. On its left side is 「木|き」, tree or wood, because boards are made of wood, the same piece you see in 「机|つくえ」, desk. On its own the reading is often 「はん」, but here it becomes 「ばん」. So the word is literally black board, exactly the same idea as the English. Some Japanese words are like that, built the same way as English, which makes them easy. A funny detail: Japanese blackboards are usually dark green, but they're still called black boards, just like in many English speaking schools. In Japanese classrooms the blackboard is still very common, and students take turns cleaning it at the end of the day. The person on duty wipes the board and cleans the erasers. A useful sentence: 「あれはこくばんです」, that over there is the blackboard. Recap: black plus board, exactly like the English, the blackboard.",
    ja: "あれは[こくばん]です。",
    en: "That over there is the blackboard." },
  "けしゴム|": {
    explain: "This word mixes a native Japanese verb with a Dutch loanword. 「けし」 comes from 「消す|けす」, to erase or to turn off, in the form that joins onto other words. The same kanji, read with its Chinese-origin reading 「しょう」, shows up in 「消防士|しょうぼうし」, firefighter, someone who puts out fires. 「ゴム」 means rubber, and it came from the Dutch word gom. The Dutch were the main Europeans trading with Japan for about two centuries, so several Dutch words came in that way. Notice it's written in katakana, while 「けし」 is in hiragana, because one half is Japanese and the other half is foreign. Put them together and you get erasing rubber. British English does almost the same thing, calling an eraser a rubber. Japanese also uses 「ゴム」 alone for a rubber band. Japanese erasers are a big deal among students. There are collectable novelty erasers shaped like food and animals, and serious ones that erase very cleanly. Asking for one is easy: 「けしゴムをください」, an eraser, please. Recap: erase plus rubber, half Japanese, half Dutch, the eraser.",
    ja: "[けしゴム]をください。",
    en: "An eraser, please." },
  "ビデオ|": {
    explain: "This comes from the English word video. Look at how the sounds were squeezed in. Japanese traditionally has no v sound, so v becomes b, giving 「ビ」. The middle d and e become 「デ」, and the final o stays as 「オ」. That v to b swap is one of the most common changes in loanwords, so it's worth remembering whenever you see a 「バ」, 「ビ」, 「ブ」, 「ベ」 or 「ボ」 in katakana. There is a special katakana spelling with a small vowel for v, but everyday words like this one use b. In this textbook, 「ビデオ」 means the video player, the machine, as well as a video tape, because the book was written when every classroom had one. Today people mostly use 「ビデオ」 for a video recording or a clip, like one you watch online. Japan was the home of the big video cassette formats, and Japanese companies made most of the world's video players for years. A simple sentence: 「これはにほんのビデオです」. Recap: English video, v turned into b, the video player.",
    ja: "これは{日本|にほん}の[ビデオ]です。",
    en: "This is a Japanese video player." },
  "ドア|": {
    explain: "This comes from the English word door. Notice the ending. Japanese doesn't keep the r sound at the end, so the word ends on an open a sound, 「ア」, much like a British pronunciation of door without the final r. The d plus o becomes 「ド」. So you get a short, two beat word. This dropped r is very common in English loanwords: curtain becomes 「カーテン」, and many words ending in er end in a long vowel instead. Now the meaning. 「ドア」 is used for Western style doors, the kind on hinges that swing open, plus car doors and automatic doors in shops and trains. Traditional Japanese rooms have sliding doors and paper screens, and those have their own native words, often using 「戸|と」, door. So the loanword helps keep the Western style door separate. A cultural note: taxi doors in Japan open and close automatically, controlled by the driver, so don't pull them yourself. In the classroom, the door sits with the 「まど」, window, which you'll meet later. A simple sentence: 「あのドアはおてあらいです」, that door is the restroom. Recap: English door with the r dropped, the swinging Western style door.",
    ja: "あの[ドア]はおてあらいです。",
    en: "That door is the restroom." },
  "カーテン|": {
    explain: "This comes from the English word curtain. Look at how the sounds were squeezed into Japanese. The c becomes 「カ」. Then the ur sound in the middle of curtain, which is a sort of r coloured vowel, becomes a long a, written with the long vowel mark, 「カー」. The r itself disappears, the same thing that happens in 「ドア」, door. Then the t and the ending become 「テン」, with the final n as 「ン」. So curtain turns into four beats in Japanese. That pattern, an English ur or er turning into a long vowel, shows up again and again. You'll see it in 「コンピューター」, computer, and 「トレーナー」, trainer. The meaning is the same as in English: the cloth hanging over a window. Japanese homes with traditional rooms might use paper screens instead, but most homes today have curtains. Many Japanese families buy blackout curtains, since the sun rises very early in summer. In the classroom, curtains go with the 「まど」, window, and the 「ドア」, door. A useful sentence: 「あのカーテンはたかいです」, that curtain is expensive. Recap: English curtain, the ur stretched into 「カー」, the curtain.",
    ja: "あの[カーテン]はたかいです。",
    en: "That curtain is expensive." },
  "たべる|食べる": {
    explain: "The kanji 「食|しょく」 is built around a food dish with a lid on top. Picture lifting that lid at mealtime to see what is inside. In this verb it uses its native Japanese reading, 「た」, and the hiragana 「べる」 after it carries the grammar. When the kanji appears in compound words, it usually switches to its Chinese-origin reading, 「しょく」. You can see that in 「食堂|しょくどう」, the cafeteria, a hall for eating. In 「食べ物|たべもの」, food, it keeps the native reading: an eating thing. Watch for this kanji squeezed onto the left side of other kanji, too. It sits inside 「飲む|のむ」, to drink, and inside the 「飯|はん」 of 「ご飯|ごはん」, a meal. Grammar note: this is a ru-verb, so you drop the 「る」 and add 「ます」 to get 「食べます|たべます」. Recap: a lidded dish of food, read 「た」 here, and the anchor for a whole family of eating words.",
    ja: "{毎日|まいにち}{朝|あさ}ごはんを[食べます|たべます|たべる]。",
    en: "I eat breakfast every day." },
  "のむ|飲む": {
    explain: "Look at the left side of the kanji. That is the food kanji from 「食べる|たべる」, squeezed narrow. The right side is a person with a wide open mouth, the same piece that often means yawning or gaping. Food plus an open mouth gives you drinking. The reading here is the native Japanese one, 「の」, with 「む」 in hiragana. It is a u-verb, so the polite form is 「飲みます|のみます」. Its family is easy to spot. 「飲み物|のみもの」 is a drinking thing, a drink, just as 「食べ物|たべもの」 is an eating thing. Here is a twist English speakers do not expect. In Japanese you drink medicine: 「薬を飲む|くすりをのむ」 means to take medicine, even if it is a pill. You can also use it with 「お酒|おさけ」 to mean drinking alcohol in general. Recap: food side plus open mouth, read 「の」, used for anything you swallow, from water to pills.",
    ja: "{朝|あさ}コーヒーを[飲みます|のみます|のむ]。",
    en: "I drink coffee in the morning." },
  "ねる|寝る": {
    explain: "The top of the kanji is the roof piece you also see on 「家|いえ」, house. Squeezed into the lower left is a narrow shape that comes from an old drawing of a bed. So you have a bed under your roof, which is where you sleep. The reading here is the native Japanese one, 「ね」, with 「る」 in hiragana. It is a ru-verb, so the polite form is 「寝ます|ねます」. Be careful with the meaning. It covers both going to bed and being asleep, and it can even mean simply lying down. To say you feel sleepy, Japanese uses a different word, 「眠い|ねむい」, with a different kanji. The same 「寝|ね」 shows up in 「朝寝坊する|あさねぼうする」, to oversleep, which is literally sleeping into the morning. A common pattern is a time plus 「に」, as in going to bed at eleven. Recap: a bed under a roof, read 「ね」, for going to bed and sleeping.",
    ja: "{毎晩|まいばん}じゅういちじに[寝ます|ねます|ねる]。",
    en: "I go to bed at eleven every night." },
  "よむ|読む": {
    explain: "The left side of this kanji is the speech piece, which comes from 「言|げん」, to say. Whenever you see it squeezed onto the left of a kanji, the meaning has something to do with words or language. It appears in 「話す|はなす」, to talk, in the 「語|ご」 of 「日本語|にほんご」 and 「外国語|がいこくご」, and in the 「説|せつ」 of 「説明する|せつめいする」, to explain. Reading is taking in words, so it belongs in this family. The right side happens to look like the kanji for selling. A way to remember it, as a hook only: the words on a page are selling you a story. In this verb the kanji has its native reading, 「よ」, with 「む」 in hiragana. It is a u-verb, so the polite form is 「読みます|よみます」. You read books, magazines like 「雑誌|ざっし」, and newspapers like 「新聞|しんぶん」. Recap: the words radical on the left, read 「よ」, for taking in written words.",
    ja: "{図書館|としょかん}で{本|ほん}を[読みます|よみます|よむ]。",
    en: "I read books at the library." },
  "えいが|映画": {
    explain: "Two kanji, both with their Chinese-origin readings. The first, 「映|えい」, means to reflect or to project, the way an image shows up on a mirror or on water. It has the sun on its left side, which fits a word about light and images. The second, 「画|が」, means a picture or a drawing. Put them together and you get a projected picture, which is exactly what a movie is: light thrown onto a big screen. The 「画|が」 also shows up in 「漫画|まんが」, comics, which are drawn pictures, and in 「漫画家|まんがか」, a cartoonist. Add the building kanji 「館|かん」 from 「図書館|としょかん」 and you get 「映画館|えいがかん」, a movie theater, a building for movies. To say you watch a movie, use 「見る|みる」, as in watching on the weekend. Recap: a projected picture, 「えい」 plus 「が」, and add 「館|かん」 for the theater.",
    ja: "{週末|しゅうまつ}に[映画|えいが]を{見ます|みます}。",
    en: "I watch a movie on the weekend." },
  "おんがく|音楽": {
    explain: "Two kanji, both read with their Chinese-origin readings here. The first, 「音|おん」, means sound. On its own it has a native reading, 「おと」, for a sound or a noise. The second, 「楽|がく」, means music, and it also carries the idea of enjoyment and ease. So sound plus music, or enjoyable sound, gives you music. The 「楽|がく」 is the part to watch, because it changes its reading depending on the word. In 「楽器|がっき」, a musical instrument, it shrinks to 「がっ」, and the word means a music tool. In 「楽しみです|たのしみです」, I am looking forward to it, it switches to the native reading 「たの」, the fun side of the kanji. Same shape, same core idea of pleasure, different sounds. To listen to music, use 「聞く|きく」, and to play it on an instrument you would use other verbs later. Recap: sound plus enjoyment equals music, and 「楽|がく」 connects music, instruments and fun.",
    ja: "よく[音楽|おんがく]を{聞きます|ききます}。",
    en: "I often listen to music." },
  "おちゃ|": {
    explain: "This is 「ちゃ」, tea, with the polite 「お」 in front. The 「お」 is so standard here that saying 「ちゃ」 alone sounds rough, so treat 「おちゃ」 as the normal word. It can be written with the kanji 「茶|ちゃ」, which has the grass piece on top, since tea is a plant. In Japan, plain 「おちゃ」 means green tea, the everyday drink served free in many restaurants. If you want the reddish brown kind most English speakers drink, that is 「紅茶|こうちゃ」, literally crimson tea, and it shares the same 「茶|ちゃ」. The tea kanji also hides in 「喫茶店|きっさてん」, an old style coffee shop, where it is read 「さ」. Here is a fun bit of history. The English word tea and the Japanese 「ちゃ」 come from the same Chinese word, said in different Chinese dialects. Words that traveled by sea became tea, and words that traveled overland became cha. Recap: polite 「お」 plus 「ちゃ」, and in Japan it means green tea unless you say otherwise.",
    ja: "{朝|あさ}[おちゃ]を{飲みます|のみます}。",
    en: "I drink green tea in the morning." },
  "がっこう|学校": {
    explain: "Two kanji with Chinese-origin readings. The first, 「学|がく」, means learning or study. You already know it from 「学生|がくせい」, a student, and 「大学|だいがく」, a college. In this word its last sound squashes into a small 「っ」, so 「がく」 plus 「こう」 becomes 「がっこう」. Japanese does this a lot when a 「く」 runs into a k sound. The second kanji, 「校|こう」, means school. It has the tree piece on its left. A way to remember it, as a hook only: an old schoolhouse built of wood. You know 「校|こう」 from 「高校|こうこう」, high school, which is a high school in the literal sense, high plus school. The learning kanji also shows up in 「留学生|りゅうがくせい」, an international student, and 「今学期|こんがっき」, this semester, where it squashes into 「がっ」 again. Recap: learning plus school building, with 「がく」 squashing to 「がっ」 in front of 「こう」.",
    ja: "{明日|あした}[学校|がっこう]に{行きます|いきます}。",
    en: "I will go to school tomorrow." },
  "としょかん|図書館": {
    explain: "Three kanji, each read with its Chinese-origin reading. The first, 「図|と」, means a drawing, chart or plan. In most words it is read 「ず」, as in 「地図|ちず」, a map, so 「と」 is a special reading you mostly meet in this word. The second, 「書|しょ」, means writing or a written document. It is the same kanji as the verb 「書く|かく」, to write, and you see it in 「辞書|じしょ」, a dictionary, 「教科書|きょうかしょ」, a textbook, and 「履歴書|りれきしょ」, a résumé. The third, 「館|かん」, means a large building or hall. Look at its left side and you will find the food piece from 「食べる|たべる」. It also ends 「映画館|えいがかん」, a movie theater, 「美術館|びじゅつかん」, an art museum, and 「旅館|りょかん」, a Japanese inn. Add it up: a building for drawings and writings, which is a library. Recap: 「と」, 「しょ」, 「かん」, pictures and writing in a big building.",
    ja: "[図書館|としょかん]で{本|ほん}を{読みます|よみます}。",
    en: "I read books at the library." },
  "テレビ|": {
    explain: "This comes from English television. The full Japanese form is 「テレビジョン」, but almost nobody says that. Japanese loves to clip long loanwords and keep only the front, so it became 「テレビ」. Notice two sound changes. Japanese traditionally has no v sound, so v turns into a b sound, giving 「ビ」. You see the same swap in 「ビデオ」, video. And the vowels are kept short and clear, with no long stretched sounds. Clipping is everywhere in Japanese loanwords. 「パソコン」 comes from personal computer, and 「エアコン」 comes from air conditioner. When you watch TV, you use 「見る|みる」, so you watch the TV rather than looking at a screen. The same word also means the TV set itself, the physical box in your living room. Recap: television, clipped to its first half, with v becoming b.",
    ja: "{毎晩|まいばん}[テレビ]を{見ます|みます}。",
    en: "I watch TV every night." },
  "ざっし|雑誌": {
    explain: "Two kanji with Chinese-origin readings. The first, 「雑|ざつ」, means mixed, assorted or miscellaneous. In this word its last sound squashes into a small 「っ」 before the 「し」, so 「ざつ」 plus 「し」 becomes 「ざっし」. The second, 「誌|し」, means a record or a periodical publication. Look at its left side and you will see the speech piece, the same one on 「読む|よむ」, to read, and 「話す|はなす」, to talk. That piece always points to words and language. So a magazine is a mixed record, a bundle of assorted articles, photos and ads. That fits real magazines well, which mix many short pieces on different topics. Compare 「新聞|しんぶん」, a newspaper, which is literally new things heard, news. A typical sentence is reading a magazine at a cafe with 「読む|よむ」. Recap: mixed plus written record, with 「ざつ」 squashing to 「ざっ」.",
    ja: "カフェで[雑誌|ざっし]を{読みます|よみます}。",
    en: "I read a magazine at a cafe." },
  "スポーツ|": {
    explain: "This comes from English sports, plural, and that plural s survives in the Japanese word. Watch how the sounds get squeezed into Japanese syllables. Japanese syllables almost always end in a vowel, so the s at the start gets a little u vowel and becomes 「ス」. The p joins with o to make 「ポ」. The or sound is borrowed the British way, without a strong r, so it turns into a long o, written with the long bar 「ー」. The final ts lands neatly on 「ツ」, a sound Japanese already has. To say you play sports, use 「する」: 「スポーツをする」. That pattern of a loanword plus 「する」 is everywhere, so it is worth getting used to. Specific sports work the same way, like 「テニス」 and 「サッカー」. One more note: Japanese uses this one word for both sport and sports, so there is no singular or plural to worry about. Recap: English sports, with extra vowels, a long o in place of the r, and paired with 「する」.",
    ja: "{週末|しゅうまつ}に[スポーツ]をします。",
    en: "I play sports on the weekend." },
  "デート|": {
    explain: "This comes from English date, but only in the romantic sense. It never means a calendar date. For the day of the month, Japanese uses completely different words, such as 「日付|ひづけ」. So the meaning got narrower when it was borrowed. Now the sounds. The English vowel in date glides from e toward i. Japanese flattens that glide into one long e, written with the long bar 「ー」, so you get 「デー」. Then the final t cannot end a syllable on its own, so it picks up an o vowel and becomes 「ト」. Most English words ending in t or d get an o like this. Like many loanwords, it pairs with 「する」, so 「デートをする」 means to go on a date. You can also say you have a date with someone using 「と」, with. A common mistake is using it for an appointment with a friend or a doctor. That would sound romantic, which is probably not what you mean. Recap: romantic date only, long e plus an o at the end, and used with 「する」.",
    ja: "{土曜日|どようび}に[デート]をします。",
    en: "I have a date on Saturday." },
  "テニス|": {
    explain: "This comes from English tennis. The sound changes are simple. English writes a double n, but it is really just one n sound, so Japanese uses a single 「ニ」. The final s cannot end a syllable, so it picks up a quiet u vowel and becomes 「ス」. In normal speech that final u is barely voiced, so it sounds close to the English. To say you play tennis, use 「する」: 「テニスをする」. This is the standard pattern for most sports in Japanese, like 「サッカー」 and 「スポーツ」 itself. English speakers sometimes reach for a separate verb meaning to play, but for sports 「する」 is what you want. Tennis is popular in Japan, especially soft tennis, a version played with a soft rubber ball that many students take up in school clubs. Recap: tennis with a single n and an extra u, and you play it with 「する」.",
    ja: "{日曜日|にちようび}に[テニス]をします。",
    en: "I play tennis on Sunday." },
  "アイスクリーム|": {
    explain: "This comes from English ice cream, and it is a great example of how Japanese adds vowels. English ice cream is just two syllables. Japanese syllables mostly end in vowels, so every lonely consonant gets one. The i sound in ice is a glide from a to i, so it becomes 「アイ」, and the final s gets a u vowel to make 「ス」. In cream, the c and r are crowded together, so each one needs its own vowel. The c becomes 「ク」, and the r becomes 「リ」 with a long vowel 「ー」. The final m becomes 「ム」. Two syllables in English grow into seven beats in Japanese. In everyday speech people often shorten it to just 「アイス」, which also means ice cream, not plain ice. If you want ice cubes, that is 「こおり」. That shortcut trips up English speakers who order ice and get dessert. Recap: ice cream stretched out with extra vowels, and often clipped to 「アイス」.",
    ja: "{今日|きょう}[アイスクリーム]を{食べます|たべます}。",
    en: "I will eat ice cream today." },
  "ハンバーガー|": {
    explain: "This comes from English hamburger, which itself is named after the German city of Hamburg. Look at the sound changes. The m in ham turns into 「ン」, which naturally sounds like m before a b. The er sounds in burger have weak r sounds, so Japanese turns them into long vowels with the long bar 「ー」, giving 「バー」 and 「ガー」. That r becoming a long vowel happens in many loanwords, like 「コンピューター」. Here is a cultural note that surprises visitors. Japan also has a dish called 「ハンバーグ」, a hamburg steak. It is a juicy patty, usually served on a plate with sauce and rice, with no bun at all. So 「ハンバーガー」 is the sandwich in a bun, and 「ハンバーグ」 is the plate dinner. Mixing them up at a restaurant can get you the wrong meal. Recap: hamburger with r sounds turned into long vowels, and not to be confused with the bunless 「ハンバーグ」.",
    ja: "{昼|ひる}ごはんに[ハンバーガー]を{食べます|たべます}。",
    en: "I eat a hamburger for lunch." },
  "おさけ|お酒": {
    explain: "This is the polite 「お」 plus 「酒|さけ」. The 「お」 is almost always used, so treat 「お酒|おさけ」 as the normal word. Look at the kanji. On the left are three drops, the water piece, which is a squeezed form of 「水|みず」, water. On the right is a shape that shows a jar for fermenting and storing liquor. Liquid in a wine jar gives you alcohol. The reading here is the native Japanese one, 「さけ」. Its Chinese-origin reading is 「しゅ」, which you hear in 「日本酒|にほんしゅ」, Japanese rice wine. That is an important cultural point. In English, sake means rice wine, but in Japanese 「お酒|おさけ」 means any alcoholic drink at all, including 「ビール」 and wine. If you want the rice wine specifically, say 「日本酒|にほんしゅ」. To drink alcohol, use 「飲む|のむ」. The legal drinking age in Japan is twenty. Recap: water drops plus a liquor jar, read 「さけ」, and it means alcohol in general.",
    ja: "わたしは[お酒|おさけ]を{飲みません|のみません}。",
    en: "I don't drink alcohol." },
  "コーヒー|": {
    explain: "This word did not come from English. It came from Dutch, where the word is spelled koffie. In the Edo period, when Japan closed itself off to most of the world, Dutch traders were among the very few Europeans allowed to trade there, at a small island in Nagasaki. Coffee arrived with them, along with many other Dutch words. Look at the sounds. The first o is stretched into a long vowel with the bar 「ー」. The f sound did not exist in older Japanese, so the f plus i became 「ヒ」. Then the end is stretched long too, giving 「ヒー」. That is why it sounds like a stretched out version of koffie. There are even old kanji used just for their sounds to write it, but katakana is what you will see on menus. To drink coffee, use 「飲む|のむ」. You can find it in cans from vending machines everywhere, hot in winter and cold in summer. Recap: from Dutch koffie, with long vowels and f turned into an h sound.",
    ja: "{朝|あさ}[コーヒー]を{飲みます|のみます}。",
    en: "I drink coffee in the morning." },
  "みず|水": {
    explain: "This kanji is one of the oldest pictures in the writing system. It shows flowing water: a central stream down the middle, with splashes or ripples on both sides. Here it uses its native Japanese reading, 「みず」. Its Chinese-origin reading is 「すい」, which you know from 「水曜日|すいようび」, Wednesday, literally water day. The weekdays use the old elements, so Monday is moon day, Tuesday fire day, and Wednesday water day. When water squeezes onto the left side of another kanji, it becomes three little drops. You can spot them in 「お酒|おさけ」, alcohol, and in the 「漢|かん」 of 「漢字|かんじ」, kanji. Whenever you see those three drops, think liquid. One more note: 「水|みず」 means cold or room temperature water. Hot water is a different word, 「おゆ」, so you would not ask for 「水|みず」 to make tea. Recap: a picture of a stream, read 「みず」 alone and 「すい」 in Wednesday, and it becomes three drops on other kanji.",
    ja: "{毎日|まいにち}[水|みず]を{飲みます|のみます}。",
    en: "I drink water every day." },
  "あさごはん|朝ご飯": {
    explain: "This is two words put together. 「朝|あさ」 means morning, read with its native Japanese reading. 「ご飯|ごはん」 means cooked rice, and by extension a meal, since rice was the center of a traditional Japanese meal. The 「ご」 is a polite prefix, and 「飯|はん」 is the Chinese-origin reading of the rice kanji. Look at the left side of 「飯|はん」 and you will find the food piece from 「食べる|たべる」. So breakfast is literally the morning rice. This word is one of a set of three. Swap the time word and you get 「昼ご飯|ひるごはん」, lunch, and 「晩ご飯|ばんごはん」, dinner. Learn the pattern once and you have all three meals. The morning kanji also appears in 「今朝|けさ」, this morning, which has a special reading, and in 「朝寝坊する|あさねぼうする」, to oversleep. A traditional Japanese breakfast really does include rice, along with miso soup and fish, though toast is common now too. Recap: morning plus rice, the first of the three meal words.",
    ja: "{七時|しちじ}に[朝ご飯|あさごはん]を{食べます|たべます}。",
    en: "I eat breakfast at seven." },
  "ひるごはん|昼ご飯": {
    explain: "This is 「昼|ひる」, noon or daytime, plus 「ご飯|ごはん」, a meal. Both pieces use their usual readings: 「ひる」 is the native Japanese reading of the noon kanji, and 「ご飯|ごはん」 is rice with a polite 「ご」. Look at the bottom of 「昼|ひる」 and you can find the sun, 「日|ひ」, which fits a word for the bright middle of the day. So lunch is literally the noon rice. It belongs to the set of three meal words. 「朝ご飯|あさごはん」 is breakfast and 「晩ご飯|ばんごはん」 is dinner. Only the time word changes. In casual speech people also say 「お昼|おひる」 to mean lunch, as in asking someone if they have eaten lunch yet. A cultural note: many Japanese workers and students bring a boxed lunch called 「おべんとう」, packed with rice and small side dishes. Convenience stores sell them too. Recap: noon plus rice, the middle of the three meal words, often shortened to 「お昼|おひる」.",
    ja: "{学校|がっこう}で[昼ご飯|ひるごはん]を{食べます|たべます}。",
    en: "I eat lunch at school." },
  "ばんごはん|晩ご飯": {
    explain: "This is 「晩|ばん」, evening, plus 「ご飯|ごはん」, a meal. The 「晩|ばん」 uses its Chinese-origin reading, and it has the sun piece on its left side, as many time words do. So dinner is literally the evening rice. It completes the set of three meal words with 「朝ご飯|あさごはん」, breakfast, and 「昼ご飯|ひるごはん」, lunch. The 「晩|ばん」 is worth knowing well, because it is in other words you have. 「今晩|こんばん」 means this evening, tonight, and 「毎晩|まいばん」 means every evening. It is even hiding in a greeting you learned on day one. 「こんばんは」, good evening, is really 「今晩|こんばん」 plus the topic particle 「は」. That is why that greeting is written with 「は」 at the end, even though it is pronounced like 「わ」. You may also hear another word for dinner, 「夕ご飯|ゆうごはん」, using the kanji for early evening. Both are fine. Recap: evening plus rice, and the same 「晩|ばん」 as in good evening.",
    ja: "{家|うち}で[晩ご飯|ばんごはん]を{食べます|たべます}。",
    en: "I eat dinner at home." },
  "いえ|家": {
    explain: "Look at the kanji. The top is a roof, the same roof piece that sits on 「寝る|ねる」, to sleep. Underneath is an old character for a pig. So the parts really are a roof and a pig. Scholars disagree about exactly why, so take this as a hook only: picture an old farmhouse where the family and the livestock live under the same roof. In this word the kanji uses its native Japanese reading, 「いえ」. In compound words it often uses the Chinese-origin reading 「か」. You can hear that in 「家族|かぞく」, family, the people of one house, and in 「家具|かぐ」, furniture, the tools of a house. It also attaches to the end of words for professions, like 「作家|さっか」, a writer, and 「漫画家|まんがか」, a cartoonist, meaning a person who has made that craft their trade. And in 「大家さん|おおやさん」, the landlord, it is read 「や」. Compared with 「うち」, 「家|いえ」 leans toward the physical building. Recap: a roof with a pig under it, read 「いえ」, and 「か」 in family and furniture.",
    ja: "[家|いえ]で{勉強します|べんきょうします}。",
    en: "I study at home." },
  "うち|": {
    explain: "This is a native Japanese word, and it can also be written with the same kanji as 「家|いえ」. The key difference is the feeling. 「いえ」 leans toward the building itself, the structure. 「うち」 leans toward home, your own household, the place you belong. That makes sense because 「うち」 also means inside, as opposed to outside. Your home is the inside of your world. So when you go home, the natural phrase is 「うちに帰る|うちにかえる」. Saying it with 「いえ」 is not wrong, but it sounds more like returning to a building. 「うち」 can also mean my family or our group, as in our company or our school, the inside group you belong to. This inside versus outside idea runs deep in Japanese culture and language, and you will see it again in politeness levels later. A way to remember it, as a hook: home is where you go in from the outside world. Recap: home in the warm sense, the inside of your life, and the natural word for going home.",
    ja: "{六時|ろくじ}に[うち]に{帰ります|かえります}。",
    en: "I go home at six." },
  "カフェ|": {
    explain: "This comes from French café, which reached Japanese as the name for a modern coffee shop. Look at the sounds. Older Japanese had no fe sound. To write one, Japanese takes 「フ」, a soft f-like sound, and adds a small 「ェ」 after it. The small vowel tells you to blend them into a single beat. This trick of adding a small vowel is how Japanese spells many new foreign sounds. You see it in 「ファイル」, file, with a small 「ァ」, and in 「サーフィン」, surfing, with a small 「ィ」. Note there is no accent mark and no long vowel at the end, so it stays short and crisp. Japan also has an older word for a coffee shop, 「喫茶店|きっさてん」. That word suggests a classic, slightly old fashioned place with a counter and hand-poured coffee. 「カフェ」 sounds more modern and trendy, like a chain or a stylish spot. Recap: French café, with a small 「ェ」 to build the fe sound, and the modern cousin of 「喫茶店|きっさてん」.",
    ja: "[カフェ]でコーヒーを{飲みます|のみます}。",
    en: "I drink coffee at a cafe." },
  "あした|明日": {
    explain: "Look at the first kanji, 「明|めい」. It is made of the sun on the left and the moon on the right, and it means bright. The second is 「日|ひ」, day. So the kanji say the next bright day. Here is the important part. The reading 「あした」 does not come from the separate readings of these two kanji. It is a native Japanese word for tomorrow, and the kanji were matched to it by meaning. That is called a special reading, and you learn the whole word as one piece. Several time words work this way, including 「今日|きょう」, today, and 「昨日|きのう」, yesterday. You can see the normal reading of 「明|めい」 in 「説明する|せつめいする」, to explain, which is making something bright and clear. In formal speech, tomorrow can also be 「あす」 or 「みょうにち」, but 「あした」 is the everyday word. Time words like this usually take no particle 「に」. Recap: sun plus moon is bright, the next bright day, read 「あした」 as one whole word.",
    ja: "[明日|あした]テニスをします。",
    en: "I will play tennis tomorrow." },
  "きょう|今日": {
    explain: "The first kanji, 「今|いま」, means now. The second, 「日|ひ」, means day. So the kanji say this day, the now day. But the reading 「きょう」 does not come from adding up the kanji readings. It is a special reading that belongs to the whole word, just like 「明日|あした」 and 「昨日|きのう」. Learn it as one piece. The first kanji is very useful elsewhere. On its own it is 「今|いま」, now. In compound words it is often read 「こん」. You know it from 「今晩|こんばん」, tonight, 「今週|こんしゅう」, this week, 「今月|こんげつ」, this month, and 「今学期|こんがっき」, this semester. In each one it means this current one. And here is a surprise: the greeting 「こんにちは」, hello, is really these same two kanji read 「こんにち」, plus the particle 「は」. So hello is literally as for today. Another special reading uses it too: 「今朝|けさ」, this morning. Recap: now plus day, read 「きょう」 as one word, and the same 「今|こん」 that means this.",
    ja: "[今日|きょう]は{土曜日|どようび}です。",
    en: "Today is Saturday." },
  "あさ|朝": {
    explain: "In the modern kanji, you can find the sun, 「日|ひ」, tucked in the left side, and a shape on the right that looks like the moon, 「月|つき」. Historians argue about where that right side really came from, so treat this as a hook only: picture the sun rising while the moon is still in the sky. That is early morning. Here the kanji uses its native Japanese reading, 「あさ」. You will see it again in 「朝ご飯|あさごはん」, breakfast, the morning meal, and in 「朝寝坊する|あさねぼうする」, to oversleep, to sleep into the morning. Watch out for 「今朝|けさ」, this morning. It uses the same kanji, but the whole word has a special reading, so it is not read with 「あさ」 at all. Morning time words often appear at the very start of a sentence, as in getting up at seven in the morning. You may also hear 「毎朝|まいあさ」, every morning, on the same pattern as 「毎日|まいにち」. Recap: sun and moon together in the early sky, read 「あさ」, the morning in breakfast.",
    ja: "[朝|あさ]{七時|しちじ}に{起きます|おきます}。",
    en: "I get up at seven in the morning." },
  "こんばん|今晩": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「今|こん」, means now or this current one. The second, 「晩|ばん」, means evening. This evening is tonight. The pattern of 「今|こん」 meaning this one is very productive. 「今週|こんしゅう」 is this week, 「今月|こんげつ」 is this month, and 「今学期|こんがっき」 is this semester. The 「晩|ばん」 is shared with 「毎晩|まいばん」, every evening, and 「晩ご飯|ばんごはん」, dinner. Here is the fun part. The greeting 「こんばんは」, good evening, is exactly this word plus the topic particle 「は」. Literally it means as for this evening, and the rest of the polite sentence has dropped away over time. That is why the greeting ends with 「は」 even though it sounds like 「わ」. 「こんにちは」 works the same way with today. You may also hear 「今夜|こんや」, which means tonight too, using the kanji for night from 「夜|よる」. Recap: this plus evening, and the same word that hides in good evening.",
    ja: "[今晩|こんばん]{映画|えいが}を{見ます|みます}。",
    en: "I will watch a movie tonight." },
  "まいにち|毎日": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「毎|まい」, means every or each. The second, 「日|にち」, means day. Every day. The 「毎|まい」 is a little machine for making words. Put it in front of a time word and you get every one of them. 「毎晩|まいばん」 is every evening, 「毎週|まいしゅう」 is every week, and 「毎朝|まいあさ」 is every morning. The 「日|にち」 reading of the day kanji also shows up in 「日曜日|にちようび」, Sunday, and in 「一日|いちにち」, one day. A grammar tip that English speakers often miss: words with 「毎|まい」 do not take the particle 「に」. You just say every day and then the rest of the sentence. Adding 「に」 is a common beginner mistake. The same goes for 「今日|きょう」 and 「明日|あした」. Habits are a great use for this word, with the plain 「ます」 form, like studying Japanese every day. Recap: every plus day, and 「毎|まい」 makes every week and every night too, with no 「に」.",
    ja: "[毎日|まいにち]{日本語|にほんご}を{勉強します|べんきょうします}。",
    en: "I study Japanese every day." },
  "まいばん|毎晩": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「毎|まい」, means every or each. The second, 「晩|ばん」, means evening. Every evening, every night. It is built exactly like 「毎日|まいにち」, every day, and 「毎週|まいしゅう」, every week. Learn 「毎|まい」 once and you can make a whole set. The 「晩|ばん」 links this word to two others you know. 「今晩|こんばん」 is this evening, tonight, and 「晩ご飯|ばんごはん」 is the evening meal, dinner. So if you know the meal, you know the time. A grammar tip: like other 「毎|まい」 words, this one does not need the particle 「に」. Just say every night, then the rest of the sentence. Adding 「に」 is a very common beginner mistake. This word is perfect for describing routines with the 「ます」 form, like listening to music every night or watching TV every night. Recap: every plus evening, built like 「毎日|まいにち」, and no 「に」 needed.",
    ja: "[毎晩|まいばん]{音楽|おんがく}を{聞きます|ききます}。",
    en: "I listen to music every night." },
  "しゅうまつ|週末": {
    explain: "Two kanji with Chinese-origin readings. The first, 「週|しゅう」, means week. It has the movement piece wrapping around the bottom left, and inside is a part meaning around or a full circuit. A week is a cycle that comes around again and again. You know it from 「先週|せんしゅう」, last week, 「今週|こんしゅう」, this week, 「来週|らいしゅう」, next week, and 「毎週|まいしゅう」, every week. The second kanji, 「末|まつ」, means end or tip. It is the tree shape with an extra long stroke across the top, marking the tip of the branches, the far end of the tree. Compare 「本|ほん」, which has a mark at the bottom, near the roots, the origin. The same 「末|まつ」 appears in 「期末試験|きまつしけん」, a final exam, the test at the end of a term. Put them together and you get the end of the week, the weekend, a perfect match with English. Use 「に」 after it to say on the weekend. Recap: week plus end, built like English, with 「末|まつ」 marking the tip of the tree.",
    ja: "[週末|しゅうまつ]に{友だち|ともだち}と{映画|えいが}を{見ます|みます}。",
    en: "I watch a movie with friends on the weekend." },
  "いつ|": {
    explain: "This is the question word for time. It belongs to a family of question words you already know. 「なん」 asks what, 「どこ」 asks where, 「だれ」 asks who, and 「いつ」 asks when. In a sentence it usually sits right before the verb, and the sentence ends with 「か」. For example, when will you go to Japan. A key grammar point: 「いつ」 does not take the particle 「に」. English speakers often add it because time words like at three o'clock use 「に」, but with 「いつ」 you leave it out. You can also use it as a noun with 「です」, as in asking when someone's birthday is: 「誕生日はいつですか|たんじょうびはいつですか」. It is related to 「いつも」, always, which is literally when plus also, any time at all. A way to remember it, as a hook: it sounds a bit like English it's, so imagine asking, it's when? Recap: the when word, no 「に」, and the root of 「いつも」.",
    ja: "[いつ]{日本|にほん}に{行きますか|いきますか}。",
    en: "When will you go to Japan?" },
  "〜ごろ|": {
    explain: "This little ending makes a point in time fuzzy. You stick it right onto a clock time, a day, or a date. 「三時|さんじ」 is three o'clock sharp. 「三時ごろ|さんじごろ」 is three-ish, around three. It also works with bigger units, like 「土曜日ごろ|どようびごろ」, around Saturday. You can add 「に」 after it or leave it off; both sound natural. Here is the common mistake. 「ごろ」 is only for a moment on the timeline, a when. For an amount, like about two hours or about ten dollars, Japanese uses a different word, 「ぐらい」. So around three o'clock takes 「ごろ」, but about three hours does not. You will meet the same sound in 「このごろ」, these days, which is a fuzzy stretch of recent time. A way to remember it: 「ごろ」 sounds like a ball rolling around, 「ごろごろ」, never landing on exactly one spot. To recap, put it after a time to say roughly when.",
    ja: "{毎晩|まいばん}[十一時ごろ|じゅういちじごろ|〜ごろ]{寝ます|ねます}。",
    en: "I go to bed around eleven every night." },
  "いく|行く": {
    explain: "The kanji 「行|い」 began as a picture of a crossroads, two streets crossing, the place where you set off in some direction. Here it takes its native Japanese reading, 「い」. In other words it uses the Chinese-origin reading 「こう」. You know it from 「旅行|りょこう」, travel, a journey you set out on, and from 「飛行機|ひこうき」, an airplane, a machine that flies and goes. Mark where you are going with 「に」 or 「へ」, like 「学校に行きます|がっこうにいきます」, I go to school. It is a u-verb, so the polite form is 「行きます|いきます」. Watch out for one quirk you will meet later: its te-form is 「行って|いって」, not the pattern you would expect. One more thing English speakers trip on. Japanese chooses between going and coming based on the speaker. If you move away from where you are now, it is always this verb, even when English might say I'm coming. To recap, a crossroads kanji for heading off somewhere.",
    ja: "{図書館|としょかん}に[行きます|いきます|いく]。",
    en: "I go to the library." },
  "かえる|帰る": {
    explain: "This verb is about going back to your home base. That usually means your house, but it can be your hometown or your own country. Coming back to the office after lunch is not quite it; it is the return to where you belong. The most common phrase is 「うちに帰ります|うちにかえります」, I go home. Here the kanji takes its native Japanese reading, 「かえ」. Grammar alert: even though it ends in 「える」, it is a u-verb, not a ru-verb. So the polite form is 「帰ります|かえります」, and later the negative is 「帰らない|かえらない」. It belongs to a small club of tricky ones that look like ru-verbs but are not. A fun cultural note. The word for frog is also 「かえる」, and many Japanese people carry little frog charms when they travel. The pun is that the frog helps you come home safely. A way to remember it: picture a frog hopping back home. To recap, going back to where you belong, and it conjugates as a u-verb.",
    ja: "{六時|ろくじ}にうちに[帰ります|かえります|かえる]。",
    en: "I go home at six." },
  "はなす|話す": {
    explain: "Look at the kanji 「話|はな」. On the left is the speech radical, the same piece you will see in 「言う|いう」, to say. On the right is a shape that looks like 「舌|した」, tongue. A way to remember it: words plus a tongue make talking. In this verb the kanji uses its native reading, 「はな」. In compounds it uses the Chinese-origin reading 「わ」. That is the 「わ」 in 「電話|でんわ」, telephone, literally electric talk, since 「電|でん」 is electricity. It also appears in 「電話する|でんわする」, to make a call. With this verb, the person you talk with takes 「と」, and the language takes 「で」. So 「友だちと日本語で話します|ともだちとにほんごではなします」 means I talk with my friend in Japanese. It is a u-verb, so the polite form is 「話します|はなします」. Compare it with 「言う|いう」, which is about the words someone says, while this one is about having a conversation. To recap, speech plus tongue, the talking kanji.",
    ja: "{友だち|ともだち}と{日本語|にほんご}で[話します|はなします|はなす]。",
    en: "I talk with my friend in Japanese." },
  "おきる|起きる": {
    explain: "The kanji 「起|お」 has the run radical on its left side, the same shape that stands alone as 「走|はし」 in 「走る|はしる」, to run. That piece is about movement, getting your feet going. In this word the kanji takes its native reading, 「お」. A way to remember it: picture yourself springing up out of bed, ready to run. That is getting up. It is a ru-verb, so you drop the 「る」 and add 「ます」 to get 「起きます|おきます」. It pairs naturally with its opposite, 「寝る|ねる」, to go to bed. Notice that it is about you getting up yourself. When you wake someone else up, Japanese uses a related verb with the same kanji, 「起こす|おこす」. One small cultural note: a classic Japanese worry is 「朝寝坊|あさねぼう」, oversleeping, which is exactly what happens when this verb fails. To recap, the run radical for jumping out of bed.",
    ja: "{朝|あさ}{六時|ろくじ}に[起きます|おきます|おきる]。",
    en: "I get up at six in the morning." },
  "みる|見る": {
    explain: "The kanji 「見|み」 is one of the clearest pictures in Japanese. On top is 「目|め」, the eye, and underneath are two little legs. So it is an eye walking around, looking at things. In this verb it takes its native reading, 「み」. In compounds it often uses the Chinese-origin reading 「けん」. It covers seeing, looking, and watching all at once, so use it for movies, TV, and sports, where English switches to watch. That means 「テレビを見ます|テレビをみます」 and 「映画を見ます|えいがをみます」. It is a ru-verb with a very short stem, so the polite form is just 「見ます|みます」. You will meet a whole family built on the same kanji. 「見せる|みせる」 is to show, making someone else see. 「見える|みえる」 is to be visible, something that can be seen. 「見つかる|みつかる」 is to be found. To recap, an eye on legs, the verb for seeing and watching.",
    ja: "{今晩|こんばん}テレビを[見ます|みます|みる]。",
    en: "I will watch TV tonight." },
  "くる|来る": {
    explain: "This is the opposite of 「行く|いく」. It means moving toward where the speaker is, or toward the place being talked about. The kanji 「来|く」 is traditionally said to have started as a picture of a wheat plant, and the meaning come was borrowed onto it. In this verb it uses the native reading. In time words it uses the Chinese-origin reading 「らい」, meaning the one that is coming. So 「来週|らいしゅう」 is next week, 「来月|らいげつ」 is next month, and 「来年|らいねん」 is next year, the week, month, and year that are on their way to you. Grammar alert: this is one of only two irregular verbs, along with 「する」. Its vowel changes. The dictionary form is 「くる」, but the polite form is 「来ます|きます」, and later the negative is 「来ない|こない」. The kanji stays the same while the sound shifts, so read carefully. To recap, the coming verb, irregular, and the 「らい」 in next week and next year.",
    ja: "{友だち|ともだち}がうちに[来ます|きます|くる]。",
    en: "My friend is coming to my house." },
  "する|": {
    explain: "This is the all-purpose verb of Japanese. On its own it means to do, but its real power is turning nouns into actions. Put a noun with 「を」 before it, like 「テニスをする」, to play tennis, or 「宿題をする|しゅくだいをする」, to do homework. Many nouns can even attach directly. 「勉強|べんきょう」 is study, the noun, and 「勉強する|べんきょうする」 is to study. 「電話|でんわ」 is a phone, and 「電話する|でんわする」 is to call. 「旅行|りょこう」 is travel, and 「旅行する|りょこうする」 is to travel. It is one of only two irregular verbs, together with 「来る|くる」. The polite form is 「します」, and later the negative is 「しない」. A common mistake for English speakers is reaching for 「あそぶ」 for playing sports. With sports and games, Japanese simply does them, so use this verb. A way to remember it: think of it as the glue that sticks onto a noun and makes it move. To recap, to do, the verb that turns nouns into actions.",
    ja: "{週末|しゅうまつ}テニスを[します|します|する]。",
    en: "I play tennis on the weekend." },
  "べんきょうする|勉強する": {
    explain: "Break it apart. 「勉|べん」 means to make an effort, to push yourself. 「強|きょう」 means strong, the same kanji as in 「強い|つよい」, strong. Both use their Chinese-origin readings here. Put them together and you get pushing hard with effort, which is how Japanese thinks of studying. Then add 「する」 to turn the noun into a verb. Here is a fun anecdote. In Chinese, the same two characters mean doing something reluctantly, forcing yourself. And in Japanese shops, especially in the old merchant city of Osaka, a shopkeeper might say they will make an effort for you with this word, meaning they will give you a discount. So the core idea really is straining yourself. Grammar note: the subject you study takes 「を」, like 「日本語を勉強します|にほんごをべんきょうします」. You can also say it as 「日本語の勉強をします|にほんごのべんきょうをします」. It is different from 「練習する|れんしゅうする」, to practice, which is drilling a skill. To recap, effort plus strong, hard work at your books.",
    ja: "{図書館|としょかん}で[勉強します|べんきょうします|べんきょうする]。",
    en: "I study at the library." },
  "いい|": {
    explain: "This is the everyday, friendly form of an older adjective, 「よい」. Both mean good, but in conversation people almost always say 「いい」. Here is the catch that trips up every learner. Only the plain present form uses the 「いい」 shape. As soon as you conjugate it, it goes back to 「よ」. So not good is 「よくない」, not 「いくない」. Was good is 「よかった」. You already know that one inside 「よかったら」, if you like, which literally means if it is good. The adverb 「よく」, often or well, comes from the same root. You will also hear it a lot in 「頭がいい|あたまがいい」, smart, which literally says the head is good. It can also mean no thanks, depending on the tone, when someone says 「いいです」 to decline an offer, so listen for context. A way to remember it: think of a happy squeal, eee, that's good. To recap, 「いい」 when you say it plain, but 「よ」 whenever you change its shape.",
    ja: "それは[いい]ですね。",
    en: "That's good." },
  "あまり|": {
    explain: "This adverb softens a negative. Pair it with a negative verb or adjective and it means not very much, not very often. So 「テレビはあまり見ません|テレビはあまりみません」 means I don't watch TV much. It is not a flat no, just a little. The key rule for English speakers is that it needs a negative ending in this meaning. You cannot say 「あまり見ます|あまりみます」 to mean I watch a little. On the frequency scale it sits near the bottom. From most to least, you have 「いつも」, always, then 「たいてい」, usually, then 「よく」, often, then 「ときどき」, sometimes, then this one, not much, and finally 「ぜんぜん」, not at all. In casual speech you will also hear it squeezed into 「あんまり」. A way to remember it: picture a dial turned almost all the way down, but not quite to zero. To recap, a soft not much that always goes with a negative.",
    ja: "テレビは[あまり]{見ません|みません}。",
    en: "I don't watch TV much." },
  "ぜんぜん|全然": {
    explain: "Break it apart. 「全|ぜん」 means whole or complete. You know it from 「全部|ぜんぶ」, all of it, every part. 「然|ぜん」 is a kanji that describes a state, the way something is. Both use their Chinese-origin readings. Together they mean completely, wholly. Paired with a negative, that gives you not at all, a no all the way through. So 「お酒は全然飲みません|おさけはぜんぜんのみません」 means I don't drink alcohol at all. It is the strongest step on the scale below 「あまり」, not much. Keep that order in mind: 「あまり」 is just a little no, this one is a total no. A cultural note. Younger Japanese people often use it with positive words, as in 「全然いい|ぜんぜんいい」, totally fine. Some older people find that sloppy, but you will hear it everywhere. In your class, stick with negatives. To recap, wholly and completely, which with a negative means not at all.",
    ja: "お{酒|さけ}は[全然|ぜんぜん]{飲みません|のみません}。",
    en: "I don't drink alcohol at all." },
  "たいてい|": {
    explain: "This adverb tells you how often something happens, and it sits high on the scale, just under 「いつも」, always. It means usually, most of the time. So 「たいてい七時に起きます|たいていしちじにおきます」 is I usually get up at seven. It goes near the start of the sentence, before the verb, like the other frequency words. Let's place it on the full ladder. From most to least, you have 「いつも」, always, then this word, usually, then 「よく」, often, then 「ときどき」, sometimes, then 「あまり」, not much, and 「ぜんぜん」, not at all, with a negative. Unlike the last two, this one goes with a positive verb. It can be written with kanji, but in everyday writing and in your textbook it is usually just kana. A way to remember it: it sounds a bit like tight-tay, so picture a tight daily routine you nearly always stick to. To recap, usually, the second rung from the top of the frequency ladder.",
    ja: "[たいてい]{七時|しちじ}に{起きます|おきます}。",
    en: "I usually get up at seven." },
  "ちょっと|": {
    explain: "This little word means a small amount, a bit. 「日本語をちょっと話します|にほんごをちょっとはなします」 is I speak a little Japanese. It is the casual cousin of 「少し|すこし」, which means the same thing but sounds a bit more careful. You will also hear it on its own in 「ちょっと待って|ちょっとまって」, wait a sec. Here is the big cultural point. Japanese people often avoid a direct no. Instead, they say 「ちょっと」 and let the voice trail off, often with a little intake of breath. That unfinished sentence means that's a bit difficult, which really means no. If you invite someone and hear 「土曜日はちょっと|どようびはちょっと」, they are politely declining Saturday. Don't push for a reason. A way to remember it: think of a tiny pinch between your thumb and finger, just a smidge. To recap, a little bit, and when it trails off, a gentle no.",
    ja: "{日本語|にほんご}を[ちょっと]{話します|はなします}。",
    en: "I speak a little Japanese." },
  "ときどき|時々": {
    explain: "The kanji 「時|とき」 means time. It takes its native reading here. The second character is not really a kanji at all. It is a repeat mark that means write the last one again. So the word is literally time, time. Something that happens at times and times, now and then. When the word doubles, the second 「と」 softens to 「ど」, which is very common in Japanese doubling. You can see the same kanji with the same native reading in 「時|とき」, the word for when or at the time of. With its Chinese-origin reading 「じ」, it shows up in 「時間|じかん」, time or hours, and in clock times like 「三時|さんじ」. It is also the first part of 「時計|とけい」, a clock. On the frequency ladder it sits in the middle. It is less than 「よく」, often, and more than 「あまり」, not much, and it takes a positive verb. To recap, time doubled, so it happens from time to time.",
    ja: "[時々|ときどき]{図書館|としょかん}に{行きます|いきます}。",
    en: "I sometimes go to the library." },
  "よく|": {
    explain: "This adverb comes from 「よい」, good, the same root as 「いい」. Adding 「く」 turns the adjective into an adverb, the way English adds ly. So its first meaning is well, as in doing something well. You hear that in 「よくできました」, well done, the phrase teachers write on homework. Its second meaning is often, a lot. The idea is that doing something well and doing something often go together. So 「よくカフェに行きます|よくカフェにいきます」 is I often go to cafes. On the frequency ladder it sits below 「たいてい」, usually, and above 「ときどき」, sometimes. Context tells you which meaning you have. With a verb about how often, like going or eating, it is usually often. With a verb of ability or understanding, like 「わかる」, it means well. 「よくわかります」 is I understand well. A way to remember it: good things happen often. To recap, from good, meaning well or often.",
    ja: "[よく]カフェに{行きます|いきます}。",
    en: "I often go to cafes." },
  "そうですね|": {
    explain: "Break it into pieces. 「そう」 means so, that way, like that. 「です」 is the polite is. And 「ね」 is the little particle that invites agreement, like right? or isn't it? at the end of an English sentence. Put together, it literally says it is so, isn't it. The magic is that the same phrase does two different jobs, and your tone tells people which one. Said brightly and quickly, it means that's right, I agree. If a friend says it is hot today, you answer 「そうですね」, it sure is. Said slowly and thoughtfully, with the 「ね」 stretched out, it becomes a filler that buys you time, like well, let me see. You will hear Japanese speakers use it constantly while they think of an answer. Don't confuse it with 「そうですか」, with 「か」 at the end, which means oh, is that so, when you just learned something new. A way to remember it: 「ね」 nods along with the other person. To recap, so plus a nod, meaning I agree, or let me think.",
    ja: "[そうですね]、テニスはどうですか。",
    en: "Let me see, how about tennis?" },
  "でも|": {
    explain: "This word starts a new sentence and flips what came before it. The first sentence says one thing, and then 「でも」 says, however, here is the other side. For example, 「日本語はむずかしいです。でも、おもしろいです|にほんごはむずかしいです。でも、おもしろいです」 means Japanese is hard. But it is interesting. Notice that it sits at the very start of the second sentence, usually with a little pause or comma after it. That is the main difference from English, where but often joins two parts in one sentence. To connect two clauses inside a single sentence, Japanese uses a different tool, which you will meet later as 「けど」 or 「が」 tacked onto the end of the first clause. 「でも」 is fine in both polite and casual speech. Later you will also see it used after a noun to mean even or something like, as in coffee or something, so listen for where it sits. A way to remember it: picture a demo that looks great, but then something breaks. To recap, a sentence opener that means but, flipping the story.",
    ja: "[でも]、{今日|きょう}は{行きません|いきません}。",
    en: "But I won't go today." },
  "どうですか|": {
    explain: "Break it apart. 「どう」 is the question word how, in what way. You will see it again in 「どうして」, why, literally how come, and in 「どうやって」, how, by what means. Add 「ですか」, the polite is plus the question marker, and you get how is it? This phrase does two jobs. First, it asks for someone's opinion or how something went. 「日本の生活はどうですか|にほんのせいかつはどうですか」 means how is life in Japan? Second, it makes a suggestion or an offer. 「コーヒーはどうですか」 means how about some coffee? and 「明日はどうですか|あしたはどうですか」 means how about tomorrow? That second use is super handy for making plans. When you want to be extra polite, for example with a customer or a guest, swap in the fancy version 「いかがですか」, which means the same thing. In casual speech with friends, just say 「どう」 with rising intonation. To recap, how plus is it, for asking opinions and making suggestions.",
    ja: "{明日|あした}は[どうですか]。",
    en: "How about tomorrow?" },
  "ええ|": {
    explain: "This is a yes, but a softer and more relaxed one than 「はい」. Think of the difference between yes and yeah, though 「ええ」 is still perfectly polite in everyday conversation. You will hear it a lot when someone is chatting comfortably, agreeing with what was just said, or answering a simple question. 「行きますか|いきますか」, are you going? 「ええ、行きます|ええ、いきます」, yeah, I'm going. In formal situations, like answering a teacher in class, a job interview, or responding when your name is called, stick with 「はい」. That one is crisp and clear. Also, Japanese people often make an 「ええ」 sound while listening, to show they are following along, so it is not always a firm agreement. It can just mean I hear you. Be careful with the tone. A long, rising 「えええ」 is a surprised what?! And never mix it up with 「いいえ」, which is no. A way to remember it: 「ええ」 sounds like a relaxed yeah. To recap, a soft, conversational yes.",
    ja: "[ええ]、{行きます|いきます}。",
    en: "Yes, I'll go." },
  "きく|聞く": {
    explain: "Look at the kanji 「聞|き」. The outside is 「門|もん」, a gate, and inside the gate is 「耳|みみ」, an ear. Picture an ear pressed up against a gate, listening to what is happening on the other side. In this verb the kanji takes its native reading, 「き」. With its Chinese-origin reading 「ぶん」, it appears in 「新聞|しんぶん」, newspaper. 「新|しん」 is new, the same kanji as in 「新しい|あたらしい」, so a newspaper is literally new things you hear about. This verb has two meanings. The first is to listen or to hear, like 「音楽を聞きます|おんがくをききます」, I listen to music. The second is to ask, like asking a teacher a question. In that case the person you ask takes 「に」. Asking is just how you go and hear an answer, so the two meanings fit together. It is a u-verb, so the polite form is 「聞きます|ききます」. To recap, an ear at the gate, for listening and for asking.",
    ja: "{毎晩|まいばん}{音楽|おんがく}を[聞きます|ききます|きく]。",
    en: "I listen to music every night." },
  "はやい|早い": {
    explain: "The kanji 「早|はや」 is small and simple. On top is 「日|ひ」, the sun, and underneath is a shape that looks like a cross or a post. A way to remember it: picture the sun just peeking over a post at dawn, very early in the day. That image is a hook, not the official history of the kanji. In this word it uses its native reading, 「はや」. It means early in time, like getting up early or arriving early. Here is a common learner trap. Japanese has another word with exactly the same sound that means fast in speed, and it is written with a different kanji, 「速い|はやい」. Spoken aloud they sound identical, so context does the work. Early morning uses this one; a fast car uses the other. Your vocab list even lists 「早く|はやく」 as early or fast, because the adverb form gets both spellings. The adverb shows up in sentences like 「早く起きます|はやくおきます」, I get up early. It also appears in 「おはようございます」, good morning, which is built on this same word, meaning it is early. To recap, sunrise kanji for early, not fast.",
    ja: "{今日|きょう}は[早く|はやく|はやい]{起きます|おきます}。",
    en: "Today I will get up early." },
  "どようび|土曜日": {
    explain: "Break it apart. 「土|ど」 means earth or soil, here with its Chinese-origin reading. 「曜|よう」 is a kanji you will mostly see in days of the week. And 「日|び」 means day, with a sound change from 「ひ」 to 「び」. The days of the week in Japanese come from an old system that named the seven days after the sun, the moon, and five planets. Each planet has a name built on one of the classical elements. The planet Saturn is called 「土星|どせい」, the earth star. So Saturday is earth day, and it lines up with Saturn day in English too, which is nice. Notice how the whole week fits this pattern. 「月曜日|げつようび」 is moon day, Monday. 「火曜日|かようび」 is fire day, Tuesday. 「水曜日|すいようび」 is water day, Wednesday. 「木曜日|もくようび」 is wood or tree day, Thursday. A way to remember it: Saturday is for working in your garden, digging in the earth. To recap, earth day, Saturn day, Saturday.",
    ja: "[土曜日|どようび]に{映画|えいが}を{見ます|みます}。",
    en: "I watch a movie on Saturday." },
  "にちようび|日曜日": {
    explain: "Break it apart. 「日|にち」 is the sun, here with its Chinese-origin reading. 「曜|よう」 is the kanji you will mostly see in days of the week. And the last 「日|び」 is day, with its native reading softened from 「ひ」 to 「び」. So this word uses the same kanji twice, with two different readings. The first one is the sun, and the second one is the day. Sun day: a perfect match with English Sunday. This is no accident, because both Japanese and English day names come from the same ancient idea of naming the days after the sun, the moon, and the five visible planets. The partner day is 「月曜日|げつようび」, moon day, which matches Monday. The same sun kanji with the reading 「に」 also starts 「日本|にほん」, Japan, which means the origin of the sun, the land of the rising sun. And with the reading 「にち」 again, it shows up in 「毎日|まいにち」, every day. To recap, sun plus day of the week, Sunday, the easiest day name to remember.",
    ja: "[日曜日|にちようび]に{家|いえ}で{勉強します|べんきょうします}。",
    en: "I study at home on Sunday." },
  "おどる|踊る": {
    explain: "Look at the kanji 「踊|おど」. On the left side is the foot radical, the same piece you see at the bottom left of 「足|あし」, foot or leg. Kanji with that piece usually have something to do with feet or stepping. In this verb the kanji uses its native reading, 「おど」. A way to remember it: feet moving to music, that is dancing. It is a u-verb, so the polite form is 「踊ります|おどります」. Drop the 「る」 and you get the noun 「踊り|おどり」, a dance. A great cultural note. Every summer, Japanese towns hold festivals for 「お盆|おぼん」, the time when families honor their ancestors. At these festivals people dance 「盆踊り|ぼんおどり」, slow circle dances around a tall stage with drummers, often in light summer kimono. It is a big part of 「お祭り|おまつり」, festival season, and anyone can join in, even beginners. Don't confuse it with the loanword 「ダンス」, which you'd use for modern styles. To recap, a foot radical for moving your feet, the native verb for dancing.",
    ja: "{友だち|ともだち}と[踊りました|おどりました|おどる]。",
    en: "I danced with my friends." },
  "ピアノをひく|ピアノを弾く": {
    explain: "Two pieces here. 「ピアノ」 comes from Italian pianoforte, shortened just like piano in English. The sounds fit into Japanese easily. The verb is 「弾く|ひく」. The kanji 「弾|ひ」 has 「弓|ゆみ」, a bow, on its left side, the kind of bow used to shoot arrows. Plucking a bowstring is a good image to hold onto, and this verb covers playing instruments where you pluck, strike, or press: piano, guitar, violin. Here it takes its native reading. With its Chinese-origin reading 「だん」, the same kanji means a bullet, something shot out, which fits the bow image too. The big mistake for English speakers is using 「する」 or 「あそぶ」 for play. For instruments you pluck or press, Japanese uses this specific verb. Wind instruments, like the flute, use 「吹く|ふく」, to blow, instead. Be careful too, because another 「ひく」, written differently, means to pull, which is the one in 「かぜをひく」, to catch a cold. They sound the same but are unrelated. A way to remember it: a pianist pressing keys like plucking strings. To recap, the plucking verb for playing the piano.",
    ja: "{毎日|まいにち}[ピアノを弾きます|ピアノをひきます|ピアノをひく]。",
    en: "I play the piano every day." },
  "ギター|": {
    explain: "This loanword comes from English guitar, which itself came from Spanish guitarra. Look at how the sound was squeezed into Japanese. The g and the i become 「ギ」. The t sound becomes 「タ」. And the er at the end, which many English speakers hardly pronounce, turns into a long a sound, written with the long line, 「ー」. That is a very common pattern. Lots of English words ending in er do the same thing, like 「コンピューター」, computer. An electric guitar is 「エレキギター」, from electric, shortened. For playing it, Japanese doesn't use 「する」. You use 「弾く|ひく」, to pluck, the same verb as for the piano. So I play the guitar is 「ギターを弾きます|ギターをひきます」. A guitar is a 「楽器|がっき」, musical instrument. That word shares the kanji 「楽|がく」 with 「音楽|おんがく」, music. 「楽|がく」 is music or fun, and 「器|き」 is a tool or vessel, so an instrument is a music tool. To recap, English guitar with a long vowel at the end, played with 「弾く|ひく」.",
    ja: "{兄|あに}は[ギター]を{弾きます|ひきます}。",
    en: "My older brother plays the guitar." },
  "くすりをのむ|薬を飲む": {
    explain: "Break it apart. 「薬|くすり」 is medicine, with its native reading. Look at its shape. On top is the grass radical, the little pair of crosses that marks plants, like in 「花|はな」, flower. Under it is 「楽|らく」, the same kanji that means music in 「音楽|おんがく」 and fun in 「楽しみ|たのしみ」. A way to remember it: plants that make you feel at ease. In the old days, most medicine really did come from herbs and plants. The second part is 「飲む|のむ」, to drink, which you know from 「飲み物|のみもの」, drinks. Here is the twist for English speakers. In English you take medicine. In Japanese you always drink it, even if it is a pill or a powder, because you swallow it with water. So never use 「とる」 for medicine. Say 「薬を飲みます|くすりをのみます」. You will also see 「薬局|やっきょく」, pharmacy, where the kanji uses its Chinese-origin reading 「やっ」. To recap, a plant kanji for medicine, and you drink it rather than take it.",
    ja: "{朝|あさ}[薬を飲みます|くすりをのみます|くすりをのむ]。",
    en: "I take medicine in the morning." },
  "かぜをひく|風邪をひく": {
    explain: "Break it apart. 「風邪|かぜ」 is written with two kanji. The first, 「風|かぜ」, means wind, and on its own it is read 「かぜ」 too. You see it with its Chinese-origin reading 「ふう」 in 「台風|たいふう」, typhoon. The second kanji, 「邪|じゃ」, means evil or wicked. So a cold is literally an evil wind. This comes from traditional Chinese medicine, which taught that harmful winds could blow into the body and make you sick. The whole pair is simply read as 「かぜ」, the same sound as wind, so context tells you which one is meant. Now the verb. You don't get or catch a cold in Japanese. You 「ひく」 one, which in this sense means to pull or draw in. Picture yourself drawing that evil wind into your body. So I caught a cold is 「風邪をひきました|かぜをひきました」. Don't mix this 「ひく」 up with 「弾く|ひく」, to play the piano. Same sound, different word. To recap, an evil wind, and you pull it in.",
    ja: "{昨日|きのう}[風邪をひきました|かぜをひきました|かぜをひく]。",
    en: "I caught a cold yesterday." },
  "とり|鳥": {
    explain: "The kanji 「鳥|とり」 is a real picture of a bird, and you can still see it. At the top is the head, with a little stroke for the eye. In the middle is the body and folded wings. And the four dots at the bottom are the tail feathers and feet. Here it uses its native reading, 「とり」. With its Chinese-origin reading 「ちょう」 it appears in more advanced words. A neat detail is that the four dots also show up in other kanji, like the bottom of the kanji for horse, so you may start to recognize them as legs. This word means bird in general, but in Japanese food it often means chicken, too. 「焼き鳥|やきとり」, grilled chicken on skewers, is a classic snack at bars and summer festivals. So if you see this kanji on a menu, think chicken. When there is a bird in a tree, use 「いる」 for it, since it is alive and moves on its own, not 「ある」. To recap, a picture of a bird, and on menus, chicken.",
    ja: "{木|き}の{上|うえ}に[鳥|とり]がいます。",
    en: "There is a bird in the tree." },
  "おぼえる|覚える": {
    explain: "Look at the kanji 「覚|おぼ」. The bottom part is 「見|み」, to see, the eye on legs from 「見る|みる」. The top part is a crown-like shape with three little strokes. A way to remember it: picture seeing something again and again until it sticks in your head, like drilling flashcards. In this verb the kanji uses its native reading, 「おぼ」. It is a ru-verb, so the polite form is 「覚えます|おぼえます」. One subtle point for English speakers. This verb is about the act of memorizing, committing something to memory. To say I remember right now, Japanese uses the te-iru form, 「覚えています|おぼえています」, meaning I have it memorized and still hold it. And to say I forgot, you'd use a different verb altogether. The same kanji also appears in the phrase 「目が覚める|めがさめる」, to wake up, literally the eyes become aware. Seeing clearly, waking up, and remembering are all about the mind becoming alert. To recap, a seeing kanji for locking things into memory.",
    ja: "{漢字|かんじ}を[覚えます|おぼえます|おぼえる]。",
    en: "I memorize kanji." },
  "かぶき|歌舞伎": {
    explain: "Break it apart. 「歌|か」 is song, the same kanji as in 「歌|うた」, song, 「歌う|うたう」, to sing, and 「歌手|かしゅ」, singer. 「舞|ぶ」 is dance, especially graceful stage dance. 「伎|き」 is skill or art. All three use Chinese-origin readings here. Song, dance, skill: a perfect description of Japan's classic stage theater. But here is the anecdote. The name actually came first, from an old verb 「かぶく」, which meant to lean, and then to act wild, flashy, and outrageous. The kanji were chosen later to fit the sound, and they happened to describe the art beautifully. Kabuki began around the year sixteen hundred, started by a woman performer named Okuni in Kyoto. Later, women were banned from the stage, so today all the roles, even female ones, are played by men. Shows are famous for bold red and white makeup, dramatic poses, and audience members shouting actors' names at key moments. To recap, song plus dance plus skill, written over an older word for wild.",
    ja: "{友だち|ともだち}と[歌舞伎|かぶき]を{見ました|みました}。",
    en: "I saw kabuki with a friend." },
  "いぬ|犬": {
    explain: "Here the kanji takes its native Japanese reading. In compound words it switches to the Chinese-origin reading, 「けん」. Look at the shape. It is almost exactly 「大|だい」, the kanji for big that you know from 「大学|だいがく」 and 「大きい|おおきい」, with one extra dot up in the top right. A way to remember it: picture a big dog with one ear perked up. That dot is the ear. Be careful with a close cousin. 「太る|ふとる」, to gain weight, also starts from 「大|だい」, but its dot sits low, inside the legs. Dot up high, dog. Dot down low, getting fat. The dog kanji also lives on inside other kanji. Squeezed down onto the left side, it becomes a narrow animal mark, and you can see it in 「猫|ねこ」, cat. For counting dogs, use the small animal counter you will meet later, 「〜ひき」. A cultural note: Japan's most famous dog is 「ハチ公|ハチこう」, who waited at 「渋谷|しぶや」 station for his owner every day for years. There is a statue of him there, and it is a classic meeting spot. So the recap: big plus a perked-up ear makes a dog.",
    ja: "{毎日|まいにち}[犬|いぬ]と{公園|こうえん}にいきます。",
    en: "I go to the park with my dog every day." },
  "ねこ|猫": {
    explain: "This is the native Japanese reading. The Chinese-origin reading, 「びょう」, shows up only in rarer compound words. Break the kanji in two. The left side is the animal mark, a squeezed-down form of 「犬|いぬ」, dog. Lots of animal kanji carry it. The right side is 「苗|びょう」, which means a seedling. It isn't there for its meaning. It is there for its sound, and that is where the Chinese-origin reading comes from. A way to remember it: the Chinese word for cat sounds a lot like a meow, so think of the right side as the meow, and the left side as the label that says this is an animal. A cultural note: in many Japanese shops you will see the 「招き猫|まねきねこ」, the beckoning cat statue with one paw raised. It is supposed to wave in customers and good luck. Like dogs, cats are counted with 「〜ひき」, the counter for small animals. Recap: animal mark on the left, meow sound on the right, and you have a cat.",
    ja: "[猫|ねこ]はいすのうえにいます。",
    en: "The cat is on the chair." },
  "はな|花": {
    explain: "This is the native Japanese reading. The Chinese-origin reading is 「か」. The kanji has two parts. On top are the little marks for grass. That top piece shows up on a huge number of plant kanji, including the 「茶|ちゃ」 of 「お茶|おちゃ」 and the 「菜|さい」 of 「野菜|やさい」, vegetables. Underneath is 「化|か」, which means to change or transform. It gives the kanji its Chinese-origin sound. You will see it again in 「化粧品|けしょうひん」, cosmetics, things that change how you look. A way to remember it: a plant that changes, as a tight bud turns into a bloom. Watch out for a sound twin. 「鼻|はな」, nose, is also said this way. Context almost always makes it clear. A cultural note: in spring, people gather under cherry trees for 「花見|はなみ」, flower viewing, with picnics and drinks. Recap: grass on top, change underneath. A plant that blooms is a flower.",
    ja: "{公園|こうえん}に[花|はな]がたくさんあります。",
    en: "There are lots of flowers in the park." },
  "こうえん|公園": {
    explain: "Both kanji here use their Chinese-origin readings, which is typical for two-kanji words. 「公|こう」 means public or official, belonging to everyone rather than to one person. 「園|えん」 means a garden or a fenced-in plot of grounds. Notice the big box around the outside of the kanji. That box is a real piece that often marks an enclosure. Put them together and a public garden, open to everybody, is a park. The garden kanji has a sibling you will meet in Lesson 10. 「動物園|どうぶつえん」 is a zoo, literally a garden of moving things, animals. Same 「園|えん」, same idea of an enclosed space. A cultural note: a Japanese park can be a huge green space like 「上野公園|うえのこうえん」 in 「東京|とうきょう」, but it can also be a tiny neighborhood lot with a swing, a slide and a sandbox. Both are called this. Recap: public plus garden equals park.",
    ja: "{日曜日|にちようび}に[公園|こうえん]で{本|ほん}をよみました。",
    en: "I read a book in the park on Sunday." },
  "おてら|お寺": {
    explain: "「寺|てら」 is a Buddhist temple, using its native reading. The 「お」 in front is the polite prefix, which people almost always add when talking about temples in everyday speech. In names of famous temples you will hear the Chinese-origin reading, 「じ」, instead. The Golden Pavilion in 「京都|きょうと」 is 「金閣寺|きんかくじ」. Don't mix this up with 「神社|じんじゃ」, a Shinto shrine, which you will meet in Lesson 11. A handy rule: temples are Buddhist, with monks, incense and statues of the Buddha. Shrines are Shinto, with the big red gates. The temple kanji is also a building block inside other kanji you know, usually on the right side. In 「時|とき」, time, it sits next to the sun. In 「待つ|まつ」, to wait, and 「持つ|もつ」, to hold, it sits beside another part. In those kanji it mainly helps with the sound. Recap: polite prefix plus temple, and if you spot this shape on the right of a kanji, you are seeing the temple piece.",
    ja: "{京都|きょうと}で[お寺|おてら]を{見ました|みました}。",
    en: "I saw a temple in Kyoto." },
  "ぎんこう|銀行": {
    explain: "Both kanji use Chinese-origin readings. 「銀|ぎん」 means silver. Its left side is the metal mark, which comes from 「金|きん」, gold or metal. That is the same kanji as in 「お金|おかね」, money, and 「金曜日|きんようび」, Friday. 「行|こう」 is the kanji you know from 「行く|いく」, to go. But here it has an older meaning. In Chinese, this character also meant a trading firm or a merchant guild. So a silver firm, a business that deals in money, is a bank. The word was put together in the 1800s, when Japan needed a term for Western-style banks. The same reading 「行|こう」 appears in 「旅行|りょこう」, travel, though there it keeps its everyday meaning of going. A tip for life in Japan: banks often close mid-afternoon on weekdays, but cash machines at convenience stores and post offices run much longer. Recap: silver plus firm. A money business is a bank.",
    ja: "[銀行|ぎんこう]は{九時|くじ}からです。",
    en: "The bank opens at nine." },
  "ゆうびんきょく|郵便局": {
    explain: "All three kanji use Chinese-origin readings. 「郵|ゆう」 and 「便|びん」 together make 「郵便|ゆうびん」, mail. 「郵|ゆう」 carries the idea of sending messages. 「便|びん」 carries the idea of a delivery or a service. You already know 「便|べん」 from 「便利|べんり」, convenient, in Lesson 7. Same kanji, a slightly different reading. The shared idea is something that makes life easier, which is what a postal service does. 「局|きょく」 means a bureau or an office, a place that handles one kind of public business. So the mail bureau is the post office. A cultural note: look for the red symbol that looks like a capital T with an extra bar on top. That is the postal mark, and you will see it on post offices, mailboxes and even before postal codes on envelopes. Japan's post offices also offer banking, so people go there to pay bills and save money too. Recap: mail plus bureau equals post office.",
    ja: "[郵便局|ゆうびんきょく]で{手紙|てがみ}をだしました。",
    en: "I mailed a letter at the post office." },
  "きっさてん|喫茶店": {
    explain: "Three Chinese-origin readings, one of them unusual. 「喫|きっ」 means to take in, to drink, or to smoke. The mouth mark on its left side fits that idea. 「茶|さ」 is tea. Normally this kanji is read 「ちゃ」, as in 「お茶|おちゃ」 and 「紅茶|こうちゃ」. Here it uses an older reading, 「さ」, which survives in a few set words. 「店|てん」 is shop. You will meet it on its own in Lesson 13 with its native reading, 「店|みせ」. So a tea-drinking shop is a cafe. A cultural note: this word has a nostalgic, old-school feel. Picture a dim room with wood paneling, a coffee master pouring slow drip coffee, jazz playing, and a morning set of thick toast and a boiled egg. For a bright modern place, people say 「カフェ」 instead, a loanword from French. Recap: drink plus tea plus shop. The classic Japanese coffee house.",
    ja: "[喫茶店|きっさてん]でコーヒーをのみました。",
    en: "I drank coffee at a cafe." },
  "スーパー|": {
    explain: "This comes from the English word supermarket, and then Japanese chopped it short. Japanese loves to clip long loanwords down to their first few sounds. Listen to how the sounds were squeezed. The long vowel in super became a stretched sound, and the er at the end, with its r sound, simply turned into a long vowel too. English r sounds at the end of a syllable usually vanish like that in Japanese. So in Japanese, this word on its own means a supermarket, not super as in great. Super as a prefix still exists, as in Superman, but if you say you are going to the 「スーパー」, everyone knows you mean the grocery store. Its neighbor 「デパート」, department store, was clipped the same way. So was the convenience store, 「コンビニ」. A tip: many Japanese supermarkets mark down bento boxes and prepared food in the evening, with discount stickers, so the hour before closing is popular. Recap: supermarket, trimmed down to its first half.",
    ja: "[スーパー]で{肉|にく}をかいました。",
    en: "I bought meat at the supermarket." },
  "デパート|": {
    explain: "This comes from the English department store, chopped down to just the first part, department, and then trimmed again. Here is how the sounds got squeezed. Each consonant gets a vowel after it, so de and pa come out clearly. The ar sound, with its r, becomes a long vowel. And the final t picks up an extra o sound, which is what Japanese usually does with a t at the end. A fun thing for English speakers: in English, depart means to leave. In Japanese, this word only ever means the big store. A cultural note: Japanese department stores are famous for their basement food halls, called 「デパ地下|デパちか」. The second half, 「地下|ちか」, means underground. You will see the same kanji in 「地下鉄|ちかてつ」, the subway, an underground iron road. Down there you will find beautiful sweets, bento, and free samples. Gift-wrapping upstairs is an art form too. Recap: department store, clipped to department, and then squeezed into Japanese sounds.",
    ja: "[デパート]で{時計|とけい}をかいました。",
    en: "I bought a watch at the department store." },
  "ゲーム|": {
    explain: "This comes from the English word game. Look at how the sounds changed. The English vowel in game, a sliding ay sound, became a long e sound in Japanese. And the final m picked up a u sound, because Japanese syllables like to end on a vowel. In Japanese, this word covers video games most of all, plus board games and card games. Ask a Japanese friend if they like these, and they will probably think of a game console first. A common mistake: in English we say we watched a baseball game. In Japanese, a sports match is usually 「試合|しあい」, which you will learn in Lesson 12. This loanword is more for things you play for fun. A cultural note: an arcade is a 「ゲームセンター」, a game center, often clipped to 「ゲーセン」. Big ones in 「秋葉原|あきはばら」 have floors of claw machines, rhythm games and photo booths. To say you play, use 「する」 or 「やる」 after the word. Recap: English game, with a long vowel and a u on the end.",
    ja: "{友だち|ともだち}と[ゲーム]をしました。",
    en: "I played games with my friend." },
  "アルバイト|": {
    explain: "This loanword comes from German, not English. The German word Arbeit simply means work. The sounds were squeezed into Japanese in a neat way. The ar became two syllables, with the r sound turning into a 「ル」. The bei part stayed close to the German. And the final t picked up an o sound, which is typical for a t at the end of a word. The meaning also shifted. In German it means any work. In Japanese it narrowed to a part-time job, especially the kind students do, like working at a convenience store or a restaurant. In casual speech it gets clipped to 「バイト」. You will hear students say they have 「バイト」 tonight. Compare 「仕事|しごと」, from Lesson 1, which is a general word for a job or work. A full-time career is 「仕事|しごと」. Shifts at the cafe to pay rent are this word. To say you work part-time, add 「する」 after it. Recap: German for work, narrowed in Japanese to a part-time job.",
    ja: "{土曜日|どようび}に[アルバイト]をします。",
    en: "I work my part-time job on Saturdays." },
  "かいもの|買い物": {
    explain: "Two kanji, both with native Japanese readings. 「買|か」 is the start of 「買う|かう」, to buy. Look at the bottom of the kanji. That piece is 「貝|かい」, a shell. In ancient China, shells were used as money, so the shell mark often appears in kanji about money and value. It also sits on the left of 「財|さい」 in 「財布|さいふ」, wallet. 「物|もの」 means thing. You know it from 「食べ物|たべもの」, food, things to eat, and 「飲み物|のみもの」, drinks, things to drink. In some other words it switches to its Chinese-origin reading, like the 「物|ぶつ」 of 「動物園|どうぶつえん」, zoo. Put them together: buying things. That is shopping. To use it, say you go shopping, with 「に行く|にいく」 after the word, or say you do shopping with 「する」 after it. Notice the pattern of verb stem plus thing. Buying things, eating things, drinking things. Once you see it, you can guess these words on sight. Recap: buy plus thing equals shopping.",
    ja: "{母|はは}と[買い物|かいもの]にいきました。",
    en: "I went shopping with my mother." },
  "クラス|": {
    explain: "This comes from the English word class. Here is how the sounds were squeezed. English cl starts with two consonants together, and Japanese can't do that, so a little u sound slips in after the k. The l becomes a Japanese r sound, as always. And the final s picks up a u sound too. The meaning is mostly the same as English: a group of students who study together, or a level, as in a beginner class. It can also mean a rank or grade, as in top class. A common mistake: when you mean the actual lesson or lecture period, Japanese often uses 「授業|じゅぎょう」, which you will meet in Lesson 11. So your class, meaning your classmates, can be fun, but the lesson that starts at nine is better called 「授業|じゅぎょう」. A cultural note: in Japanese schools, students in a 「クラス」 often stay together all year in the same homeroom, and the teachers come to them. Recap: English class, with extra vowels tucked in.",
    ja: "[クラス]に{学生|がくせい}が{十人|じゅうにん}います。",
    en: "There are ten students in the class." },
  "ひと|人": {
    explain: "This is the native reading. The Chinese-origin readings are 「じん」 and 「にん」, and you already use both. The kanji began as a picture of a person seen from the side, standing or walking on two legs. It is one of the simplest kanji to recognize. Here is the family. In 「日本人|にほんじん」, a Japanese person, it is 「じん」, used for nationality. For counting people, it is 「にん」, as in three people, 「三人|さんにん」. But one person and two people are special native readings, 「一人|ひとり」 and 「二人|ふたり」. You also have 「男の人|おとこのひと」 and 「女の人|おんなのひと」, man and woman, with the native reading. When this kanji is squeezed onto the left side of another kanji, it becomes a thin standing stroke called the person mark. In 「休み|やすみ」, rest or a day off, you see the person leaning against 「木|き」, a tree. A person resting against a tree. Recap: a stick-figure person, with three readings depending on the job.",
    ja: "あの[人|ひと]は{先生|せんせい}です。",
    en: "That person is a teacher." },
  "あなた|": {
    explain: "This word is usually written in kana. It is the standard textbook word for you, but here is the big surprise for English speakers: Japanese people avoid saying it to someone's face most of the time. Instead, they use the person's name plus 「さん」. So rather than asking are you a student, you would ask if 「田中さん|たなかさん」 is a student, even while talking to that very person. Why? Using this word to someone older or higher in rank can sound distant, a bit cold, or even rude, as if you didn't bother to learn their name. Teachers are called 「先生|せんせい」, not this. There is a twist. Between married couples, a wife traditionally calls her husband this word, and then it means something like dear or honey. You will still see it on forms, ads and song lyrics, where it speaks to everybody at once. A way to remember it: think of it as a word you know but keep in your pocket. Use names first. Recap: it means you, but a name plus 「さん」 is almost always the better choice.",
    ja: "[あなた]は{学生|がくせい}ですか。",
    en: "Are you a student?" },
  "レポート|": {
    explain: "This comes from the English word report. The sounds were squeezed like this. The re stays as a simple syllable. The port part loses its r sound, which becomes a long o instead. And the final t picks up an extra o, which Japanese usually adds after a t at the end. The big meaning shift: in Japanese, this word most often means a student's written assignment, like a term paper or a lab report. If a Japanese university student says they have one due tomorrow, they mean an essay to hand in. A news report on TV is usually 「ニュース」, not this word. Typical verbs: you write one with 「書く|かく」, and you hand one in with 「出す|だす」, which you will learn in Lesson 16. A way to remember it: it is the report you have to give your professor, not the one you watch on the evening news. Recap: English report, squeezed into Japanese sounds and narrowed to a school paper.",
    ja: "{今日|きょう}[レポート]を{書きます|かきます}。",
    en: "I will write a paper today." },
  "ごはん|ご飯": {
    explain: "「飯|はん」 is the main kanji, and here it uses its Chinese-origin reading. Look at the left side of the kanji. It is the food mark, a squeezed version of 「食|しょく」, the kanji in 「食べる|たべる」, to eat. The same food mark sits on the left of 「飲む|のむ」, to drink. The 「ご」 in front is a polite prefix. As a rule of thumb, Chinese-origin words take 「ご」, while native words take 「お」. Rice is so central to Japanese eating that the word for cooked rice also became the word for a meal. That is why you have 「朝ご飯|あさごはん」, breakfast, morning rice, 「昼ご飯|ひるごはん」, lunch, and 「晩ご飯|ばんごはん」, dinner. Even if breakfast is toast, it is still called morning rice. A related word: uncooked rice grains, the kind you buy in a bag, are 「米|こめ」, a different word. Recap: food mark plus the polite prefix. Cooked rice, and by extension, any meal.",
    ja: "{朝|あさ}[ご飯|ごはん]を{食べます|たべます}。",
    en: "I eat a meal in the morning." },
  "パン|": {
    explain: "This is one of the oldest loanwords in Japanese, and it does not come from English. It comes from Portuguese, from the word pão, meaning bread. Portuguese traders and missionaries arrived in Japan in the 1500s, and they brought bread with them. The word stuck long before English loanwords arrived. That is why it is written in katakana but doesn't sound like the English word bread at all. Spanish speakers will also recognize it, since Spanish uses pan too. A fun trap: the frying pan you cook with is 「フライパン」, which comes from English frying pan. Same sound, completely different source, so it has nothing to do with bread. A cultural note: Japanese bakeries are amazing, with sweet buns, curry bread, and melon bread, a sweet bun with a crispy top. A bakery is a 「パン屋|パンや」, using the same shop ending as 「本屋|ほんや」, bookstore. Recap: Portuguese bread, arriving in the 1500s and never leaving.",
    ja: "{朝|あさ}[パン]を{食べます|たべます}。",
    en: "I eat bread in the morning." },
  "バスてい|バス停": {
    explain: "This is a mixed word: a loanword glued to a kanji. The first half is 「バス」, from the English word bus, which you met in Lesson 5. The vowel in bus becomes a short a sound, and a little u is added after the final s. The second half is 「停|てい」, with its Chinese-origin reading. It means to stop or to halt. On its left side is the person mark, the squeezed form of 「人|ひと」. A way to remember it: picture a person standing still under a little roofed shelter, waiting for the bus to halt. Put them together and a bus halt is a bus stop. Compare 「駅|えき」, station, from Lesson 10. Trains stop at a station. Buses stop at this. A cultural note: Japanese bus stops usually have a detailed timetable posted, and buses tend to stick closely to it. On many city buses you get on at the back, take a numbered ticket, and pay at the front when you get off. Recap: bus plus halt equals bus stop.",
    ja: "[バス停|バスてい]で{友だち|ともだち}をまちました。",
    en: "I waited for my friend at the bus stop." },
  "びょういん|病院": {
    explain: "Both kanji use Chinese-origin readings. 「病|びょう」 means illness. Look at the frame around its top and left. That frame is the sickness mark, and you will find it on many kanji about disease and pain. You will meet the same kanji in 「病気|びょうき」, being sick, in Lesson 12. 「院|いん」 means an institution, a large building with a special purpose. You will see it again in 「大学院|だいがくいん」, graduate school, in Lesson 16. So an illness institution is a hospital. Now the famous trap. In Lesson 10 you will learn 「美容院|びよういん」, a hair salon. It shares the same 「院|いん」. The only difference in sound is that this word has a squished 「びょう」, while the salon has two separate beats, 「び」 and 「よう」. Say the wrong one, and you may tell a taxi driver you need a haircut when you need a doctor. A way to remember it: the sick word is squeezed, like someone doubled over. Recap: illness plus institution equals hospital.",
    ja: "{明日|あした}[病院|びょういん]にいきます。",
    en: "I will go to the hospital tomorrow." },
  "ホテル|": {
    explain: "This comes from the English word hotel. The sounds were squeezed in a simple way. Each consonant gets its own vowel, so ho and te come out cleanly. The final l becomes a Japanese r sound with a u after it, because Japanese has no l and likes to end on a vowel. Notice that the stress pattern changes. English leans on the second half of the word, while Japanese gives each beat an even weight. In Japan this word means a Western-style hotel with beds. The traditional Japanese inn, with tatami mats, futons and often hot spring baths, is a 「旅館|りょかん」, which you will learn in Lesson 15. Its first kanji is the 「旅|りょ」 of 「旅行|りょこう」, travel. A cultural note: Japan has some unique styles of this word. A business hotel is small, cheap and efficient, made for people traveling for work. A capsule hotel gives you just a sleeping pod. Recap: English hotel, squeezed into Japanese sounds, and the Western cousin of the 「旅館|りょかん」.",
    ja: "[ホテル]は{駅|えき}のちかくです。",
    en: "The hotel is near the station." },
  "ほんや|本屋": {
    explain: "Two kanji. The first uses its Chinese-origin reading, the second its native reading. 「本|ほん」 is book, from Lesson 1. Its shape is a tree, 「木|き」, with an extra short line across the bottom. That line marks the root, so the kanji originally meant root or origin. Later it came to mean book too. You also see the origin meaning in 「日本|にほん」, the origin of the sun, the land where the sun rises. 「屋|や」 means a shop, and also the person who runs one. It attaches to many things to make shop names. A bakery is a 「パン屋|パンや」. The same kanji, with the same reading, is in 「部屋|へや」, a room, from Lesson 5. So a book shop is a bookstore. A cultural note: big Japanese bookstores have whole floors of manga, and many people stand and browse for ages. Also, staff will often offer to wrap your book in a paper cover, so nobody on the train can see what you are reading. Recap: book plus shop equals bookstore.",
    ja: "[本屋|ほんや]で{日本語|にほんご}の{本|ほん}をかいました。",
    en: "I bought a Japanese book at the bookstore." },
  "まち|町": {
    explain: "This is the native reading. The Chinese-origin reading is 「ちょう」, which you will see in many addresses and place names. The kanji has two parts. On the left is 「田|た」, a rice field, which really does look like a field divided into four plots. On the right is a simple piece that gives the kanji its Chinese-origin sound. A way to remember it: picture rice fields with a straight road running beside them, and houses popping up along that road. That is how a town grows. In meaning, this word covers both a small town and a part of a city where people live and shop. You can say you go out into town, meaning downtown. Another kanji with the same native reading is used for busy shopping streets, but this one is the everyday choice for a town. A tip on addresses: in Japan, the address often names a district ending in 「〜町|〜ちょう」, so if you see that ending on a map, you know it is a neighborhood name. Recap: a field with a road beside it, growing into a town.",
    ja: "この[町|まち]はしずかです。",
    en: "This town is quiet." },
  "レストラン|": {
    explain: "This comes from English restaurant, which English itself borrowed from French. Here is how the sounds were squeezed. The re stays simple. The st in the middle is two consonants in a row, which Japanese can't do, so each gets its own vowel: a 「ス」 and then a 「ト」. The r in the middle becomes a Japanese r sound, the vowel turns into a plain a, and the word ends with the 「ン」 sound. The final t of the English word disappears entirely, much like in the French pronunciation. In Japan, this word tends to suggest a sit-down place with a menu, often Western-style food. Other eating places have their own words. A cafeteria at a school or company is a 「食堂|しょくどう」, which you will learn in Lesson 7. A general word for a shop, including small eateries, is 「店|みせ」. A cultural note: a very common type is the 「ファミレス」, short for family restaurant, a casual chain with big picture menus and a drink bar where you refill your own drinks. Many restaurants also show plastic food models in the window, so you can point at what you want. Recap: English restaurant, with vowels added and the final t dropped.",
    ja: "{駅|えき}のちかくの[レストラン]で{食べました|たべました}。",
    en: "I ate at a restaurant near the station." },
  "きのう|昨日": {
    explain: "This word has a special reading. The kanji are chosen for meaning, but the whole word is read as one native unit, not piece by piece. 「昨|さく」 means previous or last, and 「日|にち」 is the sun or day. So previous day, yesterday. Notice that 「昨|さく」 has its own little sun on the left side too. In formal speech, like news or business letters, people use the Chinese-origin reading, 「昨日|さくじつ」, with the same two kanji. This word has two famous siblings with the same trick. 「今日|きょう」, today, and 「明日|あした」, tomorrow, are also special readings that you can't build from the pieces. So yesterday, today and tomorrow are a little trio of exceptions. Learn them as whole words. Usage tip: like other time words such as today and tomorrow, this word usually doesn't take the particle 「に」. You just say yesterday I went, with no particle after it. Recap: previous plus day, read as a single special word.",
    ja: "[昨日|きのう]{映画|えいが}を{見ました|みました}。",
    en: "I saw a movie yesterday." },
  "〜じかん|〜時間": {
    explain: "Both kanji use Chinese-origin readings. 「時|じ」 is time or hour. On its left side is 「日|ひ」, the sun, and on its right is 「寺|じ」, temple, which supplies the sound. You know this kanji from 「〜時|〜じ」, o'clock, and from 「時計|とけい」, watch, where it takes a different reading. 「間|かん」 means an interval, a space between. Look at its shape: 「門|もん」, a gate, with 「日|ひ」, the sun, inside. A way to remember it: sunlight shining through the gap in a gate. You will see the native reading of this kanji in 「この間|このあいだ」, the other day, in Lesson 16. So a time interval, a span of time, is a number of hours. Here is the most common mistake. 「三時|さんじ」 is three o'clock, a point on the clock. Add this ending and 「三時間|さんじかん」 is three hours, a length of time. Point versus length. Watch the number readings: four hours is 「四時間|よじかん」, and nine hours is 「九時間|くじかん」. Recap: hour plus interval equals hours, a length of time.",
    ja: "{毎日|まいにち}[三時間|さんじかん|〜じかん]{勉強|べんきょう}します。",
    en: "I study for three hours every day." },
  "いちじかん|一時間": {
    explain: "This is the hours counter with the number one in front. 「一|いち」 is the Chinese-origin reading of one, and the kanji is just one stroke. Easy. Then comes 「時間|じかん」. 「時|じ」 means hour, and 「間|かん」 means an interval, a space between. Together they mean a span of time. So one span of an hour is one hour. The big trap is with 「一時|いちじ」, without the ending. That is one o'clock, a point on the clock. If you say you will wait for 「一時|いちじ」, you mean until one o'clock. If you say you will wait for this word, you mean for sixty minutes. Handy add-ons. An hour and a half is 「一時間半|いちじかんはん」, using 「半|はん」, half, from Lesson 1. About an hour is 「一時間ぐらい|いちじかんぐらい」, using the word for about that you learn in this same lesson. You also have the same pattern with weeks later on: 「一週間|いっしゅうかん」 is one week. Recap: one plus hours, a length of time, not the time on the clock.",
    ja: "[一時間|いちじかん]テレビを{見ました|みました}。",
    en: "I watched TV for one hour." },
  "せんしゅう|先週": {
    explain: "Both kanji use Chinese-origin readings. 「先|せん」 means ahead, or before, earlier. You know it from 「先生|せんせい」, teacher, literally someone born before you, someone who has gone ahead. 「週|しゅう」 means week. On its left and bottom is the movement mark, a little road, which shows up in kanji about moving and going round. A week goes round and round. So the week before is last week. This kanji has a whole family. 「今週|こんしゅう」 is this week and 「来週|らいしゅう」 is next week, both from Lesson 6. 「毎週|まいしゅう」 is every week, and 「週末|しゅうまつ」 is the weekend, the week's end, from Lesson 3. The same pattern partly works with months: 「今月|こんげつ」 is this month and 「来月|らいげつ」 is next month. But be careful with years. Last year is a different word, 「去年|きょねん」, not built this way. Like most time words, this one usually takes no 「に」 after it. Recap: before plus week equals last week.",
    ja: "[先週|せんしゅう]{京都|きょうと}にいきました。",
    en: "I went to Kyoto last week." },
  "とき|時": {
    explain: "This is the native reading of the time kanji. In compound words it uses its Chinese-origin reading, 「じ」. The shape: 「日|ひ」, the sun, on the left, and 「寺|じ」, temple, on the right. The sun tells you it is about time, and the temple part gives the Chinese-origin sound. As a word on its own, it means time, but its biggest job is as a grammar word meaning when. You put a description in front of it. For example, 「子供の時|こどものとき」 means when I was a child, literally the time of being a child. Later in Genki you will use it after verbs and adjectives, like when I am busy, or when I went to Japan. A common mistake: English speakers try to use it like the question word when. But to ask when, you use 「いつ」, from Lesson 3. This word only works in the middle of a sentence, explaining the time of something. Its family: 「時々|ときどき」, sometimes, is this same native reading doubled. And 「時間|じかん」 and 「時計|とけい」 use other readings of the same kanji. Recap: sun plus temple, the time when something happens.",
    ja: "{子供|こども}の[時|とき]、{犬|いぬ}がいました。",
    en: "When I was a child, I had a dog." },
  "げつようび|月曜日": {
    explain: "All three kanji use Chinese-origin readings. 「月|げつ」 is the moon. The kanji began as a picture of a crescent moon. On its own it is read 「月|つき」 natively. 「曜|よう」 is the kanji for days of the week. It has 「日|ひ」, the sun, on its left side and carries the idea of shining. The days of the week were named after shining things in the sky. 「日|び」 is day. The sound softens to 「び」 here. So moon day is Monday, exactly like English, where Monday also comes from moon day. Here is the system. The seven days are named after the sun, the moon, and the five planets visible to the naked eye, whose Chinese names come from the five elements: fire, water, wood, metal and earth. You already know 「日曜日|にちようび」, sun day, and 「土曜日|どようび」, earth day, which is Saturn. The moon reading 「げつ」 also appears in 「今月|こんげつ」 this month and 「来月|らいげつ」 next month, since months follow the moon. Recap: moon plus shining plus day equals Monday.",
    ja: "[月曜日|げつようび]にテストがあります。",
    en: "There is a test on Monday." },
  "かようび|火曜日": {
    explain: "All three kanji use Chinese-origin readings. 「火|か」 means fire. The kanji began as a picture of flames rising up, and it still looks like a little campfire with sparks flying out of each side. On its own, it is read natively as 「火|ひ」. 「曜|よう」 is the day-of-the-week kanji, about shining things in the sky. 「日|び」 is day. So fire day is Tuesday. Why fire? The planet Mars has the Chinese name fire star, 「火星|かせい」, and its red color fits that name nicely. Tuesday is the day of Mars, and in languages like French and Spanish it is still named after Mars. English Tuesday comes from a Norse god of war, which matches Mars, the Roman god of war. So the whole week lines up: Monday is the moon, Tuesday is fire, which is Mars, and so on through the planets. A way to remember it: Tuesday is the fiery red planet day. Recap: fire plus shining plus day equals Tuesday.",
    ja: "[火曜日|かようび]に{日本語|にほんご}のクラスがあります。",
    en: "I have Japanese class on Tuesday." },
  "すいようび|水曜日": {
    explain: "All three kanji use Chinese-origin readings. 「水|すい」 means water. The kanji began as a picture of flowing water, with a main stream in the middle and splashes on either side. On its own, natively, it is 「水|みず」, which you learned in Lesson 3. 「曜|よう」 is the day-of-the-week kanji, and 「日|び」 is day. So water day is Wednesday. The planet behind it is Mercury, whose Chinese name is water star, 「水星|すいせい」. In French and Spanish, Wednesday is still named after Mercury. The water kanji has a squeezed form too. On the left side of a kanji, it becomes three little drops. You can see those drops in 「海|うみ」, sea, 「泳ぐ|およぐ」, to swim, and 「洗う|あらう」, to wash. Everything wet. A way to remember it: Wednesday is the middle of the week, and you need a drink of water to get through it. Recap: water plus shining plus day equals Wednesday.",
    ja: "[水曜日|すいようび]にプールでおよぎます。",
    en: "I swim in the pool on Wednesday." },
  "もくようび|木曜日": {
    explain: "All three kanji use Chinese-origin readings. 「木|もく」 means tree or wood. The kanji began as a picture of a tree, with a trunk, branches spreading at the top, and roots at the bottom. On its own, natively, it is read 「木|き」. 「曜|よう」 is the day-of-the-week kanji, and 「日|び」 is day. So wood day is Thursday. The planet behind it is Jupiter, whose Chinese name is wood star, 「木星|もくせい」. In French and Spanish, Thursday is still named after Jupiter. English Thursday comes from Thor, the Norse god of thunder, who was matched with Jupiter. The tree kanji is a building block you already know. 「本|ほん」, book, is a tree with a line marking the root. 「休み|やすみ」, rest, is a person leaning on a tree. Be careful not to mix up 「木|もく」 Thursday and 「金|きん」 Friday, since both are near the weekend. Wood comes first, then gold. Recap: tree plus shining plus day equals Thursday.",
    ja: "[木曜日|もくようび]は{忙しい|いそがしい}です。",
    en: "I'm busy on Thursday." },
  "きんようび|金曜日": {
    explain: "All three kanji use Chinese-origin readings. 「金|きん」 means gold, and more broadly metal. On its own, natively, it is 「金|かね」, the money word you know from 「お金|おかね」. It also shows up squeezed onto the left side of metal kanji, like 「銀|ぎん」, silver, in 「銀行|ぎんこう」, bank. 「曜|よう」 is the day-of-the-week kanji, and 「日|び」 is day. So gold day is Friday. The planet behind it is Venus, whose Chinese name is metal star, 「金星|きんせい」. In French and Spanish, Friday is still named after Venus. A fun bit of slang: people sometimes call Friday night 「花金|はなきん」, short for flower Friday, the night the week blooms into the weekend. It is like saying thank goodness it's Friday. A way to remember it: Friday is payday in many places. Gold, money, Friday. Recap: gold plus shining plus day equals Friday.",
    ja: "[金曜日|きんようび]に{友だち|ともだち}と{出かけます|でかけます}。",
    en: "I go out with friends on Friday." },
  "あう|会う": {
    explain: "This uses the native reading of 「会|かい」. In compounds it takes the Chinese-origin reading, 「かい」. The kanji means to meet or to gather. You already know the Chinese-origin reading from 「会社|かいしゃ」, a company, literally a gathering of people working together, and 「会社員|かいしゃいん」, office worker. Now the most important grammar point. You meet a person with the particle 「に」, not 「を」. So you say you meet 「友だちに|ともだちに」, to your friend. English speakers often use 「を」 because meet takes a direct object in English. In Japanese, think of it as going toward someone for a meeting. It is an u-verb, so the polite form is 「会います|あいます」, and the te-form is 「会って|あって」. Also note: this verb is for meeting or seeing people. For seeing a movie or a thing, use 「見る|みる」. If you say you will see a friend tomorrow, use this verb. A useful phrase: 「また会いましょう|またあいましょう」 means let's meet again, a friendly way to say goodbye. Recap: gather and meet, with 「に」 for the person you meet.",
    ja: "{昨日|きのう}{友だち|ともだち}に[会いました|あいました|あう]。",
    en: "I met a friend yesterday." },
  "ある|": {
    explain: "This is the verb for the existence of things that don't move by themselves: objects, buildings, plants and events. It is usually written in kana. The pattern is: place, then 「に」, then the thing, then 「が」, then this verb. For example, there is a book on the desk. Its partner, 「いる」, which you learn in this same lesson, is for people and animals. A handy test: can it walk away on its own? Then use 「いる」. If not, use this one. A tree, a car, or a building takes this word. It also covers having things. If you have time, you say time exists. If you have a fever, 「熱がある|ねつがある」, from Lesson 12, a fever exists. And events too: there is a party on Saturday, using this verb. Conjugation: the polite form is 「あります」. The negative is irregular. It is just 「ない」, with nothing in front. A way to remember it: things that just are, sitting still, take this word. Recap: there is, for objects, plants and events, and for having things.",
    ja: "{机|つくえ}のうえに{本|ほん}が[あります|あります|ある]。",
    en: "There is a book on the desk." },
  "かう|買う": {
    explain: "This uses the native reading of the kanji. In compounds, the Chinese-origin reading is 「ばい」. Look at the bottom of the kanji. That piece is 「貝|かい」, a shell. In ancient China, shells were used as money, so the shell mark appears in many kanji about money and value. It also sits on the left of 「財|さい」 in 「財布|さいふ」, wallet, where you keep your money. The family: the noun 「買い物|かいもの」, shopping, literally buying things, comes straight from this verb's stem. It is an u-verb. The polite form is 「買います|かいます」, and the te-form is 「買って|かって」, with a small pause. You buy something with 「を」, and where you buy it takes 「で」. So at the supermarket, I buy bread. A sound trap: in Lesson 11 you will learn 「飼う|かう」, to keep a pet. Same sound, different kanji. You buy a dog with this verb, and then you keep it with the other one. Recap: shell money underneath. To buy.",
    ja: "スーパーで{肉|にく}を[買いました|かいました|かう]。",
    en: "I bought meat at the supermarket." },
  "かく|書く": {
    explain: "This uses the native reading of the kanji. In compounds, the Chinese-origin reading is 「しょ」, and you already know several of those words. Look at the top of the kanji. That piece is a hand holding a brush, a real part that appears in kanji about writing. A way to remember the whole thing: picture that hand and brush hovering over a sheet of paper, mid-stroke. Now the family, all with 「しょ」. 「図書館|としょかん」, library, a building of drawings and writing. 「辞書|じしょ」, dictionary, a book of words. 「教科書|きょうかしょ」, textbook, from Lesson 6. And later, 「履歴書|りれきしょ」, a résumé, in Lesson 14. Whenever you spot this kanji, think of writing. It is an u-verb. The polite form is 「書きます|かきます」, and the te-form is 「書いて|かいて」. The thing you write takes 「を」, like a letter, and the person you write to takes 「に」. A sound trap: in Lesson 15 you will meet 「描く|かく」, to draw or paint. Same sound, different kanji. Words take this one, pictures take the other. Recap: a hand with a brush. To write.",
    ja: "{手紙|てがみ}を[書きました|かきました|かく]。",
    en: "I wrote a letter." },
  "とる|撮る": {
    explain: "This uses the native reading. The Chinese-origin reading, 「さつ」, appears in words about filming and photography. On the left side is the hand mark, a squeezed form of 「手|て」, hand. It appears in lots of action kanji, like 「持つ|もつ」, to hold, 「払う|はらう」, to pay, and 「探す|さがす」, to look for. On the right is 「最|さい」, the kanji for most. Here is the key idea. The native verb for take has several kanji, and each one picks a different kind of taking. This one is only for photos and video. In Lesson 11 you will meet 「取る|とる」, which is for taking or getting things in general, like taking a class or picking something up. So the standard phrase is 「写真を撮る|しゃしんをとる」, to take a picture. 「写真|しゃしん」 means photo, literally a copy of the truth. It is an u-verb. The polite form is 「撮ります|とります」, and the te-form is 「撮って|とって」. A way to remember it: your hand reaches for the camera button. Recap: hand mark plus a sound part. Take, but only for pictures.",
    ja: "{海|うみ}で{写真|しゃしん}を[撮りました|とりました|とる]。",
    en: "I took pictures at the sea." },
  "まつ|待つ": {
    explain: "This uses the native reading. The Chinese-origin reading is 「たい」. The kanji has two parts. On the left is a mark that looks like a doubled person mark. It is the going mark, often linked to walking and roads. On the right is 「寺|てら」, temple. It mostly helps with the sound here. But it makes a nice hook. A way to remember it: picture yourself walking to the temple gate and waiting for your friend there. The temple piece shows up in kanji you know. 「時|とき」, time, has it on the right, and so does 「持つ|もつ」, to hold. Time, hold and wait all share it. Now the grammar. You wait for someone with 「を」. English uses for, so learners sometimes reach for another particle, but in Japanese the person or thing you wait for is the direct object. So you wait 「友だちを|ともだちを」. It is an u-verb ending in 「つ」. The polite form is 「待ちます|まちます」, and the te-form is 「待って|まって」. A phrase you will hear constantly: 「ちょっと待ってください|ちょっとまってください」, please wait a moment. Recap: walking plus temple, waiting at the gate.",
    ja: "{駅|えき}で{友だち|ともだち}を[待ちました|まちました|まつ]。",
    en: "I waited for my friend at the station." },
  "わかる|": {
    explain: "This verb is often written with kana alone at your level, but its kanji is 「分かる|わかる」. 「分|ぶん」 means to divide or a part. The native verb 「分ける|わける」 means to divide or sort things. The idea behind understanding is that things have been sorted out and separated clearly in your mind. You know the same kanji from 「自分|じぶん」, oneself, a portion that is you, in Lesson 16, and from minutes, which divide an hour. Now the most important grammar point. The thing you understand takes 「が」, not 「を」. So you say 「日本語がわかります|にほんごがわかります」. English speakers often use 「を」, because understand takes a direct object in English. Think of it more like Japanese is clear to me. It is an u-verb. The polite form is 「わかります」. The past form, 「わかりました」, is extremely common. It means understood, or got it, and in a workplace it often means I'll do that. The negative, 「わかりません」, is the polite way to say I don't know or I don't understand. Recap: things divided out clearly in your mind, with 「が」 for what you understand.",
    ja: "{日本語|にほんご}が[わかります|わかります|わかる]。",
    en: "I understand Japanese." },
  "いる|": {
    explain: "This is the verb for the existence of people and animals, things that can move around on their own. It is usually written in kana. The pattern is: place, then 「に」, then the person or animal, then 「が」, then this verb. For example, there is a cat under the chair. Its partner, 「ある」, from this same lesson, is for objects, plants and events. A handy test: can it walk away by itself? Then use this word. People, dogs, fish and birds take it. A tree or a car takes the other one. It also covers having people in your life. If you have a younger sister, you say a younger sister exists, using this verb. It is a ru-verb. The polite form is 「います」, and the negative is 「いません」. Its te-form is 「いて」. A heads-up: in Lesson 7, this verb becomes a helper after the te-form, to say someone is doing something right now, or is in a state. So you will be using it a lot. And a sound trap: in Lesson 8 you will learn another verb with this same sound meaning to need. That one is an u-verb with different endings. Recap: there is, for living things that move on their own.",
    ja: "{教室|きょうしつ}に{先生|せんせい}が[います|います|いる]。",
    en: "The teacher is in the classroom." },
  "〜ぐらい|": {
    explain: "This is a little ending you attach to an amount to mean about or roughly. You put it right after the number and counter. For example, 「一時間ぐらい|いちじかんぐらい」 means about an hour, and you can say about thirty minutes or about ten people the same way. You will also hear it said 「くらい」, with a softer first sound. Both are correct, and they mean the same thing. Now the classic mistake. In Lesson 3 you learned 「〜ごろ」, which also means about. The difference: 「〜ごろ」 is about a point in time, like around three o'clock. This ending is about an amount or a length, like about three hours. So you go to bed around eleven with 「ごろ」, and you sleep about seven hours with this one. A way to remember it: when you measure how much or how long, use this. When you point at the clock, use 「ごろ」. Family: 「どのぐらい」, how long or how much, comes in Lesson 10, and 「このぐらい」, about this much, comes in Lesson 16. Recap: about, for amounts and lengths.",
    ja: "{毎日|まいにち}{二時間|にじかん}[ぐらい|ぐらい|〜ぐらい]{勉強|べんきょう}します。",
    en: "I study about two hours every day." },
  "ごめんなさい|": {
    explain: "This apology has a clear makeup. 「ごめん」 can be written 「御免|ごめん」, a polite prefix plus a kanji meaning pardon or permission. Then 「なさい」 is a soft way of telling someone to do something. So the whole phrase is roughly please grant me pardon. Now the important part: when to use it. This is a warm, personal apology. It is common between friends and family, and it is the word children say to their parents. Shorter and more casual still is just 「ごめん」, which you will meet in Lesson 16. For strangers, shops, teachers or work, people usually say 「すみません」 instead. That word also works as excuse me and even thank you for your trouble. So if you bump into someone on the train, 「すみません」 is the safe choice. In very formal situations, like a company apologizing to customers, you will hear much longer, stiffer phrases. A way to remember it: this one is for people close to your heart. Recap: please pardon me, for friends and family.",
    ja: "[ごめんなさい]、{宿題|しゅくだい}をわすれました。",
    en: "I'm sorry, I forgot my homework." },
  "それから|": {
    explain: "This word is built from two pieces you already know. 「それ」 means that, from Lesson 2. 「から」 means from, or after. So it is literally from that, or after that. It is used to connect events in order, like and then. You usually put it at the start of a new sentence. For example: I ate breakfast. And then I went to school. It can also add one more item to a list, meaning and also, or in addition. A customer ordering food might say coffee, and then, a cake too. Compare some neighbors. 「でも」, from Lesson 3, means but. 「だから」, from this lesson, means so or therefore. And 「そして」, from Lesson 11, also means and then, but feels a little more like written storytelling. A common mistake is to use it to join two nouns, like dogs and cats. For that you need the particle 「と」. This word links sentences and events, not single nouns. A way to remember it: start from that point, and move on to the next thing. Recap: that plus from. After that, and then.",
    ja: "{宿題|しゅくだい}をしました。[それから]、ねました。",
    en: "I did my homework. And then I went to bed." },
  "だから|": {
    explain: "This word is built from two pieces. 「だ」 is the casual form of 「です」, it is. 「から」 means because. So it is literally it is so, because of that. In English, that becomes so, or therefore. You put it at the start of a sentence to show a result. The first sentence gives the reason, and the next one starts with this word. For example: Tomorrow there is a test. So I will study tonight. The polite version is 「ですから」. That sounds more formal, and you will hear it from teachers and in announcements. Compare 「から」 on its own. Inside one sentence, 「から」 goes at the end of the reason. This word starts a new sentence instead. Same idea, different place. A caution: said with a sharp tone, this word can sound like I told you so, or that's why. So in polite speech, keep it gentle, or use 「ですから」. A way to remember it: it is the hinge between the reason and the result. Recap: it is plus because. So, therefore.",
    ja: "あしたはテストです。[だから]、{勉強|べんきょう}します。",
    en: "There's a test tomorrow. So I'll study." },
  "たくさん|": {
    explain: "This word is usually written in kana. It means a lot, and it works for both things you can count, like books, and things you can't, like water or homework. There are two main ways to use it. As an adverb, it comes right before the verb: eat a lot, or study a lot. As a describer, it goes before a noun with 「の」, as in 「たくさんの人|たくさんのひと」, a lot of people. A tip for natural Japanese: the adverb pattern is more common. Instead of saying I have many books, Japanese often says books, a lot, I have. Compare its opposite, 「ちょっと」, from Lesson 3, which means a little. A related word is 「多い|おおい」, many, from Lesson 12. That one is an adjective, so it usually comes at the end, as in people are many. This word comes before the verb or the noun. A way to remember it: picture a big pile of things stacking up higher and higher. Recap: many, much, a lot, for counted things and uncounted things alike.",
    ja: "{公園|こうえん}に{人|ひと}が[たくさん]います。",
    en: "There are a lot of people in the park." },
  "〜と|": {
    explain: "This little particle has two jobs, and both are about putting things together. First job: and, between nouns. 「犬と猫|いぬとねこ」 means dogs and cats. It gives a complete list, meaning exactly these, nothing more. Second job: together with, for people. You put it after a person to show who you do something with. So you go to the movies with a friend by saying 「友だちと|ともだちと」, then the verb. You can make the together idea stronger by adding 「一緒に|いっしょに」, together, from Lesson 5. So with my friend, together, I go. Now the big mistake for English speakers. In English, and joins anything: nouns, verbs, whole sentences. This particle only joins nouns. You can't use it to say I ate and slept, or to join two adjectives. For linking sentences, use words like 「それから」, and then. Verbs and adjectives get their own te-forms later. Compare 「一人で|ひとりで」, alone, from this lesson. Alone, versus with a friend. Recap: and between nouns, and together with for people.",
    ja: "{友だち|ともだち}[と|と|〜と]{映画|えいが}を{見ました|みました}。",
    en: "I saw a movie with my friend." },
  "どうして|": {
    explain: "This question word is built from two pieces. 「どう」 means how, from Lesson 8 style questions like how was it. 「して」 is the te-form of 「する」, to do. So it is roughly having done how, which turned into why. It is used to ask the reason for something. You usually put it at the start of the question. For example: why aren't you eating? The answer usually ends with 「から」, because. Why didn't you come? Because I was sick, with 「から」 at the end. There are a few other ways to ask why. 「なぜ」 is more formal and common in writing. 「なんで」 is casual and very common among friends. This word sits nicely in the middle, polite enough for most situations. A caution: asking why bluntly can feel pushy in any language. Softening it with a gentle tone helps a lot. Its relative 「どうやって」, coming in Lesson 10, means how, by what means. Same 「どう」 at the start, different question. Recap: how plus doing. Why.",
    ja: "[どうして]{日本語|にほんご}を{勉強|べんきょう}しますか。",
    en: "Why do you study Japanese?" },
  "ひとりで|一人で": {
    explain: "This has two parts. 「一人|ひとり」 means one person, and 「で」 is a particle that shows the way something is done. 「一人|ひとり」 is a special native reading. The kanji are 「一|いち」, one, and 「人|ひと」, person, but you don't read them separately. Two people is also special, 「二人|ふたり」. From three on, counting people switches to the Chinese-origin pattern, like 「三人|さんにん」. So with one person, on your own, is alone. You put it before the verb. For example, I went to 「東京|とうきょう」 alone, or I live alone. It doesn't mean lonely. It just means by yourself, and Japanese people often say it with pride, like I did it all by myself. For feeling lonely there is a different word. Compare 「友だちと|ともだちと」, with a friend, using the particle 「と」 from this lesson. Alone or with somebody. A cultural note: 「一人暮らし|ひとりぐらし」, living alone, is a big life step for Japanese students who move to a city for university. Recap: one person, plus the particle of manner. On your own.",
    ja: "[一人で|ひとりで]{映画|えいが}を{見ました|みました}。",
    en: "I saw a movie alone." },
  "もしもし|": {
    explain: "This phone greeting has a real origin. It comes from 「申す|もうす」, a humble verb meaning to say. In the past, people answering a call said I'm speaking, I'm speaking, by repeating that verb, and over time it shrank to the doubled sound you use today. You will see the same humble verb in Lesson 13 in 「〜と申します|〜ともうします」, a humble way to say my name is. Usage: say it when you answer the phone, or when you can't hear the other person and want to check they are still there. It is mostly for phone calls. Face to face, people say hello differently. The one exception: you might use it to get the attention of a stranger who dropped something, but that is less common. In business calls, people often skip it and say their company name instead. A fun bit of folklore, just a story and not history: people used to say that ghosts and foxes in disguise could only say this word once, so saying it twice proved you were human. Recap: a doubled, shortened I'm speaking. Hello on the phone.",
    ja: "[もしもし]、たけしさんですか。",
    en: "Hello? Is this Takeshi?" },
  "こども|子供": {
    explain: "Two kanji, both with native readings. 「子|こ」 means child. The kanji began as a picture of a baby, with a big head and arms reaching out, and its legs wrapped up. In other words it often takes the Chinese-origin reading 「し」. You see that in 「帽子|ぼうし」, hat, and 「お菓子|おかし」, sweets, from Lesson 11, where it works like a little ending for things. The second kanji, 「供|とも」, means a companion or to attend, and it has the person mark on its left. In this word it is borrowed to write 「ども」, an old ending that made plurals. So the word first meant children, a group of kids. Over time it came to mean just a child, one or more. You will often see this word written with kana for the second half, as 「子ども|こども」. Many schools and newspapers prefer that spelling. The opposite is 「大人|おとな」, adult, in Lesson 13. That is another special reading, made of big and person. A cultural note: Japan has a national holiday for children, 「こどもの日|こどものひ」, on May 5th. Families fly colorful carp-shaped streamers outside their homes. Recap: a baby picture plus a companion, a child.",
    ja: "[子供|こども]が{公園|こうえん}であそんでいます。",
    en: "A child is playing in the park." },
  "しゃしん|写真": {
    explain: "Two kanji, both read with their Chinese-origin readings. The first, 「写|しゃ」, means to copy or to depict. As a verb it shows up with its native reading in 「写す|うつす」, to copy or to capture an image. The second, 「真|しん」, means truth, reality, the genuine thing. Put them together and you get a copy of the truth, an image that captures what is really there. That is a nice fit for a photograph, which records the world exactly as it looks. The word was around before cameras, used for lifelike pictures, and it was naturally picked up for photography. When you take a photo, the verb is 「撮る|とる」, so you say 「写真を撮る|しゃしんをとる」. Notice that 「撮る|とる」 has the hand mark on the left, your hand on the camera. It sounds the same as the ordinary 「取る|とる」, to take, but for photos you use the camera one. One more tip. A selfie is often just called a 「自撮り|じどり」, a self shot, using that same camera kanji. To recap: copy plus truth, a true copy of the world, a photograph.",
    ja: "{海|うみ}の[写真|しゃしん]を{撮りました|とりました}。",
    en: "I took a picture of the sea." },
  "うみ|海": {
    explain: "This word uses the native Japanese reading. The kanji is a great one to take apart. On the left are three little strokes, the water mark. You will see it on lots of water words you already know: 「泳ぐ|およぐ」, to swim, 「湖|みずうみ」, lake, 「洗う|あらう」, to wash, and 「温泉|おんせん」, hot spring. Now look at the right side. It is 「毎|まい」, the same kanji as in 「毎日|まいにち」, every day, and 「毎晩|まいばん」, every night. A way to remember it: every drop of water eventually ends up in the sea. Water plus every equals sea. That is just a hook, but the two pieces really are water and every. Japan is an island country, so the sea is everywhere in daily life, from seafood to summer beach trips. There is even a national holiday in July called 「海の日|うみのひ」, Marine Day, to give thanks for the ocean. When you go to the beach in Japanese, you usually just say 「海に行く|うみにいく」, go to the sea. To recap: water mark plus every, and every drop flows to the sea.",
    ja: "{夏|なつ}に[海|うみ]へいきます。",
    en: "I go to the sea in summer." },
  "サーフィン|": {
    explain: "This is a loanword from English, surfing. Watch how the sounds got squeezed into Japanese. The sur part becomes 「サー」, with the long bar standing in for that drawn-out vowel. Then the f sound. Old Japanese had no real f followed by i, so a small 「ィ」 was added after 「フ」 to make 「フィ」. You will see that same trick in other loanwords with fi sounds. Finally, the ing ending. Usually it becomes 「イング」 in Japanese, but here the final g dropped away, leaving just 「イン」. To say you do it, use 「サーフィンをする」, to do surfing, just like other sports. Japan has a real surf culture. The Shonan coast near Tokyo is famous for it, and surfing made its Olympic debut at the Tokyo Games, held on a beach in Chiba. So the word goes naturally with 「海|うみ」, the sea, which you just learned. To recap: English surfing, with a long 「サー」, the small 「ィ」 trick for f, and the g dropped at the end.",
    ja: "{海|うみ}で[サーフィン]をしました。",
    en: "I went surfing in the sea." },
  "たんじょうび|誕生日": {
    explain: "Three kanji. The first two make the word for birth, and the last one is day. 「誕|たん」 means birth. You will rarely see it outside this word, so think of it as the birthday kanji. 「生|じょう」 means life or to be born. This is a less common reading of a very common kanji. You already know it as 「せい」 in 「学生|がくせい」, student, 「先生|せんせい」, teacher, and 「生活|せいかつ」, daily life. Same kanji, same idea of life, just a different Chinese-origin reading here. Then 「日|び」, day. It is normally 「ひ」, but the h sound softens to a b sound when it is joined on, a common sound change. So birth plus day, birthday, exactly like English. To wish someone a happy birthday, say 「お誕生日おめでとう|おたんじょうびおめでとう」, adding 「ございます」 to be polite. Here is a cultural note. Japan used to count everyone's age by the New Year, so everyone got a year older together. Personal birthday celebrations became really common only in the twentieth century. To recap: birth, life, day, the day you came to life.",
    ja: "あしたは{私|わたし}の[誕生日|たんじょうび]です。",
    en: "Tomorrow is my birthday." },
  "てがみ|手紙": {
    explain: "Two kanji, both with native Japanese readings. 「手|て」 means hand. You know it from 「手伝う|てつだう」, to help, lending a hand, and 「手袋|てぶくろ」, gloves, hand bags. It is also in 「上手|じょうず」 and 「下手|へた」, good at and bad at, skilled or clumsy hands. 「紙|かみ」 means paper. The left side is the thread mark, because paper was made from fibers. In this word 「かみ」 softens to 「がみ」 when it is joined to 「て」. Paper by hand, a handwritten letter. That is the image. Be careful with the sound 「かみ」. It also means hair, 「髪|かみ」, with a different kanji. Here is a fun fact. In Chinese, the very same two characters mean toilet paper, so a Chinese reader may smile at this word. To say you write one, use 「手紙を書く|てがみをかく」, and for sending, 「送る|おくる」. Japan still has a strong letter culture, like New Year postcards sent to everyone you know. To recap: hand plus paper, a letter written by hand.",
    ja: "{母|はは}に[手紙|てがみ]を{書きました|かきました}。",
    en: "I wrote a letter to my mother." },
  "すき|好き": {
    explain: "The kanji is made of two pieces you may already recognize: 「女|おんな」, woman, on the left, and 「子|こ」, child, on the right. It is commonly explained as a mother with her child, the picture of affection. A lovely way to remember liking something. Here it takes its native reading, 「す」. Now the grammar, which trips up English speakers. In English you like something, and that thing is the object. In Japanese, the thing you like is marked with 「が」, not 「を」. So you say 「ねこが好きです|ねこがすきです」, I like cats. A way to think about it: the cat is likable to me. Also, even though this word looks like it ends in an i sound, it is a na-adjective. So before a noun you say 「好きな食べ物|すきなたべもの」, favorite food, and the negative is 「好きじゃない|すきじゃない」. Add 「大|だい」, big, in front and you get 「大好き|だいすき」, to love something. One more cultural note. 「好きです|すきです」 said directly to a person is a classic love confession in Japan. To recap: woman plus child, affection, with 「が」 marking what you like.",
    ja: "{私|わたし}は{猫|ねこ}が[好き|すき]です。",
    en: "I like cats." },
  "おいしい|": {
    explain: "This word is usually written in kana, but you may see it with kanji as 「美味しい|おいしい」. Those kanji mean beautiful and taste. You know the first from 「美術館|びじゅつかん」, art museum, and the second from 「意味|いみ」, meaning. So it is literally beautiful taste. Where does the sound come from? There was an old word, 「いしい」, meaning good or tasty. The polite 「お」 was added in front, and it was used as refined language by women at the imperial court before spreading to everyone. Today it is the standard, polite way to say something tastes good. Men often say 「うまい」 in casual speech, which means the same thing. If something tastes bad, the word is 「まずい」. Be careful, it is quite blunt. Here is a habit worth copying. In Japan, people say 「おいしい」 out loud the moment they taste something, at home, on TV, everywhere. After a meal, say 「おいしかったです」, it was delicious, using the past form. To recap: polite 「お」 plus an old word for good, beautiful taste.",
    ja: "このケーキはとても[おいしい]です。",
    en: "This cake is very delicious." },
  "おおきい|大きい": {
    explain: "The kanji 「大|おお」 is a picture of a person standing with arms and legs spread wide, making themselves as big as possible. Here it takes its native reading 「おお」. But the same kanji has a Chinese-origin reading, 「だい」, and you know many words with it. 「大学|だいがく」, college, is the big school. 「大好き|だいすき」 is big liking, to love. 「大丈夫|だいじょうぶ」, it's okay, also starts with it. There is also 「たい」 in 「大変|たいへん」, tough, a big change or big trouble. And a fun irregular one: 「大人|おとな」, adult, a big person. The word itself is an i-adjective. The past is 「大きかった|おおきかった」, and the negative is 「大きくない|おおきくない」. You may also see 「大きな|おおきな」 before a noun, which means the same thing. The opposite is 「小さい|ちいさい」, small. To recap: a person stretching out wide, big, read 「おお」 here and 「だい」 in many other words.",
    ja: "{私|わたし}の{家|いえ}は[大きい|おおきい]です。",
    en: "My house is big." },
  "ちいさい|小さい": {
    explain: "The kanji 「小|ちい」 is a small, simple shape: a short vertical stroke with a tiny mark on each side. A way to remember it: something tiny being split into even tinier bits. That is a hook, not an origin story. Here it takes its native reading, 「ちい」. It is the partner of 「大きい|おおきい」, big. Learn them as a pair. Just like big, it is an i-adjective. The past is 「小さかった|ちいさかった」, and the negative is 「小さくない|ちいさくない」. And just like big, there is also a form 「小さな|ちいさな」 that goes before a noun, as in 「小さな町|ちいさなまち」, a small town. Its Chinese-origin reading is 「しょう」, as in 「小学校|しょうがっこう」, elementary school, the small school. That pairs nicely with 「大学|だいがく」, the big school. Kids and casual speakers often say 「ちっちゃい」, a cute, squeezed version of the same word. To recap: a tiny stroke split by little marks, small, the partner of big.",
    ja: "この[小さい|ちいさい]{猫|ねこ}はかわいいです。",
    en: "This small cat is cute." },
  "あたらしい|新しい": {
    explain: "The kanji 「新|あたら」 has two sides. On the left are the pieces for stand and tree, and on the right is a shape that means axe. It is often explained as taking an axe to a tree to get fresh wood. Fresh cut wood is new. In this word it has its native reading, 「あたら」. The Chinese-origin reading is 「しん」, and you know it from two words already. 「新聞|しんぶん」, newspaper, is new things heard, the news. And 「新幹線|しんかんせん」, the bullet train, is the new trunk line. There is also the famous Tokyo district Shinjuku, written with this same kanji at the front. It is an i-adjective, so the past is 「新しかった|あたらしかった」 and the negative is 「新しくない|あたらしくない」. Its opposite is 「古い|ふるい」, old. At New Year in Japan, people buy new things and start fresh, which fits the feeling of this word. To recap: an axe cutting fresh wood, new, read 「しん」 in newspaper and bullet train.",
    ja: "[新しい|あたらしい]{時計|とけい}を{買いました|かいました}。",
    en: "I bought a new watch." },
  "ふるい|古い": {
    explain: "The kanji 「古|ふる」 is made of 「十|じゅう」, ten, on top of 「口|くち」, mouth. A way to remember it: a story passed down through ten mouths, generation after generation, must be very old. That is a hook, not a proven origin. Here it takes its native reading, 「ふる」. It is the opposite of 「新しい|あたらしい」, new. Now an important usage note. Use this word for things, ideas and buildings, like 「古いお寺|ふるいおてら」, an old temple. Do not use it to say a person is old. Calling someone 「古い|ふるい」 sounds like they are outdated. For people, talk about age, or say someone is 「年上|としうえ」, older than you. Here is another trap. 「古い友だち|ふるいともだち」 means a friend you have known for a long time, not an elderly friend. It is an i-adjective, so the past is 「古かった|ふるかった」 and the negative is 「古くない|ふるくない」. Japan has a lot of very old things, from temples in Kyoto to shops running for hundreds of years. To recap: ten mouths passing down a story, old, for things and not for people.",
    ja: "この[古い|ふるい]{お寺|おてら}はきれいです。",
    en: "This old temple is beautiful." },
  "たべもの|食べ物": {
    explain: "This word is a verb plus a noun, a very handy pattern in Japanese. The first part, 「食べ|たべ」, is the stem of 「食べる|たべる」, to eat. The second part, 「物|もの」, means thing, a physical object. Eat plus thing, things to eat, food. The same kanji has a Chinese-origin reading in 「食堂|しょくどう」, cafeteria, the eating hall. And 「物|もの」 shows up all over your vocabulary. Its partner is 「飲み物|のみもの」, things to drink. 「買い物|かいもの」 is buying things, shopping. 「着物|きもの」 is a thing to wear, a kimono. 「果物|くだもの」 is fruit, and 「建物|たてもの」 is a building. Once you see the pattern, you can often guess a new word: verb stem plus 「物|もの」. A natural question to ask a new friend is 「どんな食べ物が好きですか|どんなたべものがすきですか」, what kind of food do you like. To recap: eat plus thing, food, partner of drink, one of a whole family of thing words.",
    ja: "どんな[食べ物|たべもの]が{好き|すき}ですか。",
    en: "What kind of food do you like?" },
  "のみもの|飲み物": {
    explain: "This is the partner of 「食べ物|たべもの」, food, and it is built the same way: a verb stem plus thing. 「飲み|のみ」 is the stem of 「飲む|のむ」, to drink. 「物|もの」 means thing. Drink plus thing, things to drink. Look closely at the kanji for drink. The left side is the eating kanji, squeezed narrow. The right side is a shape that shows a person with an open mouth. Put them together and you have consuming with your mouth open, drinking. In Japanese, 「飲む|のむ」 covers more than drinks. You also use it for medicine, 「薬を飲む|くすりをのむ」, to take medicine, because you swallow it. At a restaurant or someone's home, you will often be asked 「飲み物は何がいいですか|のみものはなにがいいですか」, what would you like to drink. Also, 「飲み会|のみかい」 is a drinking party, a big part of Japanese work and school social life. To recap: drink plus thing, things to drink, with eat on the left side of the kanji.",
    ja: "[飲み物|のみもの]はなにがいいですか。",
    en: "What would you like to drink?" },
  "くだもの|果物": {
    explain: "This one has a special reading. The two kanji are read together as one unit, 「くだもの」, rather than piece by piece. The first kanji means fruit, and also result, the fruit of your efforts. Its shape has a tree at the bottom with something round growing on top. Fruit on a tree. The second kanji is 「物|もの」, thing, as in 「食べ物|たべもの」 and 「飲み物|のみもの」. Where does the sound come from? Old Japanese had 「く」, an old word for tree, and 「だ」, an old linking sound like today's 「の」. So 「くだもの」 was originally a thing of the tree. Here is a cultural note. Fruit in Japan can be very expensive, and perfect melons or boxes of fruit are given as fancy gifts. In winter, families eat 「みかん」, mandarin oranges, sitting around a heated table. Also, a tomato counts as a vegetable, 「野菜|やさい」, in Japanese, not a fruit. To recap: fruit on a tree, plus thing, an old phrase meaning thing of the tree.",
    ja: "{毎朝|まいあさ}[果物|くだもの]を{食べます|たべます}。",
    en: "I eat fruit every morning." },
  "りょこう|旅行": {
    explain: "Two kanji, both with their Chinese-origin readings. 「旅|りょ」 means a journey. You will see it again in 「旅館|りょかん」, a traditional Japanese inn, a journey building. On its own, with the native reading, it is 「旅|たび」, a trip, a slightly more poetic word. 「行|こう」 means to go. It started as a picture of a crossroads, a place where people go. You know it with the native reading in 「行く|いく」, to go. And you know 「こう」 from 「銀行|ぎんこう」, bank, and 「飛行機|ひこうき」, airplane, a flying going machine. Journey plus go, going on a journey, travel. Add 「する」 and it becomes a verb, 「旅行する|りょこうする」, to travel. Here is a cultural note. When Japanese people travel, they are expected to bring back 「お土産|おみやげ」, souvenirs, for family and coworkers. To recap: journey plus go, travel, sharing the go kanji with bank and airplane.",
    ja: "{夏|なつ}に[旅行|りょこう]をします。",
    en: "I'll travel in the summer." },
  "バス|": {
    explain: "This is a loanword from English, bus. It is one of the easiest: the b and the s sounds come across almost directly, with an extra a vowel in the middle and a quiet u sound at the end, 「バス」. Here is a fun trap. The same sound, 「バス」, is also the Japanese for bath, from English bath, because the th sound becomes s. So a 「バスタオル」 is a bath towel, not a bus towel. Context makes it clear. For a real Japanese bath, people usually say 「お風呂|おふろ」. You already know 「バス停|バスてい」, bus stop, which adds a kanji meaning to stop. To ride the bus, say 「バスに乗る|バスにのる」, with 「に」, and to get off, 「バスを降りる|バスをおりる」. A cultural note. On many Japanese city buses, you take a little ticket as you board and pay when you get off, so watch what the locals do. To recap: English bus, with an extra vowel squeezed in, and the same sound can mean bath.",
    ja: "[バス]で{学校|がっこう}に{行きます|いきます}。",
    en: "I go to school by bus." },
  "てんき|天気": {
    explain: "Two kanji, both with Chinese-origin readings. 「天|てん」 means heaven or sky. Its shape is a person, 「大|だい」, with an extra line on top, the sky above their head. 「気|き」 is a rich kanji meaning spirit, air, or energy. It is like the invisible mood of something. Sky plus energy, the mood of the sky, the weather. That 「気|き」 is one of the most useful kanji you will meet. You already know several words with it. 「元気|げんき」 is source energy, being healthy and lively. 「病気|びょうき」 is sick energy, illness. 「電気|でんき」 is electric energy, electricity or the lights. And 「気温|きおん」 is air warmth, temperature. There is also 「天気予報|てんきよほう」, the weather forecast. The most common small talk in Japan is about the weather. 「いい天気ですね|いいてんきですね」, nice weather, isn't it, is a classic greeting. To recap: sky plus energy, the mood of the sky, weather.",
    ja: "{今日|きょう}は[天気|てんき]がいいです。",
    en: "The weather is nice today." },
  "しゅくだい|宿題": {
    explain: "Two kanji, both with their Chinese-origin readings. 「宿|しゅく」 has a roof on top, and it means lodging, a place where you stay the night. It also carries the idea of something kept or held over until later. You can see it in the name of the Tokyo district Shinjuku, which was once a new post town where travelers stayed. 「題|だい」 means a topic or a title, as in a problem you are set. Put them together and you have a problem that is held over to be worked on later, at the place you stay. Homework. For the verb, people say 「宿題をする|しゅくだいをする」, to do homework. In casual speech, 「宿題をやる|しゅくだいをやる」 is also very common. A cultural note. Japanese schoolkids are famous for summer vacation homework, including keeping a diary and doing a free research project. Lots of them rush to finish it in the last days of August. To recap: lodging plus topic, a problem held over and taken home, homework.",
    ja: "{今日|きょう}は[宿題|しゅくだい]がたくさんあります。",
    en: "I have a lot of homework today." },
  "テスト|": {
    explain: "This is a loanword from English, test. Watch how the sounds got squeezed in. Japanese syllables almost always end in a vowel, so English consonant clusters get vowels added. The st at the end of test becomes two syllables, 「ス」 and 「ト」, with a quiet u and a full o sound added. So one English syllable turns into three Japanese ones, 「テ」, 「ス」, 「ト」. You will see the same thing with lots of loanwords that end in t, which usually gain an o. For taking a test, people say 「テストを受ける|テストをうける」, to receive a test, or simply 「テストがある」, there is a test. Japanese also has a native-feeling word, 「試験|しけん」, which you will meet later. That one sounds more formal, for big exams like entrance exams or finals. A 「テスト」 is more everyday, like a quiz in class. Japanese schools are famous for tough high school and university entrance exams, so students hear both words a lot. To recap: English test, with extra vowels added after the s and the t, an everyday quiz or test.",
    ja: "{明日|あした}[テスト]があります。",
    en: "There is a test tomorrow." },
  "へや|部屋": {
    explain: "This word has a special reading. The two kanji are read together as 「へや」, rather than with their usual separate readings. The first kanji, read 「ぶ」 elsewhere, means a part or a section. You will meet it later in words like club activities at school. The second kanji, 「屋|や」, means a roof, a house, or a shop. You already know it at the end of 「本屋|ほんや」, bookstore, a book shop. Put them together and a room is a section of the house. That makes good sense. In Japan, rooms are often measured in tatami mats rather than square meters. A six mat room is a common size for a small bedroom. Apartment ads even describe layouts with codes like one room plus a kitchen. A cultural note. Before you step into a Japanese room with tatami, you take your slippers off too, not just your shoes. To say my room, just add 「わたしの」, giving 「わたしの部屋|わたしのへや」. To recap: a section of the house, a room, with the shop and house kanji you know from bookstore.",
    ja: "{私|わたし}の[部屋|へや]は{小さい|ちいさい}です。",
    en: "My room is small." },
  "ぼく|僕": {
    explain: "The kanji has the person mark on the left, the same one you see in 「休み|やすみ」, rest, a person by a tree. Here it takes its Chinese-origin reading, 「ぼく」. The kanji originally meant a servant, so calling yourself this was a humble way to say I. Today it is the word boys and men often use for I in casual and friendly situations. It sounds softer and gentler than 「おれ」, which is rough and very casual, and more relaxed than 「わたし」, which is neutral and polite. In a job interview or with your boss, a man would usually switch to 「わたし」 or the even more formal 「わたくし」. A common pattern is a boy using 「ぼく」 as a child and adding 「おれ」 with friends as he grows up. You will also hear it in lots of song lyrics, sometimes even sung by women. A way to remember it: picture a polite young man bowing, saying 「ぼく」 with a little smile. That is just a hook. To recap: a person mark, an old humble word for servant, now a soft and casual I for men.",
    ja: "[僕|ぼく]は{大学|だいがく}の{学生|がくせい}です。",
    en: "I am a college student." },
  "エルサイズ|": {
    explain: "This is made from English, the letter L plus the word size. The letter L is read 「エル」 in Japanese. Since Japanese has no separate l sound, it uses its r-like sound, and an extra u sound is added at the end. Then size becomes 「サイズ」, with the z sound followed by a quiet u. So you get large size, but said with the letter, just like on a clothing tag. The same pattern works for other sizes: 「エム」 for M and 「エス」 for S. Here is a practical tip for shopping in Japan. Japanese clothing sizes tend to run smaller than American ones. A Japanese L may fit like an American M, so try things on. You may also see 「エルエル」 for extra large on some tags. And the same word works for drinks at a coffee shop or fast food place. To recap: the letter L read 「エル」, plus size, large size, just like a tag.",
    ja: "[エルサイズ]のシャツをください。",
    en: "A size L shirt, please." },
  "あつい|暑い": {
    explain: "This is the hot for weather and air, like a hot summer day. The kanji has 「日|ひ」, sun, sitting on top. A way to remember it: the sun beating down on you from above. The sun on top tells you this is weather heat. It uses its native reading, 「あつ」. Here is the important part. Japanese has more than one 「あつい」, written with different kanji. This one, 「暑い|あつい」, is for the weather. The other one, 「熱い|あつい」, is for things that are hot to touch, like coffee or a bath. The opposite of this one is 「寒い|さむい」, cold weather. The opposite of the other one is 「冷たい|つめたい」, cold to the touch. Japanese summers are famously hot and humid. People greet each other with 「暑いですね|あついですね」, it's hot, isn't it. That is one of the most common summer small talk lines you will hear. To recap: sun on top, hot weather, and the partner of cold weather.",
    ja: "{今日|きょう}はとても[暑い|あつい]です。",
    en: "It's very hot today." },
  "さむい|寒い": {
    explain: "This is cold for weather and air, the cold you feel all over your body on a winter day. The kanji has a roof on top, and at the very bottom there are two little strokes. Those two strokes are a form of the ice mark. You can see the ice mark on the left of 「冷たい|つめたい」, cold to the touch. And the same two little strokes sit at the bottom of 「冬|ふゆ」, winter. So think of it as ice creeping in under the roof of the house. Cold. It uses its native reading, 「さむ」. Its opposite is 「暑い|あつい」, hot weather. Be careful not to mix it up with 「冷たい|つめたい」. That one is for things, like cold water, or for cold-hearted people. A cultural note. Many Japanese houses are not well insulated, so winter indoors can be chilly. That is why people love the heated table called a 「こたつ」, often with mandarin oranges on top. To recap: ice under the roof, cold weather, the partner of hot weather.",
    ja: "{冬|ふゆ}は[寒い|さむい]です。",
    en: "It's cold in winter." },
  "あつい|熱い": {
    explain: "This is hot for things you touch or drink, like hot coffee, a hot bath, or a hot pan. Look at the bottom of the kanji. Those four dots are a form of the fire mark. Fire underneath, so it is hot to touch. It uses its native reading here, 「あつ」. The Chinese-origin reading is 「ねつ」, and it means fever, as in 「熱がある|ねつがある」, to have a fever. That is your body getting hot. Now compare it with 「暑い|あつい」, which has the sun on top and is for hot weather. Same sound, different kanji, and the kanji tells you what kind of heat it is. Sun on top, weather. Fire underneath, things. The opposite of this one is 「冷たい|つめたい」, cold to the touch. You can also use it for feelings, like a hot, passionate heart. Japanese baths can be very hot, so you might hear 「熱い|あつい」 as someone steps in. To recap: fire underneath, hot things, the same kanji as fever.",
    ja: "このおちゃは[熱い|あつい]です。",
    en: "This tea is hot." },
  "おもしろい|面白い": {
    explain: "Two kanji, both with native readings. 「面|おも」 means face or surface. 「白|しろ」 means white, and by extension bright. So the word is literally something like bright face. A way to remember it: picture people sitting around a fire listening to a great story, their faces lit up white by the flames. That is a popular folk story, not a proven origin, so treat it as a hook. The word covers two ideas that English splits. It can mean interesting, like an interesting book. It can also mean funny, like a funny comedian. Context tells you which. The opposite is 「つまらない」, boring. It is an i-adjective, so the past is 「面白かった|おもしろかった」, and the negative is 「面白くない|おもしろくない」. After a movie, 「面白かったです|おもしろかったです」 is a natural thing to say whether it was gripping or hilarious. If you specifically mean full of laughs, you might add that it made you laugh. To recap: face plus white, faces lighting up, interesting or funny.",
    ja: "この{本|ほん}は[面白い|おもしろい]です。",
    en: "This book is interesting." },
  "つまらない|": {
    explain: "This word is usually written in kana. It means boring, dull, not worth much. A way to remember it: think of something with nothing packed inside, an empty box of a movie. That is a hook. It is the opposite of 「面白い|おもしろい」, interesting or funny. Even though it ends in 「ない」, it is a regular i-adjective on its own. The past is 「つまらなかった」. In casual speech you will often hear it squeezed to 「つまんない」. Now a great cultural note. When Japanese people give a gift, they traditionally say 「つまらないものですが」. It means this is a trifling thing, but please take it. It is not an insult to the gift. It is a humble way of offering something, playing down your own effort. These days some people find it a bit old-fashioned, and might say something like this is a little something instead. But you will still hear it, so do not be confused when someone hands you a nice present and calls it boring. To recap: boring, the opposite of interesting, and a humble phrase for giving gifts.",
    ja: "その{映画|えいが}は[つまらない]です。",
    en: "That movie is boring." },
  "やさしい|": {
    explain: "This word is usually written in kana, and it has two meanings. Each meaning has its own kanji. For easy, as in an easy problem, it is written 「易しい|やさしい」. For kind or gentle, as in a kind person, it is written 「優しい|やさしい」. That second kanji may look familiar. It is the same one you see at the end of 「俳優|はいゆう」, actor. Both meanings share the same feeling: something soft, gentle, not harsh on you. An easy test is gentle on your brain. A kind person is gentle on your heart. The opposite of the easy meaning is 「難しい|むずかしい」, difficult. Another word for easy is 「簡単|かんたん」, simple, which is a na-adjective. Use 「やさしい」 for problems or questions, and also for people, like 「やさしい人|やさしいひと」, a kind person. A way to remember it: picture a gentle teacher giving you an easy quiz. That is a hook. To recap: gentle on you, easy for problems and kind for people.",
    ja: "{先生|せんせい}は[やさしい]です。",
    en: "The teacher is kind." },
  "むずかしい|難しい": {
    explain: "The kanji means difficult or trouble. It uses its native reading here, 「むずか」. Its Chinese-origin reading is 「なん」, as in a word meaning a problem or hardship, which you will meet later. It is the opposite of 「やさしい」, easy, and of 「簡単|かんたん」, simple. It is an i-adjective, so the past is 「難しかった|むずかしかった」 and the negative is 「難しくない|むずかしくない」. Young people often shorten it to 「むずい」 in casual chat. Now an important cultural note. When you ask a Japanese person for something, they may answer 「ちょっと難しいです|ちょっとむずかしいです」. Literally that is, it is a little difficult. But it very often means no, that will not be possible. It is a polite, soft way of refusing without saying no directly. So if your request gets this answer, do not push. Thank them and move on. To recap: difficult, the opposite of easy, and a soft, polite way of saying no.",
    ja: "{漢字|かんじ}は[難しい|むずかしい]です。",
    en: "Kanji are difficult." },
  "かっこいい|": {
    explain: "This word is a squeezed version of two pieces. The first is 「かっこう」, meaning appearance, shape, or how you look. The second is 「いい」, good. So it is literally good looking appearance, looks good, or cool. It can describe people, but also things, like a cool car, a cool jacket, or a cool move in sports. Here is the common mistake. Because it ends in 「いい」, it conjugates just like 「いい」 does. And 「いい」 is irregular. Its forms come from an older word, 「よい」. So the negative is 「かっこよくない」, not good-looking, and the past is 「かっこよかった」, it was cool. Saying 「かっこいくない」 is a classic learner mistake. Its opposite is 「かっこわるい」, uncool or embarrassing. You will hear 「かっこいい」 all the time from fans talking about actors and singers. To recap: appearance plus good, cool or good-looking, with the same tricky forms as 「いい」.",
    ja: "あの{人|ひと}は[かっこいい]です。",
    en: "That person is good-looking." },
  "こわい|怖い": {
    explain: "Look at the left side of the kanji. That narrow, upright shape is the heart mark, a squeezed version of the heart kanji. It is used for words about feelings. You will see the same heart mark on 「忙しい|いそがしい」, busy, which you are learning in this lesson too. So scary is a feeling in your heart. The word uses its native reading, 「こわ」. English splits this idea into scary and scared. Japanese often uses the same word for both. 「この映画は怖い|このえいがはこわい」 means this movie is scary. But 「怖い|こわい」 on its own, said about yourself, can mean I am scared. You can also use it for people, like a strict, frightening teacher, 「怖い先生|こわいせんせい」. A cultural note. Japan has a big tradition of ghost stories, told especially in summer, because a good chill is supposed to cool you down. To recap: the heart mark on the left, a feeling, scary or scared.",
    ja: "この{映画|えいが}は[怖い|こわい]です。",
    en: "This movie is scary." },
  "きらい|嫌い": {
    explain: "The kanji has 「女|おんな」, woman, on the left, the same piece that appears in 「好き|すき」, to like. That makes a handy pair to remember, two feeling words that both start with the woman piece. It uses its native reading, 「きら」. Now the grammar, which works just like 「好き|すき」. The thing you dislike is marked with 「が」, not 「を」. 「やさいが嫌いです|やさいがきらいです」 means I dislike vegetables. And here is the big trap. Even though it ends in an i sound, it is a na-adjective, not an i-adjective. So the negative is 「嫌いじゃない|きらいじゃない」, I do not dislike it. Never 「きらくない」. Before a noun you say 「嫌いな食べ物|きらいなたべもの」, a food you dislike. A cultural note. In Japanese, saying you dislike something directly can sound strong. People often soften it by saying they are not very fond of it, using 「あまり好きじゃない|あまりすきじゃない」. To recap: the partner of like, marked with 「が」, and a na-adjective despite its ending.",
    ja: "{私|わたし}は{肉|にく}が[嫌い|きらい]です。",
    en: "I dislike meat." },
  "だいすき|大好き": {
    explain: "This word is just 「好き|すき」, to like, with 「大|だい」, big, put in front. Big liking, to love. The kanji 「大|だい」 is a person stretching out arms and legs as wide as possible. Here it has its Chinese-origin reading. You know it from 「大学|だいがく」, college, and 「大丈夫|だいじょうぶ」, it's okay. The kanji 「好|す」 is woman plus child, a picture of affection. The grammar is the same as for 「好き|すき」. The thing you love takes 「が」. 「すしが大好きです|すしがだいすきです」 means I love sushi. It is a na-adjective, so before a noun you say 「大好きな|だいすきな」, as in my very favorite thing. Here is a usage tip. For food, hobbies, music and so on, this is the natural way to say you love something. For romantic love, Japanese people rarely say the heavier word for love. They are much more likely to say 「大好き|だいすき」. Its opposite is 「大嫌い|だいきらい」, to hate. To recap: big plus like, to love, with 「が」 marking what you love.",
    ja: "{私|わたし}はサーフィンが[大好き|だいすき]です。",
    en: "I love surfing." },
  "だいきらい|大嫌い": {
    explain: "This word is 「嫌い|きらい」, to dislike, with 「大|だい」, big, in front. Big dislike, to hate. It follows the same pattern as 「大好き|だいすき」, big liking, to love. Learn them as a pair. The kanji 「大|だい」 is a person stretching out wide, read with its Chinese-origin reading here, like in 「大学|だいがく」. The grammar works like 「嫌い|きらい」. The thing you hate takes 「が」. 「虫が大嫌いです|むしがだいきらいです」 means I hate bugs. It is a na-adjective, even though it ends in an i sound, so before a noun you say 「大嫌いな|だいきらいな」. Here is a strong caution. This word is very direct. Said about a person, it can really hurt. In daily conversation, people often soften things with 「あまり好きじゃない|あまりすきじゃない」, not very fond of it. That said, in anime and dramas you will hear it shouted between friends or lovers, sometimes not quite meaning it. To recap: big plus dislike, to hate, the strong partner of love.",
    ja: "{私|わたし}はテストが[大嫌い|だいきらい]です。",
    en: "I hate tests." },
  "きれい|": {
    explain: "This word is usually written in kana. There is a kanji spelling, but it is complicated and rarely used. It has two meanings. One is pretty or beautiful, like a beautiful flower, 「きれいな花|きれいなはな」. The other is clean, like a clean room. The idea that joins them is something pure and neat, pleasing to look at. Its opposite for the clean meaning is 「汚い|きたない」, dirty, which you will meet later. Now the big trap. Even though it ends in an i sound, it is a na-adjective, not an i-adjective. So the negative is 「きれいじゃない」, not 「きれくない」. Before a noun, you say 「きれいな」, and the past is 「きれいでした」. Two other words that look like i-adjectives but are actually na-adjectives are 「好き|すき」 and 「嫌い|きらい」. A way to remember it: picture a clean, beautiful room. One image covers both meanings. That is a hook. To recap: pretty and clean, with the na-adjective trap.",
    ja: "この{部屋|へや}は[きれい]です。",
    en: "This room is clean." },
  "げんき|元気": {
    explain: "Two kanji, both with Chinese-origin readings. 「元|げん」 means origin, source, or the base of something. 「気|き」 means spirit, air, or energy, the invisible force inside things. Put them together and you get your source energy, the basic life force that keeps you going. Healthy and lively. That 「気|き」 is a superstar kanji. You know it from 「天気|てんき」, the mood of the sky, weather, 「病気|びょうき」, sick energy, illness, and 「電気|でんき」, electric energy. The opposite feeling is 「元気がない|げんきがない」, to have no energy, to look down. It is a na-adjective, so you say 「元気な子供|げんきなこども」, an energetic child. You will use it in greetings constantly. 「お元気ですか|おげんきですか」 is how are you, for someone you have not seen for a while. And 「元気でね|げんきでね」 is a warm way to say take care when parting for a long time. To recap: source plus energy, your basic life force, healthy and lively.",
    ja: "{子供|こども}たちはとても[元気|げんき]です。",
    en: "The children are very energetic." },
  "しずか|静か": {
    explain: "The kanji has two parts. On the left is the kanji for blue or green, and on the right is a shape meaning to compete or struggle. A way to remember it: calm blue water where all the struggle has settled down. That is a hook, not a proven origin. It uses its native reading, 「しず」. It is a na-adjective, so you say 「静かな部屋|しずかなへや」, a quiet room, and the negative is 「静かじゃない|しずかじゃない」. Its opposite is 「にぎやか」, lively and bustling. Learn them as a pair. There is also 「うるさい」, noisy or annoying, which is negative, while 「にぎやか」 is positive. A very useful phrase is 「静かにしてください|しずかにしてください」, please be quiet. Teachers say it to students all the time. A cultural note. Japanese trains are famously quiet. People avoid phone calls and keep their voices low. To recap: calm blue with the struggle settled, quiet, the opposite of lively.",
    ja: "{図書館|としょかん}は[静か|しずか]です。",
    en: "The library is quiet." },
  "にぎやか|": {
    explain: "This word is usually written in kana. It describes a place or event that is lively, bustling, full of people and fun noise. Think of a busy shopping street, a festival, or a family dinner with lots of chatter. It is a positive word. That is the key difference from 「うるさい」, which means noisy in an annoying way. A busy market is 「にぎやか」. Your neighbor's loud music at midnight is 「うるさい」. It is a na-adjective, so you say 「にぎやかな町|にぎやかなまち」, a lively town. Its opposite is 「静か|しずか」, quiet. A cultural note. Japanese 「お祭り|おまつり」, festivals, with their drums, food stalls and crowds, are the perfect picture of this word. At New Year, shrines are very 「にぎやか」 with visitors, and shopping streets get the same way before holidays. To recap: lively and bustling in a good way, the opposite of quiet.",
    ja: "この{町|まち}は[にぎやか]です。",
    en: "This town is lively." },
  "ひま|暇": {
    explain: "The kanji has 「日|ひ」, sun or day, on the left, a fitting piece for a word about time. It uses its native reading, 「ひま」. It means having free time, not being busy. Its opposite is 「忙しい|いそがしい」, busy. It is a na-adjective, so you say 「暇な日|ひまなひ」, a free day, and the negative is 「暇じゃない|ひまじゃない」. Here is an important politeness note. Asking someone 「暇ですか|ひまですか」 can sound a bit too direct, almost like are you idle. With friends it is fine. But with a teacher or boss, it is better to ask if they have some time. The word can also mean bored when you have nothing to do. A teenager lying around might groan that they are so bored, using this word. So it covers both free time and boring empty time, depending on context. A way to remember it: picture a free afternoon, with the sun on the left of the kanji, and nothing on your schedule. That is a hook. To recap: sun on the left, free time, the opposite of busy.",
    ja: "{明日|あした}は[暇|ひま]です。",
    en: "I'm free tomorrow." },
  "およぐ|泳ぐ": {
    explain: "The kanji has the water mark on the left, the three little drops you saw in 「海|うみ」, sea. On the right is the kanji for eternal or long-lasting. A way to remember it: moving through water on and on, stroke after stroke. That is a hook, but the pieces really are water and long. It uses its native reading, 「およ」. This is a u-verb. In its polite form it becomes 「泳ぎます|およぎます」. For the te-form, the 「ぐ」 ending turns into 「いで」, giving 「泳いで|およいで」. You know another verb with the same ending: 「急ぐ|いそぐ」, to hurry, which becomes 「急いで|いそいで」. When you say where you swim, use 「で」, the place of action: 「海で泳ぐ|うみでおよぐ」, to swim in the sea. Or 「プールで泳ぐ|プールでおよぐ」, to swim in a pool. A cultural note. Most Japanese elementary schools have an outdoor pool, and swimming lessons in summer are a standard part of school life. To recap: water plus long-lasting, swimming, with the 「ぐ」 to 「いで」 te-form.",
    ja: "{海|うみ}で[泳ぎました|およぎました|およぐ]。",
    en: "I swam in the sea." },
  "のる|乗る": {
    explain: "The kanji is often described as a person standing on top of a tree. That is a hook to remember it, picture someone riding high up. It uses its native reading, 「の」. Now the key grammar point, which English speakers often get wrong. The thing you ride takes 「に」, not 「を」. So you say 「バスに乗る|バスにのる」, to ride the bus, and 「電車に乗る|でんしゃにのる」, to take the train. Think of it as getting on to the bus, moving onto it. The opposite, to get off, is 「降りる|おりる」, and that one takes 「を」, getting off from the bus. You will meet 「乗り遅れる|のりおくれる」 later, which means to miss a train or bus, literally to be late to board. This is a u-verb, so the te-form is 「乗って|のって」. You can also use it for riding a bicycle, a horse, or a ride at an amusement park. To recap: someone up high, riding, with 「に」 for what you get on.",
    ja: "{毎日|まいにち}バスに[乗ります|のります|のる]。",
    en: "I ride the bus every day." },
  "やる|": {
    explain: "This word is usually written in kana. It is a casual word for to do, much like 「する」. People say 「宿題をやる|しゅくだいをやる」, to do homework, or 「テニスをやる」, to play tennis. It often feels a bit more active and hands-on than 「する」, like really getting into something. It is a u-verb. The polite form is 「やります」 and the te-form is 「やって」. Here is a politeness note. 「やる」 is casual. In formal settings, 「する」 is safer, and for your boss's actions you would use more respectful words. It has a second meaning too, to give to someone below you, like giving food to a pet or water to plants. 「犬にえさをやる|いぬにえさをやる」 means to feed the dog. You will hear 「やった」 a lot as a happy shout, meaning I did it, or yes. And 「やってみる」 means to give it a try. A way to remember it: think of a coach clapping and shouting let's do it. That is a hook. To recap: a casual, energetic to do, plus a joyful 「やった」 when you succeed.",
    ja: "{友だち|ともだち}とゲームを[やります|やります|やる]。",
    en: "I play games with my friend." },
  "でかける|出かける": {
    explain: "The first kanji, 「出|で」, means to go out or exit. Here it uses its native reading. You know it from 「出す|だす」, to take something out, and 「せきが出る|せきがでる」, a cough comes out. With its Chinese-origin reading it appears in 「出身|しゅっしん」, coming from a place, where you came out from. The rest, 「かける」, adds a sense of setting off. So the whole word means to step out and set off somewhere. This is a ru-verb, so it becomes 「出かけます|でかけます」 and 「出かけて|でかけて」. Here is how it differs from 「行く|いく」, to go. With 「行く|いく」, you usually say where you are going. With 「出かける|でかける」, the focus is on leaving the house. You do not need a destination. A very common sentence is 「母は今出かけています|はははいまでかけています」, my mother is out right now. On the phone, you will hear this often when someone is not home. To recap: exit plus set off, to go out, with the focus on leaving home.",
    ja: "{日曜日|にちようび}に[出かけました|でかけました|でかける]。",
    en: "I went out on Sunday." },
  "いっしょに|一緒に": {
    explain: "Two kanji, both with Chinese-origin readings, and then the particle 「に」 making it an adverb. The first is 「一|いち」, one. Here it shrinks to 「いっ」, with a small pause, before the next sound. You know it from 「一人|ひとり」, one person, 「一番|いちばん」, number one, and 「一日|いちにち」, one day. The second kanji, 「緒|しょ」, has the thread mark on the left and means a cord or string. A way to remember it: everyone tied together on one string. That is a hook, but the pieces really are one and cord. So doing something together is like being on the same thread. The most useful pattern is inviting someone. 「一緒に行きませんか|いっしょにいきませんか」 means won't you go with me. Asking with a negative like this sounds softer and friendlier than a direct question. You can also say who you are with by adding 「と」: 「友だちと一緒に|ともだちといっしょに」, together with a friend. To recap: one plus cord, tied together, doing things together.",
    ja: "[一緒に|いっしょに]{帰りましょう|かえりましょう}。",
    en: "Let's go home together." },
  "すごく|": {
    explain: "This word is usually written in kana. It comes from the adjective 「すごい」, amazing or incredible, which you will meet later. When an i-adjective changes its final 「い」 to 「く」, it becomes an adverb that can describe other words. So 「すごい」 becomes 「すごく」, and it means extremely or really. 「すごくおいしい」 means really delicious, and 「すごく難しい|すごくむずかしい」 means extremely difficult. It is casual and very common in conversation. In more formal speech or writing, 「とても」 is a safer choice for very. Here is something you will hear a lot. Young people often say 「すごいおいしい」, using the adjective form directly. That is everyday slang, but the standard form is 「すごく」. A fun fact. The adjective 「すごい」 originally meant eerie or dreadful, something that gives you chills. Over time it shifted to mean amazing, a bit like how English awesome went from fearsome to great. To recap: 「すごい」 turned into an adverb with 「く」, extremely, casual and common.",
    ja: "このケーキは[すごく]おいしいです。",
    en: "This cake is extremely delicious." },
  "だいじょうぶ|大丈夫": {
    explain: "Three kanji, all with Chinese-origin readings. 「大|だい」 means big, the person stretching out wide, as in 「大学|だいがく」, college. 「丈|じょう」 is an old measure of length, linked to a tall height. 「夫|ぶ」 means man. With its native reading 「おっと」, it means husband. The pair 「丈夫|じょうぶ」 on its own means sturdy, strong, or healthy. In Chinese, these three characters were used for a great, brave man, someone strong you could rely on. In Japanese it came to mean safe, sound, nothing to worry about. Like a strong man saying, I can handle it. Now the tricky part. 「大丈夫です|だいじょうぶです」 can mean I am fine. It can also be a polite no thanks. If a shop clerk offers a bag and you say 「大丈夫です|だいじょうぶです」, you mean you do not need one. Use tone and context to tell which. To recap: big, strong man, sturdy and safe, it's okay, and sometimes no thanks.",
    ja: "[大丈夫|だいじょうぶ]ですか。",
    en: "Are you okay?" },
  "とても|": {
    explain: "This word is usually written in kana. It means very, and it is the standard, polite choice. It goes in front of adjectives: 「とてもおいしい」, very delicious, 「とても静か|とてもしずか」, very quiet. It works well in both writing and polite speech. In casual talk, people often swap in 「すごく」. Here is something useful. With a negative, it has a special meaning, cannot possibly. 「とても食べられない|とてもたべられない」 means I cannot possibly eat it all. But for not very, Japanese uses a different word. You say 「あまり」 with a negative. So not very interesting is 「あまり面白くない|あまりおもしろくない」, not 「とても」 with a negative. That is a common mistake for English speakers who just translate very word for word. A way to remember it: think of a toe that is very, very sore, toe-te-mo. That is just a sound-alike hook. To recap: the standard very, with 「あまり」 for not very.",
    ja: "{今日|きょう}は[とても]{暑い|あつい}です。",
    en: "It's very hot today." },
  "どんな|": {
    explain: "This word is usually written in kana. It belongs to a family of words built on four starting sounds: 「こ」 for near me, 「そ」 for near you, 「あ」 for over there, and 「ど」 for the question. You already know the family from 「これ」, 「それ」, 「あれ」, 「どれ」, this, that, that over there, which one. In the same way, 「こんな」 is this kind of, 「そんな」 is that kind of, 「あんな」 is that kind of over there, and 「どんな」 is what kind of. It always comes right before a noun. 「どんな食べ物|どんなたべもの」, what kind of food. 「どんな人|どんなひと」, what kind of person. To answer, you usually describe with an adjective: 「やさしい人です|やさしいひとです」, a kind person. A common mistake is using 「なに」, what, when you really mean what kind. 「なに」 asks for the thing itself. 「どんな」 asks what it is like. To recap: the 「ど」 question member of the 「こそあど」 family, what kind of, always before a noun.",
    ja: "[どんな]{音楽|おんがく}が{好き|すき}ですか。",
    en: "What kind of music do you like?" },
  "〜まい|〜枚": {
    explain: "This is a counter, a word you attach to numbers when counting flat, thin things. Paper, tickets, photos, shirts, plates, stamps, slices of bread, all of these are counted with it. The kanji has 「木|き」, tree, on the left, so think of thin sheets cut from wood. That is a hook to remember it. It uses its Chinese-origin reading, 「まい」. The good news is that it is very regular. One sheet is 「一枚|いちまい」, two is 「二枚|にまい」, three is 「三枚|さんまい」. No tricky sound changes. To ask how many, say 「何枚|なんまい」. In Japanese, the counter usually comes after the thing and its particle: 「写真を三枚撮りました|しゃしんをさんまいとりました」, I took three photos. You will use this with 「写真|しゃしん」, photos, 「手紙|てがみ」, letters, and 「切符|きっぷ」, train tickets. English speakers often forget counters and just say the number. Japanese almost always needs one. To recap: tree on the left, thin sheets, the counter for flat things.",
    ja: "{写真|しゃしん}を[二枚|にまい|〜まい]{撮りました|とりました}。",
    en: "I took two pictures." },
  "やすみ|休み": {
    explain: "The kanji is one of the best pictures in Japanese. On the left is the person mark, and on the right is 「木|き」, tree. A person leaning against a tree, taking a break. Rest. It uses its native reading, 「やす」. This noun comes from the verb 「休む|やすむ」, to rest, or to be absent from school or work. So the word covers several ideas: a holiday, a day off, a break, and an absence. 「明日は休みです|あしたはやすみです」 means tomorrow is a day off. And if a classmate is absent, you might hear that they are off today, using this same word. You can attach it to seasons: 「夏休み|なつやすみ」, summer vacation, and 「冬休み|ふゆやすみ」, winter vacation. At lunch, workers and students have a 「昼休み|ひるやすみ」, the lunch break. A cultural note. Japan has many national holidays, and a cluster of them in spring, called Golden Week, when the whole country travels. To recap: a person resting against a tree, a break, a day off, or a holiday.",
    ja: "{明日|あした}は[休み|やすみ]です。",
    en: "Tomorrow is a day off." },
  "おみやげ|お土産": {
    explain: "This word has a special reading. The two kanji are read together as 「みやげ」, with polite 「お」 in front. The first kanji is 「土|ど」, earth or land. You know it from 「土曜日|どようび」, Saturday, the earth day. The second kanji means to produce or give birth. Put them together and you get the products of the land, things that a place is known for. That is exactly what a good souvenir is in Japan, a local specialty. Here is a big cultural note. Bringing back souvenirs is almost an obligation in Japan. When you travel, you bring back a box of local sweets for your coworkers or classmates. Train stations and airports have huge shops full of individually wrapped treats, made just for sharing. Every region has its famous gift, and people love comparing them. The souvenir is less about you, and more about sharing the trip with the people you left behind. To recap: products of the land, local specialties, the gifts you bring home to share.",
    ja: "{京都|きょうと}で[お土産|おみやげ]を{買いました|かいました}。",
    en: "I bought souvenirs in Kyoto." },
  "いそがしい|忙しい": {
    explain: "Look at the left side of the kanji. It is the narrow heart mark, used for feeling words. You will see it on 「怖い|こわい」, frightening, which you are learning in this lesson too. On the right is a kanji that means to lose or to perish. It is commonly remembered as losing your heart, being so rushed that you have no room for your feelings. Treat that as a hook. The word uses its native reading, 「いそが」. It is related to the verb 「急ぐ|いそぐ」, to hurry. You can hear the shared sound at the start. Busy and hurrying go together. It is an i-adjective. The past is 「忙しかった|いそがしかった」, and the negative is 「忙しくない|いそがしくない」. Its opposite is 「暇|ひま」, free and not busy. Use it for people and for days, like 「忙しい日|いそがしいひ」, a busy day. A cultural note. Saying you are busy is very common in Japan, and 「お忙しいところ|おいそがしいところ」 is a polite phrase used when thanking someone for their time, meaning while you are so busy. To recap: the heart mark plus to lose, busy, related to hurry.",
    ja: "{月曜日|げつようび}はとても[忙しい|いそがしい]です。",
    en: "Mondays are very busy." },
  "あける|開ける": {
    explain: "Start with the kanji 「開|あ」. The outer frame is 「門|もん」, a gate, the two swinging doors of an old gateway. Inside sits a shape usually explained as two hands lifting away the wooden bar that holds the doors shut. Hands lift the bar, the gate swings open. In this verb the kanji takes its native Japanese reading, 「あ」, and the 「ける」 is just written in hiragana. That gate frame is a great family marker. 「閉める|しめる」, to close, is the same gate with a bar stuck inside it. 「聞く|きく」, to listen, is a gate with an ear inside, like an ear pressed to the door. And 「時間|じかん」 has a gate with the sun inside, sunlight slipping through the gap. You open things with 「を」: 「まどをあける」, open the window, 「ドアをあける」, open the door. It is a verb where you do the opening to something. A way to remember it: when you open something, you often go ah, so 「あ」 starts the word. So, a gate with the bar lifted: 「あける」, and its partner with the bar locked in, 「しめる」.",
    ja: "{窓|まど}を[開けます|あけます|あける]。",
    en: "I'll open the window." },
  "でんき|電気": {
    explain: "Two kanji, both read with their Chinese-origin readings. The first, 「電|でん」, has the rain kanji on top, and underneath is a shape that stands for a flash of lightning. Rain plus lightning: electricity. The second, 「気|き」, means spirit, energy, or something in the air. You already know it from 「天気|てんき」, weather, and 「元気|げんき」, healthy and energetic. So 「でんき」 is lightning energy, electricity. In everyday speech, though, it very often just means the lights in a room. 「でんきをつけてください」 is please turn on the light, and 「でんきをけしてください」 is please turn it off. The 「電|でん」 part is a family on its own. 「電話|でんわ」 is electric talk, a telephone. 「電車|でんしゃ」 is an electric vehicle, a train. 「電池|でんち」 is an electric pond, a battery. Any time you hear 「でん」 at the start of a modern gadget word, think lightning. So, lightning plus energy, which in daily life means flipping the light switch.",
    ja: "[電気|でんき]をつけてください。",
    en: "Please turn on the light." },
  "まど|窓": {
    explain: "This one is a native Japanese word, written with a single kanji and no hiragana tail. Look at the top of the kanji. That roof with two little marks under it is the hole radical, the same top you find on the kanji for hole or cave. And a window, really, is just a hole cut into a wall to let in light and air. At the bottom you will see the heart shape, 「心|こころ」, which you also find in 「心配する|しんぱいする」, to worry. You do not need a story for the whole kanji. Just hole on top is enough to recognise it. You open and close windows with the verbs from this lesson: 「まどをあける」 and 「まどをしめる」. A classic classroom line is 「まどをあけてもいいですか」, may I open the window. A way to remember it: it sounds a bit like mad oh, so picture a mad face peeking through a hole in the wall. So, a hole in the wall that lets the light in: 「まど」.",
    ja: "[窓|まど]を{閉めて|しめて}ください。",
    en: "Please close the window." },
  "すわる|座る": {
    explain: "The kanji 「座|すわ」 is read with its native Japanese reading here. Look at it in layers. Across the top and down the left is a roof with a wall, a building shape. Under that roof is the ground, 「土|つち」, the same piece you see in 「土曜日|どようび」, Saturday. And sitting on that ground are two little people, 「人|ひと」, one on each side. Two people sitting on the ground under a roof: sitting. It is one of the easiest kanji pictures to see once someone points it out. The verb is a regular u-verb, so it becomes 「すわります」 and 「すわって」. In class you will hear 「すわってください」, please sit down, and you mark the seat with 「に」: 「いすにすわる」, sit on a chair. A cultural note: the formal way of kneeling on your heels on a tatami floor is called 「正座|せいざ」, proper sitting, and it uses this very kanji. Its opposite is 「たつ」, to stand. So, two people on the ground under a roof, settled down: 「すわる」.",
    ja: "ここに[座って|すわって|すわる]ください。",
    en: "Please sit here." },
  "たつ|立つ": {
    explain: "The kanji 「立|た」 is a picture of a person standing tall. At the top is the head, the middle strokes are arms spread out, and the long line at the bottom is the ground the person stands on. In this verb it takes its native reading, 「た」. The verb ends in 「つ」, so it conjugates like 「待つ|まつ」, to wait. You get 「たちます」 in polite form and 「たって」 in the te-form. That little doubled sound in 「たって」 is a common stumbling point, so say it out loud a few times. In class you will hear 「たってください」, please stand up, and it pairs naturally with 「すわってください」, please sit down. Japanese school days often begin with a student calling out for everyone to stand, bow, and sit. You will also see this kanji on the left side of other kanji you will meet later, always with that standing person shape. A way to remember it: the kanji even looks like someone standing on a little platform, ready to give a speech. So, a person standing on the ground with arms out: 「たつ」.",
    ja: "みなさん、[立って|たって|たつ]ください。",
    en: "Everyone, please stand up." },
  "にもつ|荷物": {
    explain: "Two kanji, both with readings worth noticing. The first, 「荷|に」, means a load or cargo, something you carry on your back or on a cart. On top it has the grass radical, and underneath is 「何|なに」, what, which mostly gives the kanji its sound. Think of it as bundles of straw being hauled around. The second kanji, 「物|もつ」, means thing. You know it well from 「食べ物|たべもの」, food, 「飲み物|のみもの」, drink, and 「買い物|かいもの」, shopping, where it is read with the native reading 「もの」. In 「動物園|どうぶつえん」, the zoo, it gets the Chinese-origin reading 「ぶつ」. Here it takes a rarer Chinese-origin reading, 「もつ」. Same thing kanji, new sound. Put them together and you get load things: bags, luggage, the stuff you are lugging around. A kind person might ask 「にもつをもちましょうか」, shall I carry your bags. And notice the lucky coincidence that the verb to carry is 「もつ」, the same sound as the end of this word. So, cargo plus things: the bags you carry, 「にもつ」.",
    ja: "[荷物|にもつ]を{持ちましょうか|もちましょうか}。",
    en: "Shall I carry your bags?" },
  "おふろ|お風呂": {
    explain: "The 「お」 at the front is the polite prefix, the same one in 「お金|おかね」 and 「おちゃ」. People almost always say the bath with it. The first kanji, 「風|ふ」, means wind. You know it from 「風邪|かぜ」, a cold, and 「台風|たいふう」, a typhoon. The second kanji, 「呂|ろ」, is mostly there for its sound. So in this word the kanji are best treated as spelling the sound rather than adding up to a meaning. Do not try to find wind in your bath. The cultural side is the real lesson here. A Japanese bath is for soaking, not for washing. You wash and rinse yourself outside the tub first, then climb into very hot, clean water to relax. Because everyone is already clean, the family often shares the same bathwater, one after another, and you never pull the plug when you get out. To take a bath, you enter it: 「おふろにはいる」. Many people bathe at night to unwind, and use a quick shower in the morning. So, polite 「お」 plus two sound-spelling kanji, for a deep, hot soak at the end of the day.",
    ja: "{毎晩|まいばん}[お風呂|おふろ]に{入ります|はいります}。",
    en: "I take a bath every night." },
  "シャワー|": {
    explain: "This comes straight from the English word shower. Watch how the sounds were squeezed into Japanese. The sh sound becomes 「シャ」, using a small 「ャ」 to make the blended sound. The ow in the middle turns into 「ワ」. And the er at the end, which Japanese does not have, simply becomes a long vowel, that dash 「ー」. You see the same long dash ending in 「コンピューター」, computer, and 「スーパー」, supermarket. English er endings very often turn into a stretched vowel like this. The meaning has not shifted at all, it is just the shower. The tricky part is the verb. In English you take a shower, but in Japanese you say 「シャワーをあびる」, which means to be poured over by a shower. Do not translate take with this word. A common daily rhythm in Japan is a quick 「シャワー」 in the morning and a proper 「おふろ」 at night. So, English shower with the er turned into a long vowel: 「シャワー」.",
    ja: "{朝|あさ}[シャワー]をあびます。",
    en: "I take a shower in the morning." },
  "きょうかしょ|教科書": {
    explain: "Three kanji, all with their Chinese-origin readings. The first, 「教|きょう」, means teach. It is the same kanji as in 「教える|おしえる」, to teach, where it has its native reading. You also find it in 「教室|きょうしつ」, a classroom, and 「教師|きょうし」, a schoolteacher. The second, 「科|か」, means a subject or field of study. On the left is the grain radical, and on the right is a measuring scoop, so you can picture sorting grain into separate piles, the way school sorts knowledge into subjects. You will find it in 「科学|かがく」, science. The third, 「書|しょ」, means writing or a book. Its native reading is in 「書く|かく」, to write. It also shows up in 「辞書|じしょ」, dictionary, 「図書館|としょかん」, library, and 「履歴書|りれきしょ」, a résumé. So the pieces add up to teaching, subject, book: a book that teaches a subject. Notice how many school words are hiding in here. Learning these three kanji gives you a whole cluster of classroom vocabulary. So, teach plus subject plus book: your 「きょうかしょ」.",
    ja: "[教科書|きょうかしょ]の{二十|にじゅう}ページを{見て|みて}ください。",
    en: "Please look at page twenty of the textbook." },
  "てつだう|手伝う": {
    explain: "Two kanji, both with native readings. The first is 「手|て」, hand. You know it from 「手紙|てがみ」, a letter, 「上手|じょうず」, skillful, and 「お手洗い|おてあらい」, the restroom, the place to wash your hands. The second, 「伝|つた」, means to pass along or to convey, like passing a message down a line. It has the person radical on the left. Here its sound softens from 「つた」 to 「つだ」 because it follows another word. That kind of softening happens a lot in compounds. So the word is literally to pass along your hands, which is exactly the English idea of lending a hand. You help someone with 「を」: 「ともだちをてつだう」, help a friend. A very useful phrase is 「てつだいましょうか」, shall I help. One thing to watch: this is for helping with a task, physically pitching in. It is a regular u-verb, so you get 「てつだいます」 and 「てつだって」. So, hands passed along to someone else: 「てつだう」, to lend a hand.",
    ja: "{友だち|ともだち}を[手伝いました|てつだいました|てつだう]。",
    en: "I helped my friend." },
  "かんじ|漢字": {
    explain: "Two kanji, both read with Chinese-origin readings, and this word is literally the name of the writing system. The first, 「漢|かん」, refers to the Han, the great Chinese dynasty of about two thousand years ago. It has the water radical on the left because the name originally belonged to the Han River, and the dynasty took its name from that region. Even today the Chinese call themselves the Han people. The second, 「字|じ」, means a written character or letter. On top is a roof, and underneath is 「子|こ」, child. A way to remember it: picture children in a schoolhouse practicing their characters. So the word adds up to Han characters, the characters of China. Japan borrowed this script about fifteen hundred years ago, then built 「ひらがな」 and 「カタカナ」 out of simplified kanji to write sounds that kanji alone handled clumsily. That is why one kanji can have both a Chinese-origin reading and a native Japanese reading. You will meet 「字|じ」 again whenever people talk about handwriting or letters. So, Han plus character: 「かんじ」, the characters Japan borrowed from China.",
    ja: "[漢字|かんじ]はむずかしいです。",
    en: "Kanji are difficult." },
  "ページ|": {
    explain: "This comes from the English word page. The vowel in page is a long a sound, which Japanese writes as 「ペ」 plus a long dash, 「ー」, stretching it out. Then the soft g at the end becomes 「ジ」, because Japanese words cannot end in a bare consonant like that, so a vowel gets added. That is the same reason English words like bridge or orange get extra vowels when they come into Japanese. The meaning is exactly the same as English. To say a page number, just put the number in front: 「じゅうページ」, page ten, and 「なんページですか」, what page is it. Teachers say this constantly in class, so it is worth hearing it as a chunk. A small trap: page ten and ten pages sound the same in Japanese. The context tells you which. Pair it with 「きょうかしょ」 for the classic classroom request: 「きょうかしょのじゅうページをみてください」. So, English page, stretched and given a final vowel: 「ページ」.",
    ja: "{十|じゅう}[ページ]を{読んで|よんで}ください。",
    en: "Please read page ten." },
  "つぎ|次": {
    explain: "This is a native Japanese word, read with the kanji's native reading. The kanji itself has a debated origin, so rather than tell a story, here is a hook. A way to remember it: the right half is the same piece you see on the right of 「歌|うた」, song, often explained as a person with an open mouth. Picture someone with their mouth open, calling out next. The grammar is the most useful part. 「つぎ」 is a noun, so to say next something, you link it with 「の」: 「つぎのでんしゃ」, the next train, 「つぎのページ」, the next page. It can also stand alone as a topic: 「つぎは、だれですか」, who is next. If you ride trains in Japan, you will hear it all day. The announcement 「つぎは」 followed by a station name tells you the next stop. One mistake to avoid: 「つぎ」 means next in a sequence, the one that follows. For next week or next year you use 「来|らい」 instead, as in 「来週|らいしゅう」 and 「来年|らいねん」. So, the one that comes after in line, joined with 「の」: 「つぎ」.",
    ja: "[次|つぎ]の{電車|でんしゃ}は{何時|なんじ}ですか。",
    en: "What time is the next train?" },
  "おかね|お金": {
    explain: "The 「お」 is the polite prefix, and people nearly always use it with money. Saying just 「かね」 sounds rough. The kanji 「金|かね」 means gold, or metal in general. In this word it has its native reading, 「かね」. Its Chinese-origin reading is 「きん」, which you know from 「金曜日|きんようび」, Friday, the day of metal or gold. A way to remember the shape: picture a little roof over the ground, with two nuggets of gold sparkling in the soil. So money is polite metal, a nice reminder that money started out as coins. The family is big. 「お金持ち|おかねもち」 is a money holder, a rich person. 「税金|ぜいきん」 is tax, and 「奨学金|しょうがくきん」 is a scholarship, both using the Chinese-origin reading. A very useful phrase is 「おかねがありません」, I have no money. You can also hear 「金|きん」 alone for gold, like a gold medal. So, gold or metal, made polite: 「おかね」.",
    ja: "[お金|おかね]がありません。",
    en: "I don't have any money." },
  "パソコン|": {
    explain: "This is a loanword from English, but one that has been chopped. It started as personal computer, which in full Japanese sounds would be long and clumsy. So Japanese took the first two sounds of personal, 「パソ」, and the first two of computer, 「コン」, and glued them together. You lose the r and the long vowels in the process. Japanese loves this four-sound chopping trick. 「エアコン」, air conditioner, is built the same way, and you will meet many more like it. The full word 「コンピューター」 also exists, but in daily life a laptop or desktop at home is a 「パソコン」. This word was made in Japan. An English speaker would not understand it, so do not use it abroad. You use it with the particle 「で」 when it is your tool: 「パソコンでしゅくだいをします」, I do my homework on the computer. So, the front of personal plus the front of computer: 「パソコン」.",
    ja: "[パソコン]で{日本語|にほんご}をべんきょうします。",
    en: "I study Japanese on my computer." },
  "エアコン|": {
    explain: "Another chopped English loanword. It comes from air conditioner. The air part became 「エア」. English air ends in an r sound that Japanese does not have, so it is just a vowel. Then conditioner was cut down to its first bit, 「コン」. Put them together and you get a short, punchy four-sound word, exactly the same trick as 「パソコン」, from personal computer. Once you spot the pattern, a lot of katakana words suddenly make sense. In Japan one unit often does both cooling and heating, so the same word covers your heater in winter too. You turn it on with 「つける」 and off with 「けす」, the same verbs as for lights: 「エアコンをつけてください」. Japanese summers are hot and humid, so expect to hear this word a lot from June to September. A way to remember it: air, plus the con from conditioner. So, English air conditioner, trimmed down to its first pieces: 「エアコン」.",
    ja: "あついですから、[エアコン]をつけます。",
    en: "It's hot, so I'll turn on the air conditioner." },
  "でんしゃ|電車": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「電|でん」, is electricity, rain on top with a lightning flash below. It is the same as in 「電気|でんき」, electricity or lights, and 「電話|でんわ」, the telephone. The second, 「車|しゃ」, means vehicle. The kanji is a picture of a cart seen from above: the box in the middle is the body, and the line through it is the axle with wheels at each end. On its own, with its native reading, it is 「車|くるま」, a car. With the Chinese-origin reading 「しゃ」 it appears in 「自転車|じてんしゃ」, a bicycle, a vehicle that turns by itself. So this word is electric vehicle, which in Japan means a train running on electric rails. Japan's commuter trains are famous for being on time to the minute. To say by train, use 「で」: 「でんしゃでいきます」. And for subways there is 「地下鉄|ちかてつ」. So, electricity plus vehicle: the 「でんしゃ」 you ride to work.",
    ja: "[電車|でんしゃ]で{大学|だいがく}に{行きます|いきます}。",
    en: "I go to college by train." },
  "くに|国": {
    explain: "This word uses the kanji's native reading, 「くに」. Look at the shape. The outer box is an enclosure, like a border or a city wall drawn around a territory. Inside is 「玉|たま」, a jewel. So you can see it as a treasure guarded inside borders: a country. The older form of this kanji had a different piece inside, and the jewel version is the modern simplified one, but the picture works well for today's kanji. The Chinese-origin reading is 「こく」, which often softens to 「ごく」 at the end of a word. You already know it from country names: 「中国|ちゅうごく」, China, and 「韓国|かんこく」, Korea. And from 「外国|がいこく」, a foreign country, an outside country, plus 「外国人|がいこくじん」, a foreigner, and 「外国語|がいこくご」, a foreign language. On its own, 「くに」 can mean country, but also your home region, where you are from. A polite way to ask someone's home country is 「おくにはどちらですか」. So, a jewel inside a border: 「くに」, your country or homeland.",
    ja: "{私|わたし}の[国|くに]はアメリカです。",
    en: "My country is America." },
  "こんしゅう|今週": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「今|こん」, means now or this present one. On its own, with its native reading, it is 「今|いま」, now. It also appears in 「今晩|こんばん」, tonight, 「今月|こんげつ」, this month, and 「今学期|こんがっき」, this semester. Watch out, because 「今日|きょう」 and 「今年|ことし」 use special readings, so not every word with this kanji starts with 「こん」. The second, 「週|しゅう」, means week. It has the movement radical on the left and bottom, and inside is a piece meaning to go around in a circuit. A week is a cycle that keeps coming around. So this word is simply this week. The real gift here is the pattern. 「先週|せんしゅう」 is last week, the week before. 「今週|こんしゅう」 is this week. 「来週|らいしゅう」 is next week, the coming week. Swap 「週|しゅう」 for 「月|げつ」 and you get last month, this month, and next month with the same front pieces. You also have 「毎週|まいしゅう」, every week, and 「週末|しゅうまつ」, the weekend, the week's end. So, now plus week: 「こんしゅう」, the middle of the last, this, next set.",
    ja: "[今週|こんしゅう]はいそがしいです。",
    en: "I'm busy this week." },
  "らいしゅう|来週": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「来|らい」, means to come. With its native reading it is the verb 「来る|くる」, to come. In time words it means the coming one, the one that is on its way. The second, 「週|しゅう」, means week, with the movement radical wrapped around a piece meaning to go around: a week cycles around. So this is the coming week, next week. The 「来|らい」 family is very regular. 「来月|らいげつ」 is next month, 「来年|らいねん」 is next year, and 「来学期|らいがっき」 is next semester. Even 「将来|しょうらい」, the future, uses it, the time that is about to come. Line it up with its partners: 「先週|せんしゅう」, last week, 「今週|こんしゅう」, this week, and 「来週|らいしゅう」, next week. Like other time words, it usually does not need a particle: 「らいしゅう、きょうとにいきます」 works fine. A common slip is using 「つぎのしゅう」 for next week. People understand it, but 「らいしゅう」 is the natural word. So, the coming week: 「らいしゅう」.",
    ja: "[来週|らいしゅう]、{京都|きょうと}に{行きます|いきます}。",
    en: "I'll go to Kyoto next week." },
  "らいねん|来年": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「来|らい」, means coming, the same kanji as the verb 「来る|くる」, to come. In time words it marks the next one. The second, 「年|ねん」, means year. You know it from counting years with 「〜年|ねん」, and its native reading appears in 「年上|としうえ」, someone older, someone above you in years. Put them together and it is the coming year, next year. It slots straight into the same pattern as 「来週|らいしゅう」, next week, and 「来月|らいげつ」, next month. One small twist: for this year, Japanese does not say 「こんねん」. It uses a special reading, 「今年|ことし」. So the set you want to remember is 「ことし」, this year, and 「らいねん」, next year. A cultural note: around New Year, people say 「らいねんもよろしくおねがいします」 at the end of December, asking for continued good relations in the coming year. Like other time words, it usually works without a particle. So, the coming year: 「らいねん」.",
    ja: "[来年|らいねん]、{日本|にほん}に{行きます|いきます}。",
    en: "I'll go to Japan next year." },
  "よる|夜": {
    explain: "This is a native Japanese word, using the kanji's native reading. If you look closely at the kanji, tucked inside on the right is a shape like 「夕|ゆう」, the evening kanji, often described as a crescent moon. So there is a moon hiding in the night. That is a good thing to look for when you are trying to recognise it. The Chinese-origin reading is 「や」, which you will meet in words like 「今夜|こんや」, tonight. Learn it with the other times of day: 「あさ」, morning, 「ひる」, midday, and 「よる」, night. You know two of them already in meals: 「朝ご飯|あさごはん」, breakfast, and 「昼ご飯|ひるごはん」, lunch. Now for a useful contrast. 「晩|ばん」 also means evening or night, as in 「今晩|こんばん」, tonight, 「毎晩|まいばん」, every night, and 「晩ご飯|ばんごはん」, dinner. 「ばん」 leans toward evening, the time you eat dinner, while 「よる」 covers the dark hours, including late at night. To say at night, add 「は」 or 「に」 depending on the sentence: 「よるはテレビをみます」. So, a moon tucked inside the kanji: 「よる」, the night.",
    ja: "[夜|よる]はテレビを{見ます|みます}。",
    en: "I watch TV at night." },
  "たいへん|大変": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「大|たい」, means big. It is a picture of a person with arms and legs stretched out wide. It has several readings: 「だい」 in 「大学|だいがく」, college, 「おお」 in 「大きい|おおきい」, big, and here 「たい」. The second, 「変|へん」, means change, or strange, something out of the ordinary. So the word is a big change, a big upheaval, which is how it comes to mean a tough or terrible situation. The most useful phrase is 「たいへんですね」. You say it when someone tells you something hard, like working every day or having three tests. It means that sounds rough, and it is a key way to show sympathy in Japanese conversation. You can also say 「たいへんでした」 about something tough you went through. In formal speech it can also mean very, as in 「たいへんありがとうございます」, but for now focus on tough. It is a na-adjective, so before a noun it takes 「な」: 「たいへんなしごと」, a hard job. So, a big change in your life: 「たいへん」, and when someone is struggling, 「たいへんですね」.",
    ja: "{毎日|まいにち}アルバイトです。[大変|たいへん]です。",
    en: "I work my part-time job every day. It's tough." },
  "あそぶ|遊ぶ": {
    explain: "The kanji is read with its native reading, 「あそ」. Look at the bottom left. That swooping line is the movement radical, the same one in 「週|しゅう」, week, and 「返す|かえす」, to return. It is often used for going places, so you can picture wandering around for fun. The verb is a u-verb ending in 「ぶ」, so you get 「あそびます」 and, in the te-form, 「あそんで」. Now the most important part, a mistake English speakers make all the time. In English, play covers games, sports, and music. In Japanese, 「あそぶ」 does not. For sports you use 「する」, as in 「テニスをする」. For instruments you use a different verb, 「ひく」, as in 「ピアノをひく」. 「あそぶ」 is for children playing, and for adults hanging out and having a good time with friends: 「ともだちとあそびます」. A very friendly invitation is 「あそびにきてください」, please come visit and hang out. So, wandering around for fun with friends: 「あそぶ」, not sports and not music.",
    ja: "{友だち|ともだち}と[遊びます|あそびます|あそぶ]。",
    en: "I hang out with my friends." },
  "いそぐ|急ぐ": {
    explain: "The kanji 「急|いそ」 is read here with its native reading. At the bottom of the kanji sits 「心|こころ」, heart, the same piece you see in 「心配する|しんぱいする」, to worry. A way to remember it: picture your heart racing when you are running late. The Chinese-origin reading is 「きゅう」, and you already know it from 「急に|きゅうに」, suddenly. Something sudden and something hurried share the same feeling of a heart that will not slow down. The verb is a u-verb ending in 「ぐ」, and those have a special te-form: 「いそいで」, not with a 「て」 but with a 「で」. The polite form is 「いそぎます」. You will hear 「いそいでください」, please hurry, and the opposite, very useful phrase 「いそがなくてもいいです」, you do not have to hurry. Its natural opposite in this lesson is 「ゆっくり」, slowly and unhurriedly. So, a racing heart: 「いそぐ」, to hurry.",
    ja: "[急いで|いそいで|いそぐ]ください。",
    en: "Please hurry." },
  "かえす|返す": {
    explain: "The kanji 「返|かえ」 is read with its native reading. On the bottom left is the movement radical, and inside is a piece meaning to turn back or to flip over. So it is a movement that turns back around: returning. Its Chinese-origin reading is 「へん」, which you know from 「返事|へんじ」, a reply, words sent back. And 「お返し|おかえし」 is a return gift, given back to say thanks. Now the key contrast. 「帰る|かえる」, to go home, sounds almost the same and also means going back. The difference is who or what goes back. With 「かえる」, you yourself go back home. With 「かえす」, you send a thing back to someone. So you 「かえる」 to your house, but you 「かえす」 a book to the library. You mark what you return with 「を」 and the person with 「に」: 「ともだちにほんをかえす」. It pairs naturally with 「借りる|かりる」, to borrow. First you borrow, then you return. So, a movement that turns back, applied to a thing: 「かえす」.",
    ja: "{本|ほん}を[返します|かえします|かえす]。",
    en: "I'll return the book." },
  "けす|消す": {
    explain: "The kanji 「消|け」 is read here with its native reading. On the left are three drops of water, the water radical. On the right is a piece that means small or diminishing. So you can picture water making something smaller and smaller until it is gone, the way water puts out a fire. Its Chinese-origin reading is 「しょう」, and you know it from 「消防士|しょうぼうし」, a firefighter, someone who fights fires. That is a perfect sibling, since putting out fires is exactly the image of this kanji. In daily life, the verb covers anything you make disappear. You turn off the lights, 「でんきをけす」, the TV, 「テレビをけす」, and the air conditioner, 「エアコンをけす」. You also erase writing from a board or a page with it. The opposite, to turn things on, is 「つける」. It is a u-verb, so you get 「けします」 and 「けして」. So, water putting out a fire: 「けす」, to make something go off or go away.",
    ja: "{電気|でんき}を[消して|けして|けす]ください。",
    en: "Please turn off the light." },
  "しぬ|死ぬ": {
    explain: "The kanji 「死|し」 is read 「し」 here. On the left is a radical that stands for bones or remains. On the right is a small shape for a person, often described as someone kneeling or fallen. Bones beside a person: death. It is a heavy kanji, but a clear one. The grammar point is why the textbook includes this word so early. This is the only common modern verb that ends in 「ぬ」. So it is the model for that whole row. Its polite form is 「しにます」, and its te-form is 「しんで」, following the same pattern as 「よむ」 becoming 「よんで」 and 「あそぶ」 becoming 「あそんで」. If you can conjugate 「しぬ」, you have mastered the 「ぬ」 row in one go. A cultural note on politeness: when talking about a person's death, Japanese speakers usually prefer the softer 「なくなる」, to pass away. 「しぬ」 is fine for pets, characters in stories, and grammar practice, but it can sound blunt about people. You will also hear it in jokes, like saying you are dying of hunger. So, bones beside a person, and the one verb ending in 「ぬ」: 「しぬ」.",
    ja: "{私|わたし}の{犬|いぬ}が[死にました|しにました|しぬ]。",
    en: "My dog died." },
  "たばこをすう|たばこを吸う": {
    explain: "This is a set phrase: 「たばこ」, tobacco or cigarettes, plus 「を」, plus the verb 「吸う|すう」, to inhale. First, 「たばこ」. It is a loanword, but an old one from Portuguese, tabaco, brought by Portuguese traders in the fifteen hundreds. Because it arrived so long ago, it is usually written in hiragana, like a native word. Now the kanji 「吸|す」, read with its native reading. On the left is the mouth radical, 「口|くち」, mouth. So it is something you do with your mouth: suck in or breathe in. The verb also works for breathing in air and for sucking through a straw. So Japanese does not have a single word for smoking. You literally breathe in tobacco. It is a u-verb, so you get 「すいます」 and 「すって」. A very common question is 「たばこをすってもいいですか」, may I smoke. And a sign or rule might say 「ここでたばこをすってはいけません」. In Japan, smoking is often limited to special smoking areas, so look for those. So, an old Portuguese loanword plus a mouth verb: 「たばこをすう」.",
    ja: "ここで[たばこを吸っては|たばこをすっては|たばこをすう]いけません。",
    en: "You must not smoke here." },
  "つかう|使う": {
    explain: "The kanji 「使|つか」 is read with its native reading. On the left is the person radical, a person standing sideways. The right side is a piece connected with officials and duties. Historically the kanji had to do with a person you send on an errand, someone you put to use. From there the meaning widened to using anything at all. So 「つかう」 is to put something or someone to work for you. You mark the thing you use with 「を」: 「パソコンをつかう」, use a computer, 「はしをつかう」, use chopsticks. A very handy phrase is 「つかってもいいですか」, may I use it, perfect for borrowing a pen or a phone. It is a u-verb ending in 「う」, so you get 「つかいます」 and the te-form 「つかって」, with that little doubled sound. A way to remember it: you often need help catching a tool you use, so think of catching and using. So, a person put to work on a task: 「つかう」, to use.",
    ja: "パソコンを[使っても|つかっても|つかう]いいですか。",
    en: "May I use the computer?" },
  "はいる|入る": {
    explain: "The kanji 「入|はい」 is read with its native reading here. It is only two strokes, and it looks like an arrow pointing in or a wedge pushing into an opening. Be careful not to mix it up with 「人|ひと」, person. The person kanji leans the other way. The same kanji has another native reading, 「い」, in 「入れる|いれる」, to put something in. You enter, or you put something inside. Now for the grammar. Mark the place you go into with 「に」: 「へやにはいる」, enter the room. Japanese also uses it in some surprising set phrases. 「おふろにはいる」 is to take a bath, literally to enter the bath. And 「保険に入る|ほけんにはいる」 is to buy insurance, entering an insurance plan. Here is a big trap. It ends in 「いる」, so it looks like a ru-verb, but it is actually a u-verb. So the forms are 「はいります」 and 「はいって」, with that doubled sound. So, an arrow pointing in: 「はいる」, to enter.",
    ja: "{部屋|へや}に[入って|はいって|はいる]ください。",
    en: "Please come into the room." },
  "もつ|持つ": {
    explain: "The kanji 「持|も」 is read with its native reading. On the left is the hand radical, a squished form of the hand kanji. The right side mostly gives the sound. So the meaning lives in that hand: holding something in your hand. The verb ends in 「つ」, so its forms are 「もちます」 and 「もって」. You carry or hold things with 「を」: 「にもつをもつ」, carry the bags. Notice that 「荷物|にもつ」 ends with the same sound, a happy coincidence. Now the important twist. 「もっています」 often means to own or to have, not just holding right now. 「くるまをもっています」 is I own a car. The family is very useful. 「持ってくる|もってくる」 is to bring a thing, hold it and come. 「持っていく|もっていく」 is to take a thing along, hold it and go. And 「お金持ち|おかねもち」 is a money holder, a rich person. So, a hand gripping something: 「もつ」, to hold, to carry, and to own.",
    ja: "{荷物|にもつ}を[持ちます|もちます|もつ]。",
    en: "I'll carry the bags." },
  "やすむ|休む": {
    explain: "This is one of the classic kanji pictures. The kanji 「休|やす」 is a person, the person radical on the left, leaning against a tree, 「木|き」, on the right. Someone resting against a tree on a hot day: taking a break. In this verb it has its native reading, 「やす」. The noun form, 「休み|やすみ」, means a holiday, a day off, a break, or an absence. Think of summer holidays and lunch breaks. Now the meaning that surprises English speakers. 「やすむ」 does not only mean to rest. It also means to be absent, to skip or take a day off. You mark what you skip with 「を」: 「がっこうをやすむ」, to miss school, 「アルバイトをやすむ」, to take a day off from your job. If you are sick, you might say 「きょうはやすみます」, I am taking today off. It is a u-verb ending in 「む」, so you get 「やすみます」 and 「やすんで」. So, a person leaning on a tree: 「やすむ」, to rest, or to take a day away.",
    ja: "{今日|きょう}は{学校|がっこう}を[休みます|やすみます|やすむ]。",
    en: "I'm skipping school today." },
  "しめる|閉める": {
    explain: "The kanji 「閉|し」 is read with its native reading. The outer frame is 「門|もん」, a gate. Inside sits a piece that looks like a bar or a bolt jammed across the doors. So it is a gate with the bar in place: closed. Its partner is 「開ける|あける」, to open, the same gate with the bar being lifted out. Learning them as a pair makes both easy, since they share the gate and only the inside differs. Other gate kanji you know include 「聞く|きく」, to listen, with an ear at the gate, and 「時間|じかん」, with the sun shining through. You close things with 「を」: 「まどをしめる」, close the window, and 「ドアをしめる」, close the door. It is a ru-verb, so you get 「しめます」 and 「しめて」. 「しめてください」 is please close it. A small heads up: there is a similar verb, 「しまる」, where the door closes on its own. 「しめる」 is when you close it. So, a gate with the bar locked in: 「しめる」, to close.",
    ja: "ドアを[閉めて|しめて|しめる]ください。",
    en: "Please close the door." },
  "おしえる|教える": {
    explain: "The kanji 「教|おし」 is read with its native reading here. Its Chinese-origin reading is 「きょう」, and that opens up a whole family of school words. 「教科書|きょうかしょ」 is a textbook, a book that teaches a subject. 「教室|きょうしつ」 is a classroom, a teaching room. And 「教師|きょうし」 is a schoolteacher. So whenever you see this kanji, think teaching. Now the grammar. The person you teach takes 「に」, and the thing you teach takes 「を」. 「ともだちにえいごをおしえる」 is to teach English to a friend. It is a ru-verb, so the forms are 「おしえます」 and 「おしえて」. Here is a meaning English speakers often miss. 「おしえる」 also means to tell or to let someone know, especially information. 「でんわばんごうをおしえてください」 is please tell me your phone number. In English you would never say teach me your number, but in Japanese it is completely natural. So, the teaching kanji: 「おしえる」, to teach, and also to tell someone what they want to know.",
    ja: "{先生|せんせい}は{日本語|にほんご}を[教えます|おしえます|おしえる]。",
    en: "The teacher teaches Japanese." },
  "わすれる|忘れる": {
    explain: "The kanji 「忘|わす」 is read here with its native reading. It is built from two pieces stacked on top of each other. On top is 「亡|ぼう」, which means lost, gone, or perished. On the bottom is 「心|こころ」, heart or mind, the same piece you see in 「心配する|しんぱいする」, to worry, and 「急ぐ|いそぐ」, to hurry. Gone from the mind: forgetting. It is one of those kanji where the parts tell the story very honestly. It is a ru-verb, so you get 「わすれます」 and 「わすれて」. Now the second meaning. In Japanese, 「わすれる」 also covers leaving something behind by accident. 「かさをわすれました」 can mean I forgot my umbrella, as in I left it at home or on the train. The classic school excuse is 「しゅくだいをわすれました」, I forgot my homework. A friendly reminder is 「わすれないでください」, please do not forget. So, something lost from the heart: 「わすれる」, to forget, or to leave behind.",
    ja: "{宿題|しゅくだい}を[忘れました|わすれました|わすれる]。",
    en: "I forgot my homework." },
  "おりる|降りる": {
    explain: "The kanji 「降|お」 is read with its native reading here. On the left is the hill radical, a shape that stands for a mound or a slope. On the right is a piece usually explained as two feet stepping downward. So you can picture feet going down a hill: descending, coming down. The same kanji has another native reading in 「降る|ふる」, which is used for rain or snow falling: 「あめがふる」. Rain comes down from the sky, and you come down off a train. Same kanji, same downward movement. Now the grammar, which is where people trip. You get off something with 「を」: 「でんしゃをおりる」, get off the train. Its opposite, 「乗る|のる」, to get on, uses 「に」: 「でんしゃにのる」. So the pair is 「にのる」 and 「をおりる」. Learn them as a set. It is a ru-verb, so you get 「おります」 and 「おりて」. So, feet stepping down a hill: 「おりる」, to get off.",
    ja: "{電車|でんしゃ}を[降ります|おります|おりる]。",
    en: "I'll get off the train." },
  "かりる|借りる": {
    explain: "The kanji 「借|か」 is read with its native reading. On the left is the person radical. On the right is a piece meaning long ago, which mostly gives the kanji its sound. A way to remember it: you borrow from a person, so a person stands at the side. Here is the big trap. 「かりる」 is to borrow, to receive something for a while. Its opposite, 「貸す|かす」, is to lend, to give something for a while. They even sound alike, so mixing them up is the most common mistake. A way to remember it: in 「かりる」 the item comes to me. In 「かす」 it goes away from me. The person you borrow from takes 「に」 or 「から」: 「ともだちにほんをかりる」, borrow a book from a friend. It pairs naturally with 「返す|かえす」, to return. First you 「かりる」, then you 「かえす」. It is a ru-verb, so you get 「かります」 and 「かりて」. A useful request is 「かりてもいいですか」, may I borrow it. So, something that comes to you for a while: 「かりる」, to borrow.",
    ja: "{図書館|としょかん}で{本|ほん}を[借ります|かります|かりる]。",
    en: "I borrow books at the library." },
  "シャワーをあびる|シャワーを浴びる": {
    explain: "This phrase is 「シャワー」, from English shower, plus 「を」, plus the verb 「浴びる|あびる」. The kanji 「浴|あ」 is read with its native reading. On the left are three drops of water, the water radical. The verb means to be poured over, to bathe in, to be showered with something. So in Japanese you do not take a shower. You pour the shower over yourself, or soak it up. That is why 「シャワーをとる」 is wrong, a very common mistake for English speakers. Always use 「あびる」. The same verb shows up with other things that pour over you, like soaking up sunlight. A sibling worth knowing: the light cotton summer kimono, 「浴衣|ゆかた」, uses this kanji. It began as a robe worn after bathing. It is a ru-verb, so you get 「シャワーをあびます」 and 「シャワーをあびて」. Compare the bath: for 「おふろ」 you use 「はいる」, to enter. For 「シャワー」 you use 「あびる」, to be poured over. So, water poured over you: 「シャワーをあびる」.",
    ja: "{毎朝|まいあさ}[シャワーを浴びます|シャワーをあびます|シャワーをあびる]。",
    en: "I take a shower every morning." },
  "つける|": {
    explain: "This verb is usually written in hiragana, which is how you will see it most often. It is for switching something on: lights, the TV, the air conditioner, a heater. 「でんきをつける」 is to turn on the light, and 「テレビをつける」 is to turn on the TV. Its opposite is 「消す|けす」, to turn off, so learn them as a pair: 「つける」 and 「けす」. Here is the grammar point. It is a ru-verb, so you get 「つけます」 and 「つけて」. 「つけてください」 is please turn it on. Be careful not to confuse it with 「つく」, where the light comes on by itself. 「つける」 is when you do it. A useful fact: the same sound 「つける」 also means to attach or to stick something on, written with different kanji. That is a good memory hook. A way to remember it: picture attaching power to a lamp, and on it goes. So the light comes on when you 「つける」, and goes off when you 「けす」.",
    ja: "テレビを[つけて|つけて|つける]ください。",
    en: "Please turn on the TV." },
  "でんわする|電話する": {
    explain: "This is the noun 「電話|でんわ」, telephone, plus 「する」, to do. 「電話|でんわ」 has two kanji with Chinese-origin readings. 「電|でん」 is electricity, rain on top with a flash of lightning below. You know it from 「電気|でんき」 and 「電車|でんしゃ」. 「話|わ」 means talk. On the left is the speech radical, words coming out of a mouth, and on the right is 「舌|した」, tongue. Its native reading is in the verb 「話す|はなす」, to speak. So a telephone is electric talk, and doing electric talk is calling someone. Adding 「する」 to a noun to make a verb is a huge pattern in Japanese. You will see it again with 「しんぱいする」 and many more. Here is the grammar. The person you call takes 「に」: 「ともだちにでんわする」, call a friend. Do not use 「を」 for the person. That is a common mistake. A very useful line is 「あとででんわします」, I will call you later. So, electric talk plus do: 「でんわする」, to call.",
    ja: "{友だち|ともだち}に[電話します|でんわします|でんわする]。",
    en: "I'll call my friend." },
  "つれてくる|連れてくる": {
    explain: "This is the te-form of 「連れる|つれる」, to take along, plus 「くる」, to come. The kanji 「連|つ」 is read with its native reading. Inside is 「車|くるま」, a cart or vehicle, and wrapped around it is the movement radical. A way to see it: carts rolling along one after another, things moving in a line together. So 「つれる」 is to go along with someone, to take them with you. Then 「くる」 adds the direction, toward here. Together it means to come with someone, to bring a person here. The big rule is the split between people and things. For people and animals, use 「つれてくる」: 「ともだちをつれてくる」, bring a friend. For objects, use 「持ってくる|もってくる」 instead. It also flips direction with 「いく」: 「連れていく|つれていく」 is to take someone there. The 「くる」 part conjugates irregularly, so you get 「つれてきます」 and 「つれてきました」. So, moving along together and coming here: 「つれてくる」, to bring a person.",
    ja: "{友だち|ともだち}を[連れてきます|つれてきます|つれてくる]。",
    en: "I'll bring a friend." },
  "もってくる|持ってくる": {
    explain: "This is two verbs joined: 「持つ|もつ」, to hold or carry, in its te-form, plus 「くる」, to come. The kanji 「持|も」 has the hand radical on the left, a hand holding something. So the phrase literally means hold it and come: bring a thing here. The te-form here works like and then. You pick it up, and then you come. Now the key rule. This is for things only. For people and animals you use 「連れてくる|つれてくる」. So you 「もってくる」 an umbrella, but you 「つれてくる」 a friend. The direction also matters. 「もってくる」 is toward where the speaker is. 「持っていく|もっていく」 is taking it away from here, over there. If a friend asks you to a party, you might ask 「なにをもっていきましょうか」, what shall I take. The host might answer 「のみものをもってきてください」, please bring drinks. The 「くる」 part is irregular, so you get 「もってきます」 and 「もってきました」. So, hold it and come: 「もってくる」, to bring a thing.",
    ja: "{傘|かさ}を[持ってきて|もってきて|もってくる]ください。",
    en: "Please bring an umbrella." },
  "あとで|後で": {
    explain: "This is 「後|あと」, after, plus the particle 「で」. The kanji 「後|あと」 is read with its native reading here. On the left is a radical connected with walking along a road. A way to remember it: picture someone walking behind, coming after the others. The same kanji has a Chinese-origin reading, 「ご」. You know it from 「ごご」, afternoon, which is written 「午後|ごご」, after noon. You also have 「〜後|ご」 for in a certain amount of time, and 「後|あと」 on its own for after an event. Its other native reading is 「うしろ」, behind, so after in time and behind in space share a kanji. Now the usage. 「あとで」 means later, at some unspecified time after now. 「あとででんわします」 is I will call you later, and 「じゃあ、またあとで」 is see you later. A common slip is to say 「あと」 alone for later. You need the 「で」 to make it later on. So, after plus 「で」: 「あとで」, later on.",
    ja: "[後で|あとで]{電話します|でんわします}。",
    en: "I'll call you later." },
  "すぐ|": {
    explain: "This little word is usually written in hiragana and sits right before the verb it describes. 「すぐいきます」 is I will go right away, and 「すぐきてください」 is please come right away. You will also often hear it with 「に」 added, 「すぐに」, with the same meaning. It can also describe distance, meaning very close by: 「えきはすぐそこです」, the station is right over there. And it has a very useful relative, 「もうすぐ」, very soon or in a few moments. 「もうすぐなつやすみです」 is summer vacation is just around the corner. In a shop or restaurant, staff often say 「すぐおもちします」, I will bring it right away, so it is worth recognising. A way to remember it: it sounds like Sue goes, and Sue always goes immediately. It is quick to say, which suits its meaning. So, no waiting at all: 「すぐ」.",
    ja: "[すぐ]{行きます|いきます}。",
    en: "I'll go right away." },
  "ゆっくり|": {
    explain: "This word is usually written in hiragana, and it describes doing something without rushing. Listen to the small 「っ」 in the middle. It creates a tiny pause, almost as if the word itself is slowing down. A way to remember it: say it slowly and let that pause hang in the air. It has two main uses. The first is slowly. 「ゆっくりはなしてください」, please speak slowly, is a lifesaver for learners. Use it often. The second is leisurely, relaxed, taking your time. A host might say 「ゆっくりしてください」, please make yourself at home. And on a day off you might say 「きょうはゆっくりやすみます」, I will take it easy and rest today. So it is not only about speed. It is also about a calm, unhurried feeling, which is why it sounds warm and kind. It is the natural opposite of 「急ぐ|いそぐ」, to hurry, and of 「すぐ」, right away. So, the word with a built-in pause: 「ゆっくり」, slowly and with time to breathe.",
    ja: "[ゆっくり]{話して|はなして}ください。",
    en: "Please speak slowly." },
  "けっこうです|結構です": {
    explain: "Two kanji, both with Chinese-origin readings, plus 「です」. 「結|けつ」 means to tie or to join, and its sound shortens to 「けっ」 here. 「構|こう」 means to build or to put together. The original sense of the compound was the way something is put together, its structure. From well put together, it came to mean fine, splendid, or quite enough. Now the tricky part. In daily life 「けっこうです」 is very often a polite no thank you. If someone offers more tea and you say 「けっこうです」, you mean I am fine, I have enough. But it can also mean that is fine, that is acceptable, as in 「それでけっこうです」, that will do. So tone, gesture, and context tell you which. A small wave of the hand usually means no thanks. If you want to make a no thank you clear, add 「いいえ」 first. Learners sometimes accept something by saying 「けっこうです」 and then get nothing, so be careful. So, well put together, enough: 「けっこうです」, I am fine as I am.",
    ja: "おちゃは[結構です|けっこうです]。",
    en: "No tea for me, thank you." },
  "ほんとうですか|本当ですか": {
    explain: "This is 「本当|ほんとう」, truth, plus 「ですか」, is it. 「本|ほん」 is a tree, 「木|き」, with an extra mark near its base, pointing to the root. So its core meaning is root, origin, or the real thing. You know it from 「日本|にほん」, the sun's origin, and of course 「本|ほん」, book. 「当|とう」 means to hit the mark, to be on target or correct. Together, 「ほんとう」 is the real, on-target thing: the truth. Asking 「ほんとうですか」 is asking is that the truth, which is how Japanese says really. Use it when you are surprised by news: 「あしたテストですか。ほんとうですか」. With friends, it gets shortened to 「ほんと」 or 「ほんとに」, often with rising intonation. It also works as an adverb, 「ほんとうに」, meaning truly or really, as in 「ほんとうにありがとう」, thank you so much. So, the root of the matter, hitting the mark: 「ほんとうですか」, really.",
    ja: "あしたテストですか。[本当ですか|ほんとうですか]。",
    en: "There's a test tomorrow? Really?" },
  "めがね|": {
    explain: "This word is usually written in hiragana, though it does have kanji, 「眼鏡|めがね」. The kanji are eye and mirror, so you can picture a mirror or lens for your eyes. They have a special set reading for the whole word rather than reading each kanji on its own. You already know the eye part in its plain form, 「目|め」, eye. Now the important verb. You do not wear glasses with 「きる」 like clothes. You use 「かける」, to hang. Glasses hang on your ears and nose, so 「めがねをかける」 is to put on glasses. To describe someone who wears glasses, you say 「めがねをかけています」. Japanese has different wearing verbs for different parts of the body, so this is a good one to remember as a set phrase. A fun extra: sunglasses are 「サングラス」, a loanword, and they also take 「かける」. So, eye mirrors that hang on your face: 「めがね」, with 「かける」.",
    ja: "{父|ちち}は[めがね]をかけています。",
    en: "My father wears glasses." },
  "うたう|歌う": {
    explain: "The kanji 「歌|うた」 is read here with its native reading, and it is the same kanji as the noun 「歌|うた」, song. Look at its right side. That shape is usually explained as a person with a wide open mouth, the kind you see in kanji about breathing or singing out. The left side gives the sound. So the kanji is someone opening their mouth wide to let a song out. The Chinese-origin reading is 「か」. You know it from 「歌手|かしゅ」, a singer, a song person, and 「歌舞伎|かぶき」, kabuki, which uses song, dance, and skill. The verb is a u-verb, so the forms are 「うたいます」 and 「うたって」. You sing a song with 「を」: 「うたをうたう」. Yes, the word repeats, and that is totally natural. And a cultural note you will love: karaoke is a Japanese invention, and its name, 「カラオケ」, means empty orchestra, music with no singer. So a night out often ends with everyone taking turns to 「うたう」. So, an open mouth letting a song out: 「うたう」.",
    ja: "カラオケで[歌います|うたいます|うたう]。",
    en: "I sing at karaoke." },
  "かみ|髪": {
    explain: "This kanji is built from two parts. The whole top half is a radical that means long hair. If you look closely at its upper left, you can see the same shape as 「長い|ながい」, long, with three slanting strokes beside it, like strands of hair streaming out. The reading here is the native Japanese one. Now, a warning and a gift at the same time. The word sounds exactly like 「紙|かみ」, paper, the same 「紙|がみ」 you know from 「手紙|てがみ」, a letter. Only the kanji and the context tell them apart. A way to remember it: picture someone writing a letter on paper with a single long hair as the pen. To describe someone's hair, use 「が」 with an adjective: 「かみがながい」, has long hair, or 「かみがみじかい」, has short hair. So: long-hair radical on top, sounds like paper, and you describe it with 「が」.",
    ja: "{姉|あね}は[髪|かみ]が{長い|ながい}です。",
    en: "My older sister has long hair." },
  "め|目": {
    explain: "The kanji is a real picture of an eye. Imagine an eye drawn sideways, with the pupil in the middle, and then stood up on end to save space. That is why it is a tall box with two lines inside. The reading here is the native one. Two family words help it stick. First, look at the kanji 「見る|みる」, to see. Its top half is this very eye, sitting on a pair of legs: an eye walking around, looking at things. Second, the counter 「一日目|いちにちめ」, the first day, uses the same kanji for the idea of number so-and-so in a row. And you can hear the eye sound at the start of 「めがね」, glasses, things for your eyes. When describing people, use 「が」: 「めがおおきい」, has big eyes. So: a picture of an eye, the top of seeing, and the start of glasses.",
    ja: "{妹|いもうと}は[目|め]が{大きい|おおきい}です。",
    en: "My younger sister has big eyes." },
  "くち|口": {
    explain: "This is one of the easiest kanji in the language. It is simply a picture of an open mouth, drawn as a square. The reading here is the native one. The fun part is how often this little box hides inside other kanji, nearly always connected to speaking, eating or making sound. Look at 「歌|うた」, song. On its left side you can find little mouths stacked up, singing away. Look at 「兄|あに」, older brother. It is a big mouth sitting on top of legs. And 「知る|しる」, to know, has an arrow on the left and a mouth on the right. Whenever you spot this square inside a bigger kanji, think about the mouth first. To describe people, use 「が」, as in 「くちがおおきい」, has a big mouth, which is a physical description, not an insult like in English. So: a square for a mouth, hiding inside songs, brothers and knowing.",
    ja: "{弟|おとうと}は[口|くち]が{大きい|おおきい}です。",
    en: "My younger brother has a big mouth." },
  "せがたかい|背が高い": {
    explain: "This is really a little sentence: height is high. 「背|せ」 is a native reading meaning back, and also your height, the length of your back standing up. The kanji has the shape for north on top, which shows two people standing back to back, and the body radical underneath. So it is literally the body part on your back side. 「高い|たかい」 is the same word you already know as expensive. Its kanji is a picture of a tall building with a roof and a tower. High prices, high buildings, high height. A common mistake for English speakers is to say a person is 「ながい」, long. Japanese never does that. For people, always use this phrase, and the opposite is 「背が低い|せがひくい」. Use it like this: 「あにはせがたかいです」, my older brother is tall. Before a noun it works too: 「せがたかいひと」, a tall person. So: your back is high, and that means tall.",
    ja: "{兄|あに}は[背が高い|せがたかい]です。",
    en: "My older brother is tall." },
  "かぶる|": {
    explain: "This is the verb for putting something on your head, like a hat, a cap or a helmet. It is usually written in kana. Japanese is picky here. Instead of one verb for wearing, it chooses the verb by where the item goes. 「きる」 is for tops and whole outfits, 「はく」 is for anything below the waist, 「かける」 is for glasses, and this one is for the head. A classic mistake is to say 「ぼうしをきる」. That sounds like you are trying to wear your hat as a shirt. Say 「ぼうしをかぶる」 instead. It is a regular verb: 「かぶります」, 「かぶって」. To say someone is wearing a hat right now, use the 「ている」 form: 「ぼうしをかぶっています」. A way to remember it: it sounds a little like cover, so you cover your head. So: the head verb, and hats are never 「きる」.",
    ja: "{父|ちち}はぼうしを[かぶっています|かぶっています|かぶる]。",
    en: "My father is wearing a hat." },
  "おじいさん|": {
    explain: "This word is built like a gift wrap. The polite 「お」 goes on the front and the friendly 「さん」 goes on the end, with the core 「じい」 in the middle. The big trap is the long vowel. Hold the 「い」 for two beats and it means grandfather. Cut it short to 「おじさん」 and you have said uncle, or just a middle-aged man. The same trick works with women: 「おばあさん」 is grandmother, and 「おばさん」 is aunt. A way to remember it: grandpa is older, so he gets the longer sound. Like many family words, this one stretches beyond family. Children and adults call any elderly man by this word, a bit like saying the old gentleman. When you talk about your own grandfather to others in a formal setting, adults switch to a humbler word, 「祖父|そふ」, but in everyday talk this word is fine. So: wrapped in 「お」 and 「さん」, and the long vowel makes him older.",
    ja: "[おじいさん]は{八十|はちじゅう}さいです。",
    en: "My grandfather is eighty." },
  "きる|着る": {
    explain: "This kanji is the sheep, 「羊|ひつじ」, on top of the eye, 「目|め」. A way to remember it, purely as a hook: wool from a sheep pulled up over your face as you put on a sweater. The reading here is the native one. The same kanji has a second life. In 「着く|つく」, it means to arrive. And in 「着物|きもの」, kimono, it is literally a thing you wear. Use this verb for clothes on your upper body or your whole body, like shirts, sweaters, coats, dresses and kimono. Pants and shoes take 「はく」 instead. Watch out for a sound twin, 「切る|きる」, to cut. They behave differently. This one is a ru-verb, so it becomes 「きます」 and 「きて」. The cutting one is an u-verb, 「きります」 and 「きって」. That difference is how you tell them apart when you hear them. To say wearing right now, use 「きています」. So: sheep's wool on the body, the kimono verb, and not the cutting one.",
    ja: "{新しい|あたらしい}セーターを[着ています|きています|きる]。",
    en: "I'm wearing a new sweater." },
  "かわいい|": {
    explain: "This is a native word, normally written in kana. It comes from an older form, 「かわゆい」, which you still hear now and then in old songs and stories. It is an 「い」 adjective, so it bends like 「たかい」: not cute is 「かわいくない」, and was cute is 「かわいかった」. In Japan this word is everywhere. It is a whole aesthetic. Towns, police departments and even prisons have round, smiling mascot characters, and people say this word about animals, babies, clothes, stationery, and even a nicely wrapped bento box. Grown men say it too, and nobody blinks. That is very different from English cute, which can sound childish. It works for people as well, though for a stylish adult you may hear 「かっこいい」, cool, for men, or 「きれい」, pretty. A way to remember it: picture a fluffy kitten that makes you go wah. So: an 「い」 adjective that Japan has turned into a way of life.",
    ja: "この{猫|ねこ}は[かわいい]です。",
    en: "This cat is cute." },
  "かぞく|家族": {
    explain: "Two Chinese-origin readings combine here. 「家|か」 is the house kanji. Look at it: a roof on top, and under the roof, a pig. In ancient China, a home was where your livestock lived with you. The same kanji with its native reading is 「家|いえ」, home, which you already know. It also appears in 「作家|さっか」, writer, and 「家具|かぐ」, furniture. 「族|ぞく」 means clan or tribe. It shows a flag with arrows under it, people gathering under one banner. Put them together: the clan of one house. Japanese people often count the family when introducing it, including themselves. 「よにんかぞくです」 means we are a family of four, me included. You will also hear the question 「なんにんかぞくですか」, how many people are in your family. So: a pig under a roof, plus a clan under a flag, makes the family.",
    ja: "{私|わたし}の[家族|かぞく]は{四人|よにん}です。",
    en: "There are four people in my family." },
  "おばあさん|": {
    explain: "This is the mirror image of 「おじいさん」. The polite 「お」 goes on the front, the friendly 「さん」 on the end, and the core 「ばあ」 in the middle. Again, the long vowel matters. Stretch the 「あ」 and you are talking about grandmother. Cut it short to 「おばさん」 and you get aunt, or a middle-aged woman. A way to remember it: grandma has lived longer, so she gets the longer sound. Like grandfather, this word goes beyond family, and it is used for any elderly woman. A bit of social advice: be careful with these words for strangers. Calling a woman in her forties 「おばさん」 can sting, and calling someone 「おばあさん」 when she doesn't feel old can sting even more. When talking formally about your own grandmother, adults use 「祖母|そぼ」, but this word is fine in casual talk. So: long 「あ」, grandmother, short 「あ」, aunt.",
    ja: "[おばあさん]はやさしいです。",
    en: "My grandmother is kind." },
  "ちち|父": {
    explain: "The reading here is the native one. The kanji's origin is debated, so here is a hook instead. A way to remember it: the two dots at the top and the big cross at the bottom look like a stern dad with his arms folded across his chest. The important thing is how this word is used. Japanese splits family words into two sets. This plain set is for your own family when talking to outsiders. So if your teacher asks about your dad, you say 「ちちはかいしゃいんです」, my father is an office worker. When you talk about someone else's father, or call your own dad at home, you use 「お父さん|おとうさん」. Notice it is the very same kanji, just with a special reading. The plain one is like being modest about your own side. It pairs with 「母|はは」, mother. In June, Japan also celebrates 「父の日|ちちのひ」, Father's Day. So: your own dad, said humbly to others.",
    ja: "[父|ちち]は{会社員|かいしゃいん}です。",
    en: "My father is an office worker." },
  "はは|母": {
    explain: "The reading here is the native one. The kanji is a picture of a woman, with two dots added for breasts, a nursing mother. That shape hides inside another word you know: 「毎日|まいにち」, every day. The top of 「毎|まい」 contains this same mother shape. A way to remember it: mothers do things every day. Just like 「父|ちち」, this word is the plain, modest one, used for your own mother when talking to people outside the family. 「はははせんせいです」, my mother is a teacher. Notice how the sound repeats: that is the word, followed by the topic marker. For someone else's mother, or when calling your own mom, use 「お母さん|おかあさん」, the same kanji with a special reading. Japan celebrates 「母の日|ははのひ」, Mother's Day, in May, with red carnations, just like in many other countries. So: a nursing mother, and your own mom said modestly.",
    ja: "[母|はは]は{先生|せんせい}です。",
    en: "My mother is a teacher." },
  "あに|兄": {
    explain: "The reading here is the native one. The kanji is simple to build. On top sits 「口|くち」, mouth. Under it, two strokes that are legs, the same legs you see under the eye in 「見る|みる」. A way to remember it: a big mouth on legs, the older brother bossing the younger kids around. This plain word is for your own older brother when talking to others: 「あにはだいがくせいです」, my older brother is a college student. For someone else's older brother, or when calling your own, use the polite 「お兄さん|おにいさん」, with the special reading 「にい」. In 「兄弟|きょうだい」, siblings, the same kanji takes its Chinese-origin reading, 「きょう」. Japanese also always marks older and younger. There is no plain word for brother that ignores age, so you have to choose. So: a mouth on legs, the bossy older brother, said modestly about your own.",
    ja: "[兄|あに]は{大学生|だいがくせい}です。",
    en: "My older brother is a college student." },
  "あね|姉": {
    explain: "The reading here is the native one. On the left of the kanji is 「女|おんな」, woman. That same woman side shows up in 「妹|いもうと」, younger sister, so both sisters share it. The right side is a part that mostly gives the sound in Chinese, and it looks like the kanji for market. A way to remember it: the older sister is the woman sent to the market. This plain word is for your own older sister when talking to others: 「あねはとうきょうにすんでいます」, my older sister lives in Tokyo. For someone else's sister, or when calling your own sister at home, use 「お姉さん|おねえさん」, with the special reading 「ねえ」. A small cultural note: in Japan, younger siblings usually call older ones by this title instead of by name, while older siblings call younger ones by name. So: woman plus market, your own big sister, said modestly.",
    ja: "[姉|あね]は{東京|とうきょう}に{住んでいます|すんでいます}。",
    en: "My older sister lives in Tokyo." },
  "きょうだい|兄弟": {
    explain: "Both kanji here use their Chinese-origin readings. 「兄|きょう」 is the older brother kanji you know from 「兄|あに」. 「弟|だい」 is the younger brother kanji from 「弟|おとうと」. Older brother plus younger brother. But the word covers all siblings, sisters included. That surprises English speakers. If you want to be fully precise in writing, you may see the longer 「兄弟姉妹|きょうだいしまい」, brothers and sisters. A useful question is 「きょうだいがいますか」, do you have any siblings? Another is 「なんにんきょうだいですか」. Here is the trap: the answer counts you too. If you say 「さんにんきょうだいです」, it means there are three kids in total, including yourself, so you have two siblings. That is different from English, where you would count only the others. So: older plus younger brother, all siblings, and you count yourself.",
    ja: "[兄弟|きょうだい]がいますか。",
    en: "Do you have any brothers or sisters?" },
  "おとこのひと|男の人": {
    explain: "The kanji 「男|おとこ」 has two parts you can see clearly. On top is 「田|た」, a rice field. Underneath is 「力|ちから」, strength or power. Strength in the rice field. That is the man who did the heavy farm work, in the old picture of things. The reading here is the native one. In other words you may meet the Chinese-origin readings, like 「だん」 in 「男性|だんせい」, male, a more formal word. Then 「の」 links it to 「人|ひと」, person. Man's person, a man. A tip for English speakers: saying just 「おとこ」 on its own can sound blunt or rough, like saying that guy. Adding 「のひと」 makes it neutral and polite. The same pattern gives you 「男の子|おとこのこ」, boy, a male child. And the pair to this word is 「女の人|おんなのひと」, woman. So: field plus strength, the man, made polite with 「のひと」.",
    ja: "あの[男の人|おとこのひと]は{先生|せんせい}です。",
    en: "That man is a teacher." },
  "おんなのひと|女の人": {
    explain: "The kanji 「女|おんな」 is commonly explained as a picture of a woman kneeling, with her arms crossed in front of her. The reading here is the native one. This kanji is a great anchor, because it shows up as the left side of many others. It is in 「姉|あね」, older sister, and 「妹|いもうと」, younger sister. It is in 「好き|すき」, to like, where a woman sits beside a child. It even appears in 「彼女|かのじょ」, she or girlfriend, where it uses the Chinese-origin reading 「じょ」. Add 「の」 and 「人|ひと」, person, and you get a woman. Just like with the man word, saying only 「おんな」 can sound rough, so adding 「のひと」 keeps it polite. A girl is 「女の子|おんなのこ」. So: a kneeling figure, the woman side in sisters and liking, made polite with 「のひと」.",
    ja: "あの[女の人|おんなのひと]はだれですか。",
    en: "Who is that woman?" },
  "かいしゃ|会社": {
    explain: "Both kanji use their Chinese-origin readings. 「会|かい」 is the meeting kanji from 「会う|あう」, to meet. 「社|しゃ」 has the altar radical on the left and earth on the right. It first meant a shrine to the earth god, where villagers gathered, and grew into the idea of a group or association. You can still see the shrine meaning in 「神社|じんじゃ」, a shrine, where the sound shifts slightly. So a company is a meeting association. Family words with this kanji: 「会社員|かいしゃいん」, office worker, a member of the company, and 「社長|しゃちょう」, company president, the head of the association. Here is a fun twist. Flip the two kanji around and you get 「社会|しゃかい」, society. Same pieces, bigger group. So: people meeting in an association, and flipped, it becomes society.",
    ja: "{父|ちち}は[会社|かいしゃ]で{働いています|はたらいています}。",
    en: "My father works at a company." },
  "しょくどう|食堂": {
    explain: "Both kanji use their Chinese-origin readings. 「食|しょく」 is the eating kanji you know from 「食べる|たべる」 and 「食べ物|たべもの」, food, where it takes the native reading. 「堂|どう」 means a hall, a large room for people to gather. You can see earth at the bottom, a solid building. An eating hall. In Japan, this word has two flavors. On campus or at a company, it is the cafeteria, where you line up and get cheap set meals. Students often shorten the university one to 「がくしょく」, student cafeteria. In towns, small old-fashioned family diners also use the name, serving simple set meals with rice, miso soup and pickles. They often have a cloth curtain hanging over the door. So: eating plus hall, from the school cafeteria to the cozy neighborhood diner.",
    ja: "[食堂|しょくどう]で{昼ごはん|ひるごはん}を{食べます|たべます}。",
    en: "I eat lunch in the cafeteria." },
  "うた|歌": {
    explain: "The reading here is the native one, and it is the same kanji as the verb 「歌う|うたう」, to sing. Look at the left side and you can find little mouths, 「口|くち」, stacked up. The right side is a radical that shows a person with their mouth wide open, which is used in kanji about breathing and voice. So it is a person singing with an open mouth. The kanji also has a Chinese-origin reading, 「か」. You hear it in 「歌手|かしゅ」, singer, a person whose skill is song, and in 「歌舞伎|かぶき」, kabuki theater, where the first kanji is this one, song, followed by dance and skill. Japan also gave the world karaoke, and singing together after work or with friends is a big social habit. So: mouths and an open-mouthed person, the song in kabuki and karaoke.",
    ja: "この[歌|うた]が{好き|すき}です。",
    en: "I like this song." },
  "サークル|": {
    explain: "This loanword comes from English circle, as in a circle of friends. Watch how the sounds got squeezed in. The c becomes 「さ」. The ir sound turns into a long 「あー」, because Japanese doesn't have that English vowel. Then the cl gets split apart with extra vowels, becoming 「くる」, and the l turns into an r sound. In meaning it shifted, too. At Japanese universities, this word means a casual student club for a hobby, like tennis, music, travel or anime. It is different from the more serious 「部活|ぶかつ」, a club or team with strict practice, which you hear more about at high schools. Joining a circle is a big part of college social life in Japan, and it is where many people make their closest friends. To say you're in one: 「テニスのサークルにはいっています」. So: an English circle, turned into the relaxed college club.",
    ja: "テニスの[サークル]に{入っています|はいっています}。",
    en: "I'm in a tennis club." },
  "くるま|車": {
    explain: "The kanji is a picture of a cart seen from above. The center box is the cart, and the long line through the middle is the axle, with wheels at each end. The reading here is the native one. The same kanji with its Chinese-origin reading, 「しゃ」, shows up in many words you know. 「電車|でんしゃ」, train, is an electric vehicle. 「自転車|じてんしゃ」, bicycle, is a self-turning vehicle. In those words, the kanji means any vehicle with wheels. On its own, though, this native word almost always means a car. A way to remember it: 「くるくる」 is the Japanese sound for spinning around, and a car's wheels go round and round. So: a cart with an axle seen from above, the native word for car, and 「しゃ」 in train and bicycle.",
    ja: "[車|くるま]で{会社|かいしゃ}に{行きます|いきます}。",
    en: "I go to work by car." },
  "ながい|長い": {
    explain: "The reading here is the native one. The kanji is usually explained as a picture of an old person with long flowing hair, which gives the meanings long and also senior. That same shape sits in the top left of 「髪|かみ」, hair. The senior meaning comes out in the Chinese-origin reading, 「ちょう」, in 「社長|しゃちょう」, company president, the head person of the company. Use this adjective for length in space and in time. Long hair, a long road, a long movie, a long vacation. The opposite is 「みじかい」, short. One trap: don't use it for tall people. Japanese says 「背が高い|せがたかい」 for height. Like other 「い」 adjectives, it changes to 「ながくない」, not long, and 「ながかった」, was long. So: long-haired elder, long in space and time, and the head of the company.",
    ja: "{妹|いもうと}は{髪|かみ}が[長い|ながい]です。",
    en: "My younger sister has long hair." },
  "みじかい|短い": {
    explain: "The reading here is the native one. On the left of the kanji is 「矢|や」, arrow. On the right is a shape that means bean. The real history of the combination is debated, so here is a hook. A way to remember it: in old times you could measure short things with an arrow, so anything shorter than an arrow is short. That same arrow appears in 「知る|しる」, to know, so the two kanji are cousins. Use this adjective for short things in length or time: short hair, a short story, a short vacation. 「あにはかみがみじかいです」, my older brother has short hair. But here is a common mistake. It is never used for people's height. For a short person you say 「背が低い|せがひくい」, low height. The opposite is 「ながい」, long. So: an arrow and a bean, short things and short time, but never short people.",
    ja: "{兄|あに}は{髪|かみ}が[短い|みじかい]です。",
    en: "My older brother has short hair." },
  "はやい|速い": {
    explain: "The reading here is the native one. The kanji has the moving radical along its bottom left, the same walking road you see in kanji about travel. So this kanji is about speed, things in motion. It has a sound twin you already know: 「早い|はやい」, early. That one has 「日|ひ」, the sun, on top, because it is about time, like the early morning sun. So the trick is to ask: is it about speed or about time? A fast train uses this kanji. An early train uses the sun one. A runner who is quick, a car that is fast, a person who talks fast: all this one. Waking up early, coming home early: the sun one. When spoken there is no difference, so context decides. The adverb form 「はやく」 also comes in both kanji. So: moving radical for speed, sun kanji for early.",
    ja: "{電車|でんしゃ}は[速い|はやい]です。",
    en: "Trains are fast." },
  "せがひくい|背が低い": {
    explain: "This is a small sentence: height is low. 「背|せ」 is the same native word as in 「背が高い|せがたかい」, meaning your back, and your height. 「低い|ひくい」 means low, with the native reading. Its kanji has the person radical on the left, 「人|ひと」, and a right side that carries the sense of bottom or base. A person near the bottom. The same adjective works for a low ceiling, a low voice, or low temperatures. The big mistake English speakers make is translating short directly as 「みじかい」. In Japanese, 「みじかい」 is only for length, like hair or pencils, never for people. So a short person is always this phrase. Use it the same way as tall: 「おとうとはせがひくいです」, my younger brother is short. It can feel a little personal, so be kind when you use it. So: your back is low, and that means short.",
    ja: "{弟|おとうと}は[背が低い|せがひくい]です。",
    en: "My younger brother is short." },
  "あたまがいい|頭がいい": {
    explain: "This is a little sentence: the head is good. 「頭|あたま」 uses its native reading. Look at the kanji. The right side is a radical that means head. You can see the very same radical on the right of 「顔|かお」, face. That is a nice anchor: face and head share the head piece. Then 「いい」, good. So someone with a good head is smart. English has a similar idea, a good head on your shoulders. Use it like this: 「あねはあたまがいいです」, my older sister is smart. Remember that 「いい」 changes to 「よ」 when it bends, so the past is 「あたまがよかった」 and the negative is 「あたまがよくない」. The opposite, 「あたまがわるい」, bad head, means not smart, and can be quite rude, so use it carefully. So: a good head, and the head radical shared with face.",
    ja: "{姉|あね}は[頭がいい|あたまがいい]です。",
    en: "My older sister is smart." },
  "しんせつ|親切": {
    explain: "Both kanji use their Chinese-origin readings. 「親|しん」 means parent, and from that, close or intimate. You know it from 「親|おや」, parent, with the native reading, and 「両親|りょうしん」, parents. A popular hook, not real history: the kanji looks like standing on a tree, watching, a parent watching over a child. 「切|せつ」 is the cutting kanji, 「切る|きる」, to cut, also in 「切符|きっぷ」, ticket. In this word it carries the sense of keen or heartfelt, feelings that cut deep. So the idea is close and heartfelt, the warm care a parent would show. It is a 「な」 adjective: 「しんせつなひと」, a kind person. It is used mostly for kind actions toward others, like helping someone find the station. Another word, 「やさしい」, describes a gentle personality. So: parent-like closeness that cuts deep, which is kindness in action.",
    ja: "{先生|せんせい}はとても[親切|しんせつ]です。",
    en: "The teacher is very kind." },
  "べんり|便利": {
    explain: "Both kanji use their Chinese-origin readings. 「便|べん」 has the person radical on the left, and means convenience, ease, and also mail or delivery. That other meaning comes out as 「びん」 in 「郵便局|ゆうびんきょく」, post office. 「利|り」 has grain on the left and a knife on the right. Cutting the harvest brings profit, so it means advantage, benefit and sharpness. Ease plus benefit: convenient. It is a 「な」 adjective, so you say 「べんりなみせ」, a convenient store. Put 「不|ふ」, meaning not, in front and you get 「不便|ふべん」, inconvenient, using the same first kanji. Japan's convenience stores are the perfect example. They are open all night, and you can pay bills, send packages and print documents there. 「コンビニはべんりです」 is a sentence everyone agrees with. So: ease plus a sharp benefit, the word for every convenience store.",
    ja: "コンビニは[便利|べんり]です。",
    en: "Convenience stores are convenient." },
  "はく|": {
    explain: "This is the verb for putting on anything below your waist. Pants, jeans, skirts, socks, shoes and slippers all take it. It is usually written in kana. Japanese chooses the verb by body part, so you need to switch. 「きる」 is for shirts and coats, 「かぶる」 is for hats, and 「かける」 is for glasses. A very common English speaker mistake is 「ジーンズをきる」. That sounds odd. Say 「ジーンズをはく」 instead, and for shoes, 「くつをはく」. It is an u-verb: 「はきます」, 「はいて」. To say someone is wearing something right now, use 「はいています」. In Japan, you will do this a lot, because you take shoes off at the entrance of homes and put on slippers. A way to remember it: picture yourself hiking up your pants. So: the waist-down verb, for pants, skirts, socks and shoes.",
    ja: "くつを[はきます|はきます|はく]。",
    en: "I put on my shoes." },
  "しる|知る": {
    explain: "The reading here is the native one. The kanji is 「矢|や」, arrow, on the left, and 「口|くち」, mouth, on the right. A way to remember it, as a hook: knowledge comes out of your mouth as fast and straight as an arrow. That same arrow is in 「短い|みじかい」, short. At its heart, this verb means to come to know, to find out. That is why you need the 「ている」 form for the state of knowing: 「しっています」, I know. But here is the trap that catches everyone. The negative is NOT 「しっていません」. It is simply 「しりません」, I don't know. Also, even though it ends in 「る」, it is an u-verb, so it becomes 「しって」 with a small 「っ」. A typical question: 「でんわばんごうをしっていますか」, do you know the phone number? So: an arrow from the mouth, know is 「しっています」, and don't know is 「しりません」.",
    ja: "{先生|せんせい}の{電話番号|でんわばんごう}を[知っています|しっています|しる]か。",
    en: "Do you know the teacher's phone number?" },
  "すむ|住む": {
    explain: "The reading here is the native one. The kanji has the person radical on the left, and on the right, 「主|しゅ」, which means master or main. You see that piece in 「ご主人|ごしゅじん」, someone's husband, the master of the house in old thinking. So: a person who is master of a place, living there. Grammar matters with this verb. You mark the place with 「に」, not 「で」: 「とうきょうにすんでいます」, I live in Tokyo. And use the 「ている」 form for where you live now. A common English speaker mistake is to say 「とうきょうにすみます」, which sounds like I will live in Tokyo, a future plan. It is an u-verb: 「すみます」, 「すんで」. The Chinese-origin reading 「じゅう」 shows up in 「住所|じゅうしょ」, address, the place you live. So: a person who is master of a place, with 「に」 and the 「ている」 form.",
    ja: "{東京|とうきょう}に[住んでいます|すんでいます|すむ]。",
    en: "I live in Tokyo." },
  "はたらく|働く": {
    explain: "The reading here is the native one. This kanji is special: it was invented in Japan, not in China. The Japanese made it by putting the person radical next to 「動|どう」, to move. A person who keeps moving is working. The moving piece 「動|どう」 is in words you know, like 「動物園|どうぶつえん」, zoo, the garden of moving creatures, and 「活動|かつどう」, activity. It is an u-verb: 「はたらきます」, 「はたらいて」. Mark the workplace with 「で」, not 「に」: 「ぎんこうではたらいています」, works at a bank. That is the opposite of 「住む|すむ」, which takes 「に」. Also note the difference from 「しごと」, which is the noun for a job. This verb is the action of working. So: a person in motion, a kanji made in Japan, and the workplace takes 「で」.",
    ja: "{母|はは}は{銀行|ぎんこう}で[働いています|はたらいています|はたらく]。",
    en: "My mother works at a bank." },
  "ふとる|太る": {
    explain: "The reading here is the native one. Look at the kanji. It is 「大|だい」, big, with one extra dot. A way to remember it: big plus a little extra. The same kanji also gives the adjective 「太い|ふとい」, thick, and with its Chinese-origin reading, 「たい」, it is in 「太陽|たいよう」, the sun, a big bright thing in the sky. The grammar is the important part. This verb means the change, gaining weight. So 「ふとりました」 means I gained weight. To describe someone who is heavy, use the 「ている」 form, 「ふとっています」. It is a common mistake to make an adjective out of it for people. Even though it ends in 「る」, it is an u-verb, so it becomes 「ふとって」. A cultural note: this topic is discussed quite openly in Japan, so don't be shocked if someone mentions it. So: big plus a dot, gaining weight, and 「ふとっています」 for heavy.",
    ja: "{毎日|まいにち}ケーキを{食べます|たべます}から、[太りました|ふとりました|ふとる]。",
    en: "I eat cake every day, so I gained weight." },
  "かける|かける": {
    explain: "The core meaning of this verb is to hang something on something. You hang glasses on your nose and ears, so 「めがねをかける」 means to put on glasses. It can be written with a kanji, but for glasses it is usually in kana. This one verb does lots of jobs, all tied to the hanging idea. 「でんわをかける」 means to make a phone call, as if hanging a line out to someone. 「アイロンをかける」 means to iron clothes, laying the iron over them. Japanese chooses the wearing verb by body part, so remember 「きる」 is for tops, 「はく」 below the waist, and 「かぶる」 for hats. It is a ru-verb: 「かけます」, 「かけて」. To describe someone who wears glasses, use the 「ている」 form: 「ちちはめがねをかけています」, my father wears glasses. So: to hang, used for glasses, phone calls and ironing.",
    ja: "{父|ちち}はめがねを[かけています|かけています|かける]。",
    en: "My father wears glasses." },
  "やせる|": {
    explain: "This is a native verb, usually written in kana. It is the opposite of 「太る|ふとる」, gaining weight. It works the same way. The plain form is the change: 「やせました」, I lost weight. To describe someone who is thin, use the 「ている」 form, 「やせています」, my brother is thin. Unlike 「ふとる」, this one is a ru-verb, so it becomes 「やせます」 and 「やせて」. A cultural note: in Japan, saying 「やせましたね」, you've lost weight, is generally taken as a compliment, and people talk about weight more openly than many English speakers expect. Still, it is personal, so read the room. A way to remember it, as a sound hook: imagine someone stepping off the scale and shouting yes, sir, I lost weight! So: the change of getting thinner, and 「やせています」 for thin.",
    ja: "{兄|あに}は[やせています|やせています|やせる]。",
    en: "My older brother is thin." },
  "けっこんする|結婚する": {
    explain: "Both kanji use their Chinese-origin readings. 「結|けつ」 means to tie. It has the thread radical on the left, and on the right, the kanji for good fortune. Tying threads for good luck. Before the 「こ」 sound, its ending squeezes into a small 「っ」, giving 「けっ」. You know the same squeezed sound from 「結構です|けっこうです」, that's fine. 「婚|こん」 means marriage, with 「女|おんな」, woman, on the left. The right side is the kanji for dusk, and an old Chinese dictionary explains that weddings were held at dusk. So: tying the knot, just like the English phrase. Then add 「する」, to do. The grammar is key. 「けっこんしました」 means got married, an event. 「けっこんしています」 means is married, a state. You marry someone with 「と」. A wedding is 「結婚式|けっこんしき」. So: tie plus marriage, and the 「ている」 form for married.",
    ja: "{姉|あね}は[結婚しています|けっこんしています|けっこんする]。",
    en: "My older sister is married." },
  "〜が|": {
    explain: "This 「が」 is a connector, not the subject marker you already know. It joins two sentences that contrast, and it means but. Put it on the end of the first sentence, then a pause, then the second: 「むずかしいですが、おもしろいです」, it's difficult, but it's interesting. It sits after the verb or adjective, so you can tell it apart from the subject 「が」, which comes after a noun. How does it compare to other buts? 「でも」 starts a brand new sentence. 「けど」 is more casual and very common in conversation. This one is neutral to polite, and fits well with 「です」 and 「ます」. It also has a soft, cushioning use. 「すみませんが」 means excuse me, but, as a gentle lead in to a request. A way to remember it: think of it as a gate between two opposite ideas. So: after the first sentence, it means but, polite and smooth.",
    ja: "{日本語|にほんご}はむずかしいです[が]、おもしろいです。",
    en: "Japanese is difficult, but it's interesting." },
  "なにも|何も": {
    explain: "This is 「何|なに」, what, plus 「も」, which means even or also. Even what. The reading of the kanji is the native one, and the kanji has the person radical on the left. The key rule: it goes with a negative verb, and together they mean not anything, nothing. 「なにもたべませんでした」, I didn't eat anything. A common mistake for English speakers is to use it with a positive verb, as in I eat anything. That doesn't work. For something, use the sibling word 「何か|なにか」 instead: 「なにかたべましたか」, did you eat something? The same pattern works with other question words. 「だれも」 with a negative is nobody, and 「どこも」 is nowhere. You'll also hear it as a quick reply, often with 「べつに」: 「べつになにも」, nothing in particular. So: what plus even, with a negative, meaning nothing at all.",
    ja: "{今日|きょう}は[何も|なにも]{食べませんでした|たべませんでした}。",
    en: "I didn't eat anything today." },
  "〜にん|〜人": {
    explain: "This counter uses the Chinese-origin reading of 「人|ひと」, person. The kanji is a picture of a person walking, seen from the side, two legs apart. Put a number in front to count people: 「さんにん」, three people, 「ごにん」, five people. How many people is 「なんにん」. Now the irregulars, which you must memorize. One person is 「一人|ひとり」 and two people is 「二人|ふたり」, both using old native words. Four people is 「よにん」, not 「しにん」, because 「し」 sounds like death. Seven can be 「しちにん」 or 「ななにん」. The same kanji with the other Chinese-origin reading, 「じん」, means a person from somewhere, like 「にほんじん」, a Japanese person, or 「外国人|がいこくじん」, foreigner. Grammar tip: put the number after the noun and particle, right before the verb: 「がくせいがさんにんいます」. So: a walking person, used for counting people, with one, two and four as exceptions.",
    ja: "{学生|がくせい}が[三人|さんにん|〜にん]います。",
    en: "There are three students." },
  "ひとり|一人": {
    explain: "This word doesn't follow the regular counter. 「一|ひと」 uses its native reading, the same 「ひと」 as in 「ひとつ」, one thing. And 「人|り」 uses an old native counter for people that only survives in one and two people. From three on, you switch to the regular counter, 「さんにん」. The word has two jobs. One is counting: one person. The other is alone. Add 「で」 and you get 「一人で|ひとりで」, by myself: 「ひとりでたべます」, I eat alone. In Japan, doing things solo has become a whole trend. You will see booths for one person at ramen shops and karaoke for one. Another useful phrase is 「ひとりっこ」, an only child. Don't say 「いちにん」, which is a common beginner slip. So: the native one plus an old people counter, meaning one person or all by yourself.",
    ja: "{毎日|まいにち}[一人|ひとり]で{食べます|たべます}。",
    en: "I eat alone every day." },
  "ふたり|二人": {
    explain: "Just like 「一人|ひとり」, this word uses old native readings instead of the regular counter. 「二|ふた」 is the native reading of two, the same 「ふた」 as in 「ふたつ」, two things. And 「人|り」 is the same old people counter as in one person. These two words, one person and two people, are the only ones built this way. Three people and up use the regular 「にん」 counter. Add 「で」 and you get 「ふたりで」, the two of us, together: 「ふたりでえいがをみました」, the two of us watched a movie. The word also carries a romantic feeling, the two of them, a couple. Japanese song titles and movies use it a lot. Don't say 「にじん」 or 「ににん」, which is a common beginner slip. A way to remember it: one and two people are special, because they are the people closest to you. So: native two plus the old people counter, two people, or a pair.",
    ja: "[二人|ふたり]で{映画|えいが}を{見ました|みました}。",
    en: "The two of us watched a movie." },
  "べつに|別に": {
    explain: "The kanji 「別|べつ」 uses its Chinese-origin reading, and means separate or different. It has the knife radical on the right side, which fits the idea of cutting things apart. The same kanji with its native reading is in 「別れる|わかれる」, to separate or break up. Add 「に」 and it becomes an adverb: separately, especially. With a negative, it means not especially, nothing in particular. 「べつになにもありません」, there's nothing in particular. Careful, though. On its own as a short reply, it can sound cold, like a bored teenager saying whatever. A famous example: in 2007, an actress answered reporters at her movie premiere with just this word, and the curt reply turned into a national scandal. So use it with a soft tone, or add more words. So: cut apart and separate, and with a negative, nothing in particular.",
    ja: "[別に|べつに]{何も|なにも}ありません。",
    en: "Nothing in particular." },
  "もちろん|": {
    explain: "This word does have a Chinese-origin kanji spelling, but it is almost always written in kana. The original meaning is roughly no need to argue it. That makes sense for of course: it is so obvious it doesn't need discussing. Use it to agree with energy: 「もちろんいきます」, of course I'll go. It is friendly and fine in polite conversation. It can stand alone as a full answer: someone asks if you're coming, and you just say it. It also works with sentences like 「もちろんです」, of course, which sounds a bit more polite. A tip for English speakers: it can sound a little strong if someone asks you a real question, since it implies the answer was obvious. A way to remember it, as a sound hook: picture someone yelling mochi run! Would you run for mochi? Of course! So: no need to argue, a warm and energetic of course.",
    ja: "[もちろん]{行きます|いきます}。",
    en: "Of course I'll go." },
  "よかったら|": {
    explain: "This little phrase comes from 「いい」, good. When 「いい」 bends, it uses its older form 「よい」, so the past tense is 「よかった」, was good. Add 「ら」, which makes a condition, if. So literally, if it is good for you. You will study this 「たら」 if pattern later, but this phrase is so useful it gets learned early as a set expression. Use it to offer or invite gently, often with a 「ませんか」 question: 「よかったら、いっしょにいきませんか」, if you like, would you like to go together? It softens the request, so the other person can easily say no. That fits the Japanese habit of leaving room for others to decline politely. In more formal situations, you'll hear 「よろしかったら」, which is even more polite. So: if it was good, which means if you like, the soft key to invitations.",
    ja: "[よかったら]、いっしょに{行きませんか|いきませんか}。",
    en: "If you like, would you like to go together?" },
  "おにいさん|お兄さん": {
    explain: "This is the polite version of 「兄|あに」, older brother. It is the same kanji, but with a special reading, 「にい」, wrapped in a polite 「お」 at the front and 「さん」 at the end. Japanese family words come in two sets. The plain ones, like 「あに」, are for your own family when talking to outsiders. The polite ones, like this, are for other people's families: 「おにいさんはなにをしていますか」, what does your older brother do? But you also use this word to call out to your own older brother at home, since younger siblings call older ones by title, not by name. It even stretches beyond family. A shopkeeper might call a young man this word, a bit like calling out to a young guy. So: the polite older brother, used for other people's, for calling your own, and for young men.",
    ja: "[お兄さん|おにいさん]は{何|なに}をしていますか。",
    en: "What does your older brother do?" },
  "おねえさん|お姉さん": {
    explain: "This is the polite version of 「姉|あね」, older sister. It is the same kanji, but with a special reading, 「ねえ」, wrapped in 「お」 and 「さん」. The rule follows the brother word. Use the plain 「あね」 for your own sister when you talk to others, and this polite word for someone else's sister: 「おねえさんはどこにすんでいますか」, where does your older sister live? You also use it to call your own older sister at home, because in Japan younger siblings call older ones by this title, not by name. It goes beyond family too. Children call any young woman this, and customers sometimes use it for young women working in shops or restaurants. Calling a woman this instead of 「おばさん」 is the flattering choice. So: the polite older sister, for others' sisters, for calling your own, and for young women.",
    ja: "[お姉さん|おねえさん]はどこに{住んでいますか|すんでいますか}。",
    en: "Where does your older sister live?" },
  "いもうと|妹": {
    explain: "The reading here is the native one. The kanji has 「女|おんな」, woman, on the left, the same side you see in 「姉|あね」, older sister. On the right is a part that means not yet. A way to remember it, as a hook: a girl who is not yet grown up, the little sister. In Chinese-origin words, this kanji reads 「まい」, as in 「姉妹|しまい」, sisters. This plain word is for your own younger sister. For someone else's younger sister, add 「さん」: 「いもうとさん」. Unlike older siblings, younger ones don't get a special title when you call them. In Japanese families, you just call your younger sister by her name. Notice also that in Japanese you must say whether a sister is older or younger. There is no common everyday word for just sister. So: a woman not yet grown, your little sister, called by her name.",
    ja: "[妹|いもうと]は{高校生|こうこうせい}です。",
    en: "My younger sister is a high school student." },
  "おとうと|弟": {
    explain: "The reading here is the native one. The shape of this kanji has long been connected to the idea of order, coming next in line. You can see that sense in 「第|だい」, the kanji used for numbering like number one or the first. It is this same shape with bamboo on top. So the younger brother is the one who comes next in order. With its Chinese-origin reading, 「だい」, it is the second half of 「兄弟|きょうだい」, siblings. This plain word is for your own younger brother. For someone else's, add 「さん」: 「おとうとさん」. As with younger sisters, you call your younger brother by his name at home, not by a title. A way to remember it: the word starts just like 「おとうさん」, father, but ends in a short 「と」. Be careful saying it, because that tiny ending changes your dad into your little brother. So: next in order, your younger brother, and not your father.",
    ja: "[弟|おとうと]は{十|じゅう}さいです。",
    en: "My younger brother is ten years old." },
  "そうじする|掃除する": {
    explain: "Let's take it apart. The first kanji, 「掃|そう」, means to sweep. Look at its left side and you'll see the hand shape that shows up in lots of action kanji, so a hand is doing the sweeping. The second kanji, 「除|じ」, means to remove or get rid of. Both are read with their Chinese-origin readings here. Put them together and you get sweep and remove: you sweep the dirt up and take it away. In Japanese, 「掃除|そうじ」 on its own is a noun, cleaning. Add 「する」 and it becomes a verb, the same trick you've seen with 「べんきょうする」, 「洗濯する|せんたくする」 and 「料理する|りょうりする」. These three chores sit together in the same lesson, so they're easy to learn as a set. Notice that you clean a place, so the room or the house takes 「を」: 「へやを掃除する|へやをそうじする」. A cultural note: in Japanese schools, students clean their own classrooms. There is a daily cleaning time, so most Japanese people grew up doing 「そうじ」 with a broom in hand. To recap: sweep plus remove, plus 「する」, gives you to clean.",
    ja: "{毎週|まいしゅう}{土曜日|どようび}にへやを[掃除します|そうじします|そうじする]。",
    en: "I clean my room every Saturday." },
  "あめ|雨": {
    explain: "This kanji is one of the clearest pictures in Japanese. The line across the top is the sky, the frame below it is like a cloud or a window onto the sky, and the four little dots inside are drops of water falling. On its own it's read 「あめ」, the native Japanese reading. The best part is that 「雨|あめ」 works as a weather badge on top of other kanji. Look at 「雪|ゆき」, snow. It has the rain kanji squashed on top, because snow falls from the sky too. 「曇り|くもり」, cloudy, contains the cloud kanji, and that cloud kanji also wears the rain shape on top. And 「電気|でんき」, electricity, starts with a kanji that has rain on top as well. That kanji first meant lightning, the flash that comes with a storm, and that's how it ended up meaning electricity. So whenever you see that flattened rain shape on top of a kanji, think sky and weather. Rain falls with the verb 「降る|ふる」: 「雨が降る|あめがふる」. A cultural note: in early summer Japan has a rainy season of several weeks, and people carry umbrellas everywhere. Recap: sky, cloud and drops make rain, and that shape tops many weather kanji.",
    ja: "{今日|きょう}は[雨|あめ]がふっています。",
    en: "It is raining today." },
  "せんたくする|洗濯する": {
    explain: "Both kanji in this word have three little drops of water on their left side. That water radical tells you right away that this word is about water. The first kanji, 「洗|せん」, means to wash. Its right side is 「先|せん」, the same kanji as in 「先生|せんせい」, and it lends its sound, so 「洗|せん」 is read just like it. That's a real hint you can use: water plus the sound of 「先|せん」. It's the same kanji you'll see in 「洗う|あらう」, to wash, but there it uses the native reading. The second kanji, 「濯|たく」, means to rinse. Both readings here are the Chinese-origin ones. Wash and rinse your clothes, and that's laundry. Add 「する」 to make it a verb, just like 「掃除する|そうじする」. A cultural note: many Japanese homes don't use a dryer. People hang their laundry outside on the balcony, so weather forecasts often tell you whether it's a good day for drying clothes. Recap: water, wash and rinse together make laundry.",
    ja: "{日曜日|にちようび}に[洗濯します|せんたくします|せんたくする]。",
    en: "I do laundry on Sundays." },
  "りょうりする|料理する": {
    explain: "Let's break it down. The first kanji, 「料|りょう」, has rice, 「米|こめ」, on its left and a measuring ladle on its right. So it's about measuring out materials. It came to mean ingredients or materials, and also fees. The second kanji, 「理|り」, means reason, logic, or putting things in order. Both use their Chinese-origin readings here. Together they suggest taking your ingredients and handling them in a sensible, orderly way. Measured materials, put in order: that's a cooked dish. On its own, 「料理|りょうり」 is a noun meaning cooking or cuisine, so you can say 「日本料理|にほんりょうり」 for Japanese food. Add 「する」 and it becomes the verb to cook, the same pattern as 「掃除する|そうじする」 and 「洗濯する|せんたくする」. You can also use 「作る|つくる」 for making a particular dish, like a cake, but 「料理する|りょうりする」 is the general word for cooking as an activity. Recap: measured ingredients, arranged with reason, give you cooking.",
    ja: "{母|はは}はよく[料理します|りょうりします|りょうりする]。",
    en: "My mother often cooks." },
  "あらう|洗う": {
    explain: "Look at the left side of this kanji. Those three little drops are the water radical, the same one in many water words. So the kanji is clearly about water. The right side is 「先|せん」, from 「先生|せんせい」. It's there mostly for its sound. In this verb the kanji uses its native reading, 「あら」, with 「う」 after it. In 「洗濯|せんたく」, laundry, the very same kanji uses its Chinese-origin reading, 「せん」, which matches the sound of 「先|せん」. Same kanji, same idea of washing, two readings. There's one more sibling you already know: 「お手洗い|おてあらい」, the restroom. It literally means the place where you wash your hands. That's the polite word for the toilet in Japan. You wash something, so the thing takes 「を」: 「手を洗う|てをあらう」, to wash your hands. It's a regular u-verb: 「洗います|あらいます」, 「洗って|あらって」. Recap: water on the left means washing, read 「あら」 here, and you'll see it again in laundry and in the restroom.",
    ja: "{手|て}を[洗います|あらいます|あらう]。",
    en: "I wash my hands." },
  "はれ|晴れ": {
    explain: "This kanji is a lovely little picture. On the left is the sun, 「日|ひ」. On the right is the kanji for blue, 「青|あお」. Sun plus blue gives you a bright, clear, sunny sky. The blue part also gives the kanji its Chinese-origin sound in other words, but here we use the native reading, 「は」, followed by 「れ」. 「晴れ|はれ」 is a noun, sunny weather, the kind of word you hear in a forecast: 「あしたは晴れです|あしたははれです」. It comes from the verb 「晴れる|はれる」, to clear up. You'll hear it when the rain stops and the sky opens up. Put it next to its weather friends: 「雨|あめ」, rain, 「曇り|くもり」, cloudy, and 「雪|ゆき」, snow. Notice that cloudy also has the sun, 「日|ひ」, but buried under a cloud. A cultural note: Japanese children hang a little white cloth doll in the window before a school trip or sports day. It's a wish for a sunny day. Recap: sun and blue sky make sunny.",
    ja: "{明日|あした}は[晴れ|はれ]です。",
    en: "It will be sunny tomorrow." },
  "くもり|曇り": {
    explain: "Here's a kanji you can almost see. At the top is the sun, 「日|ひ」. Under it is the kanji for cloud, 「雲|くも」. So the sun is stuck behind a cloud. That's cloudy weather. The cloud kanji itself wears the rain kanji, 「雨|あめ」, on top, so this one kanji stacks sun, rain and cloud together. It's a little weather report in one character. Here it's read with the native reading, 「くも」, followed by 「り」. The word 「くも」 for a cloud and 「くもり」 for cloudy weather share the same sound, which is a nice anchor. 「曇り|くもり」 is the noun you hear in a weather forecast. It comes from the verb 「くもる」, to get cloudy. Compare it with 「晴れ|はれ」, sunny, where the sun sits happily next to blue sky. In cloudy, the sun is covered up. You'll often hear the combination 「曇りのち雨|くもりのちあめ」 in forecasts, cloudy, later rain. Recap: the sun hidden under a cloud gives you cloudy, read like the word for a cloud.",
    ja: "{今日|きょう}は[曇り|くもり]です。",
    en: "It's cloudy today." },
  "ゆうめい|有名": {
    explain: "Let's take it apart. The first kanji, 「有|ゆう」, means to have or to exist. The second kanji, 「名|めい」, means name. It's the same kanji used to write 「なまえ」, your name, where it has its native reading. Here both kanji use their Chinese-origin readings. So the word literally says having a name. Not just any name, but a name that people know. If your name is out there in the world, you're famous. You've got a sibling for it too: 「有名人|ゆうめいじん」, a celebrity. Add 「人|じん」, person, and you get a famous person. Grammar note: 「有名|ゆうめい」 is a na-adjective. So you say 「有名な店|ゆうめいなみせ」, a famous shop, with 「な」 in front of a noun. To say what something is famous for, use 「で」: 「京都はお寺で有名です|きょうとはおてらでゆうめいです」, Kyoto is famous for its temples. A common mistake is to drop the 「な」 before a noun. Keep it in. Recap: to have a name that people know means famous.",
    ja: "この{店|みせ}は[有名|ゆうめい]です。",
    en: "This shop is famous." },
  "ゆき|雪": {
    explain: "Look at the top of this kanji. It's the rain kanji, 「雨|あめ」, flattened into a lid. That tells you it's something that falls from the sky. The bottom part looks like a sideways letter E. In older forms of the kanji, that bottom part was a hand holding a broom. A way to remember it: snow is the weather you have to sweep up afterwards. Here it's read with the native reading, 「ゆき」. Snow falls with the same verb as rain, 「降る|ふる」: 「雪が降る|ゆきがふる」, it snows. Put it next to the other rain-topped kanji you know. 「曇り|くもり」, cloudy, contains the cloud kanji with rain on top, and 「電気|でんき」, electricity, starts with a kanji that was first about lightning. All of them share that sky-water shape. A cultural note: northern Japan gets huge amounts of snow. Sapporo holds a famous snow festival every winter, with giant sculptures made of snow and ice. And kids everywhere build a snowman, which in Japanese is 「雪だるま|ゆきだるま」, a snow doll made of two balls instead of three. Recap: rain on top, a broom below, and you get snow.",
    ja: "{冬|ふゆ}は[雪|ゆき]がたくさんふります。",
    en: "It snows a lot in winter." },
  "てんきよほう|天気予報": {
    explain: "This is a four-kanji compound, but it's really two words you can handle. The first half, 「天気|てんき」, is weather, a word you already know. 「天|てん」 means heaven or sky, the same 「天|てん」 you see in 「天ぷら|てんぷら」. 「気|き」 means spirit or air, as in 「元気|げんき」 and 「電気|でんき」. So the weather is the air of the sky. The second half is 「予報|よほう」. 「予|よ」 means beforehand, in advance. You know it from 「予約|よやく」, a reservation, and 「予定|よてい」, a plan. Both are things set up in advance. 「報|ほう」 means a report or news. So a forecast is a report made in advance, and this is a report on the sky's weather before it happens. All four kanji use their Chinese-origin readings here, which is normal for long compounds like this. A cultural note: Japanese weather forecasts on TV are very detailed. Besides rain and temperature, they often tell you whether it's a good day to dry laundry, and in spring they even report how the cherry blossoms are coming along. Recap: sky weather plus an advance report gives you the weather forecast.",
    ja: "{明日|あした}の[天気予報|てんきよほう]を{見ます|みます}。",
    en: "I'll check tomorrow's weather forecast." },
  "きおん|気温": {
    explain: "Two kanji, both with their Chinese-origin readings. The first, 「気|き」, means air or spirit. You know it from 「天気|てんき」, weather, and from 「元気|げんき」, energetic. In this word it's the air around you. The second, 「温|おん」, means warm. Notice the three little drops of water on its left side. Think of warm water. In fact, you know it from 「温泉|おんせん」, a hot spring, which is literally a warm spring of water. Put them together: the warmth of the air. That's the air temperature, the number you hear in the weather report. It's specifically about the air outside. For the temperature of water, or a person's fever, Japanese uses other words. You give the number with the counter 「度|ど」, degrees: 「気温は三十度です|きおんはさんじゅうどです」. Japan uses Celsius, so thirty degrees is a hot summer day, and zero is freezing. Recap: the air's warmth is the temperature, and it shares its warm kanji with hot springs.",
    ja: "{今日|きょう}の[気温|きおん]は{三十度|さんじゅうど}です。",
    en: "Today's temperature is thirty degrees." },
  "なつ|夏": {
    explain: "This word uses the native Japanese reading, 「なつ」. The kanji's shape doesn't have a simple, reliable story, so let's anchor it with a hook instead. A way to remember it: it sounds a bit like nuts, and Japanese summer is nuts. It's hot, it's very humid, and it's full of festivals and fireworks. It belongs to the set of four seasons you know: 「春|はる」, spring, 「夏|なつ」, summer, 「秋|あき」, fall, and 「冬|ふゆ」, winter. Learning them as a set helps, and they all come up together when people talk about 「季節|きせつ」, the seasons. A common phrase: 「夏休み|なつやすみ」 is summer vacation, using 「休み|やすみ」, a holiday, which you already know. A cultural note: summer is the season of fireworks shows by the river, people in light cotton robes, cold noodles, and shaved ice with syrup. In mid-August many people travel to their hometowns to honor their ancestors, so trains and highways get very crowded. Words you'll use with it: 「暑い|あつい」, hot, and 「気温|きおん」, temperature, which often climbs past thirty degrees. Recap: summer is the hot, crazy season, and it sounds like nuts.",
    ja: "{日本|にほん}の[夏|なつ]はあついです。",
    en: "Summer in Japan is hot." },
  "ふゆ|冬": {
    explain: "This word uses the native Japanese reading, 「ふゆ」. Look at the bottom of the kanji. Those two little dots come from the kanji element for ice, the same two strokes you see on the left of some cold-related kanji. So ice sits right at the bottom of winter. A way to remember the sound: picture blowing on your cold hands, going foo, and then thinking, you, it's freezing. Foo, you. It's one of the four seasons: 「春|はる」, 「夏|なつ」, 「秋|あき」 and 「冬|ふゆ」. The adjective that goes with it is 「寒い|さむい」, cold, for weather. And snow, 「雪|ゆき」, falls in winter with the verb 「降る|ふる」. A cultural note: many Japanese homes don't have central heating. Instead, families gather around a low table with a heater underneath and a blanket draped over it. Everyone tucks their legs under and eats mandarin oranges. It's one of the classic images of a Japanese winter. Winter also holds the biggest holiday of the year, the New Year, when families get together and visit shrines. Recap: ice at the bottom of the kanji, foo you for the sound, and that's winter.",
    ja: "[冬|ふゆ]はさむいです。",
    en: "Winter is cold." },
  "けさ|今朝": {
    explain: "Let's look at the two kanji. 「今|いま」 means now, and 「朝|あさ」 means morning, as in 「朝ご飯|あさごはん」, breakfast. Now plus morning: this morning. But here's the twist. When these two kanji come together, they don't use either of their usual readings. The whole word gets a special reading, 「けさ」. You can't build it from the pieces, so learn it as one sound. You've already met several words like this, and they're all time words with 「今|いま」 in them. 「今日|きょう」, today, is one. 「今年|ことし」, this year, is another. Both have special readings that don't come from the individual kanji. Compare them with 「今晩|こんばん」, tonight, and 「今週|こんしゅう」, this week, which use the regular reading 「こん」. So the rule of thumb is: today, this morning, and this year are special. Most of the others use 「こん」. A common mistake is to say 「こんあさ」. That's not a word. Like other time words, you don't need 「に」 after it: 「けさ七時に起きました|けさしちじにおきました」. Recap: now plus morning, but read as one special word, 「けさ」.",
    ja: "[今朝|けさ]{七時|しちじ}に{起きました|おきました}。",
    en: "I got up at seven this morning." },
  "あさって|": {
    explain: "This is a native Japanese word, usually written in kana. It fits into a chain of days that's worth learning together. 「きのう」 is yesterday, 「きょう」 is today, 「あした」 is tomorrow, and 「あさって」 is the day after that. A way to remember it: 「あした」 and 「あさって」 both start with the same sound, so think of A for After. Tomorrow, and then After tomorrow. And if you want to go one more step, the day after the day after tomorrow is 「しあさって」, which is just 「あさって」 with an extra sound in front. Going backwards, the day before yesterday is 「おととい」. Like other time words relative to today, you don't put 「に」 after it. Say 「あさって行きます|あさっていきます」, with no 「に」. It's perfectly fine in polite speech, and it's very common when making plans: 「あさってはひまですか」, are you free the day after tomorrow? Recap: tomorrow is 「あした」, and one step further is 「あさって」, the A for After day.",
    ja: "[あさって]テストがあります。",
    en: "I have a test the day after tomorrow." },
  "まいしゅう|毎週": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「毎|まい」, means every. You know it from 「毎日|まいにち」, every day, and 「毎晩|まいばん」, every night. The second, 「週|しゅう」, means week. Look at its shape. The bottom left has the movement radical, the one that looks like a winding road. Inside sits a part meaning around, or a full circle. So a week is time going around one full cycle. You know this kanji from a whole family: 「今週|こんしゅう」, this week, 「来週|らいしゅう」, next week, 「先週|せんしゅう」, last week, and 「週末|しゅうまつ」, the weekend, literally the end of the week. Put them together and 「毎週|まいしゅう」 is every week. Grammar note: like other time words built with 「毎|まい」, you don't use 「に」 after it. Just say 「毎週テニスをします|まいしゅうテニスをします」. You can do the same with month and year too, once you meet those words: every plus month, every plus year. Recap: every plus week, the same 「毎|まい」 as every day and the same 「週|しゅう」 as this week.",
    ja: "[毎週|まいしゅう]テニスをします。",
    en: "I play tennis every week." },
  "こんげつ|今月": {
    explain: "Two kanji, both with their Chinese-origin readings. The first, 「今|こん」, means now or this. On its own it's 「いま」, now, but in compounds it often becomes 「こん」, like in 「今週|こんしゅう」, this week, 「今晩|こんばん」, tonight, and 「今学期|こんがっき」, this semester. The second, 「月|げつ」, means moon or month. Its native reading is 「つき」, the moon. It also shows up as 「げつ」 in 「月曜日|げつようび」, Monday, the moon day. A month is one cycle of the moon, which is why one kanji covers both. So 「今月|こんげつ」 is this month. Now swap the first kanji and you get a whole set. 「来月|らいげつ」 is next month, using 「来|らい」, coming. It works exactly like 「来週|らいしゅう」, next week. Watch out for one trap: the names of months, like January and February, use a different reading, 「がつ」. So it's 「一月|いちがつ」, January, but 「今月|こんげつ」, this month. Recap: this plus moon equals this month, with the moon read 「げつ」.",
    ja: "[今月|こんげつ]はいそがしいです。",
    en: "I'm busy this month." },
  "らいげつ|来月": {
    explain: "Two kanji, both with their Chinese-origin readings. The first, 「来|らい」, means coming. It's the kanji from the verb 「来る|くる」, to come, which uses the native reading. In time words it becomes 「らい」 and points to the one that's coming next. The second, 「月|げつ」, means moon or month. A month is one turn of the moon. You know it from 「月曜日|げつようび」, Monday, and from 「今月|こんげつ」, this month. So 「来月|らいげつ」 is the coming month: next month. Here's the family that makes it easy. 「来週|らいしゅう」 is next week, 「来年|らいねん」 is next year, and 「来学期|らいがっき」 is next semester. They all use 「来|らい」 for next. And there's 「将来|しょうらい」, the future, where 「来|らい」 means what's coming. Like other time words, don't put 「に」 after it. Just say 「来月行きます|らいげついきます」. Recap: the coming moon is next month, part of the same family as next week and next year.",
    ja: "[来月|らいげつ]{日本|にほん}に{行きます|いきます}。",
    en: "I'm going to Japan next month." },
  "カメラ|": {
    explain: "This is a loanword from English, camera. The sound fit into Japanese very easily: three beats, each one a consonant plus a vowel. The English r becomes the Japanese 「ラ」 sound, which sits somewhere between an English r and l. The English word itself has a fun history. It comes from Latin, where camera simply meant a room or chamber. Early cameras were literally dark rooms with a tiny hole that let in light and projected an image on the wall. Later the room shrank into a box, and the name stuck. Japan has a special connection to cameras. Many of the world's best-known camera makers are Japanese, and taking photos everywhere you go is a big part of travel culture there. You'll also hear 「デジカメ」, a shortened form of digital camera. Japanese loves chopping long loanwords into short, snappy ones, just like 「カラオケ」 uses a shortened orchestra. To take a photo, people say 「しゃしんをとる」. Recap: from English camera, which goes back to the Latin word for a room.",
    ja: "{新しい|あたらしい}[カメラ]をかいました。",
    en: "I bought a new camera." },
  "ところ|所": {
    explain: "This is a native Japanese word, and the kanji 「所|ところ」 uses its native reading here. Its left side looks like the kanji for a door, and its right side is an old element for an axe. The kanji's origin is debated, so take this as a hook rather than history. A way to remember it: a door marks a spot, a place where something is. It's a very general word. It can be a physical place, like 「きれいなところ」, a pretty place, or 「しずかなところ」, a quiet place. A great phrase to learn is 「どんなところですか」, what kind of place is it? You can ask it about someone's hometown and get them talking. You'll often see it written in kana only, especially when it's used in a more abstract way. Both spellings are correct. The kanji shows up with a Chinese-origin reading in other words you'll meet later, like the words for an address and a kitchen, so keep an eye out for it. A common mistake is to think it only means a big place like a city. It can also be a tiny spot, like the place on a map or a spot by the window. Recap: a general, everyday word for a place or spot, and you'll often see it in kana.",
    ja: "きれいな[所|ところ]ですね。",
    en: "It's a beautiful place, isn't it?" },
  "トマト|": {
    explain: "This loanword came into Japanese from English tomato. The sounds fit Japanese perfectly, because each syllable is already a simple consonant plus a vowel. So Japanese keeps all three beats, each one short and even. English speakers tend to stress the middle beat. Japanese gives each beat the same length, so try saying it smooth and flat. The word has a long journey behind it. English got it from Spanish, and Spanish got it from the Aztec language of Mexico, Nahuatl, where the plant was first grown. Spanish explorers carried the plant, and the word, to Europe. Many vegetables and fruits in Japanese come from English this way, written in katakana. Think of 「バナナ」 or 「レタス」. In Japan you'll often see it in salads, sandwiches and bento lunches. In a recipe, you might cut it with 「切る|きる」: 「トマトを切ります|トマトをきります」. Recap: from English tomato, which came from Spanish and the Aztec language, three even beats in Japanese.",
    ja: "[トマト]をきってください。",
    en: "Please cut the tomato." },
  "はし|": {
    explain: "This is a native Japanese word. It does have a kanji, 「箸|はし」, with the bamboo radical on top, because chopsticks were made of bamboo. But it's very often written in kana. Here's the tricky part. The sound 「はし」 also means bridge, written 「橋|はし」, and edge, written 「端|はし」. Japanese tells them apart with pitch. In standard Tokyo speech, chopsticks start high and drop. Bridge starts low and rises. So listen for the melody. A way to remember it: picture your chopsticks laid across your bowl like a little bridge. You'll often hear the polite form 「おはし」 at the table. Some etiquette that every visitor should know. Don't stick your chopsticks straight up in a bowl of rice. That's done at funerals, as an offering to the dead. Also, don't pass food from your chopsticks to someone else's. That too recalls a funeral custom. When you're done, lay them down neatly across your bowl or on the chopstick rest. Japanese chopsticks are usually shorter and more pointed than Chinese ones, which makes them good for picking bones out of fish. Recap: same sound as bridge, a different melody, and some important table manners.",
    ja: "[はし]でごはんを{食べます|たべます}。",
    en: "I eat rice with chopsticks." },
  "パーティー|": {
    explain: "A loanword from English party. Japanese can't end a syllable on an r sound, so the r in party disappears. The vowel before it gets stretched instead, which is what the long dash after 「パ」 does. The tricky bit is the tea sound in the middle. Traditional Japanese only has the sound chi there, so to write a real tea sound, Japanese uses 「テ」 with a small 「ィ」 after it. That small 「ィ」 is a modern tool for sounds that native Japanese words don't have. Then a second long dash stretches the final vowel. You may also see it spelled with no final dash. Both spellings are used and both are correct. You use it with 「する」 or with 「ある」: 「パーティーがあります」, there's a party. A cultural note: in Japan, parties with coworkers or classmates are often held at a pub-style restaurant, where everyone starts with a toast of 「乾杯|かんぱい」. There are welcome parties in spring and year-end parties in December. Recap: English party, with the r gone, the vowels stretched, and a small 「ィ」 for the tea sound.",
    ja: "{週末|しゅうまつ}に[パーティー]があります。",
    en: "There's a party on the weekend." },
  "バーベキュー|": {
    explain: "A loanword from English barbecue. Watch how the sounds get adapted. The r at the end of the first syllable disappears, and the vowel stretches instead, shown by the dash after 「バ」. The b sounds stay as the Japanese b sound, and each consonant gets a vowel after it, so 「ベ」 gets its own beat. Then the last part, cue, uses 「キ」 plus a small 「ュ」, which squeezes the sound into one beat, and a final dash stretches it. The English word itself comes from Spanish, which borrowed it from a native Caribbean language. It was originally a wooden frame for cooking or drying meat over a fire. You do one with 「する」: 「バーベキューをする」. A cultural note: barbecue in Japan is a popular group outing, especially by a river or at a park in summer. Groups of friends and coworkers bring grills, meat and vegetables, and cook together. It's very social, so you'll often hear it with 「みんなで」, everyone together. Japanese barbecue usually means grilling thin slices of meat and vegetables, not slow-smoked meat. Recap: English barbecue, with the r dropped, long vowels stretched, and a small 「ュ」 for the cue sound.",
    ja: "みんなで[バーベキュー]をしましょう。",
    en: "Let's all have a barbecue together." },
  "ホームステイ|": {
    explain: "This is made from two English words, home and stay. Look at how each half was squeezed into Japanese. Home becomes 「ホーム」. The long o vowel gets a dash, and the m gets its own beat with an extra vowel added after it, 「ム」. Stay becomes 「ステイ」. Japanese can't start with two consonants together like s and t, so it adds a little vowel after the s, giving 「ス」. Then the ending is written with 「テイ」. You've got a sibling in 「ホームシック」, homesick, which uses the same 「ホーム」. And for the people you stay with, you've got 「ホストファミリー」, your host family. You do a homestay with 「する」: 「ホームステイをする」. A cultural note: many students who study in Japan do a homestay. It's a great way to see daily life, eat home cooking, and practice Japanese every day. Common tips include taking off your shoes at the door, offering to help, and bringing a small gift from home when you arrive. Recap: home plus stay, each word reshaped to fit Japanese sounds.",
    ja: "{日本|にほん}で[ホームステイ]をしました。",
    en: "I did a homestay in Japan." },
  "スペイン|": {
    explain: "The name of the country, a loanword from English Spain. Japanese can't start a word with the cluster s and p together, so it adds a small vowel after the s, giving 「ス」. Then the rest, pain, becomes 「ペイン」. Interestingly, older Japanese used a name that was closer to the country's own Spanish name. The modern name follows English. Country names give you a really useful pattern. Add 「語|ご」 for the language, 「スペイン語|スペインご」, Spanish. Add 「人|じん」 for the people, 「スペイン人|スペインじん」, a Spanish person. You can do the same with 「日本|にほん」: 「日本語|にほんご」 and 「日本人|にほんじん」. It's the same trick for any country, so it's worth practicing a few. A historical note: Spanish and Portuguese traders and missionaries were among the first Europeans to reach Japan, in the 1500s. Some everyday Japanese words came in from that time, like the word for bread, which comes from Portuguese. Recap: English Spain with an extra vowel after the s, and add 「語|ご」 or 「人|じん」 for the language and the people.",
    ja: "{友|とも}だちは[スペイン]の{人|ひと}です。",
    en: "My friend is from Spain." },
  "なにか|何か": {
    explain: "This is 「何|なに」, what, plus the little particle 「か」. You know 「か」 as the question marker. Here it adds a feeling of uncertainty. What, I'm not sure, some sort of thing. So it becomes something. The same trick works with other question words. 「だれ」 plus 「か」 is 「だれか」, someone. 「どこ」 plus 「か」 is 「どこか」, somewhere. 「いつ」 plus 「か」 is 「いつか」, someday. One pattern, a whole family. Now compare it with 「何も|なにも」, which you also know. With a negative verb, it means not anything. So the question 「何か食べましたか|なにかたべましたか」, did you eat something?, has two natural answers: 「はい、食べました|はい、たべました」, or 「いいえ、何も食べませんでした|いいえ、なにもたべませんでした」, I didn't eat anything. A common mistake is to answer with 「何か|なにか」 in the negative. Use 「何も|なにも」 for nothing. You'll often drop the particle 「を」 after it in speech, so 「何か飲みますか|なにかのみますか」 sounds natural. Recap: what plus 「か」 means something, and the same 「か」 makes someone and somewhere.",
    ja: "[何か|なにか]{食べましょう|たべましょう}。",
    en: "Let's eat something." },
  "じょうず|上手": {
    explain: "Let's look at the kanji. 「上|うえ」 means up or above, and 「手|て」 means hand. Picture a hand that's above the rest, a skilled hand. The reading is special, though. 「上|じょう」 uses its Chinese-origin reading, and 「手|ず」 uses an unusual reading you won't see much elsewhere. So learn the sound as a whole word. Its mirror image is 「下手|へた」, poor at, made from down plus hand. Learn the pair together. You've got other words with the hand kanji too: 「歌手|かしゅ」, a singer, a person skilled with songs, and 「手紙|てがみ」, a letter. And the kanji for up shows up in 「年上|としうえ」, someone older. Grammar note: it's a na-adjective, and the skill takes 「が」: 「テニスが上手です|テニスがじょうずです」, good at tennis. A cultural tip: don't say it about yourself. It sounds like bragging. Use it to praise other people. And when someone praises your Japanese with 「上手ですね|じょうずですね」, the modest reply is 「いいえ、まだまだです」, no, I still have a long way to go. Recap: an upper hand is a skilled hand, said about others, never yourself.",
    ja: "{田中|たなか}さんはテニスが[上手|じょうず]です。",
    en: "Mr. Tanaka is good at tennis." },
  "へた|下手": {
    explain: "Let's look at the kanji. 「下|した」 means down or below, and 「手|て」 means hand. Picture a hand that's down low, not much skill. But the reading is special. Neither kanji uses one of its usual readings here, so the whole word is read 「へた」. Learn it as one sound. It's the mirror image of 「上手|じょうず」, skillful, which is up plus hand. Up hand, down hand. That pair is one of the easiest ways to remember both words. You know the down kanji from 「地下鉄|ちかてつ」, the subway, the train that runs under the ground. Grammar note: it's a na-adjective, and the skill takes 「が」: 「歌が下手です|うたがへたです」, bad at singing. A cultural tip: unlike 「上手|じょうず」, this word is fine to use about yourself, and Japanese people do it all the time to sound modest. But saying it directly to someone else about them can sound rude, so be careful. A softer way to say you're not good at something is 「あまり上手じゃないです|あまりじょうずじゃないです」, not very good. Recap: a low hand is a clumsy hand, and it's the modest word you use about yourself.",
    ja: "わたしは{歌|うた}が[下手|へた]です。",
    en: "I'm bad at singing." },
  "いう|言う": {
    explain: "The kanji 「言|い」 uses its native reading here. Its shape has a box at the bottom that looks like a mouth, 「口|くち」, with lines stacked on top. The real origin of the shape is debated, so treat this as a hook. A way to remember it: picture words coming out of a mouth in lines. You'll see this kanji as a building block on the left of lots of kanji about speech, like the ones in 「話す|はなす」, to speak, and 「語|ご」, language. And it's the first kanji in 「言葉|ことば」, a word or language. Here's a sound quirk that surprises learners. It's written 「いう」, but people actually say it like 「ゆう」 in normal speech. Write it one way and say it the other. The key grammar pattern is quoting with 「と」: 「先生はあした休みだと言いました|せんせいはあしたやすみだといいました」, the teacher said there's no class tomorrow. Compare it with 「話す|はなす」. That one is about talking or speaking a language, while 「言う|いう」 is about saying specific words. For the humble version, you already know 「と申します|ともうします」, used for your name. Recap: words coming out of a mouth, written 「いう」 but said like 「ゆう」, and it quotes with 「と」.",
    ja: "{先生|せんせい}はあした{休み|やすみ}だと[言いました|いいました|いう]。",
    en: "The teacher said there's no class tomorrow." },
  "おそくなる|遅くなる": {
    explain: "This is two pieces you know put together. 「遅い|おそい」 is the adjective late or slow. Change the final 「い」 to 「く」 and you get 「遅く|おそく」. Then add 「なる」, to become. So the whole thing literally means to become late. This adjective plus 「なる」 pattern is everywhere. 「寒くなる|さむくなる」 is to get cold. 「暑くなる|あつくなる」 is to get hot. Once you know the pattern, you can describe any change. The kanji 「遅|おそ」 uses its native reading here. Look at its bottom left. That's the movement radical, the winding road shape you also see in 「週|しゅう」, week. Here it's about how slowly you're moving along. Its sibling 「遅刻する|ちこくする」 means to be late for an appointment, like class or work, and there the kanji uses its Chinese-origin reading. The most useful phrase of all: 「遅くなってすみません|おそくなってすみません」, sorry for being late. Or in the past, 「遅くなりました|おそくなりました」, I'm late. It can also mean it's gotten late in the evening: 「遅くなりましたから、帰ります|おそくなりましたから、かえります」. Recap: late plus become means to be late, and it's the go-to word for apologizing.",
    ja: "すみません、[遅くなりました|おそくなりました|おそくなる]。",
    en: "Sorry I'm late." },
  "おふろにはいる|お風呂に入る": {
    explain: "Let's take it apart. 「お」 is the polite prefix. 「風呂|ふろ」 is the bath. 「に」 marks where you go, and 「入る|はいる」 means to enter. So you literally enter the bath. English says take a bath, but Japanese thinks of it as getting into the tub. About the kanji. The first one, 「風|ふ」, normally means wind. You know it from 「台風|たいふう」, a typhoon. But in 「風呂|ふろ」, the kanji are mostly a way of spelling the word, so don't look for a wind meaning in your bath. The verb 「入る|はいる」 uses the native reading. You also know 「入れる|いれる」, to put something in, from the same kanji. A grammar trap: 「入る|はいる」 looks like a ru-verb but it's actually a u-verb. So it's 「入ります|はいります」 and 「入って|はいって」. A cultural note: in Japan, you wash and rinse yourself outside the tub first, then soak in clean hot water. The whole family often uses the same bathwater, one after another, so keeping it clean matters. Many people bathe every night to relax before bed. Recap: you enter the bath, and you wash before you get in.",
    ja: "{毎晩|まいばん}[お風呂に入ります|おふろにはいります|おふろにはいる]。",
    en: "I take a bath every night." },
  "おもう|思う": {
    explain: "This kanji uses its native reading, 「おも」, followed by 「う」. Look at its shape. The top looks like a field, 「田|た」, and the bottom is the heart, 「心|こころ」. A way to remember it: thoughts are what grow in the field of your heart. The heart at the bottom is a real meaning clue. You also see 「心|しん」 in 「心配する|しんぱいする」, to worry, and it's the bottom part of 「念|ねん」 in 「残念|ざんねん」. Kanji about feelings and thoughts often have a heart in them. The key pattern is 「と思います|とおもいます」, I think that. You put your opinion before 「と」: 「あしたは雨だと思います|あしたはあめだとおもいます」, I think it will rain tomorrow. Notice that with nouns and na-adjectives you add 「だ」 before 「と」. Japanese uses this a lot to soften statements. Saying I think, instead of stating something flat out, sounds more modest. For someone else's thoughts, use 「思っています|おもっています」: they think that. Recap: a field over a heart, and 「と思います|とおもいます」 is how you give your opinion.",
    ja: "あしたは{雨|あめ}だと[思います|おもいます|おもう]。",
    en: "I think it will rain tomorrow." },
  "きる|切る": {
    explain: "The kanji 「切|き」 uses its native reading here. Look at its right side. That's 「刀|かたな」, a sword or blade. Anything with a blade shape in a kanji often has to do with cutting. The left side looks like the number seven. A way to remember it: seven quick strokes with a blade. This kanji shows up in some words you know with surprising meanings. 「切符|きっぷ」 is a train ticket, which used to be a slip cut from paper. And 「親切|しんせつ」 means kind. That one's a bit abstract, so just enjoy the connection. Now an important trap. 「着る|きる」, to wear, sounds exactly the same. But they're different verbs and conjugate differently. 「切る|きる」 is a u-verb, so you say 「切ります|きります」 and 「切って|きって」. 「着る|きる」 is a ru-verb, so it's 「着ます|きます」 and 「着て|きて」. Context helps too. You cut vegetables, paper or hair. You wear clothes. You'll also hear it for hanging up the phone, cutting the connection. Recap: a blade on the right means cutting, and it's a u-verb, unlike wear.",
    ja: "{肉|にく}を[切ります|きります|きる]。",
    en: "I cut the meat." },
  "つくる|作る": {
    explain: "The kanji 「作|つく」 uses its native reading here, followed by 「る」. On its left side is a squeezed-in person, the same narrow person shape you see in many kanji. A way to remember it: picture a person busy at work, making something with their hands. You've got a sibling in 「作家|さっか」, a writer, someone who makes books for a living. There the kanji uses its Chinese-origin reading. It's a regular u-verb: 「作ります|つくります」, 「作って|つくって」. It's used for making all sorts of things. Food, like 「ケーキを作る|ケーキをつくる」, to make a cake. Things, like making a chair. Even making friends uses this verb. A common question from English speakers is when to use it and when to use 「する」. Use 「作る|つくる」 when something new comes into existence. Use 「する」 for activities, like doing homework. And for general cooking, there's also 「料理する|りょうりする」. Recap: a person at work, making something new.",
    ja: "{母|はは}とケーキを[作りました|つくりました|つくる]。",
    en: "I made a cake with my mother." },
  "ふる|降る": {
    explain: "The kanji 「降|ふ」 uses its native reading here, followed by 「る」. Look at its left side. That shape is a radical for a hill or a set of steps. The right side is about feet coming down. Together they picture coming down from a hill. That's why this kanji is all about descending. It's used for things that come down from the sky: 「雨が降る|あめがふる」, it rains, and 「雪が降る|ゆきがふる」, it snows. Don't try to use 「する」 with rain. In Japanese, rain and snow always fall. You've got a sibling with the same kanji, 「降りる|おりる」, to get off a train or a bus. It's the same idea of coming down, but with a different native reading. The ongoing form is used for weather happening right now: 「雨が降っています|あめがふっています」, it's raining. It's a u-verb: 「降ります|ふります」, 「降って|ふって」. Recap: coming down the hill, the verb for rain and snow falling, and the same kanji as getting off a train.",
    ja: "{雨|あめ}が[降っています|ふっています|ふる]。",
    en: "It's raining." },
  "もっていく|持っていく": {
    explain: "This is two verbs joined together. 「持って|もって」 is the te-form of 「持つ|もつ」, to hold or carry. 「いく」 is to go. So the literal meaning is to go while holding something. In other words, you take it with you. The kanji 「持|も」 uses its native reading here. On its left is the hand radical, which shows up in lots of action kanji, like 「捨てる|すてる」, to throw away. A hand that holds: that's 「持つ|もつ」. Now flip the direction. Swap 「いく」 for 「くる」, to come, and you get 「持ってくる|もってくる」, to bring something here. Going away from where you are means take. Coming toward where you are means bring. Think about which way you're moving. To a friend's party, you take a dish: 「持っていきます|もっていきます」. If your friend says bring a dish, from their point of view it's 「持ってきて|もってきて」. One important limit: this is for things, not people. For taking a person somewhere, Japanese uses a different verb. Recap: hold it and go, and you take it along; hold it and come, and you bring it.",
    ja: "かさを[持っていきます|もっていきます|もっていく]。",
    en: "I'll take an umbrella." },
  "すてる|捨てる": {
    explain: "The kanji 「捨|す」 uses its native reading here, followed by 「てる」. On its left side is the hand radical, the same one you see in 「持つ|もつ」, to hold, and 「掃除|そうじ」, cleaning. A way to remember it: picture your hand opening and letting go of something you don't want. It's a ru-verb, so it's 「捨てます|すてます」 and 「捨てて|すてて」. The most common phrase is 「ごみを捨てる|ごみをすてる」, to throw away the garbage, using 「ごみ」, which you know. A cultural note: throwing away garbage in Japan is serious business. Trash has to be sorted into burnable and non-burnable items, bottles, cans and plastic, and each type goes out only on its own day of the week. Neighbors notice if you get it wrong, and public trash cans are rare, so many people carry their trash home. If you do a homestay, ask your host family about the rules on your first day. Recap: a hand letting go means to throw away, and in Japan you sort it first.",
    ja: "ごみを[捨てます|すてます|すてる]。",
    en: "I throw away the trash." },
  "はじめる|始める": {
    explain: "The kanji 「始|はじ」 uses its native reading here, followed by 「める」. Its left side is the kanji for woman. The origin of the full shape is not something to rely on, so let's use meaning and sound to anchor it. The key grammar point is that 「始める|はじめる」 takes an object with 「を」. You begin something: 「仕事を始めます|しごとをはじめます」, I start work. It's a ru-verb, so 「始めます|はじめます」 and 「始めて|はじめて」. There's also a partner verb you'll meet, for when something begins on its own, like a class starting. That one takes 「が」 instead. So you begin a class, but a class begins. Here's a lovely connection. The phrase 「はじめまして」, nice to meet you, comes from the same native root, meaning for the first time. It's usually written with a different kanji, one that means first, but the sound and idea are the same. So when you say it, you're saying this is our beginning. Another useful phrase is 「始めましょう|はじめましょう」, let's begin, which teachers say at the start of class. Recap: to begin something with 「を」, from the same root as the greeting for a first meeting.",
    ja: "{九時|くじ}にしごとを[始めます|はじめます|はじめる]。",
    en: "I begin work at nine." },
  "うんてんする|運転する": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「運|うん」, means to carry or to transport. It has the movement radical at the bottom left, the winding road shape. It can also mean luck, as in good fortune that carries you along. The second, 「転|てん」, means to turn or to roll. Look at its left side: it's 「車|くるま」, a car or vehicle. A vehicle with turning wheels. Together they suggest moving something along by turning wheels. That's driving. Add 「する」 to make the verb. Here's a great sibling: 「自転車|じてんしゃ」, a bicycle. It has the same 「転|てん」, plus 「自|じ」, self, and 「車|しゃ」, vehicle. A vehicle whose wheels you turn yourself. The thing you drive takes 「を」: 「車を運転する|くるまをうんてんする」. A cultural note: in Japan, people drive on the left side of the road, and you can get a driver's license at eighteen. In big cities like Tokyo, many people don't drive at all, because trains are so convenient. Recap: carry plus turning wheels, the same turning kanji as in bicycle.",
    ja: "{父|ちち}は{車|くるま}を[運転します|うんてんします|うんてんする]。",
    en: "My father drives a car." },
  "うん|": {
    explain: "This is the casual way to say yes. It's the everyday version of 「はい」. Use it with friends, family and people younger than you. With teachers, bosses or strangers, stick with 「はい」. Switching to 「うん」 with someone you should be polite to can sound too familiar. It also works as a listening sound while someone talks. Japanese listeners make little sounds of agreement all the time, to show they're following along. With friends, that sound is often 「うん、うん」. A way to remember it: it's basically the English mm-hmm, the little grunt of agreement. Just say it with a nod. Watch out for its opposite, 「ううん」, which means no. They look almost the same, but the extra 「う」 at the start and the change in pitch flip the meaning. Listen closely to the melody. It pairs naturally with casual speech forms: 「うん、いいよ」, yeah, sure, or 「うん、行く|うん、いく」, yeah, I'll go. Recap: the friendly, casual yes, like mm-hmm, and only with people close to you.",
    ja: "[うん]、いいよ。",
    en: "Yeah, sure." },
  "ううん|": {
    explain: "This is the casual way to say no, the everyday version of 「いいえ」. It looks almost the same as 「うん」, yes, but there's an extra 「う」 at the start. It's also said with a different melody. That little change flips the meaning completely. A way to remember it: think of English uh-uh versus uh-huh. Two sounds that are almost identical, but one means no. The Japanese pair works just the same way. Use it with friends and family, never with your teacher or boss. With them, stick with 「いいえ」. It's often followed by a casual negative: 「ううん、行かない|ううん、いかない」, no, I'm not going. Careful not to mix it up with a long, thinking sound like 「うーん」, which is more like hmm, let me think. That one is just a pause, not a no. People usually shake their head a little as they say 「ううん」, which helps make it clear. Recap: the casual no, with an extra 「う」 and a dip in pitch, just like uh-uh.",
    ja: "[ううん]、{行かない|いかない}。",
    en: "No, I'm not going." },
  "いつも|": {
    explain: "This is 「いつ」, the question word when, plus the particle 「も」. When you add 「も」 to a question word and use a positive verb, it covers every case. So 「いつ」 plus 「も」 means at any time, every time: always. Compare it with 「何も|なにも」, which you also know. There, 「も」 with a negative verb means not anything. So 「も」 after a question word can mean all or none, depending on the verb. It sits at the top of a ladder of frequency words you've learned. 「いつも」, always. 「よく」, often. 「ときどき」, sometimes. 「あまり」 with a negative, not much. And 「ぜんぜん」 with a negative, not at all. Learning them as a ladder makes them easy to use. You usually put it before the verb, or near the start of the sentence: 「いつも七時に起きます|いつもしちじにおきます」, I always get up at seven. A common everyday phrase is 「いつもありがとう」, thanks for always being there. People say it to friends and family. Recap: when plus 「も」 means every time, which is always.",
    ja: "[いつも]{七時|しちじ}に{起きます|おきます}。",
    en: "I always get up at seven." },
  "おそく|遅く": {
    explain: "This is the adjective 「遅い|おそい」, late or slow, with its final 「い」 changed to 「く」. That change turns an i-adjective into an adverb, a word that describes an action. So 「遅い|おそい」 describes something, and 「遅く|おそく」 describes doing something late. For example, 「遅く寝ました|おそくねました」, I went to bed late. 「遅く起きました|おそくおきました」, I got up late. You know the same pattern with 「早い|はやい」, early: 「早く|はやく」, early or quickly. So 「早く起きる|はやくおきる」 and 「遅く起きる|おそくおきる」 make a perfect pair. It also forms 「遅くなる|おそくなる」, to become late, which you've learned. A useful phrase is 「遅くまで|おそくまで」, until late: 「遅くまでべんきょうしました|おそくまでべんきょうしました」, I studied until late. The kanji 「遅|おそ」 uses its native reading. It has the movement radical, the winding road at the bottom left, about moving slowly along. Recap: change the 「い」 of late to 「く」, and you can do things late.",
    ja: "きのうは[遅く|おそく]{寝ました|ねました}。",
    en: "I went to bed late yesterday." },
  "かんぱい|乾杯": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「乾|かん」, means dry. The second, 「杯|ぱい」, means a cup or a glass. Notice the tree radical on its left side, because cups were often made of wood. So the word literally says dry the cup, which is just like the English bottoms up. Drink until the cup is dry. About the sound: 「杯|はい」 starts with an h sound on its own, but after the 「ん」 of 「かん」, it changes to a p sound, 「ぱい」. Sound changes like this are common when kanji join together. The same kanji works as a counter for cups and glasses, so you'll hear it counting drinks later. Chinese uses the same pair of kanji for its toast, too. A cultural note: at a Japanese party, nobody drinks until the toast. Someone gives a short speech, everyone raises their glass, says 「乾杯|かんぱい」 together, and then drinks. It's polite to pour drinks for others, and let them pour for you, instead of filling your own glass. Recap: dry the cup, the Japanese bottoms up, and wait for the toast before you drink.",
    ja: "{誕生日|たんじょうび}おめでとう！[乾杯|かんぱい]！",
    en: "Happy birthday! Cheers!" },
  "みんなで|": {
    explain: "This is 「みんな」, everyone, plus the particle 「で」. You know 「で」 for places and for tools, like eating with chopsticks. Here it marks how many people take part, or the group that does something. So 「みんなで」 means doing it as everyone, all together. You know a sibling: 「一人で|ひとりで」, alone, by yourself. It's the same 「で」. One person doing it, or everyone doing it. A typical use: 「みんなで食べましょう|みんなでたべましょう」, let's all eat together. Or 「みんなで歌いました|みんなでうたいました」, we all sang together. Watch for a difference. 「みんなが」 just means everyone does it, maybe separately. 「みんなで」 means they do it together, as one group. Everyone has lunch versus everyone has lunch together. A way to remember it: think of 「で」 as with, as in with everyone. It fits the Japanese love of group activities, like a barbecue by the river, karaoke with coworkers, or a class trip. Recap: everyone plus 「で」 means all together, the group version of by yourself.",
    ja: "[みんなで]{歌|うた}を{歌いました|うたいました}。",
    en: "We all sang a song together." },
  "ざんねん|残念": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「残|ざん」, means to remain or be left over. The second, 「念|ねん」, means a thought or feeling. Look at its shape: on top is 「今|いま」, now, and at the bottom is the heart, 「心|こころ」. A feeling in your heart right now. That bottom heart is the same one in 「思う|おもう」, to think. So together, the word is a feeling that remains, something that stays with you. That's regret or disappointment. You use it to react when something doesn't work out. If a friend can't come to your party, you say 「残念ですね|ざんねんですね」, that's too bad. If you didn't win, 「残念でした|ざんねんでした」. It's also a gentle way to turn down an invitation. Starting with 「残念ですが|ざんねんですが」, unfortunately, sounds kind and polite. A common mistake is to use it for serious tragedies. It's for everyday disappointment, like missing out or bad luck. For deeper loss, Japanese uses other expressions. Recap: a feeling left behind in your heart, the everyday that's too bad.",
    ja: "あした{来ません|きません}か。[残念|ざんねん]ですね。",
    en: "You're not coming tomorrow? That's too bad." },
  "まだ|": {
    explain: "This native word has two main uses, and Genki focuses on one of them. With a negative verb, it means not yet: 「まだ食べていません|まだたべていません」, I haven't eaten yet. Notice the form. In Japanese, not yet uses the te-form plus 「いません」, not the past tense. A very common mistake is to say 「まだ食べませんでした|まだたべませんでした」. That sounds wrong. The idea is that you're still in the state of not having eaten. Its partner is 「もう」, already. So the question is 「もう食べましたか|もうたべましたか」, have you eaten already? If yes, 「はい、食べました|はい、たべました」. If no, the short answer is 「いいえ、まだです」, no, not yet. With a positive sentence, 「まだ」 means still: 「まだ学生です|まだがくせいです」, I'm still a student. A way to remember it: Ma, dinner's not ready yet. Picture someone asking if it's done, and the answer is, not yet. Recap: with a negative, not yet, and remember the te-form with 「いません」.",
    ja: "[まだ]{食べていません|たべていません}。",
    en: "I haven't eaten yet." },
  "〜について|": {
    explain: "You put this right after a noun to mean about or concerning that topic. It's built from the particle 「に」 and the te-form of an old verb meaning to attach or follow. So the idea is attached to that topic, sticking to it. You don't need to use the verb, just the whole chunk. Some typical patterns. 「日本について話しましょう|にほんについてはなしましょう」, let's talk about Japan. 「かぞくについて書きます|かぞくについてかきます」, I'll write about my family. It works with verbs like talk, write, think, read and ask. So it's great for essays, presentations and class discussions. To modify a noun, add 「の」: 「日本についての本|にほんについてのほん」, a book about Japan. A common mistake for English speakers is to use it for casual chatter where English about means roughly, like around ten o'clock. For approximate times, Japanese uses 「ごろ」 instead. 「について」 is only for topics. Recap: noun plus 「について」 means about that topic, perfect for talks and essays.",
    ja: "{日本|にほん}[について]{話しましょう|はなしましょう}。",
    en: "Let's talk about Japan." },
  "〜ど|〜度": {
    explain: "This is a counter for degrees, placed after a number. The kanji 「度|ど」 uses its Chinese-origin reading. Its basic idea is a measure or a degree, how much of something there is. So 「三十度|さんじゅうど」 is thirty degrees, and 「何度|なんど」 asks how many degrees. You'll pair it with 「気温|きおん」, temperature: 「気温は二十度です|きおんはにじゅうどです」. Japan uses Celsius. Thirty degrees is a hot summer day, twenty is pleasant, and zero is freezing. If you're used to Fahrenheit, that can be confusing at first. You also use it for a fever: thirty-eight degrees is a real fever. Here's a sibling you know: 「もう一度|もういちど」, one more time. In that phrase, the same kanji counts times. One time, two times. So 「度|ど」 can measure degrees or count times. For below zero, Japanese uses a word for minus before the number, so cold winter forecasts are easy to follow. Recap: number plus 「度|ど」 is degrees, and the same kanji counts times in one more time.",
    ja: "{今日|きょう}は[三十五度|さんじゅうごど|〜ど]です。",
    en: "It's thirty-five degrees today." },
  "どう|": {
    explain: "This is the question word how. It belongs to the family of words that start with 「こ」, 「そ」, 「あ」 and 「ど」. You know 「これ」, 「それ」, 「あれ」 and 「どれ」. In the same way, 「こう」 means this way, 「そう」 means that way, 「ああ」 means that way over there, and 「どう」 asks which way, or how. That's why 「そうですね」 means that's right: it's literally that way, isn't it. The most common use is asking how something is: 「どうですか」, how is it? Or in the past, 「どうでしたか」, how was it? 「テストはどうでしたか」, how was the test? It's also used for offering things: 「コーヒーはどうですか」, how about some coffee? And it builds other question words. 「どうして」 means why. In very polite situations, like in a restaurant or with a guest, you'll hear a fancier word for how in its place. But 「どう」 is perfectly fine for everyday polite speech. Recap: the 「ど」 question word for how, used to ask how things are and to offer things.",
    ja: "テストは[どう]でしたか。",
    en: "How was the test?" },
  "かいしゃいん|会社員": {
    explain: "Three kanji, all with Chinese-origin readings. The first two make 「会社|かいしゃ」, a company. 「会|かい」 means to meet or gather. You know it from 「会う|あう」, to meet, which uses the native reading. 「社|しゃ」 means a company or society, and you also see it in 「神社|じんじゃ」, a shrine, and 「社長|しゃちょう」, a company president. So a company is a gathering of people working together. The last kanji, 「員|いん」, means member, a person on the staff. You know it from 「駅員|えきいん」, a station attendant, a member of the station staff. Put it together: a member of a company. That's an office worker, a company employee. It's the standard answer for someone who works at a company and isn't a boss. On forms in Japan, it's one of the job boxes you can tick. You'll also hear a loanword for male office workers, built from English salary and man. A cultural note: being a company employee in Japan has traditionally meant long hours and evenings out with coworkers. That's slowly changing. Recap: company plus member equals office worker, with the same member kanji as station staff.",
    ja: "{兄|あに}は[会社員|かいしゃいん]です。",
    en: "My older brother is an office worker." },
  "しごと|仕事": {
    explain: "Two kanji. The first, 「仕|し」, means to serve or to do work for someone. On its left is the narrow person radical, so it's a person who serves. The second, 「事|ごと」, means a thing or a matter. Its native reading is 「こと」, but in this word it becomes 「ごと」, with the sound softened because it comes second. You know the same kanji with its Chinese-origin reading 「じ」 in 「用事|ようじ」, an errand, and 「返事|へんじ」, a reply. So the word is the things you do in service, your work. It covers a job, a task, and an occupation. Use it for both. 「仕事があります|しごとがあります」 can mean I have work to do today, and 「仕事は何ですか|しごとはなんですか」 asks what someone's job is. To be polite, add 「お」: 「お仕事は|おしごとは」. A common English speaker mistake is to use it like a countable job title. Japanese tends to say 「会社員|かいしゃいん」 or 「先生|せんせい」 for the role, and 「仕事|しごと」 for the work itself. After work, people say 「おつかれさまでした」 to thank each other for their hard work. Recap: things you do in service, your job and your work.",
    ja: "{父|ちち}の[仕事|しごと]はいそがしいです。",
    en: "My father's job keeps him busy." },
  "カラオケ|": {
    explain: "This one's special, because it's a Japanese invention, and the word went from Japanese into English, not the other way around. It's made of two parts. 「から」 is a native Japanese word meaning empty. You know it from 「空手|からて」, karate, literally empty hand, fighting with no weapon. 「オケ」 is short for 「オーケストラ」, orchestra, a loanword from English. Japanese loves chopping long loanwords down to short ones. So the word means empty orchestra. The music is all there, but the singer's part is empty, so you fill it in. Karaoke machines spread in Japan in the 1970s, and from there to the rest of the world. Notice how English speakers say it compared with Japanese, which keeps each beat short and even. A cultural note: in Japan, people usually go to karaoke boxes, private rooms you rent by the hour with friends. Nobody has to sing in front of strangers. It's a popular way to end a night out with coworkers or classmates, and you go with 「行く|いく」: 「カラオケに行く|カラオケにいく」. Recap: an empty orchestra, the same empty as in karate, and a gift from Japan to the world.",
    ja: "{友|とも}だちと[カラオケ]に{行きました|いきました}。",
    en: "I went to karaoke with friends." },
  "きせつ|季節": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「季|き」, means season. On top is the grain radical, a plant with a drooping head of grain, and below it is 「子|こ」, child. A way to remember it: the grain grows and ripens with the seasons. The second, 「節|せつ」, has the bamboo radical on top. It first meant a joint or node of bamboo, the rings that divide a bamboo stalk into sections. From there it came to mean a division or a period of time. So the year is like a bamboo stalk, divided into sections, and each section is a season. The four seasons you know are 「春|はる」, 「夏|なつ」, 「秋|あき」 and 「冬|ふゆ」. All four use native readings. A typical question: 「どの季節が好きですか|どのきせつがすきですか」, which season do you like? A cultural note: Japan is very proud of its four distinct seasons. Food, decorations and even snacks change with each one: cherry blossoms in spring, fireworks in summer, red leaves in fall, and hot pots in winter. Traditional poems often include a seasonal word, so every reader knows what time of year it is. Recap: grain that grows with the year, and a bamboo joint that divides it, give you season.",
    ja: "どの[季節|きせつ]が{好き|すき}ですか。",
    en: "Which season do you like?" },
  "はる|春": {
    explain: "Here the kanji is read with its native Japanese reading. Look at the bottom of 「春|はる」 and you will find the sun, 「日|ひ」. The top part is an old shape whose history scholars still argue about, so here is just a hook instead. A way to remember it: picture new plants pushing up toward a warming sun. Spring is one of a set of four you already know. 「夏|なつ」 is summer, 「秋|あき」 is fall, and 「冬|ふゆ」 is winter, and all four are short native words. You also know 「休み|やすみ」, a break, so 「春休み|はるやすみ」 is spring break. In Japan spring matters even more than usual, because the school year and the working year both start in April. So spring means cherry blossoms, new classes, new jobs and fresh starts all at once. People hold picnics under the blossoms, called 「はなみ」, flower viewing. To recap: the sun at the bottom, and the season when everything begins.",
    ja: "[春|はる]はさくらがきれいです。",
    en: "Cherry blossoms are pretty in spring." },
  "あき|秋": {
    explain: "This is the native reading of the kanji. 「秋|あき」 has two clear parts. On the left is a stalk of grain, the shape called 「のぎへん」, which shows up in many kanji about crops. On the right is fire, 「火|ひ」, the same fire you know from 「火曜日|かようび」, Tuesday. A way to remember it: picture fields of ripe grain glowing red and orange at harvest, as if they were on fire. Fall is harvest time, so grain and fire make a nice picture. It sits with the other seasons, 「春|はる」, 「夏|なつ」 and 「冬|ふゆ」. In Japan fall is famous for red maple leaves, for good food, and for being pleasantly 「涼しい|すずしい」, cool, after the hot summer. People even talk about fall as the season for eating and the season for reading. To recap: grain plus fire, the glowing harvest season.",
    ja: "[秋|あき]はすずしいです。",
    en: "Fall is cool." },
  "ぎゅうにゅう|牛乳": {
    explain: "Both kanji use their Chinese-origin readings here. The first, 「牛|ぎゅう」, means cow. On its own, with the native reading, a cow is 「うし」. The shape is said to be a simple picture of a cow's head with horns, which makes it easy to spot. The second, 「乳|にゅう」, means milk, the milk that a mother animal gives. Put them together and you get cow milk, which is exactly what this word is. You will see the cow kanji again on menus, because beef is 「牛肉|ぎゅうにく」, cow meat. In everyday talk people also say 「ミルク」, from English milk, but on the carton at the supermarket it usually says this kanji word. A small cultural note: Japanese school lunches traditionally come with a little carton of milk every day, so almost every adult in Japan grew up with this word printed in front of them. To recap: cow plus milk, plain cow milk.",
    ja: "{毎朝|まいあさ}[牛乳|ぎゅうにゅう]を{飲みます|のみます}。",
    en: "I drink milk every morning." },
  "ケーキ|": {
    explain: "This comes from the English word cake. Japanese has no single sound for the A in cake, so it became a long E sound, written with 「ケ」 and the long dash. English words that end in a hard K sound need a vowel added in Japanese, so the final K became 「キ」. That is the usual pattern: Japanese syllables end in a vowel, so extra vowels get tacked on. It is written in katakana because it is a loanword. In Japan the word most often means a Western style sponge cake with cream, and cake shops are everywhere, with beautiful little slices in glass cases. A fun cultural note: on Christmas Eve, many Japanese families buy a strawberry shortcake, white cream with red berries on top. Shops take orders weeks ahead. You might also see 「チーズケーキ」, cheesecake, which follows the same pattern. To recap: cake, with a stretched vowel and an extra one at the end.",
    ja: "{母|はは}と[ケーキ]を{作りました|つくりました}。",
    en: "I made a cake with my mother." },
  "すし|": {
    explain: "This is a native Japanese word, usually written in kana or with a special kanji you don't need yet. It is generally linked to an old word meaning sour, the same idea as 「すっぱい」, sour, which you might hear in a kitchen. The reason is the rice. Sushi rice is seasoned with vinegar, so it has a light sour taste. Long ago, sushi was a way of preserving fish packed in fermenting rice, and that was very sour indeed. Here is a sound change worth knowing. When the word comes second in a compound, the first sound becomes voiced, so it turns into 「ずし」. Rolled sushi is 「まきずし」, and conveyor belt sushi is 「かいてんずし」. English speakers often think sushi means raw fish, but the word is really about the vinegared rice. Raw fish on its own is 「さしみ」. To recap: the sour vinegared rice, which becomes 「ずし」 inside longer words.",
    ja: "[すし]を{食べに|たべに}{行きましょう|いきましょう}。",
    en: "Let's go eat sushi." },
  "てんぷら|天ぷら": {
    explain: "Most likely this word came with Portuguese traders and missionaries who reached Japan in the fifteen hundreds. Several Portuguese words have been suggested as the source, and nobody is completely sure which one, so treat the details as uncertain. The Portuguese did fry food in batter, and Japanese cooks took the idea and made it their own. The kanji 「天|てん」 means heaven or sky, the same kanji as in 「天気|てんき」, weather. In this word it is just borrowed for its sound, so don't look for a heavenly meaning. That is also why the rest is written in kana. Tempura is shrimp, fish and vegetables in a very light, crispy batter, often eaten with a dipping sauce and grated radish. A bowl of rice topped with tempura is called 「てんどん」, from the first part of this word plus the word for a rice bowl. To recap: a likely Portuguese import, with the heaven kanji borrowed only for its sound.",
    ja: "[天ぷら|てんぷら]はおいしいです。",
    en: "Tempura is delicious." },
  "りんご|": {
    explain: "Today this word is almost always written in kana. There is a kanji spelling, but it is rare and hard, so kana is what you will see in shops. The word came into Japanese long ago from Chinese, and the sounds were softened over time. A way to remember it: picture an apple with a ring around it, ready to go. Ring, go. Apples in Japan are often very large, sweet and a bit expensive, and they are sometimes given as gifts. Aomori, at the northern tip of the main island, grows more apples than anywhere else in the country, and its name is almost a synonym for apples. When counting apples, use the general counter 「一つ|ひとつ」, 「二つ|ふたつ」 and so on, as in the example. It belongs with 「くだもの」, fruit, and with 「ケーキ」 as a dessert word from this lesson. To recap: a kana word for apple, picture the ring on the apple that you take to go.",
    ja: "[りんご]を{一つ|ひとつ}ください。",
    en: "One apple, please." },
  "りょうり|料理": {
    explain: "Both kanji use their Chinese-origin readings. The first, 「料|りょう」, is made of rice, 「米|こめ」, on the left and a measuring dipper on the right. Measuring out rice gives the idea of materials or ingredients, and also of fees, things that are measured out. The second, 「理|り」, means reason, logic or putting things in order. So the word is ingredients put in order: taking raw materials and arranging them into a dish. It means both the act of cooking and the food that comes out of it, a cuisine. Add 「する」 and you get 「料理する|りょうりする」, to cook, which you already know. Put a country in front and you get a cuisine, like 「日本料理|にほんりょうり」, Japanese food. A common mix up: 「料理|りょうり」 is cooking a real meal. For just making something simple, people often say 「作る|つくる」. To recap: measured ingredients put in order, so cooking and cuisine.",
    ja: "{母|はは}の[料理|りょうり]はおいしいです。",
    en: "My mother's cooking is delicious." },
  "サッカー|": {
    explain: "This comes from the English word soccer. Here is a fun fact. Soccer itself is British slang, made from the middle of the word association, as in association football, plus an E R ending. Japanese uses this word because it came in through American English, where football means something else. Now the sounds. The small 「ッ」 is a pause that doubles the next consonant, so you get a strong K sound in the middle. The E R ending of English turns into a long A sound, written with the dash. You see the same pattern in 「コンピューター」, computer, and in other words that end in E R. Use 「する」 with it: 「サッカーをする」, to play soccer. Japan's national teams are popular, and the men's team is often nicknamed after the color blue. To recap: from English soccer, with a doubled K and a long ending.",
    ja: "{週末|しゅうまつ}に[サッカー]をします。",
    en: "I play soccer on weekends." },
  "やきゅう|野球": {
    explain: "Both kanji are read with their Chinese-origin readings. The first, 「野|や」, means field or open country. You know it from 「野菜|やさい」, vegetables, which is literally field greens. The second, 「球|きゅう」, means ball or sphere. So the word is field ball, a ball game played on a big open field. The word was made in Japan in the late eighteen hundreds when the American game arrived. Baseball is one of the most loved sports in Japan. Every summer the national high school tournament is held at a famous stadium near Osaka, and the whole country watches on TV. Players who lose often scoop up a little of the field's dirt to take home. Use 「する」 to play it and 「見る|みる」 to watch it. To recap: field plus ball, the game played on a big open field.",
    ja: "テレビで[野球|やきゅう]を{見ます|みます}。",
    en: "I watch baseball on TV." },
  "いしゃ|医者": {
    explain: "Both kanji are read with their Chinese-origin readings. The first, 「医|い」, means medicine or healing. The second, 「者|しゃ」, means person, someone who does something. You have this same person kanji in 「研究者|けんきゅうしゃ」, researcher, someone who does research. So a doctor is literally a medicine person. The word for hospital is a different kanji, 「病院|びょういん」, a building for illness, so don't mix the two up. Politeness matters with this word. Talking about your own job, you can say 「医者|いしゃ」 plainly. But for someone else's doctor, people usually say 「お医者さん|おいしゃさん」, with the polite pieces added. And when you speak directly to a doctor, you call them 「先生|せんせい」, the same word as for a teacher. Being a doctor is a classic dream job in Japan, and it often comes up when people talk about what they want to become. To recap: medicine plus person, the person who heals.",
    ja: "{姉|あね}は[医者|いしゃ]です。",
    en: "My older sister is a doctor." },
  "おかねもち|お金持ち": {
    explain: "This one is built from two words you already know. The first is 「お金|おかね」, money. The kanji 「金|かね」 means gold or metal, the same one as in 「金曜日|きんようび」, Friday, gold day. The 「お」 at the front is the polite prefix, and with money it is almost always used. The second part, 「持ち|もち」, comes from the verb 「持つ|もつ」, to hold or to have. You know it from 「持ってくる|もってくる」, to bring. When the verb drops its ending and joins a noun, it means someone who has that thing. So this word is a money haver, someone who holds a lot of money. The same pattern gives 「力持ち|ちからもち」, a person who has strength, a strong person. It is fine in normal conversation, but saying it straight to a person's face can sound a little rude, so be careful. To recap: money plus holding, the person who holds lots of money.",
    ja: "あの{人|ひと}は[お金持ち|おかねもち]です。",
    en: "That person is rich." },
  "ゆうめいじん|有名人": {
    explain: "This is three kanji, all with Chinese-origin readings. The first, 「有|ゆう」, means to have or to exist. The second, 「名|めい」, means name. The same kanji gives you 「なまえ」, name. Together they make 「有名|ゆうめい」, famous, which you already know. Being famous is literally having a name. Then comes 「人|じん」, person. This is the same reading as in 「日本人|にほんじん」, a Japanese person, and 「外国人|がいこくじん」, a foreigner. So the whole word is a person who has a name, a famous person, a celebrity. Note that 「有名|ゆうめい」 is a na-adjective, so to say a famous person in a normal phrase you can also say 「有名な人|ゆうめいなひと」. This compound version is shorter and is the usual word on TV. Japanese TV is full of celebrities on variety shows, and they are often just called 「タレント」, from English talent. To recap: having a name plus person.",
    ja: "きのう[有名人|ゆうめいじん]を{見ました|みました}。",
    en: "I saw a celebrity yesterday." },
  "かお|顔": {
    explain: "This uses the native Japanese reading. The kanji 「顔|かお」 has two halves. The right half is a shape that appears in many kanji about the head. You can see it in 「頭|あたま」, head, as in 「頭がいい|あたまがいい」, smart. Both share that same right side. So when you see that shape, think head. The left half helps with the sound and meaning, but you don't need its history to remember it. A way to remember the sound: picture a cow with a big round face looking at you. Cow, face. This word also shows up in useful phrases. To wash your face is 「顔を洗う|かおをあらう」. And the Japanese idea of face as in reputation is just as strong as in English. Losing face is a real concern. Japanese has lots of idioms with face, like having a wide face, meaning knowing lots of people. To recap: the head shape on the right, and a cow's big face for the sound.",
    ja: "[顔|かお]を{洗います|あらいます}。",
    en: "I wash my face." },
  "としうえ|年上": {
    explain: "Both kanji are read with their native Japanese readings here. The first, 「年|とし」, means year, and by extension age, how many years old you are. With the Chinese-origin reading it is 「ねん」, as in 「来年|らいねん」, next year. The second, 「上|うえ」, means above or on top. It is the same kanji as in 「上手|じょうず」, good at, though there it is read differently. So this word is above in age, someone older than you. The opposite is 「年下|としした」, below in age, someone younger. The pattern is: person, 「は」, me, 「より」, then this word, as in the example. This matters a lot in Japan. Age decides who uses polite speech to whom, and even a single year can change how people talk at school or work. That is why people often ask your age early on. To recap: year plus above, the person above you in age.",
    ja: "{田中|たなか}さんはわたしより[年上|としうえ]です。",
    en: "Mr. Tanaka is older than me." },
  "えき|駅": {
    explain: "This kanji is read with its Chinese-origin reading, but it is used like a plain everyday word. On the left of 「駅|えき」 is a horse, the kanji 「馬|うま」. You can spot the mane and the four legs at the bottom. That horse is there for a real historical reason. Long ago, a station was a post stop on the main roads, where messengers and travelers changed to fresh horses. When the railways came, the same word was used for train stations. So a station is still, in its shape, a place with horses. You will see it in 「駅員|えきいん」, station attendant, a member of the station staff. Big stations in Japan are like small cities, full of shops and restaurants. And meeting someone at a station exit is a very common plan. To ask the way, say 「駅はどこですか|えきはどこですか」. To recap: the horse on the left, from the days of changing horses at the post stop.",
    ja: "[駅|えき]までバスで{十分|じゅっぷん}です。",
    en: "It's ten minutes to the station by bus." },
  "しんかんせん|新幹線": {
    explain: "All three kanji use their Chinese-origin readings. The first, 「新|しん」, means new. You know it from 「新しい|あたらしい」, new, and 「新聞|しんぶん」, newspaper, which is new things heard. The second, 「幹|かん」, means trunk, like a tree trunk, and so the main part of something. The third, 「線|せん」, means line. It has the thread shape on its left, a long line of thread. So the word is new trunk line, the new main railway line. The first one opened in nineteen sixty four, just before the Tokyo Olympics, running between Tokyo and Osaka. It was the fastest train in the world at the time, and it has an amazing safety record. Trains are famously on time, often to within a minute. In English it is called the bullet train because of the rounded nose of the early trains. To recap: new plus trunk plus line, the new main line.",
    ja: "[新幹線|しんかんせん]で{東京|とうきょう}に{行きます|いきます}。",
    en: "I go to Tokyo by bullet train." },
  "ちかてつ|地下鉄": {
    explain: "All three kanji use their Chinese-origin readings. The first, 「地|ち」, means ground or earth. You know it from 「地図|ちず」, map, a ground picture, and 「地震|じしん」, earthquake, the ground shaking. The second, 「下|か」, means below. Together 「地下|ちか」 means underground, and it is also the word for a basement floor in a department store. The third, 「鉄|てつ」, means iron. You can see the metal shape, the left side of 「金|かね」, on its left. In Japan, iron is used as a short way of saying railway, an iron road. So this word is under the ground iron, the underground railway. Tokyo's subway network is one of the busiest in the world, and at rush hour staff sometimes help push people onto the cars. Use 「で」 to say by subway, as in the example. To recap: ground plus below plus iron, the railway under the ground.",
    ja: "[地下鉄|ちかてつ]で{学校|がっこう}に{行きます|いきます}。",
    en: "I go to school by subway." },
  "ふね|船": {
    explain: "This is the native Japanese reading. On the left of 「船|ふね」 is a smaller kanji that is also read 「ふね」 and also means boat. That small one is an old picture of a little boat, and in its full form it looks a bit like a narrow boat seen from above. So the boat shape on the left tells you the topic right away. The bigger kanji is the everyday one for ships of any size, from ferries to huge ocean liners. A way to remember the sound: picture a funny little boat rocking on the waves. Funny boat. Japan is an island country, so boats matter a lot. Ferries connect the main islands with thousands of smaller ones. Use 「で」 to say by boat, as in 「船で行きます|ふねでいきます」, and use 「乗る|のる」, to ride, when you get on: 「船に乗る|ふねにのる」. Notice that you get on with 「に」, the same way you get on a train or a bus. To recap: the little boat on the left, inside the big word for ship.",
    ja: "[船|ふね]で{島|しま}に{行きました|いきました}。",
    en: "I went to the island by boat." },
  "ひこうき|飛行機": {
    explain: "All three kanji use their Chinese-origin readings. The first, 「飛|ひ」, means to fly. The shape is often said to look like a bird's wings, which makes a handy picture. The second, 「行|こう」, means to go. You know it from 「行く|いく」, to go, and from 「旅行|りょこう」, travel. Together, 「飛行|ひこう」 means flight, flying and going. The third, 「機|き」, means machine. So the whole word is a flying machine, which is a perfect description of an airplane. You have a close cousin in 「宇宙飛行士|うちゅうひこうし」, astronaut, which shares the same flying part, a space flight person. And the place planes leave from is 「空港|くうこう」, airport, which is a sky harbor. Use 「で」 for by plane, and 「乗る|のる」 for getting on: 「飛行機に乗る|ひこうきにのる」. To recap: fly plus go plus machine, the flying machine.",
    ja: "[飛行機|ひこうき]で{日本|にほん}に{来ました|きました}。",
    en: "I came to Japan by plane." },
  "よやく|予約": {
    explain: "Both kanji use their Chinese-origin readings. The first, 「予|よ」, means beforehand or in advance. You know it from 「天気予報|てんきよほう」, the weather forecast, which tells you the weather before it happens. It is also in 「予定|よてい」, a plan or schedule, something set beforehand. The second, 「約|やく」, means promise or agreement. It has the thread shape on the left, like tying something together. You know it from 「約束|やくそく」, a promise or appointment. So a reservation is a promise made ahead of time. Add 「する」 to make the verb: 「予約する|よやくする」, to make a reservation. You use it for restaurants, hotels, tickets, and even doctors and hair salons. Popular restaurants in Japan can be booked out for weeks, so this is a very useful word. To recap: beforehand plus promise, a promise made in advance.",
    ja: "ホテルを[予約しました|よやくしました|よやく]。",
    en: "I reserved a hotel." },
  "ツアー|": {
    explain: "This comes from the English word tour. Japanese has no true T U sound, so it uses 「ツ」, which has a little hiss after the T. Then the vowel is stretched with 「ア」 and the long dash, to match the drawn out sound of tour. It is written in katakana because it is a loanword. In Japanese it usually means a package tour, a guided trip that a travel company sets up, with a bus, a guide and a fixed plan. Group tours with a guide holding up a little flag are a classic image of Japanese travelers abroad. You join one with 「に」 and 「参加する|さんかする」, to take part, or simply with 「行く|いく」. It goes nicely with 「旅行|りょこう」, travel, from this same lesson. A tour is one kind of trip, organized by someone else. To recap: from English tour, with a hissy 「ツ」 and a long stretched ending.",
    ja: "{京都|きょうと}の[ツアー]に{行きました|いきました}。",
    en: "I went on a tour of Kyoto." },
  "どうぶつえん|動物園": {
    explain: "All three kanji use their Chinese-origin readings. The first, 「動|どう」, means to move. It has the shape for power on the right, so think of moving with force. You know it from 「活動|かつどう」, activity, and 「感動する|かんどうする」, to be moved emotionally. The second, 「物|ぶつ」, means thing. With the native reading it is 「もの」, as in 「食べ物|たべもの」, food. So 「動物|どうぶつ」, animal, is literally a thing that moves. That is a neat way to describe an animal. The third, 「園|えん」, means garden or park. It is the same kanji as in 「公園|こうえん」, park. You can even see a big box around it, like a fence around a garden. So the whole word is an animal park, a zoo. Ueno Zoo in Tokyo is the most famous, and its giant pandas have drawn huge crowds for decades. To recap: moving thing plus garden, a garden of animals.",
    ja: "[動物園|どうぶつえん]でパンダを{見ました|みました}。",
    en: "I saw pandas at the zoo." },
  "じかん|時間": {
    explain: "Both kanji use their Chinese-origin readings. The first, 「時|じ」, means time or hour. It has the sun, 「日|ひ」, on the left, a nice reminder that people once told time by the sun. You know it from telling the time, like 「三時|さんじ」, three o'clock. With the native reading it is 「とき」, a time when something happens. The second, 「間|かん」, means interval or space between. Look at the shape: a sun inside a gate, light shining through the gap. With the native reading it is 「あいだ」, as in 「この間|このあいだ」, the other day. So the word is a stretch of time, the space between two moments. That is why it also counts hours: 「一時間|いちじかん」 is one hour long. A common mix up: 「三時|さんじ」 is three o'clock, but 「三時間|さんじかん」 is three hours. To recap: hour plus gap, a span of time.",
    ja: "[時間|じかん]がありません。",
    en: "I don't have time." },
  "せかい|世界": {
    explain: "Both kanji use their Chinese-origin readings. The first, 「世|せ」, means world, society, or a generation of people. The second, 「界|かい」, means boundary or realm. It has a rice field, 「田|た」, on top, and fields have edges and borders. So the word is the realm of the world, everything within the borders of human society. The word actually came from Buddhist texts, where it described the universe, and it later came to mean the world as we know it. A very useful add on is 「中|じゅう」, all through. 「世界中|せかいじゅう」 means all over the world. You have the same 「中|じゅう」 in 「一日中|いちにちじゅう」, all day long. To say the world's best, you can say 「世界で一番|せかいでいちばん」, number one in the world, using 「一番|いちばん」 from this lesson. A typical sentence: 「世界は広いです|せかいはひろいです」, the world is big. To recap: world plus boundary, the whole realm of the world.",
    ja: "[世界|せかい]は{広い|ひろい}です。",
    en: "The world is big." },
  "びよういん|美容院": {
    explain: "All three kanji use their Chinese-origin readings. The first, 「美|び」, means beauty. You will meet it again in 「美術館|びじゅつかん」, art museum. The second, 「容|よう」, means appearance or looks. Together, 「美容|びよう」 means beauty care, making your looks beautiful. The third, 「院|いん」, means an institution or building. It is the same kanji as in 「病院|びょういん」, hospital, and 「大学院|だいがくいん」, graduate school. Here is a trap. 「美容院|びよういん」 and 「病院|びょういん」 sound very close. The beauty parlor has a full 「よ」 sound, while the hospital has a small 「ょ」 squeezed in. Listen carefully, or you may end up at the wrong place. In Japan this word is mostly used for a hair salon, the place to get your hair cut and styled. A barber shop for men has its own word. To recap: beauty plus looks plus institution, the place that makes you look good.",
    ja: "[美容院|びよういん]で{髪|かみ}を{切りました|きりました}。",
    en: "I got my hair cut at the beauty parlor." },
  "てぶくろ|手袋": {
    explain: "Both kanji use their native Japanese readings. The first, 「手|て」, means hand. You know it from 「手紙|てがみ」, letter, and 「お手洗い|おてあらい」, restroom, the place to wash your hands. The second, 「袋|ふくろ」, means bag or sack. Look at the bottom of the kanji and you can see the shape for clothing. So gloves are literally hand bags, little bags for your hands. It is a very Japanese way of naming something, just by describing it. Notice the sound change. On its own, bag is 「ふくろ」. When it comes second in a compound, the first sound gets voiced and becomes 「ぶくろ」. This happens a lot in Japanese, just like 「すし」 becoming 「ずし」. Gloves go on with the verb 「する」, as in the example, or with 「はめる」. To recap: hand plus bag, with 「ふくろ」 turning into 「ぶくろ」.",
    ja: "{冬|ふゆ}は[手袋|てぶくろ]をします。",
    en: "I wear gloves in winter." },
  "せいかつ|生活": {
    explain: "Both kanji use their Chinese-origin readings. The first, 「生|せい」, means life or being born. It is the same kanji as in 「学生|がくせい」, student, and 「先生|せんせい」, teacher, someone born before you. It also appears in 「誕生日|たんじょうび」, birthday, with a different reading. The second, 「活|かつ」, means activity or being lively. It has the water shape on its left, and you can think of water flowing, full of life. You know it from 「活動|かつどう」, activity. So the word is life plus activity, the everyday business of living. It means your daily life and lifestyle, like student life or life in Japan. A common mistake: English life can also mean being alive or a whole lifetime, but this word is mostly about the daily routine of living. Add 「する」 and it means to live or get by, as in living on a small budget. To recap: life plus lively activity, your day to day living.",
    ja: "{日本|にほん}の[生活|せいかつ]はたのしいです。",
    en: "Life in Japan is fun." },
  "ことし|今年": {
    explain: "This word has a special reading that belongs to the whole word, not to each kanji. The first kanji, 「今|いま」, means now. The second, 「年|とし」, means year. So the meaning is easy: the year we are in now, this year. But the sound 「ことし」 can't be split neatly into the two kanji, so it is best to learn it as one unit. The same thing happens with 「今日|きょう」, today, and 「今朝|けさ」, this morning, which also have special whole-word readings. Other words with the same kanji use the normal sound 「こん」, as in 「今週|こんしゅう」, this week, and 「今月|こんげつ」, this month. For the years around it, you have 「来年|らいねん」, next year. Notice that last year and next year use 「ねん」, but this year is special. A common greeting at New Year is to ask someone to look after you well again this year. To recap: now plus year, read with its own special sound.",
    ja: "[今年|ことし]{日本|にほん}に{行きます|いきます}。",
    en: "I'm going to Japan this year." },
  "あたたかい|暖かい": {
    explain: "This is the native Japanese reading of the kanji. On the left of 「暖|あたた」 is the sun, 「日|ひ」. That sun is the key. This kanji is for warmth in the air and in the weather, like the warmth of a sunny spring day. There is a second kanji with exactly the same sound, 「温かい|あたたかい」. That one has the water shape on its left, and it is for warm things you touch or drink, like soup or a bath. You know it from 「温泉|おんせん」, hot spring. So remember: sun for warm weather, water for warm food and drinks. In speech they sound identical, so you only need to choose when writing. In casual speech people often shorten it to 「あったかい」. It fits between 「暑い|あつい」, hot weather, and 「涼しい|すずしい」, cool weather, as a nice in between. Warm can also describe a kind heart, with the water version. To recap: the sun on the left for the warmth of the weather.",
    ja: "{今日|きょう}は[暖かい|あたたかい]です。",
    en: "It's warm today." },
  "すずしい|涼しい": {
    explain: "This is the native Japanese reading. On the left of 「涼|すず」 is the water shape, three little drops. On the right is the kanji for capital, the same one at the start of the city name Kyoto, which you may know. A way to remember it: picture a cool breeze blowing in off the water, the most refreshing place in the capital. This word is for pleasantly cool weather, the kind you enjoy. It is used after the summer heat, for an autumn evening, or for shade on a hot day. Compare it with 「寒い|さむい」, which is unpleasantly cold, and 「冷たい|つめたい」, which is cold to the touch. A common mistake is to use this word for a cold drink. For that, Japanese uses 「冷たい|つめたい」. The season of cool is 「秋|あき」, fall, as in the example. Japanese summers are so hot and humid that people really look forward to this feeling. To recap: water on the left, a cool breeze you are happy to feel.",
    ja: "{秋|あき}は[涼しい|すずしい]です。",
    en: "Fall is cool." },
  "つめたい|冷たい": {
    explain: "This is the native Japanese reading. On the left of 「冷|つめ」 are two little strokes. This shape stands for ice, and it shows up in kanji about cold. So this word is about cold you can touch, like ice. Use it for cold drinks, cold water, cold hands, or a cold wind on your skin. It also works for people, like in English, for someone who is cold or unkind. Here is the big trap for English speakers. Cold weather is a different word, 「寒い|さむい」. If you say the day itself is cold, use 「寒い|さむい」. If you touch something cold, use this word. And for pleasantly cool weather you have 「涼しい|すずしい」. The opposite of this word is 「温かい|あたたかい」, warm to the touch. Vending machines in Japan sell both cold drinks, with blue labels, and hot drinks, with red labels, right next to each other. To recap: the ice strokes on the left, for cold you can touch.",
    ja: "[冷たい|つめたい]{水|みず}を{飲みます|のみます}。",
    en: "I drink cold water." },
  "おそい|遅い": {
    explain: "This is the native Japanese reading. The kanji 「遅|おそ」 has the road shape wrapping around the bottom and left side. This shape appears in kanji about moving along a road. A way to remember it: picture someone dragging their feet on a long road, slow and late. That is the double meaning of this word. It can mean slow, as in a slow bus, and it can mean late, as in a late hour. You have already met the adverb 「遅く|おそく」, doing something late, and 「遅くなる|おそくなる」, to be late. The same kanji shows up in 「遅刻する|ちこくする」, to be late for an appointment, and 「乗り遅れる|のりおくれる」, to miss a train. The opposite for both meanings is 「はやい」, with one kanji for early and another for fast. A common phrase at night is 「もう遅いです|もうおそいです」, it's already late. To recap: the road shape for slow going, so slow or late.",
    ja: "このバスは[遅い|おそい]です。",
    en: "This bus is slow." },
  "ねむい|眠い": {
    explain: "This is the native Japanese reading. On the left of 「眠|ねむ」 is the eye, 「目|め」. Eyes are what close when you get sleepy. A way to remember it: picture heavy eyes slowly drooping shut. Another hook for the sound: it is like the long sleepy moan you make when you have to get up early. This is an i-adjective, so it describes how you feel: 「眠いです|ねむいです」, I'm sleepy. The verb for going to bed is 「寝る|ねる」. It sounds similar but is a different kanji, so don't mix them up. Being sleepy is the feeling, and 「寝る|ねる」 is the action. In Japan you often see people napping on trains, even standing up. Long commutes and late nights make this word very common. A related useful word is 「朝寝坊する|あさねぼうする」, to oversleep, what happens when you stay sleepy too long. To recap: the eye on the left, heavy and ready to close.",
    ja: "{今朝|けさ}はとても[眠い|ねむい]です。",
    en: "I'm very sleepy this morning." },
  "かんたん|簡単": {
    explain: "Both kanji use their Chinese-origin readings. The first, 「簡|かん」, has bamboo on top. Long ago people wrote on thin strips of bamboo, and this kanji came to mean brief and simple, like a short note. The second, 「単|たん」, means single or one alone. Put them together and you get brief and single, nothing complicated, so simple or easy. This is a na-adjective. Before a noun, add 「な」: 「簡単な料理|かんたんなりょうり」, simple cooking. The opposite is 「難しい|むずかしい」, difficult. You also know 「やさしい」, easy. 「やさしい」 often means gentle and easy, and can also mean kind. 「簡単|かんたん」 is more about something being simple and quick to do. A very common phrase is to say a dish is easy to make, or a test was easy, as in the example. To recap: bamboo note plus single, short and simple.",
    ja: "このテストは[簡単|かんたん]でした。",
    en: "This test was easy." },
  "かかる|": {
    explain: "This verb is usually written in kana. It tells you how much time or money something takes. The amount comes right before it, with no particle: 「一時間かかります|いちじかんかかります」, it takes an hour. With money, it is the same: 「千円かかります|せんえんかかります」, it costs a thousand yen. To ask, combine it with 「どのぐらい」, how long, from this lesson: 「どのぐらいかかりますか」. Use 「から」 and 「まで」 to give the start and end: from home to school, it takes ten minutes. A common mistake for English speakers is to try to say it with 「とる」 or 「する」, because English says take. In Japanese, time and money hang on this verb instead. Notice that the thing taking the time is not the person. The trip or the task takes the time. A way to remember it: it sounds a little like car, car. Picture a line of cars, car after car, stuck in traffic, and the trip taking ages. To recap: put the amount first, then this verb.",
    ja: "{駅|えき}まで{十分|じゅっぷん}[かかります|かかります|かかる]。",
    en: "It takes ten minutes to the station." },
  "とまる|泊まる": {
    explain: "This is the native Japanese reading of the kanji. On the left of 「泊|と」 is the water shape. On the right is 「白|しろ」, white. The kanji first meant a boat anchoring in a harbor for the night. Today it means staying somewhere overnight, at a hotel, an inn, or a friend's place. The place takes 「に」: 「ホテルに泊まる|ホテルにとまる」, to stay at a hotel. Be careful. There is another verb with the same sound, 「止まる|とまる」, to stop, like a car stopping. A way to keep them apart: a boat stops in the harbor for the night, so the watery one is the overnight stop. Also note that this verb is about spending the night. For staying a long time somewhere, Japanese uses other words. In Japan, a classic trip means staying at a 「旅館|りょかん」, a traditional inn, with tatami floors, a hot bath and dinner served in your room. Hotels count nights with a special counter, so a one night stay is 「一泊|いっぱく」. To recap: the water shape, a boat anchoring for the night.",
    ja: "ホテルに[泊まりました|とまりました|とまる]。",
    en: "I stayed at a hotel." },
  "なる|": {
    explain: "This verb is usually written in kana. It is one of the most useful verbs in Japanese. It shows a change, something turning into something else. After a noun, use 「に」: 「医者になる|いしゃになる」, to become a doctor. After a na-adjective, also use 「に」: 「元気になる|げんきになる」, to get well. After an i-adjective, change the final 「い」 into 「く」: 「寒くなる|さむくなる」, to get cold. You already know 「遅くなる|おそくなる」, to be late, which uses exactly this pattern. A very common mistake for English speakers is to say the i-adjective with 「に」. Remember, the 「い」 becomes 「く」 instead. English often says get or become, like get cold or get better. Japanese uses this verb for all of them. It is also used for things that happen by themselves, like seasons changing: 「春になる|はるになる」, spring comes. A way to remember it: picture a caterpillar turning into a butterfly. Change happens, and this verb is the change. To recap: noun or na-adjective plus 「に」, or the 「く」 form, then this verb.",
    ja: "{兄|あに}は{医者|いしゃ}に[なりました|なりました|なる]。",
    en: "My older brother became a doctor." },
  "きめる|決める": {
    explain: "This is the native Japanese reading. On the left of 「決|き」 is the water shape. The kanji originally had to do with water breaking through a bank, and from that came the idea of something being settled for good. A way to remember it: picture a river bursting through, no going back. Once you decide, it's done. It is a transitive verb, so the thing you decide takes 「を」: 「日を決める|ひをきめる」, to decide on the date. To decide on one choice from several, use 「に」: 「これに決めます|これにきめます」, I'll go with this one. You also know that 「する」 can mean to decide on an item, as in ordering this one, which is the same idea in a more casual way. There is a partner verb, 「決まる|きまる」, which means something gets decided, without saying who did it. Japanese often prefers that one, which sounds softer. To recap: the water shape, breaking through to a final decision.",
    ja: "{旅行|りょこう}の{日|ひ}を[決めました|きめました|きめる]。",
    en: "We decided the date of the trip." },
  "ごろごろする|": {
    explain: "This is a sound and feeling word, a mimetic word, plus 「する」. Japanese has hundreds of these doubled words that paint a picture with sound. The core image of this one is something heavy rolling around. So when people use it about themselves, it means lazing around at home, rolling over on the sofa or floor, doing nothing in particular. It is a casual, friendly word. You might say it about your day off: 「週末はうちでごろごろします|しゅうまつはうちでごろごろします」. The same sound has other uses that share the rolling, rumbling feel. It is the sound of thunder rumbling in the distance, and also the sound of a cat purring. A way to remember it: picture a big cat rolling around on the floor and purring, completely relaxed. That's you on a lazy Sunday. A common mistake is to use this word for being busy at home. It means the opposite: no plans, no effort. To recap: rolling around like a heavy, happy cat, so lazing at home.",
    ja: "{日曜日|にちようび}はうちで[ごろごろします|ごろごろします|ごろごろする]。",
    en: "On Sundays I laze around at home." },
  "りょこうする|旅行する": {
    explain: "Both kanji use their Chinese-origin readings. The first, 「旅|りょ」, means journey or trip. You will see it again in 「旅館|りょかん」, a traditional Japanese inn, a building for travelers. The second, 「行|こう」, means to go. You know it from 「行く|いく」, to go, and it is also in 「飛行機|ひこうき」, airplane. So the word is to go on a journey. Without 「する」, 「旅行|りょこう」 is the noun, a trip. With 「する」, it becomes the verb, to travel. The place you travel around takes 「を」, as in the example, a little like traveling across or through Japan. If you just say where you are going, use 「に」 with 「行く|いく」 instead. Japanese travelers love to bring back small gifts from trips for friends and coworkers, so a trip usually means shopping too. To recap: journey plus go.",
    ja: "{夏|なつ}に{日本|にほん}を[旅行します|りょこうします|りょこうする]。",
    en: "I'll travel around Japan in the summer." },
  "れんしゅうする|練習する": {
    explain: "Both kanji use their Chinese-origin readings. The first, 「練|れん」, has the thread shape on its left. It originally meant working raw silk until it became soft and fine, and from there it came to mean training or polishing a skill. The second, 「習|しゅう」, means to learn. It has feathers on top. A common hook is a young bird flapping its wings again and again until it learns to fly. You know this kanji from 「習う|ならう」, to learn from someone, and 「習慣|しゅうかん」, a custom or habit, something learned by repetition. So the word is polishing what you learn, which is what practice is. Use 「を」 for what you practice: 「ピアノを練習する|ピアノをれんしゅうする」. A common mix up: 「勉強する|べんきょうする」 means to study, mostly from books, while this word is for skills you repeat, like music, sports or speaking. To recap: polishing the silk plus a bird learning to fly.",
    ja: "{毎日|まいにち}ピアノを[練習します|れんしゅうします|れんしゅうする]。",
    en: "I practice piano every day." },
  "いちばん|一番": {
    explain: "Both kanji use their Chinese-origin readings. The first, 「一|いち」, is one, a single line. The second, 「番|ばん」, means number or turn in order. You know it from 「ばんごう」, number. So the word is number one, first in line, the best. It is the main way to say most or best in Japanese. Just put it before an adjective: 「一番好き|いちばんすき」, like the most, or 「一番高い|いちばんたかい」, the most expensive. For a group, use 「の中で|のなかで」, among: 「季節の中で夏が一番好きです|きせつのなかでなつがいちばんすきです」. English speakers sometimes look for a special ending for words like biggest or best. Japanese doesn't change the adjective at all. It just adds this word in front. It can also mean number one in a line, like the first person in a queue. To recap: one plus number, the number one, the most.",
    ja: "わたしは{夏|なつ}が[一番|いちばん]{好き|すき}です。",
    en: "I like summer the best." },
  "どっち／どちら|": {
    explain: "Both of these ask which one when there are two choices. They belong to the big set of words that start with 「こ」, 「そ」, 「あ」 and 「ど」. The 「ど」 words ask questions. 「どっち」 matches 「こっち」, this way, and 「どちら」 matches 「こちら」, this person or this way, politely. 「どっち」 is the casual form. You use it with friends. 「どちら」 is the polite form. You use it in shops, with strangers, and in polite speech. The typical pattern is A 「と」 B 「と」, then this word 「が」, as in the example: coffee and tea, which is better? Here is a common mistake. For three or more choices, use 「どれ」, which one, instead. So choose these words for exactly two options. 「どちら」 can also politely mean where, as in asking where someone is from. A way to remember it: two options, two words, one casual, one polite. To recap: which of the two, with a casual and a polite version.",
    ja: "コーヒーとこうちゃと[どっち]がいいですか。",
    en: "Which is better, coffee or tea?" },
  "はやく|早く／速く": {
    explain: "Two kanji, one sound, and both use the native reading. The first, 「早|はや」, has the sun, 「日|ひ」, on top. Think of the sun just rising. This one means early, as in getting up early. The second, 「速|はや」, has the road shape along the bottom. Think of moving fast along a road. This one means fast, as in speed. Both come from the adjectives you know, 「早い|はやい」, early, and 「速い|はやい」, fast. Change the final 「い」 to 「く」 and you get the adverb, the way you do something: early or quickly. Like in English, early and fast are related ideas, which is why they share one sound. In speech you can't hear the difference, so you only need to pick when writing. A very common phrase is 「早く|はやく」 on its own, said to someone who is slow: hurry up. The opposite is 「遅く|おそく」, late or slowly. To recap: sun for early, road for fast.",
    ja: "{明日|あした}は[早く|はやく]{起きます|おきます}。",
    en: "I'll get up early tomorrow." },
  "あるいて|歩いて": {
    explain: "This is the te-form of 「歩く|あるく」, to walk, read with its native reading. The kanji 「歩|ある」 comes from an old picture of two feet, one stepping in front of the other. You can still see the shape for stopping, a foot, on top. Used before a verb of motion, the te-form tells you how you go: 「歩いて行く|あるいていく」, to go by walking, on foot. This is the te-form linking two actions, walking and going, so it means going while walking. A common mistake is to say on foot with 「で」, like you do for transportation. With a bus you say 「バスで」, but for walking you use this te-form instead. You can also use it with 「来る|くる」, to come on foot, and 「帰る|かえる」, to walk home. Japanese cities are very walkable, and many people walk to the station every day. To recap: two feet stepping, in the te-form for going on foot.",
    ja: "[歩いて|あるいて]{学校|がっこう}に{行きます|いきます}。",
    en: "I walk to school." },
  "〜で|": {
    explain: "This is a particle, so it comes right after a noun. It marks the means you use to do something. After a vehicle, it means by: 「バスで」, by bus, 「電車で|でんしゃで」, by train. After a tool, it means with: 「はしで」, with chopsticks, or 「日本語で|にほんごで」, in Japanese. You already know this same particle for the place where something happens, like studying at the library. The connecting idea is setting: the place you act in, or the tool you act with. A common mistake is to use it for walking. For on foot, Japanese uses 「歩いて|あるいて」 instead. To ask how, use 「何で|なにで」, by what means, or 「どうやって」, from this lesson. Watch out: 「何で|なんで」, with a different reading, usually means why. A way to remember it: think of English with or by, the tool you hold in your hand. To recap: after a vehicle or tool, it means by or with.",
    ja: "バス[で]{行きます|いきます}。",
    en: "I'll go by bus." },
  "どうやって|": {
    explain: "This is built from two pieces you know. The first, 「どう」, means how. The second, 「やって」, is the te-form of 「やる」, to do. So together it means doing it how, by what means, in what way. Use it to ask about method or route: 「どうやって行きますか|どうやっていきますか」, how do you get there? The answer usually uses 「で」 for a vehicle, like 「バスで」, or 「歩いて|あるいて」 for on foot. You can also use it for doing something, like how do you make this dish. A common mix up: 「どう」 on its own asks how something is, like how was the movie. This word asks for the way you do something. It is fine in polite speech when followed by a polite verb. To recap: how plus doing, the question about method.",
    ja: "[どうやって]{来ました|きました}か。",
    en: "How did you get here?" },
  "どのぐらい|": {
    explain: "This word is built from two pieces you know. The first, 「どの」, means which, before a noun. The second, 「ぐらい」, means about or roughly, as in 「一時間ぐらい|いちじかんぐらい」, about an hour. So together it is about which amount, which is a natural way to ask how much or how long. You can also say 「どのくらい」, with a 「く」. Both are correct and mean the same thing. It pairs perfectly with 「かかる」, from this lesson: 「どのぐらいかかりますか」, how long does it take, or how much does it cost. You can use it for time, money, distance and amounts. A typical answer includes 「ぐらい」 again, like about ten minutes. A related word you will see later is 「このぐらい」, about this much. A way to remember it: you ask with 「ぐらい」, and you answer with 「ぐらい」. To recap: which plus about, how much or how long.",
    ja: "{駅|えき}まで[どのぐらい]かかりますか。",
    en: "How long does it take to the station?" },
  "〜しゅうかん|〜週間": {
    explain: "Both kanji use their Chinese-origin readings. The first, 「週|しゅう」, means week. It has the road shape on its left, like the week going round and round. You know it from 「週末|しゅうまつ」, weekend, 「毎週|まいしゅう」, every week, and 「来週|らいしゅう」, next week. The second, 「間|かん」, means span or interval. It is the same kanji as in 「時間|じかん」, time or hours. So this counter means a span of weeks, a length of time in weeks. Put a number in front: 「一週間|いっしゅうかん」, one week, 「二週間|にしゅうかん」, two weeks. Notice the small 「っ」 with one, and with eight and ten, which squeeze into the next sound. Here is the trap. Without 「間|かん」, like 「来週|らいしゅう」, it is a point in time, next week. With 「間|かん」, it is a length of time, for weeks. That matches 「時間|じかん」 for hours. To recap: week plus span, how many weeks long.",
    ja: "[二週間|にしゅうかん|〜しゅうかん]{日本|にほん}にいました。",
    en: "I was in Japan for two weeks." },
  "〜かげつ|〜か月": {
    explain: "This counter is for lengths of time in months. The kanji 「月|げつ」 means month or moon, read here with a Chinese-origin reading. The small 「か」 in the middle is a counting marker. You may also see it written with a tiny katakana 「ヶ」, and it is still read 「か」. So 「三か月|さんかげつ」 is three months long. Some numbers squeeze sounds together: 「一か月|いっかげつ」, one month, and 「六か月|ろっかげつ」, six months. Here is the big trap. Without 「か」, you get the names of the months: 「三月|さんがつ」 is March. So 「さんがつ」 is a point on the calendar, but 「さんかげつ」 is a length of time. You also know 「今月|こんげつ」, this month, and 「来月|らいげつ」, next month, with the same reading 「げつ」. A way to remember it: the little 「か」 is like a tape measure, it turns a month into a length. To recap: number plus 「か」 plus month, for how many months long.",
    ja: "[三か月|さんかげつ|〜かげつ]{日本語|にほんご}をべんきょうしました。",
    en: "I studied Japanese for three months." },
  "〜ねん|〜年": {
    explain: "The kanji 「年|ねん」 means year, read here with its Chinese-origin reading. After a number it counts years: 「一年|いちねん」, one year, 「三年|さんねん」, three years. With the native reading it is 「とし」, as in 「年上|としうえ」, someone older. You know the Chinese-origin reading from 「来年|らいねん」, next year. Here is something to watch. The same number plus this kanji can be a length of time, for three years, or a calendar year, the year two thousand. To make the length clear, add 「間|かん」, span, just like with weeks and hours: 「三年間|さんねんかん」, for three years. Unlike weeks and months, years don't need the extra piece. Both forms are used for lengths of time. Also, a student's year in school uses this same counter plus 「生|せい」, so a third year student is 「三年生|さんねんせい」. Japan also counts years by the emperor's era name, which you will see on forms. To recap: number plus year, with 「間|かん」 added when you want to stress the length.",
    ja: "[二年|にねん|〜ねん]{日本|にほん}にすんでいました。",
    en: "I lived in Japan for two years." },
  "このごろ|": {
    explain: "This word is built from two pieces you know. The first, 「この」, means this, before a noun. The second, 「ごろ」, means around or about a point in time. You know it from 「三時ごろ|さんじごろ」, around three o'clock. So together it is around this time, which means these days or lately. Use it at the start of a sentence to talk about how things are recently: 「このごろいそがしいです」, I'm busy these days. It describes an ongoing situation, so it often goes with the 「ています」 form or with adjectives. A close cousin is 「最近|さいきん」, recently. 「最近|さいきん」 can be used for a single event that just happened, but this word is for a state that continues over a period. So don't use it for something that happened once yesterday. A way to remember it: 「ごろ」 is around, so this word means the time around now. To recap: this plus around, how things are these days.",
    ja: "[このごろ]いそがしいです。",
    en: "I'm busy these days." },
  "〜ご|〜後": {
    explain: "The kanji 「後|ご」 means after or behind. Here it uses its Chinese-origin reading. After a length of time, it means that much time later: 「三日後|みっかご」, three days later, 「一時間後|いちじかんご」, one hour later. You can also use it to mean in that much time from now, as in the example: please come in one hour. It is the same kanji you know from 「後で|あとで」, later on, and 「後|あと」, after an event, with the native reading. It also hides in the word for P.M., 「ごご」, written 「午後|ごご」, which is literally after noon. The kanji has the step shape on its left, a shape made of short slanted strokes that is used in kanji about walking and going. A way to remember it: someone walking behind, coming after. A common mistake: use this one after a length of time. After an event, like after class, use 「の後|のあと」 instead. To recap: length of time plus this, that much later.",
    ja: "[一時間後|いちじかんご|〜ご]に{来て|きて}ください。",
    en: "Please come back in an hour." },
  "〜か〜|": {
    explain: "This is the particle 「か」 used between two nouns to mean or. The pattern is A 「か」 B: 「コーヒーかこうちゃ」, coffee or tea. You already know 「か」 at the end of a sentence, where it makes a question. Here it is doing a related job. A question is choosing between yes or no, and this one offers a choice between two things. You can use it with more than two options, too, like A or B or C, putting 「か」 between each one. After the second item, add the particle the sentence needs, like 「を」 in the example. Here is a contrast. 「と」 between nouns means and, both things. 「か」 means or, one or the other. So 「コーヒーとこうちゃ」 is coffee and tea, but 「コーヒーかこうちゃ」 is coffee or tea. A way to remember it: the question sound, offering you a choice. To recap: put 「か」 between nouns for or.",
    ja: "コーヒー[か]こうちゃを{飲みます|のみます}。",
    en: "I drink coffee or tea." },
  "おんせん|温泉": {
    explain: "Two kanji, both read with their Chinese-origin readings. The first is 「温|おん」, warm. Look at its left side: three little strokes, the water radical, so warm water is built right into it. You already know this kanji from 「気温|きおん」, the air temperature in a weather report. The second kanji is 「泉|せん」, a spring, a place where water comes up out of the ground. Its bottom part is 「水|みず」, water. A way to remember the top: it looks like the kanji for white, so picture clear white water bubbling up. Put them together and you get warm spring water, a hot spring. Japan sits on a chain of volcanoes, so hot springs are everywhere, and a trip to one is a classic weekend getaway. People often stay at a traditional inn, a 「旅館|りょかん」, eat a big dinner, and soak in the bath several times. You wash first, then get in, and you never put your towel in the water. So, warm plus spring: a hot spring, and a very Japanese way to relax.",
    ja: "やすみに[温泉|おんせん]にいきたいです。",
    en: "I want to go to a hot spring on my break." },
  "つり|釣り": {
    explain: "This is the noun form of the verb 「釣る|つる」, to catch a fish with a hook and line. Many Japanese verbs turn into nouns this way: take the stem, and the 「り」 is left at the end, just like 「休む|やすむ」 gives 「休み|やすみ」, a break. The kanji is worth a close look. On the left is the metal radical, the same piece that is the whole kanji in 「お金|おかね」, money. Metal makes sense, because the key tool in fishing is a little metal hook. So the kanji is basically metal for catching. You use it with 「する」 or with 「行く|いく」: 「釣りをする|つりをする」, to fish, and 「釣りに行く|つりにいく」, to go fishing. That second pattern, a noun plus 「に行く|にいく」, is the same one you use for 「買い物に行く|かいものにいく」. Lakes, rivers and the sea all count, so it pairs nicely with 「川|かわ」 and 「湖|みずうみ」 from this same lesson. In short: a metal hook, a verb turned noun, and a quiet day by the water.",
    ja: "{父|ちち}と[釣り|つり]をしました。",
    en: "I went fishing with my father." },
  "キャンプ|": {
    explain: "A loanword from the English word camp. Listen to how it got squeezed into Japanese sounds. The ca at the start becomes 「キャ」, a small ya sound tucked in, because that is the closest Japanese match for the flat English a in camp. The m before the p becomes 「ン」, since Japanese has just one sound for a nasal at the end of a syllable. And the final p gets a vowel added, 「プ」, because Japanese words cannot end on a bare consonant, apart from 「ン」. You will see this extra vowel on lots of borrowed words, like 「テープ」 and 「ゲーム」. To go camping, you say 「キャンプに行く|キャンプにいく」, or to do it, 「キャンプをする」. Camping is popular in Japan, especially in the mountains and by lakes in summer, and there is a whole gear culture around it. A way to remember the spelling: the little 「ャ」 is the only tricky part, everything else is just English with vowels. So: camp, plus Japanese vowels, gives you a weekend in a tent.",
    ja: "{山|やま}で[キャンプ]をしました。",
    en: "I went camping in the mountains." },
  "やま|山": {
    explain: "This is one of the kanji that really is a picture. Three upward strokes, the middle one tallest, sitting on a base: a mountain range with one high peak. Here it uses its native Japanese reading, 「やま」. In names of mountains, though, it switches to its Chinese-origin reading, 「さん」, so Mount Fuji is 「富士山|ふじさん」. Sometimes that softens to 「ざん」, as in 「登山|とざん」, mountain climbing. It is also extremely common in family names, like 「山田|やまだ」, literally mountain rice field, and 「山下|やました」, below the mountain. Because so much of Japan is mountains, around three quarters of the land, this kanji is everywhere on maps and signs. The verb that goes with it is 「登る|のぼる」, to climb, from this lesson: 「山に登る|やまにのぼる」. You can also go camping there, or visit a hot spring at its foot. A way to remember the readings: the native 「やま」 is the mountain itself, the Chinese 「さん」 is the mountain's title. A picture of peaks, read 「やま」 on its own and 「さん」 in names.",
    ja: "{友だち|ともだち}と[山|やま]にのぼりました。",
    en: "I climbed a mountain with a friend." },
  "みずうみ|湖": {
    explain: "Listen to the native word first, because it explains itself. It sounds just like 「水|みず」, water, joined to 「海|うみ」, sea. That is a fair way to think of it: a sea of fresh water, sitting inland. Both of those words are ones you already know, from lessons three and five. The kanji has the water radical, three short strokes on the left, the same as in 「海|うみ」 and in 「温泉|おんせん」. The right side mainly gives the sound in Chinese-style compounds, where this kanji is read 「こ」. The most famous example is 「琵琶湖|びわこ」, the biggest lake in Japan, near Kyoto, named for its lute-like shape. So when you see 「こ」 at the end of a place name with this kanji, think lake. On its own, though, you say 「みずうみ」. You can swim in one, fish in one, or camp beside one, all words from this lesson. A way to remember it: water plus sea, a little sea you can see across. So, read it as water sea, and you have a lake.",
    ja: "[湖|みずうみ]でおよぎました。",
    en: "I swam in the lake." },
  "じんじゃ|神社": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「神|じん」, means god or spirit, the kind of spirits Shinto honors. On its own it is read 「かみ」. The second, 「社|じゃ」, means shrine. On its own that would be 「しゃ」, but it softens to 「じゃ」 here. Now look at both kanji: they share the same left side, a narrow radical that is linked to altars and religious things. So both halves are about the sacred, a spirit and its home. That second kanji may look familiar, because it is also in 「会社|かいしゃ」, company, and 「社長|しゃちょう」 from this lesson. Its older sense is a gathering place, which grew into both a shrine and a business. Shrines are Shinto. You can spot one by the big gate at the entrance, often painted red. Buddhist temples are 「お寺|おてら」, which you met in lesson four. At a shrine, people bow twice, clap twice, make a wish, and bow once more. At New Year, nearly everyone visits one. So: spirit plus sacred place, a home for the gods.",
    ja: "{京都|きょうと}の[神社|じんじゃ]にいきました。",
    en: "I went to a shrine in Kyoto." },
  "しゃしんをとる|写真を撮る": {
    explain: "You already know 「写真|しゃしん」, a photo, from lesson four. Its first kanji, 「写|しゃ」, means to copy, and the second, 「真|しん」, means true or real. So a photo is a true copy of what is in front of you. Nice and logical. The verb is where it gets interesting. Japanese has several verbs pronounced 「とる」, and they are written with different kanji depending on what kind of taking you mean. For photos and videos it is 「撮る|とる」. Its left side is the hand radical, like a hand holding a camera. For taking a class, or picking something up, it is 「取る|とる」, which is also in this lesson. They sound the same, so you only notice the difference when reading or writing. The pattern is just like English: 「写真を撮る|しゃしんをとる」, to take a picture. A very useful polite question when traveling is 「写真を撮ってもいいですか|しゃしんをとってもいいですか」, may I take a picture? That is the te-form plus 「もいい」 for permission, from lesson six. So: a true copy, taken with the camera kind of 「とる」.",
    ja: "ここで[写真を撮っても|しゃしんをとっても|しゃしんをとる]いいですか。",
    en: "May I take a picture here?" },
  "がいこく|外国": {
    explain: "Two kanji with Chinese-origin readings. The first, 「外|がい」, means outside. On its own, with its native reading, it is 「そと」, the outside of a building. The second, 「国|こく」, means country. On its own it is 「くに」, as in 「国に帰る|くににかえる」, to go back to your home country, from lesson six. In its modern form, the kanji is a box, a border, with a jewel inside: a way to remember it is that a country is the precious land inside the border. Put them together and you get a country outside, a foreign country. This little word is the root of a whole family. Add 「人|じん」, person, and you get 「外国人|がいこくじん」, a foreigner. Add 「語|ご」, language, and you get 「外国語|がいこくご」, a foreign language, the same 「語|ご」 as in 「日本語|にほんご」. Learning one gives you the others for free. A common question is 「外国に行ったことがありますか|がいこくにいったことがありますか」, have you ever been abroad? So: outside plus country, and you are abroad.",
    ja: "[外国|がいこく]にいったことがありますか。",
    en: "Have you ever been to a foreign country?" },
  "かわ|川": {
    explain: "Another kanji that really is a picture. Three vertical lines, the left one curving, like water flowing between two banks, seen from above. Here it uses its native Japanese reading, 「かわ」. When it comes after another word in a place name, it often softens to 「がわ」, like 「品川|しながわ」, a big station in Tokyo. Its Chinese-origin reading is 「せん」, but you will mostly see that in longer compound words, so for now just keep 「かわ」. Compare it with the water radical, the three little drops on the left of 「湖|みずうみ」 and 「温泉|おんせん」. Both are about water, but here the three lines stand tall and run downstream. A typical sentence from this lesson is 「川で釣りをしました|かわでつりをしました」, I went fishing at the river. Notice the particle 「で」, because the river is the place where the action happens. Rivers in Japan are short and fast, rushing from the mountains to the sea, so a riverside walk or barbecue is a classic summer outing. A way to remember it: three lines, flowing water. So: a picture of a stream, read 「かわ」.",
    ja: "[川|かわ]でつりをしました。",
    en: "I went fishing in the river." },
  "ドライブ|": {
    explain: "A loanword from the English word drive. Listen to how the sounds changed. The d and r run together into 「ドラ」, with an extra vowel after the d, because Japanese does not put two consonants side by side. The English v becomes a b sound, 「ブ」, because traditional Japanese has no v. And the final vowel is added so the word does not end on a consonant. The meaning also shifted. In Japanese, this is a drive for fun, a road trip or a pleasure ride through the countryside or along the coast. You say 「ドライブに行く|ドライブにいく」, to go for a drive. It is a classic date activity. If you just mean the act of operating a car, to drive to work, use 「運転する|うんてんする」, which you met in lesson eight. A common mistake is to say you do a 「ドライブ」 to the office, which sounds like you are going sightseeing on the way to work. A way to remember it: the 「ドライブ」 is the trip, 「運転|うんてん」 is the steering. So: a drive, but always the fun kind.",
    ja: "{週末|しゅうまつ}に[ドライブ]にいきました。",
    en: "I went for a drive on the weekend." },
  "びじゅつかん|美術館": {
    explain: "Three kanji, all with Chinese-origin readings. The first, 「美|び」, means beauty. A way to remember its shape: the top looks like the kanji for sheep, and the bottom is 「大|だい」, big, so picture a big, fine sheep, something admired. You have seen this kanji in 「美容院|びよういん」, a beauty salon, from lesson ten. The second, 「術|じゅつ」, means art, technique, a skill. Together, 「美術|びじゅつ」 means fine art, the art of beauty. The third, 「館|かん」, means a large public building. It is the same one as in 「図書館|としょかん」, the library, 「映画館|えいがかん」, the movie theater, and 「旅館|りょかん」, a Japanese inn. Whenever you see 「かん」 with this kanji at the end, think of a big building with a purpose. So the whole word is a building for fine art. A museum of history or science uses a different word, so this one is really for paintings and sculpture. A typical sentence is 「美術館で絵を見ました|びじゅつかんでえをみました」. So: beauty, art, building.",
    ja: "[美術館|びじゅつかん]で{絵|え}を{見ました|みました}。",
    en: "I looked at paintings at the art museum." },
  "しゃちょう|社長": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「社|しゃ」, means company here. It is the second half of 「会社|かいしゃ」, a company, and also part of 「会社員|かいしゃいん」, a company employee, from lesson one. The second, 「長|ちょう」, means the head or the chief. On its own, with its native reading, it is 「長い|ながい」, long, from lesson seven. A way to link them: the long one, the elder, becomes the leader. So the word is the head of the company, the president. In Japan, this word is used almost like a title. Staff will call the boss 「社長|しゃちょう」 directly, instead of using a name, the same way students call their teacher 「先生|せんせい」. The same 「長|ちょう」 shows up in lots of leader words, like the head of a department or a school principal, so it is a handy kanji to know. Picture the company's tallest figure standing at the front. So: company plus chief, the person at the very top.",
    ja: "{父|ちち}は[社長|しゃちょう]です。",
    en: "My father is a company president." },
  "かしゅ|歌手": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「歌|か」, means song. On its own, with its native reading, it is 「歌|うた」, a song, and the verb is 「歌う|うたう」, to sing, both from lesson seven. You also met this 「か」 reading in 「歌舞伎|かぶき」, where the three kanji are song, dance and skill. The second kanji, 「手|しゅ」, is hand. On its own it is 「て」, as in 「手紙|てがみ」, a letter. But in many job words, this kanji means a person who is skilled at something, someone who does it with their hands, so to speak. You will see it again in 「選手|せんしゅ」, an athlete, later in this lesson. So the word is a song person, a singer, usually meaning a professional one. To say you want to be one: 「歌手になりたいです|かしゅになりたいです」, with 「になる」 for becoming. A way to remember it: the hand holding the microphone. So: song plus skilled person, a singer.",
    ja: "{将来|しょうらい}、[歌手|かしゅ]になりたいです。",
    en: "I want to become a singer in the future." },
  "ルームメイト|": {
    explain: "A loanword straight from the English word roommate. Watch how the sounds got reshaped. The English r and l both become the Japanese r sound, so room is 「ルーム」. The long oo becomes a long vowel, shown by the dash. Then mate becomes 「メイト」, with the English long a written as 「メイ」 and an extra vowel added after the t, because Japanese words do not end on a consonant. So one short English word becomes six beats of Japanese. The meaning is the same as in English, someone you share a room or an apartment with. It is common for students living in dorms or for people sharing a place abroad. Japanese often borrows English words for things linked with student life and living arrangements, like 「アパート」 and 「ホームステイ」. A way to remember it: say roommate slowly, giving every consonant its own vowel, and you are there. A typical sentence is 「ルームメイトはアメリカ人です|ルームメイトはアメリカじんです」. So: room plus mate, stretched into Japanese rhythm.",
    ja: "[ルームメイト]はアメリカ{人|じん}です。",
    en: "My roommate is American." },
  "ホストファミリー|": {
    explain: "A loanword from the English phrase host family, the family a study abroad student lives with. Look at how each part was squeezed into Japanese. Host becomes 「ホスト」. The s and the t each get their own beat, with a vowel added, because Japanese does not stack consonants. Family becomes 「ファミリー」. Japanese did not have an f sound like English, so it uses 「フ」 with a small 「ァ」 to make the fa sound. The l becomes an r sound, and the y sound at the end becomes a long vowel. This word goes hand in hand with 「ホームステイ」, a homestay, from lesson eight, and with 「留学する|りゅうがくする」, to study abroad, from this lesson. Many Genki characters stay with one, so you hear it in the dialogues. When you talk about your host mother, you can say 「ホストファミリーのおかあさん」. A way to remember it: host and family, said slowly with a vowel after every consonant. So: the family that hosts you while you study.",
    ja: "わたしの[ホストファミリー]はやさしいです。",
    en: "My host family is kind." },
  "しょうらい|将来": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「将|しょう」, has a few meanings. One is a general, the leader of an army. Another, from old Chinese grammar, is about to or going to. That second meaning is the one at work here. The second kanji, 「来|らい」, means to come. You know it from 「来年|らいねん」, next year, 「来週|らいしゅう」, next week, and the verb 「来る|くる」. Put them together and you get what is about to come, the future. Japanese has more than one word for future, and this one is usually about a person's own life ahead, careers, plans, hopes. That is why it is the word for questions like what do you want to be in the future: 「将来、何になりたいですか|しょうらい、なにになりたいですか」. It often sits at the start of a sentence, with a comma after it, just like the example. A way to remember it: think of the general looking ahead to what is coming. So: about to plus come, your future.",
    ja: "[将来|しょうらい]、{先生|せんせい}になりたいです。",
    en: "In the future, I want to be a teacher." },
  "ゆめ|夢": {
    explain: "A native Japanese word, and just like in English, it covers two things: the dreams you have when you sleep, and the dreams you have for your life. The verb is the surprise. In English you have a dream, but in Japanese you see one: 「夢を見る|ゆめをみる」. That makes sense, because dreams are mostly pictures. For a life dream, people say 「夢があります|ゆめがあります」, I have a dream, or ask 「夢は何ですか|ゆめはなんですか」, what is your dream? It pairs nicely with 「将来|しょうらい」, the future, from this lesson. Now the kanji. At the very bottom is 「夕|ゆう」, evening, a real part of this character. A way to remember the rest: picture an eye above it that stays open into the night, still seeing pictures while you sleep. That ties together the kanji and the verb 「見る|みる」. A common mistake is to say 「夢をする|ゆめをする」. So: something you see at night, or see in your future.",
    ja: "{昨日|きのう}、こわい[夢|ゆめ]を{見ました|みました}。",
    en: "I had a scary dream yesterday." },
  "おまつり|お祭り": {
    explain: "The core word is 「祭り|まつり」, and the 「お」 in front is just polite and friendly, like in 「お茶|おちゃ」. It comes from the verb 「祭る|まつる」, to worship, to honor the gods. That is the heart of it: traditionally, a festival is held to honor the spirit of a local shrine. Look at the kanji. The bottom is a radical connected with altars and offerings, the same one you see squeezed onto the left side of 「神社|じんじゃ」. The top is traditionally explained as a piece of meat and a hand, making an offering on the altar. So the word itself carries the idea of celebrating the gods. Today festivals are big community parties. In summer you will see people in light cotton robes, food stalls with grilled snacks, games, dancing, and often fireworks. Some have portable shrines carried through the streets. Kyoto's 「祇園祭|ぎおんまつり」 is one of the most famous. Inside a festival name, the 「お」 drops. So: honoring the gods, with food and fireworks.",
    ja: "{夏|なつ}に[お祭り|おまつり]があります。",
    en: "There is a festival in the summer." },
  "おしょうがつ|お正月": {
    explain: "Two kanji plus a polite 「お」. The first kanji, 「正|しょう」, usually means correct or proper. You will often see it read 「せい」, but here it takes the reading 「しょう」. In this word it carries the sense of the proper beginning, so 「正月|しょうがつ」 originally meant the first month of the year. The second kanji, 「月|がつ」, means month, as in 「一月|いちがつ」, January, and it is also in 「今月|こんげつ」 and 「来月|らいげつ」. Today the word means the New Year holidays, roughly the first few days of January, and it is the biggest holiday of the year. Families gather, eat special boxed New Year food, children get envelopes of money from relatives, and most people visit a shrine, a 「神社|じんじゃ」, to pray for a good year. Businesses close and trains fill with people going home. New Year in Japan is a quiet family time, more like an American Christmas, while Christmas is more for couples. So: the proper first month, and the most important holiday in Japan.",
    ja: "[お正月|おしょうがつ]に{神社|じんじゃ}にいきます。",
    en: "I go to a shrine at New Year's." },
  "おかし|お菓子": {
    explain: "The core word is 「菓子|かし」, and the 「お」 in front makes it polite and soft, which is how almost everyone says it. The first kanji, 「菓|か」, has the grass radical on top, the plant marker, and underneath it is 「果|か」, fruit. That is the same kanji as in 「果物|くだもの」, fruit, from lesson five. The history fits: long ago, the sweet things people snacked on were fruit and nuts, so the word for snacks was built on fruit. The second kanji is 「子|し」, child, used here as a little suffix for small things. You have seen that same suffix in 「帽子|ぼうし」, a hat. Today the word covers all kinds of snacks and sweets: candy, chocolate, cookies, chips, rice crackers. Japanese convenience stores have a whole aisle of them, with new flavors every season. Traditional Japanese sweets, often made with red bean paste, have their own name, but they are still part of this family. A way to remember it: fruit from a plant, made small and cute. So: snacks, born from fruit.",
    ja: "{子供|こども}は[お菓子|おかし]がすきです。",
    en: "Children like sweets." },
  "ビール|": {
    explain: "A loanword, but not from English. It comes from the Dutch word bier. That explains why it sounds closer to the Dutch or German word than to the English beer. For about two centuries, while Japan kept most of the world out, the Dutch were the only Europeans allowed to trade there, through a small island in Nagasaki. Quite a few words came in that way, and beer is one of them. Listen to the sounds. The b stays, the long ee becomes 「ビー」 with a long vowel, and the final r turns into 「ル」, with an extra vowel, because Japanese does not end words on a consonant. Today beer is the most popular alcoholic drink in Japan. At a work party, the first round is almost always beer, and everyone raises a glass and says 「乾杯|かんぱい」, cheers, from lesson eight. It falls under the wider word 「お酒|おさけ」, which means alcohol in general as well as rice wine. A way to remember it: think of the old Dutch ships bringing barrels in. So: Dutch bier, poured into Japanese.",
    ja: "{日本|にほん}の[ビール]はおいしいです。",
    en: "Japanese beer is tasty." },
  "おもちゃ|": {
    explain: "A native Japanese word, almost always written in kana. There is a formal kanji word for toys, but it is read differently and you mostly see it on signs in stores, so for daily life just use this one. It is a friendly, everyday word, used for anything a child plays with: blocks, cars, dolls, games. A toy store is 「おもちゃ屋|おもちゃや」, with the same shop ending as 「本屋|ほんや」, a bookstore. Stuffed animals have their own word, 「ぬいぐるみ」, which you will meet in lesson fourteen. A typical verb to go with it is 「遊ぶ|あそぶ」, to play: 「おもちゃで遊ぶ|おもちゃであそぶ」, to play with toys. Notice the particle 「で」, because the toy is what you play with, like a tool. A way to remember it: picture a little kid in a store tugging your sleeve and begging, oh, more toys, oh, more cha! The sound-alike gets you most of the way there. So: anything a child plays with, oh more toys.",
    ja: "{子供|こども}の[おもちゃ]がたくさんあります。",
    en: "There are lots of children's toys." },
  "こんがっき|今学期": {
    explain: "Three kanji. The first, 「今|こん」, means now or this. On its own, with its native reading, it is 「今|いま」, now. But at the front of time words it often takes its Chinese-origin reading 「こん」: 「今晩|こんばん」, tonight, 「今週|こんしゅう」, this week, and 「今月|こんげつ」, this month. So you already know this pattern. The rest is 「学期|がっき」, a school term. 「学|がく」 means learning, as in 「学生|がくせい」 and 「大学|だいがく」. 「期|き」 means a period of time. When these two meet, 「がく」 shrinks to 「がっ」, a little pause before the 「き」. That happens a lot in Japanese when a ku sound runs into a k sound. You will see 「期|き」 again in 「期末試験|きまつしけん」, final exams, in lesson sixteen, literally the end of the period exam. So the whole word is this learning period, this semester. Its partner is 「来学期|らいがっき」, next semester. A typical sentence: 「今学期はいそがしいです|こんがっきはいそがしいです」. So: this, plus learning period.",
    ja: "[今学期|こんがっき]はいそがしいです。",
    en: "I am busy this semester." },
  "らいがっき|来学期": {
    explain: "Three kanji. The first, 「来|らい」, means coming, and it is the key to a whole set of time words you already know: 「来週|らいしゅう」, next week, 「来月|らいげつ」, next month, and 「来年|らいねん」, next year. The verb 「来る|くる」, to come, uses the same kanji with its native reading. So whenever you see 「らい」 at the front of a time word, think the one that is coming next. The rest is 「学期|がっき」, a school term. 「学|がく」 is learning, as in 「学生|がくせい」, and 「期|き」 is a period of time. When they join, 「がく」 shrinks to 「がっ」, with a little pause. Put it all together: the coming learning period, next semester. It pairs with 「今学期|こんがっき」, this semester. Notice the neat system: 「今|こん」 for this one, 「来|らい」 for the next one, and you can plug in week, month or semester. A typical sentence: 「来学期、日本語をとります|らいがっき、にほんごをとります」, next semester I will take Japanese. So: coming, plus learning period.",
    ja: "[来学期|らいがっき]、{日本語|にほんご}をとります。",
    en: "I will take Japanese next semester." },
  "じゅぎょう|授業": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「授|じゅ」, means to give or to pass on, and it has the hand radical on the left, a hand handing something over. The second, 「業|ぎょう」, means work, business, or a field of study. You will meet it again in 「卒業|そつぎょう」, graduation, in lesson fifteen, which is finishing your studies. So the whole word is passing on studies, a teacher handing knowledge to students, a class or a lesson. How is this different from 「クラス」? This word is the actual session of teaching, the hour in the classroom. 「クラス」 is more the course, or the group of students. So you say 「授業がある|じゅぎょうがある」, I have class, or 「授業に遅刻する|じゅぎょうにちこくする」, to be late for class. You will see it again in 「授業中に|じゅぎょうちゅうに」, during class, in lesson sixteen. A way to remember it: picture the teacher's hand passing the work across the desk. So: give plus studies, a class.",
    ja: "{今日|きょう}は[授業|じゅぎょう]がありません。",
    en: "I have no class today." },
  "こちら|": {
    explain: "This word belongs to the 「こ」, 「そ」, 「あ」, 「ど」 family. The 「こ」 words point to things near the speaker: 「これ」, this thing, 「ここ」, here. This one literally means this direction, this way. Its siblings are 「そちら」, that way near you, 「あちら」, that way over there, and 「どちら」, which way, which you met in lesson ten. Here is the useful trick. Pointing toward a direction is softer and more polite than pointing at a person or thing directly. So when you introduce someone, you say 「こちらは田中さんです|こちらはたなかさんです」, this is Mr. Tanaka, instead of using 「これ」, which would be rude for a person. It also means here, this place, politely, and on the phone it can mean our side, as in we. A common mistake English speakers make is saying 「これは」 when introducing a friend. Another nice phrase is 「こちらこそ」, the pleasure is mine. So: this way, the polite way to point to people.",
    ja: "[こちら]は{田中|たなか}さんです。",
    en: "This is Mr. Tanaka." },
  "うそをつく|": {
    explain: "A set phrase made of two pieces. 「うそ」 is a lie. The verb 「つく」 is the one Japanese uses for telling lies. You do not say a lie or talk a lie in Japanese, you 「つく」 one. There is a kanji for lie, but it is usually written in kana, so learn it that way. Add 「つき」 to the end and you get 「うそつき」, a liar, which children shout at each other on the playground. You will also hear 「うそ」 on its own all the time, but not as an accusation. When a friend tells you surprising news, you say 「うそ！」 or 「うそでしょう」, meaning no way, you are kidding. It is like saying shut up in English to mean I cannot believe it. So do not be hurt if someone says it to your good news. The past form is 「うそをつきました」, someone lied. A way to remember it: picture someone poking the truth with a stick, a little jab, and that jab is the 「つく」. So: lie, plus the verb for telling it.",
    ja: "{弟|おとうと}は[うそをつきました|うそをつきました|うそをつく]。",
    en: "My little brother told a lie." },
  "おなかがすく|": {
    explain: "A set phrase made of three pieces. 「おなか」 is your stomach or belly, which you will also meet as a body word in lesson twelve. 「が」 marks it as the subject. And 「すく」 means to become empty. So the literal picture is your stomach empties out. That is how Japanese says to get hungry. The grammar is the tricky part. Because 「すく」 is about a change, becoming empty, Japanese uses the past form to say you are hungry right now: 「おなかがすきました」, my stomach has emptied out, I am hungry. Or the ongoing form, 「おなかがすいています」. A common mistake is to say 「おなかがすきます」, which sounds like a general fact or a future, instead of right now. The same logic applies to 「つかれる」, to get tired, also in this lesson. In casual speech people often say 「おなかすいた」, dropping the 「が」. A cute extra: the sound for a rumbling, empty stomach is 「ペコペコ」. So: belly becomes empty, and you say it in the past.",
    ja: "[おなかがすきました|おなかがすきました|おなかがすく]。なにかたべたいです。",
    en: "I am hungry. I want to eat something." },
  "かう|飼う": {
    explain: "This verb is only for keeping animals, raising a pet or livestock. The tricky part is that it sounds exactly like 「買う|かう」, to buy, from lesson four. In speech you tell them apart by context: 「犬を飼う|いぬをかう」 is to keep a dog, and 「犬を買う|いぬをかう」 would be buying one at a store. In writing the kanji solves it. Look at the left side of this kanji: it is the eating radical, a squeezed version of 「食|しょく」, food, the same one in 「食べる|たべる」. That fits nicely, because keeping an animal is mostly about feeding it. To say you have a pet now, use the ongoing form: 「犬を飼っています|いぬをかっています」, I have a dog. That is how you talk about a pet you keep. It goes with 「ペット」, a pet, from lesson fifteen, and with 「猫|ねこ」 and 「犬|いぬ」. A way to remember it: the food radical means feeding. So: same sound as buy, but with food in the kanji, keeping an animal.",
    ja: "{犬|いぬ}を[飼っています|かっています|かう]。",
    en: "I have a dog." },
  "サボる|": {
    explain: "This is a fun one. It comes from the French word sabotage, which Japanese borrowed as 「サボタージュ」, meaning a worker slowdown or strike. People chopped it down to just the first two sounds, 「サボ」, and then stuck the Japanese verb ending 「る」 on the end. Now it works like a normal verb, and it means to skip, to slack off, especially to skip class or work. Because it is a borrowed word, it is written in katakana, with hiragana for the endings, like 「サボります」 and 「サボりました」. It conjugates as a regular u-verb, not an ru-verb, so the te-form is 「サボって」. It is casual, and a little naughty. You would say it with friends, not to your teacher. Japanese makes verbs from borrowed words this way now and then, and the same trick turns google into a slangy verb for searching online. A typical sentence: 「授業をサボりました|じゅぎょうをサボりました」, I skipped class. A way to remember it: you are sabotaging your own grades. So: French sabotage, shortened, turned into a verb for skipping.",
    ja: "{今日|きょう}は{授業|じゅぎょう}を[サボりました|サボりました|サボる]。",
    en: "I skipped class today." },
  "とる|取る": {
    explain: "This is the general, everyday take. You take a class, 「クラスを取る|クラスをとる」, get a grade, grab something off a shelf, or pass something over: 「塩を取ってください|しおをとってください」, please pass the salt. There are several verbs pronounced 「とる」, and Japanese uses a different kanji for each kind of taking. For photos it is 「撮る|とる」, from lesson four and in 「写真を撮る|しゃしんをとる」 in this lesson. This one is the all-purpose version. Now the kanji. On the left is 「耳|みみ」, ear. On the right is a simple shape for a hand. The traditional explanation is a little grim: in ancient China, soldiers took the ear of a defeated enemy as proof, so a hand grabbing an ear meant to take. Whether or not you like the story, it is a memorable picture: a hand reaching out and taking hold. Another handy phrase is 「年を取る|としをとる」, to get older, literally to take on years. So: a hand grabbing an ear, the everyday verb for taking.",
    ja: "{日本語|にほんご}のクラスを[取っています|とっています|とる]。",
    en: "I am taking a Japanese class." },
  "ならう|習う": {
    explain: "This verb means to learn from someone, to take lessons. You learn piano, karate or cooking from a teacher: 「母に料理を習いました|ははにりょうりをならいました」. Notice the particle 「に」 for the person you learn from. Compare it with 「勉強する|べんきょうする」, which is studying on your own, with books and homework. And with 「覚える|おぼえる」, from lesson nine, which is memorizing, getting something into your head. A common mistake is using 「習う|ならう」 for studying alone at your desk. Now the kanji. The top is 「羽|はね」, wings. The traditional reading of the shape is a young bird beating its wings over and over, practicing until it can fly. That idea of repetition is the core of the kanji. You can see it in two words you know: 「練習|れんしゅう」, practice, from lesson ten, and 「習慣|しゅうかん」, a habit, from lesson fifteen, where it is read 「しゅう」. Both are about doing something again and again. So: little wings flapping, learning from a teacher by practice.",
    ja: "{母|はは}にりょうりを[習いました|ならいました|ならう]。",
    en: "I learned cooking from my mother." },
  "のぼる|登る": {
    explain: "This verb means to climb, to go up something with some effort: a mountain, a tree, a tall staircase. The thing you climb takes the particle 「に」: 「山に登る|やまにのぼる」, to climb a mountain. You can also use 「を」 when you mean climbing along a path, but 「に」 is the safe choice for now. The same kanji appears in 「登山|とざん」, mountain climbing as a hobby, where it is read 「と」 and the mountain kanji is read 「ざん」. A cultural note: every summer, many people climb Mount Fuji overnight to watch the sunrise from the top. There is a saying that a wise person climbs Fuji once, and only a fool climbs it twice. A way to remember the verb: picture your legs pushing up the slope. Its opposite, coming down, is 「降りる|おりる」, from lesson six. So: climbing up, usually to a mountain with 「に」.",
    ja: "{友だち|ともだち}と{山|やま}に[登りました|のぼりました|のぼる]。",
    en: "I climbed a mountain with a friend." },
  "はしる|走る": {
    explain: "A native Japanese verb, meaning to run. Even though it ends in 「る」, it is a u-verb, so the te-form is 「走って|はしって」, not a ru-verb shape. This is one of the classic exceptions, like 「帰る|かえる」 and 「入る|はいる」. Now the kanji. In its old forms, the top was a person swinging their arms, and the bottom was a foot. Today the top looks like soil and the bottom part looks like the lower half of 「足|あし」, foot, from lesson twelve. So the kanji is a moving body over a foot, running. Its slower partner is 「歩く|あるく」, to walk, also from lesson twelve, and you already know 「歩いて|あるいて」, on foot. With places, 「を」 marks where you run through: 「公園を走る|こうえんをはしる」, to run in the park. It is not only for people. Trains and cars 「走る|はしる」 too, which is how Japanese says a train runs on a line. A way to remember it: arms swinging, feet pounding. So: a body over a foot, running.",
    ja: "{毎朝|まいあさ}{公園|こうえん}を[走ります|はしります|はしる]。",
    en: "I run in the park every morning." },
  "つかれる|疲れる": {
    explain: "This verb means to get tired. It is a ru-verb, and like 「おなかがすく」, it describes a change: you become tired. So to say you are tired right now, use the past: 「疲れました|つかれました」, I have gotten tired, I am tired. Or the ongoing form, 「疲れています|つかれています」. A common mistake is to say 「疲れます|つかれます」, which sounds like a general fact, this job tires me out, rather than how you feel now. You will hear the casual 「疲れた|つかれた」 a lot, said with a sigh at the end of a long day. Now the kanji. On the outside is the sickness radical, a slanted roof shape with two little dots on the left. It is the same one as in 「病気|びょうき」, illness, from lesson twelve, and it marks many words about the body feeling bad. A way to remember it: being tired is a mini sickness, the body under a heavy roof. At work, people say 「お疲れ様です|おつかれさまです」 to each other, a thank you for your hard work. So: the sickness roof, and you say it in the past.",
    ja: "{今日|きょう}はとても[疲れました|つかれました|つかれる]。",
    en: "I got very tired today." },
  "やめる|": {
    explain: "This verb means to quit or to stop doing something. It is a ru-verb, and the thing you stop takes 「を」: 「たばこをやめる」, to quit smoking, 「アルバイトをやめる」, to quit a part time job. It can be written with kanji, and which one depends on the meaning: one for quitting a job, another for stopping an action. Genki uses kana, which is safe for both. You will also hear it on its own a lot. 「やめて」 or 「やめてください」 means stop it, please stop, and 「やめましょう」 means let us not do it, let us call it off. How is it different from 「止まる|とまる」 or 「止める|とめる」? Those are about stopping movement, like a car stopping, while this one is about giving up an activity or a habit. A common mistake is using it to say a bus stopped. A way to remember it: when you quit something, you say yikes, I am done, and walk away. So: giving up an activity, with 「を」.",
    ja: "{父|ちち}はたばこを[やめました|やめました|やめる]。",
    en: "My father quit smoking." },
  "けんかする|": {
    explain: "The noun 「けんか」 means a fight, and with 「する」 it becomes a verb, to fight. It covers both shouting arguments and real fistfights, so context tells you which. A couple arguing over the dishes and two drunk men brawling are both 「けんか」. There are kanji for it, but they are hard, so it is usually written in kana. The person you fight with takes 「と」, the with particle: 「兄とけんかしました|あにとけんかしました」, I had a fight with my brother. A common mistake is using 「を」, which sounds like you are fighting the person as an object. There is a nice compound for fights between brothers and sisters: 「きょうだいげんか」. Notice the sound softens to 「げんか」 when it comes second, the way 「川|かわ」 becomes 「がわ」. There is also a well known saying that fights and fires are the flowers of old Edo, the old name for Tokyo, because both happened so often there. A way to remember it: think of a tense, crackling ken, ka. So: a fight, done with someone using 「と」.",
    ja: "{昨日|きのう}、{兄|あに}と[けんかしました|けんかしました|けんかする]。",
    en: "I had a fight with my big brother yesterday." },
  "しょうかいする|紹介する": {
    explain: "Two kanji with Chinese-origin readings, plus 「する」. The first, 「紹|しょう」, has the thread radical on the left, a small twisted thread, which often marks ideas about tying and connecting. The second, 「介|かい」, means to be in between, to act as a go-between. So the word is to tie two people together by standing in the middle: to introduce. The pattern puts the person you introduce with 「を」 and the listener with 「に」: 「友だちを先生に紹介します|ともだちをせんせいにしょうかいします」, I introduce my friend to the teacher. When you introduce yourself, you do a 「自己紹介|じこしょうかい」, a self introduction, which is a big part of the first day of class, a new job, or any meeting in Japan. It usually goes: 「はじめまして」, then your name, a little about yourself, and 「よろしくおねがいします」. You also hear it in a polite request: 「紹介してください|しょうかいしてください」, please introduce me. A way to remember it: the thread connecting you to someone new. So: a thread and a go-between, introducing people.",
    ja: "{友だち|ともだち}を[紹介します|しょうかいします|しょうかいする]。",
    en: "Let me introduce my friend." },
  "ダイエットする|": {
    explain: "A loanword from the English word diet, made into a verb with 「する」. Listen to the sounds. Diet becomes 「ダイエット」. The die part stays close to English, the e gets its own beat, and the t is doubled with a small 「ッ」, a little pause, then gets an extra vowel, because Japanese does not end on a consonant. The meaning shifted. In English, your diet can just be whatever you normally eat. In Japanese, this word always means trying to lose weight, going on a diet. So 「ダイエットしています」 means I am on a diet. If you want to talk about what you eat in general, you would use a different expression, so do not say your diet is mostly vegetables with this word. It goes naturally with 「やせる」, to lose weight, and 「太る|ふとる」, to gain weight, both from lesson seven. A common pairing: 「ダイエットのために、走っています|ダイエットのために、はしっています」. A way to remember it: in Japanese, a diet is always a mission. So: diet, but only the weight loss kind.",
    ja: "{今|いま}、[ダイエットしています|ダイエットしています|ダイエットする]。",
    en: "I am on a diet now." },
  "ちこくする|遅刻する": {
    explain: "Two kanji with Chinese-origin readings, plus 「する」. The first, 「遅|ち」, means late or slow. On its own, with its native reading, it is 「遅い|おそい」, slow or late, from lesson ten. You also know it from 「遅くなる|おそくなる」, to be late, and you will meet it in 「乗り遅れる|のりおくれる」, to miss a train, in lesson sixteen. Look at the bottom left of the kanji: that long sweeping stroke is the movement radical, often found in kanji about going and walking. The second kanji, 「刻|こく」, means to carve, and from there, a precise moment of time, as if time were carved into marks. So the word is late for the set moment: to be late for something scheduled, like class or work. The thing you are late for takes 「に」: 「授業に遅刻しました|じゅぎょうにちこくしました」. Culturally, this matters a lot in Japan. Trains run to the minute, and being even a few minutes late is a real thing to apologize for. So: late for the carved moment.",
    ja: "{授業|じゅぎょう}に[遅刻しました|ちこくしました|ちこくする]。",
    en: "I was late for class." },
  "りゅうがくする|留学する": {
    explain: "Two kanji with Chinese-origin readings, plus 「する」. The first, 「留|りゅう」, means to stay, to remain somewhere. The second, 「学|がく」, means learning, the same kanji as in 「学生|がくせい」 and 「大学|だいがく」. So the word is to stay somewhere to learn, to study abroad. You actually met this word on day one of Genki. 「留学生|りゅうがくせい」, an international student, is just this word plus 「生|せい」, student. Many of the Genki characters are exactly that. The place you go takes 「に」: 「日本に留学したいです|にほんにりゅうがくしたいです」, I want to study abroad in Japan. That is the 「たい」 form for wanting to do something. It is used for a longer stay at a school, a semester or a year, not for a short tourist trip, which would be 「旅行|りょこう」. When you go, you might stay with a 「ホストファミリー」, also in this lesson. A way to remember it: you are staying to study, and you stay long enough to become a 「留学生|りゅうがくせい」. So: stay plus learn, studying abroad.",
    ja: "{日本|にほん}に[留学したい|りゅうがくしたい|りゅうがくする]です。",
    en: "I want to study abroad in Japan." },
  "しゅっしん|出身": {
    explain: "Two kanji with Chinese-origin readings. The first, 「出|しゅつ」, means to come out, to go out. Here it shrinks to 「しゅっ」, with a little pause, before the next sound. You know this kanji from 「出かける|でかける」, to go out, and 「出す|だす」, to take out, where it uses its native readings. The second, 「身|しん」, means body, or oneself. So the word is where you yourself came out from: your hometown, home country, or even your old school. It is a noun, and it attaches right after a place: 「東京出身です|とうきょうしゅっしんです」, I am from Tokyo. To ask someone politely, add the honorable 「ご」: 「ご出身はどちらですか|ごしゅっしんはどちらですか」, where are you from? That uses 「どちら」, the polite which way. It is a staple of self introductions in Japan, right after your name. A common mistake is to say you are 「出身|しゅっしん」 something without a place in front. A way to remember it: picture yourself stepping out of your hometown gate. So: come out plus self, where you are from.",
    ja: "わたしは{東京|とうきょう}[出身|しゅっしん]です。",
    en: "I am from Tokyo." },
  "ひさしぶり|久しぶり": {
    explain: "Two pieces. 「久し|ひさし」 comes from the adjective 「久しい|ひさしい」, a slightly literary word meaning long-lasting, long ago. The kanji carries that same sense of a long time. Then 「ぶり」 is a little ending that means after a gap of. You can put it after any length of time: 「三年ぶり|さんねんぶり」, for the first time in three years, or 「一週間ぶり|いっしゅうかんぶり」, after a week. So this word is after a long gap, it has been a long time. Its most common use is as a greeting when you see someone again after ages: 「お久しぶりです|おひさしぶりです」 is the polite version, with 「お」 in front, and 「久しぶり|ひさしぶり」 or 「久しぶりだね|ひさしぶりだね」 is casual, for friends. It is often followed by 「お元気ですか|おげんきですか」, how have you been? You can also use it for doing something again: 「久しぶりに映画を見ました|ひさしぶりにえいがをみました」, I watched a movie for the first time in a long while. A way to remember it: a long gap, then hello again. So: long time, plus after a gap.",
    ja: "[久しぶり|ひさしぶり]ですね。おげんきですか。",
    en: "Long time no see. How are you?" },
  "まあまあ|": {
    explain: "A native Japanese word with no kanji. It means so-so, okay, not great and not bad. It is the answer when someone asks how something was and you do not want to sound too excited or too negative. 「テストはどうでしたか」, how was the test? 「まあまあでした」, it was okay. It also works for people and things: a restaurant that is 「まあまあ」 is fine but nothing special. It comes from the little word 「まあ」, which on its own is a soft hesitation, like well, or a mild oh my. Doubling it makes a gentle, shrugging sound. Japanese loves this kind of doubled word, like 「ときどき」 and 「いろいろ」. Here is a cultural tip: Japanese people often say 「まあまあ」 about their own skills to sound modest, even when they are very good. So if a friend says their English is 「まあまあ」, it may be excellent. A common mistake is using it as a strong negative, but it is gentle. A way to remember it: picture a shoulder shrug with each 「まあ」. So: a doubled shrug, so-so.",
    ja: "テストは[まあまあ]でした。",
    en: "The test was so-so." },
  "もっと|": {
    explain: "A native Japanese word, an adverb meaning more, or even more. It goes right before what you want more of: a verb, an adjective, or another adverb. 「もっと食べてください|もっとたべてください」, please eat more. 「もっと大きいのがいいです|もっとおおきいのがいいです」, a bigger one would be good. And a very useful phrase for learners: 「もっとゆっくり話してください|もっとゆっくりはなしてください」, please speak more slowly. Notice it comes before the word it boosts, just like English more. Compare it with 「たくさん」, a lot, which is about a big amount, while this one is always about going beyond where you are now. A way to remember it, as a sound-alike hook: it sounds like the English word motto, and the motto of a hungry learner is always more. So: always more, placed before the word.",
    ja: "[もっと]{日本語|にほんご}を{勉強したい|べんきょうしたい}です。",
    en: "I want to study Japanese more." },
  "あと|後": {
    explain: "This uses the native Japanese reading of the kanji, 「あと」, and it means after or later. It follows a noun with 「の」: 「授業の後|じゅぎょうのあと」, after class. Or it follows a verb in the past: 「食べた後|たべたあと」, after eating. Notice that the verb before it is always in the past form, even when you talk about the future. You already know a close relative from lesson six: 「後で|あとで」, later, as in see you later. The same kanji has other readings too. With its Chinese-origin reading 「ご」, it is in 「〜後|〜ご」 from lesson ten, as in 「三日後|みっかご」, three days later. And with another native reading, it is in 「後ろ|うしろ」, behind. So the kanji is all about what comes after, in time or in space. Look at the left side: it is the going person radical, the same one as in 「行く|いく」. A way to remember it: someone walking along, falling behind, coming after. So: after, following a noun with 「の」 or a past verb.",
    ja: "{授業|じゅぎょう}の[後|あと]、テニスをします。",
    en: "I play tennis after class." },
  "そして|": {
    explain: "A native Japanese connecting word. It links two sentences in order, like and then, or and also. 「本を読みました|ほんをよみました」. 「そして、寝ました|そして、ねました」. I read a book, and then I went to sleep. It comes from 「そう」, in that way, plus 「して」, the te-form of 「する」, so roughly having done that. That is why it carries a sense of sequence. Like other sentence connectors, it goes at the start of the second sentence, usually followed by a comma. How is it different from 「それから」, from lesson four? They are very close. 「それから」 leans toward after that, the next thing in time. This one can mean the next step, but also just adding another point: this restaurant is cheap, and also delicious. It sounds a little more written and neat than 「それから」. A common mistake is to use it to join two nouns, like cats and dogs. For that, Japanese uses the particle 「と」 instead. A way to remember it: having done so, then the next thing. So: and then, between sentences.",
    ja: "{本|ほん}を{読みました|よみました}。[そして]、ねました。",
    en: "I read a book. And then I went to sleep." },
  "〜だけ|": {
    explain: "A small grammar word, a particle, meaning only or just. It goes right after the thing you are limiting, usually a noun or a number. 「一つだけ|ひとつだけ」, just one. 「水だけ|みずだけ」, only water. 「日本語だけ話します|にほんごだけはなします」, I speak only Japanese. When it comes after a noun, it often replaces 「を」 or 「が」, so you do not need them. It is a neutral word. It just states the limit, without any feeling of too little or too much. In later lessons you will meet another word for only that carries more of a not enough feeling, but this one is calm and simple. It can also follow a verb in the plain form: 「見るだけ|みるだけ」, just looking, which is perfect when a shop clerk comes to help you and you are only browsing. A common mistake English speakers make is putting it in front of the word, like English only. In Japanese it always comes after. A way to remember it: picture a fence put up right after the word, and nothing gets past. So: only, placed after the thing.",
    ja: "{日本語|にほんご}[だけ]{話します|はなします}。",
    en: "I speak only Japanese." },
  "〜てん|〜点": {
    explain: "A counter for points and scores. It goes right after a number: 「九十点|きゅうじゅってん」, ninety points, or 「百点|ひゃくてん」, a hundred points. Japanese school tests are usually scored out of a hundred, so a hundred points is a perfect score, and you hear that phrase a lot from proud kids. Watch for the little sound changes, the same ones you meet with other counters. One point is 「一点|いってん」, three is 「三点|さんてん」, and ten is 「十点|じゅってん」, where the number shrinks and leaves a small pause. The kanji itself means a dot, a point, a mark. The four little strokes at the bottom are like dots. The same word is used for points in a sports match, and for a point in the sense of a point in an argument. To ask about a score: 「テストは何点でしたか|テストはなんてんでしたか」, how many points did you get on the test? A way to remember it: each point is a little dot on the scoreboard. So: dots on a scoreboard, a counter for points.",
    ja: "テストは[九十点|きゅうじゅってん|〜てん]でした。",
    en: "I got ninety points on the test." },
  "さっか|作家": {
    explain: "Two kanji with Chinese-origin readings. The first, 「作|さく」, means to make, to create. Here it shrinks to 「さっ」 before the 「か」, with a little pause. You know it with its native reading in 「作る|つくる」, to make, from lesson eight. The second, 「家|か」, usually means house, as in 「家|いえ」. But at the end of a word, read 「か」, it means a person who does something as their profession, a specialist. You will see that use in 「漫画家|まんがか」, a manga artist, from this same lesson. The house sense is in 「家族|かぞく」, family, where it is also read 「か」. So this word is a maker by profession, a creator of writing, a writer or novelist. It is more for authors of books and stories than for journalists, who are 「ジャーナリスト」. Japan has a big literary tradition and a famous literary prize for new writers, so this word comes up often. A way to remember it: the maker who works from home all day. So: make, plus professional, an author.",
    ja: "あの[作家|さっか]の{本|ほん}がすきです。",
    en: "I like that writer's books." },
  "ジャーナリスト|": {
    explain: "A loanword straight from the English word journalist. Listen to how the sounds were fitted into Japanese. The j sound becomes 「ジャ」, a small ya tucked after a ji sound. The ur in the middle of journal becomes a long vowel, 「ジャー」, since Japanese has no ur sound. The n gets its own vowel, 「ナ」, then the l becomes an r sound, 「リ」. And the st at the end splits into two beats, 「ス」 and 「ト」, because Japanese does not stack consonants. So three syllables in English turn into six beats in Japanese. The meaning is the same as English: someone who reports news, for a newspaper, a magazine, TV or online. That links to 「新聞|しんぶん」, a newspaper, and 「雑誌|ざっし」, a magazine, from earlier lessons. A writer of novels, by contrast, is a 「作家|さっか」. A way to remember it: just say journalist slowly and give every consonant its own vowel. A typical sentence: 「姉はジャーナリストです|あねはジャーナリストです」. So: journalist, stretched to Japanese rhythm.",
    ja: "{姉|あね}は[ジャーナリスト]です。",
    en: "My older sister is a journalist." },
  "けいさつかん|警察官": {
    explain: "Three kanji, all with Chinese-origin readings. The first, 「警|けい」, means to warn or to guard. Look at the bottom: it contains 「言|げん」, the speech part, which fits giving a warning. The second, 「察|さつ」, means to observe, to look into, to inspect. Together, 「警察|けいさつ」 is the police, the ones who guard and watch over things. The third, 「官|かん」, means a government official. So the full word is a police official, a police officer. It is the formal job title. In everyday speech, people usually say 「おまわりさん」, a friendly word that literally means the honorable one who goes around, because officers patrol the neighborhood. Kids learn that one first. A big part of Japanese policing is the tiny neighborhood police box, where officers help people with directions and lost items. That is why the Genki example asks an officer for directions. If you lose a wallet in Japan, there is a good chance it ends up there. A way to remember it: guard, observe, official. So: the official who guards and watches, a police officer.",
    ja: "[警察官|けいさつかん]にみちを{聞きました|ききました}。",
    en: "I asked a police officer for directions." },
  "しょうぼうし|消防士": {
    explain: "Three kanji, all with Chinese-origin readings. The first, 「消|しょう」, means to put out, to extinguish. You know it with its native reading in 「消す|けす」, to turn off or erase, from lesson six. Look at its left side: the water radical, three little drops. Perfect, since water puts out fire. The second, 「防|ぼう」, means to prevent or to defend against. Together, 「消防|しょうぼう」 means firefighting, both putting fires out and preventing them. The third, 「士|し」, means a trained person, a professional. You will see the same ending in 「弁護士|べんごし」, a lawyer, from lesson thirteen, and in 「宇宙飛行士|うちゅうひこうし」, an astronaut, from this lesson. So the word is a trained person who fights fires, a firefighter. A fun fact: in Japan, the emergency number for fire and ambulances is one one nine, while the police use one one zero. Kids in Japan often say they want to be a firefighter when they grow up. A way to remember it: water to put it out, a wall to prevent it. So: extinguish, prevent, professional.",
    ja: "[消防士|しょうぼうし]はかっこいいです。",
    en: "Firefighters are cool." },
  "きょうし|教師": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「教|きょう」, means to teach. You know it with its native reading in 「教える|おしえる」, to teach, from lesson six. It is also in 「教科書|きょうかしょ」, a textbook, and 「教室|きょうしつ」, a classroom. The second, 「師|し」, means master or expert, a person who has mastered something and passes it on. The same kanji is in 「看護師|かんごし」, a nurse, later in this lesson. So this word is a teaching master, a teacher. Here is the key difference from 「先生|せんせい」. This word is the job title, how you describe the profession: 「母は教師です|はははきょうしです」, my mother is a teacher. But you never call your own teacher by it. To their face, or when talking about them with respect, you say 「先生|せんせい」. A common mistake is to say 「教師|きょうし」 when greeting your teacher, which sounds cold and odd. And when talking about your own teaching job, you use this word, never 「先生|せんせい」, since you would not give yourself that title of respect. A way to remember it: the job title on a business card. So: teach plus master, a teacher as a profession.",
    ja: "{母|はは}は{高校|こうこう}の[教師|きょうし]です。",
    en: "My mother is a high school teacher." },
  "けんきゅうしゃ|研究者": {
    explain: "Three kanji, all with Chinese-origin readings. The first, 「研|けん」, means to polish or to grind, and it has the stone radical on the left, like grinding a stone smooth. The second, 「究|きゅう」, means to go to the very bottom of something, to investigate fully. Together, 「研究|けんきゅう」 means research, polishing an idea and digging down to the bottom of it. You will meet that word by itself in lesson sixteen. The third kanji, 「者|しゃ」, means a person who does something. It is the same ending as in 「医者|いしゃ」, a doctor, from lesson ten. So this word is a person who does research, a researcher or scientist. It is used for people at universities, labs and companies. Many students in a 「大学院|だいがくいん」, graduate school, hope to become one. A typical sentence: 「研究者になりたいです|けんきゅうしゃになりたいです」, I want to be a researcher. A way to remember it: polish the stone, dig to the bottom, and you are the person doing it. So: polish, dig deep, person.",
    ja: "[研究者|けんきゅうしゃ]になりたいです。",
    en: "I want to become a researcher." },
  "うちゅうひこうし|宇宙飛行士": {
    explain: "A long word, but it breaks into three easy chunks, all with Chinese-origin readings. First, 「宇宙|うちゅう」, outer space, the universe. Both of these kanji have the same roof radical on top, the one that shows up in many kanji about houses and covering. So a way to picture it: space is the great roof over everything. Next, 「飛行|ひこう」, flying. The first kanji is to fly, and the second is to go. You already know this pair from 「飛行機|ひこうき」, an airplane, from lesson ten, which is a flying machine. And the second kanji, 「行|こう」, is the same as in 「旅行|りょこう」, a trip, and 「行く|いく」. Last, 「士|し」, a trained professional, the same ending as in 「消防士|しょうぼうし」, a firefighter, and 「弁護士|べんごし」, a lawyer. So the whole word is a trained person who flies in space, an astronaut. Japan has sent several astronauts to the space station, and many children dream of becoming one. A way to remember it: space, flying, professional. So: three chunks stacked together, a space flyer.",
    ja: "{将来|しょうらい}、[宇宙飛行士|うちゅうひこうし]になりたいです。",
    en: "I want to be an astronaut in the future." },
  "スポーツせんしゅ|スポーツ選手": {
    explain: "A mix of a loanword and a kanji word. The first part, 「スポーツ」, comes from the English word sports, with a long vowel for the or sound and extra vowels so each consonant gets its own beat. You have known it since lesson three. The second part, 「選手|せんしゅ」, uses Chinese-origin readings. 「選|せん」 means to choose, to select. Look at its bottom left: the long movement stroke you also see in 「遅刻|ちこく」. 「手|しゅ」 means hand, and here a skilled person, the same as in 「歌手|かしゅ」, a singer, from this lesson. So 「選手|せんしゅ」 is a chosen skilled person, the player picked for the team, an athlete. You can swap in a specific sport: a baseball player is 「野球選手|やきゅうせんしゅ」, and a soccer player is 「サッカー選手|サッカーせんしゅ」. Baseball is huge in Japan, and the summer high school tournament is a national event. A way to remember it: the coach chooses you, and you are the hand that plays. So: sports, plus chosen player, an athlete.",
    ja: "{兄|あに}は[スポーツ選手|スポーツせんしゅ]です。",
    en: "My older brother is an athlete." },
  "はいゆう|俳優": {
    explain: "Two kanji, both with Chinese-origin readings. Both have the person radical on the left, the thin standing person, so you know right away this word is about people. The first, 「俳|はい」, means a performer or entertainer in old usage. You may know it from 「俳句|はいく」, the famous short poem. The second, 「優|ゆう」, also meant a performer long ago. Today it also means excellent or gentle. With its native reading it is 「優しい|やさしい」, kind, the same sound as the gentle 「やさしい」 from lesson five. So the word is two old words for performer, put together: an actor. It is used for film, TV and stage actors, and for both men and women. If you want to say actress specifically, there is 「女優|じょゆう」, a woman performer, which is still very common. Japan also has famous traditional actors in 「歌舞伎|かぶき」, all of them men, even in women's roles. A typical sentence: 「あの俳優はとても有名です|あのはいゆうはとてもゆうめいです」. A way to remember it: two people standing on a stage. So: performer plus performer, an actor.",
    ja: "あの[俳優|はいゆう]はとても{有名|ゆうめい}です。",
    en: "That actor is very famous." },
  "かんごし|看護師": {
    explain: "Three kanji, all with Chinese-origin readings. The first, 「看|かん」, means to watch over carefully. Its shape is traditionally explained as a hand held over an eye, shading it to look closely. You can see the eye 「目|め」 at the bottom. The second, 「護|ご」, means to protect. It is also in 「弁護士|べんごし」, a lawyer, from lesson thirteen, someone who protects you in court. Together, 「看護|かんご」 means nursing care, watching over and protecting a patient. The third, 「師|し」, means a professional, a master of a skill. It is the same one as in 「教師|きょうし」, a teacher, from this lesson. So the whole word is a nursing professional, a nurse. Here is a nice bit of history. The old word ended in a kanji meaning woman, because nurses were assumed to be female. Around two thousand two, the official title changed to this one, so it covers everyone. You will still hear people say 「看護婦|かんごふ」 sometimes. A way to remember it: a hand over the eye, watching the patient. So: watch, protect, professional, a nurse.",
    ja: "{姉|あね}は{病院|びょういん}の[看護師|かんごし]です。",
    en: "My older sister is a nurse at a hospital." },
  "シェフ|": {
    explain: "This one comes from French. The French word chef simply means chief or head, and it is the same root as the English word chief. A French head cook is the chef de cuisine, the head of the kitchen, and English and Japanese both kept just the first word. Look at how the sounds fit into Japanese. Japanese has no native sheh sound, so it uses a special combination, a big 「シ」 with a small 「ェ」, made for foreign words. And because a Japanese word can't end on an f sound, the final sound gets an extra u vowel and becomes 「フ」. So you get 「シェフ」. It's also a loanword sibling of 「レストラン」, another French word that came in through cooking and dining. In Japanese, 「シェフ」 has a stylish feel. It suggests a trained cook at a proper restaurant, often Western-style, and on TV you'll hear famous cooks called by name plus 「シェフ」, almost like a title. A plain everyday cook is more often 「コック」, which came from Dutch. To recap: French chef, head of the kitchen, with an extra vowel tacked on the end.",
    ja: "あの[シェフ]のりょうりはおいしいです。",
    en: "That chef's food is delicious." },
  "まんがか|漫画家": {
    explain: "Let's break it into three kanji. 「漫|まん」 means rambling, free-flowing, aimless, using its Chinese-origin reading. 「画|が」 means picture, and you know it from 「映画|えいが」, a movie, literally moving pictures, and from 「映画館|えいがかん」. Put them together and 「漫画|まんが」 is free, loose pictures: drawings done for fun rather than serious fine art. The great woodblock artist Hokusai used this word for his famous sketchbooks over two hundred years ago, long before modern comics. Then comes 「家|か」. On its own with its native reading, 「家|いえ」 is a house, and it's in 「家族|かぞく」, family. But tacked on the end of a word with the Chinese-origin reading 「か」, it means a person who makes a profession of something, a specialist. You've met it in 「作家|さっか」, a writer, literally a person of making, and you'll see it in 「政治家|せいじか」, a politician. So 「漫画家|まんがか」 is a professional of loose, playful pictures. In Japan this is a serious and respected career, and famous ones are household names. To recap: 「漫画|まんが」, comics, plus 「家|か」, the professional who makes them.",
    ja: "[漫画家|まんがか]になりたいです。",
    en: "I want to become a cartoonist." },
  "だいとうりょう|大統領": {
    explain: "Three kanji, all with their Chinese-origin readings. 「大|だい」 means big or great, the same as in 「大学|だいがく」, college, and 「大好き|だいすき」. 「統|とう」 means to unite or bring together under one control; it has the thread radical on the left, like gathering many threads into one. 「領|りょう」 means to govern or to hold territory. The pair 「統領|とうりょう」 already meant a leader who commands everyone, and putting 「大|だい」 in front makes it the great leader. Japanese built this word in the eighteen-hundreds, when it needed a way to talk about the head of the United States. That's why it's used for elected heads of countries, like the American or French president. Here's a common mix-up for English speakers: president in English covers companies too, but in Japanese the head of a company is 「社長|しゃちょう」, with the 「社|しゃ」 of 「会社|かいしゃ」. Japan itself has no 「大統領|だいとうりょう」; its leader is the prime minister, 「総理大臣|そうりだいじん」. To recap: the great, 「大|だい」, uniting leader, for countries only.",
    ja: "アメリカの[大統領|だいとうりょう]はだれですか。",
    en: "Who is the president of America?" },
  "おなか|": {
    explain: "This word is two pieces. First the polite prefix 「お」, the same softening 「お」 you hear in 「お金|おかね」 and 「お茶|おちゃ」. Then 「なか」, which you know as middle or inside, the word written 「中|なか」. So your stomach is, literally, your honorable middle. It's the soft, polite, everyday way to talk about your belly, and you'll hear it from everyone, kids and adults. There is a kanji spelling, 「お腹|おなか」, but kana is very common. You already met it in 「おなかがすく」, to get hungry, literally the stomach becomes empty. Two other patterns are worth knowing. 「おなかがいたい」 means my stomach hurts, and 「おなかがいっぱい」 means I'm full. A common mistake for English speakers is using it only for the organ inside. In Japanese it covers the whole tummy area, so a baby's round belly or a cat's fluffy underside is also 「おなか」. There's a blunter word for belly, 「はら」, but that one sounds rough, so stick with 「おなか」 to be safe. To recap: polite 「お」 plus 「なか」, the middle of you.",
    ja: "[おなか]がいたいです。",
    en: "My stomach hurts." },
  "あし|足": {
    explain: "The kanji is a picture of a leg. The bottom part looks like a foot taking a step, and the box on top is usually explained as the knee. That's a handy way to see it: knee on top, foot at the bottom, the whole leg in one character. And that matches the word. English splits leg and foot, but Japanese 「足|あし」 covers both, from the hip all the way to the toes. So 「足がいたい|あしがいたい」 could mean your feet hurt after a long walk or your legs ache after a run, and context tells you which. The reading here is the native Japanese one, 「あし」. The same kanji also carries the idea of being enough, as in 「足りる|たりる」, to be sufficient. A way to remember it: having enough is like standing on your own two feet. You'll also see 「足|あし」 used for animals and furniture, like the legs of a table. Look at 「歩く|あるく」, to walk: its top part is 「止|し」, another old drawing of a foot. Feet and walking keep showing up in these shapes. To recap: one kanji, one word, for the whole leg down to the foot.",
    ja: "たくさん{歩いて|あるいて}、[足|あし]がいたいです。",
    en: "I walked a lot, and my legs hurt." },
  "は|歯": {
    explain: "The reading here is the native Japanese one, just 「は」, a single sound. Look at the kanji. The bottom part shows rows of teeth inside an open mouth, a frame with little marks lined up inside it. The 「止|し」 sitting on top originally helped give the character its sound. So when you see the boxy bottom with teeth inside, think of a mouth full of teeth. The best sibling word is 「歯医者|はいしゃ」, a dentist. You know 「医者|いしゃ」, a doctor, and putting 「歯|は」 in front makes a tooth doctor. It's an easy one to build yourself. To brush your teeth is 「歯をみがく|はをみがく」, using the verb for polishing. Watch out for one thing: there are many words pronounced 「は」 in Japanese, such as 「葉|は」, a leaf, and of course the particle 「は」. Context sorts them out, and the tooth one is almost always followed by something like 「がいたい」 or 「をみがく」. A small cultural note: when a child loses a baby tooth in Japan, the tradition is to throw a lower tooth up onto the roof and an upper tooth down below, so the new one grows in straight. To recap: one sound, 「は」, a mouth full of teeth.",
    ja: "{毎日|まいにち}[歯|は]をみがきます。",
    en: "I brush my teeth every day." },
  "のど|": {
    explain: "This is a native Japanese word, usually written in kana in everyday life, though it does have a kanji, 「喉|のど」, with the mouth radical on the left. It covers your throat from the inside, where you swallow and where your voice comes from. A way to remember it: 「のど」 starts like 「のむ」, to drink, and your throat is exactly where drinks go down. That's a hook, not a word history. The two big patterns in this lesson are about being sick or thirsty. 「のどがいたい」 means I have a sore throat, a classic symptom you'd tell a doctor along with 「せき」, a cough, and 「熱|ねつ」, a fever. And 「のどがかわく」 means your throat dries out, which is how Japanese says you're thirsty. A common mistake for English speakers is to say thirsty with an adjective. Japanese describes the throat instead. One fun cultural note: Japan has a very long-running TV singing contest for ordinary people called 「のど自慢|のどじまん」, literally bragging about your throat, meaning showing off your singing voice. So 「のど」 is also your singing voice. To recap: the throat, where you swallow, where you sing, and what gets dry when you're thirsty.",
    ja: "かぜで[のど]がいたいです。",
    en: "My throat hurts because of a cold." },
  "ねつ|熱": {
    explain: "Look at the bottom of 「熱|ねつ」. Those four little dots are the fire radical, the same dots you see under many heat-related characters. So this kanji is about heat. Here it uses its Chinese-origin reading, 「ねつ」. When it means a fever, it's simply your body having extra heat. The same kanji with its native reading gives you 「熱い|あつい」, hot to the touch, like hot tea or a hot pan. Be careful: hot weather uses a different kanji, 「暑い|あつい」. Both are pronounced 「あつい」, but 「熱い|あつい」 is for things you touch, and 「暑い|あつい」 is for the air around you. The fever pattern is 「熱がある|ねつがある」, literally there is heat, which you also learn as its own phrase in this lesson. Japanese people usually measure fever in Celsius under the arm, so you'll hear something like 「三十八度|さんじゅうはちど」, using the counter 「〜度|〜ど」, degrees. The same kanji also shows up in 「熱心|ねっしん」, enthusiastic, a heart full of heat. To recap: fire dots at the bottom, heat in the body, a fever.",
    ja: "{子供|こども}は[熱|ねつ]があります。",
    en: "My child has a fever." },
  "せき|": {
    explain: "This is a native Japanese word, nearly always written in kana. There is a kanji, but it's rare, so don't worry about it. It's a noun, the cough itself, not the action. To say you're coughing, Japanese says the cough comes out: 「せきが出る|せきがでる」, which is its own phrase in this lesson. You can also say 「せきがひどい」, my cough is bad, when you see a doctor, along with 「のどがいたい」, sore throat, and 「熱がある|ねつがある」, I have a fever. A way to remember it: say it out loud with a sharp ending, something like seh-KEE, and it sounds a little like a dry cough clearing your throat. That's a sound-alike hook, nothing more. Watch out for other words with the same sound. 「せき」 can also be a seat, and it's the end of 「成績|せいせき」, grades, and of 「親せき|しんせき」, relatives. Those are completely different words that happen to sound alike. In Japan, when you have a cough, it's considered good manners to wear a mask in public, so you'll often see people masked up during cold season. To recap: the noun for cough, which comes out with 「出る|でる」.",
    ja: "かぜで[せき]がでます。",
    en: "I have a cough from my cold." },
  "びょうき|病気": {
    explain: "Two kanji, both with their Chinese-origin readings. 「病|びょう」 means sickness. Look at its outer frame, the shape that leans like a bed tipped on its side with dots on the left. That frame is the sickness radical, and it's often explained as a sickbed. You'll find the same 「病|びょう」 in 「病院|びょういん」, hospital, a building for the sick. The second kanji is 「気|き」, spirit, energy, the feeling in the air. It's everywhere: 「元気|げんき」, healthy and full of energy, 「天気|てんき」, weather, the feeling of the sky, and 「電気|でんき」, electricity. So 「病気|びょうき」 is sick energy, the opposite of 「元気|げんき」. Grammar tip: it's a noun, so you say 「病気です|びょうきです」, I'm sick, or 「病気になる|びょうきになる」, to get sick. A common mistake is treating it like an adjective and adding 「い」, which doesn't work. It's also a little serious. For a simple cold, people usually just say 「かぜ」, and save 「病気|びょうき」 for real illness or being sick in general. To recap: 「病|びょう」, the sickbed kanji, plus 「気|き」, energy. Sick energy.",
    ja: "{母|はは}は[病気|びょうき]です。",
    en: "My mother is sick." },
  "プレゼント|": {
    explain: "This comes from the English word present, in the sense of a gift. Watch how the sounds get squeezed into Japanese. The pr cluster needs a vowel between the letters, so pre becomes 「プレ」. In English the s in present is actually spoken as a z, and Japanese keeps that with 「ゼ」. The n stays as 「ン」, and the final t can't end a word in Japanese, so it gets an o vowel and becomes 「ト」. Put together: 「プレゼント」. The meaning is narrower than English. It's only the gift, never the present moment and never the verb to present. To give a present, you use 「あげる」 or 「もらう」, as in 「プレゼントをあげる」. It's very common for birthdays, 「誕生日|たんじょうび」, and Christmas. Japan also has a related idea, 「お土産|おみやげ」, a souvenir gift you bring back from a trip for coworkers and friends, which is almost an obligation. And there's White Day, March fourteenth, when people who received chocolates on Valentine's Day give a return present a month later. To recap: English present, the gift kind, with a z sound and an extra o at the end.",
    ja: "{彼女|かのじょ}に[プレゼント]をかいました。",
    en: "I bought a present for my girlfriend." },
  "ふつかよい|二日酔い": {
    explain: "Let's break it apart. 「二日|ふつか」 means two days or the second day of the month, with the special native reading you learned for dates, like 「三日|みっか」. Then 「酔い|よい」, the noun form of the verb 「酔う|よう」, to get drunk. Look at the left side of the kanji in 「酔い|よい」. That's the same part you see in 「お酒|おさけ」, alcohol. It's a drawing of a jar for liquor, and it shows up in lots of drinking-related kanji. So the whole thing is second-day drunkenness: you drank last night, and now on the next day you're still paying for it. It's a perfect description, honestly. The usual pattern is 「二日酔いです|ふつかよいです」, I'm hungover, or 「二日酔いになる|ふつかよいになる」. In Japan, after-work drinking parties are a big part of office culture, so this word comes up a lot, and convenience stores sell little energy drinks marketed as hangover helpers. Don't confuse it with 「にさんにち」, written 「二三日|にさんにち」, two or three days, which uses the Chinese-origin reading for the numbers. To recap: 「二日|ふつか」, the second day, plus 「酔い|よい」, drunkenness, still drunk the day after.",
    ja: "{今朝|けさ}は[二日酔い|ふつかよい]です。",
    en: "I have a hangover this morning." },
  "しけん|試験": {
    explain: "Two kanji, both with Chinese-origin readings. 「試|し」 means to try or to test. It has the speech radical on the left, the same one in many words about language, which fits: testing often means asking questions. You'll see it again in this very lesson in 「試合|しあい」, a match, where people try their strength against each other. 「験|けん」 means to check or verify, to see if something holds up. It's also in 「経験|けいけん」, experience, things you've actually checked out by living through them. So 「試験|しけん」 is trying you out and checking the results. It sounds more formal than the loanword 「テスト」. A quiz in class might be a 「テスト」, while big official exams are 「試験|しけん」. Finals are 「期末試験|きまつしけん」, the end-of-term exam. The pattern is 「試験がある|しけんがある」, there's an exam, or 「試験を受ける|しけんをうける」, to take an exam. A cultural note: Japanese university entrance exams are so intense that people have long called them exam hell, and students often buy good-luck charms at shrines before them. To recap: try, 「試|し」, plus check, 「験|けん」. Trying you out and checking.",
    ja: "あしたは[試験|しけん]があります。",
    en: "I have an exam tomorrow." },
  "インフルエンザ|": {
    explain: "This came into Japanese from Italian, not from English. In Italian, influenza means influence. Centuries ago, people in Italy thought epidemics were caused by the influence of the stars, so the disease got that name. English took the word too, and then shortened it to flu. Japanese kept the whole long form. Look at how the sounds were fitted in. The l becomes an r-like sound in 「ル」, since Japanese doesn't separate l and r. Each consonant that sits next to another one gets its own vowel, which is why it grows to seven kana. The final za sound stays as 「ザ」. In casual speech, people often shorten it themselves to 「インフル」, just like English did with flu, but they chopped off the other end. In Japan, flu season is taken seriously. Many people get a flu shot every autumn, schools sometimes close classes when too many kids are out, and wearing a mask on the train is normal. A common pattern is 「インフルエンザになる」, to come down with the flu, or 「インフルエンザで休む|インフルエンザでやすむ」, to take time off because of it. To recap: the Italian word for influence, kept whole in Japanese, often clipped to 「インフル」.",
    ja: "[インフルエンザ]で{学校|がっこう}をやすみました。",
    en: "I missed school because of the flu." },
  "かぜ|風邪": {
    explain: "This word has a fun story. The first kanji, 「風|かぜ」, means wind, and on its own it's read 「かぜ」 with its native reading. The second kanji, 「邪|じゃ」, means wicked or evil; on its own its Chinese-origin reading is 「じゃ」. So it's written as an evil wind. That idea comes from old Chinese medicine, where illnesses like colds were thought to blow into the body on a bad wind. Here's the tricky part. In this word, the two kanji together are simply read 「かぜ」. The second kanji doesn't get its 「じゃ」 sound at all; it's silent here and just adds meaning. So 「風|かぜ」, wind, and 「風邪|かぜ」, a cold, sound the same, and the writing tells you which you mean. The key pattern is 「風邪をひく|かぜをひく」, to catch a cold, literally to pull in a cold. Don't use the verb for catch a ball here. The same wind kanji also shows up with its Chinese-origin readings in words you know, like 「お風呂|おふろ」, bath, and 「台風|たいふう」, typhoon, a big wind. If you're sick with a cold, you say 「風邪です|かぜです」, and the reply might be 「お大事に|おだいじに」. To recap: an evil wind blows in, and you pull in a cold.",
    ja: "[風邪|かぜ]をひきました。",
    en: "I caught a cold." },
  "ホームシック|": {
    explain: "From the English word homesick. Look at how the sounds were fitted in. Home gets a long vowel, 「ホーム」, shown by the long dash. Sick gets a small 「ッ」 before the final sound, which gives that little catch you hear before the k, and then an extra u vowel at the end, because Japanese words don't end in a k sound. So you get 「シック」. Here's a grammar difference. In English, homesick is an adjective, I am homesick. In Japanese it's a noun, so you become it: 「ホームシックになる」, to get homesick. You might also hear 「ホームシックです」. You know 「ホーム」 from another loanword, 「ホームステイ」, a homestay with a local family, which is exactly the situation where homesickness tends to hit. A cute side note: 「ホーム」 on its own in Japanese often means a train platform, from the English word platform, so the same sounds can mean two different things. If a friend studying abroad says 「ホームシックになりました」, a kind reply is to ask about their family or suggest a video call. To recap: English homesick, made into a noun, that you become with 「になる」.",
    ja: "{留学|りゅうがく}して、[ホームシック]になりました。",
    en: "I studied abroad and got homesick." },
  "アレルギー|": {
    explain: "This word came from German, not English. The German word is Allergie, said roughly al-ler-GEE, with a hard g. That's why the Japanese version has 「ギ」 in it, while English allergy has a soft j-like sound. The sounds were fitted in the usual way. The double l becomes 「レ」 and 「ル」, since Japanese uses its r-like sound for l. The r in the middle gets its own vowel, and the long ee at the end becomes 「ギー」 with a long dash. Why German? In the late eighteen-hundreds, Japan modeled its modern medicine on Germany, so many medical words came straight from German. Another example is 「カルテ」, a patient's medical chart, from German Karte. The usual pattern is 「アレルギーがある」, to have an allergy, with the trigger in front plus 「の」: 「卵のアレルギーがある|たまごのアレルギーがある」, I'm allergic to eggs. A very common one in Japan is hay fever from cedar pollen every spring, which millions of people suffer from. People also use the word jokingly for a strong dislike, like being allergic to math. To recap: German Allergie, with its hard g, from Japan's German-influenced medicine.",
    ja: "{卵|たまご}の[アレルギー]があります。",
    en: "I have an egg allergy." },
  "ジュース|": {
    explain: "From the English word juice. The j sound at the start is 「ジュ」, and the long oo in the middle becomes a long vowel, shown by the dash. The final s sound can't end a word in Japanese, so it gets an extra u vowel and becomes 「ス」. That gives you 「ジュース」. Here's the meaning shift that surprises English speakers. In everyday Japanese, 「ジュース」 often means any sweet, cold soft drink, so a kid might call a cola or a melon soda 「ジュース」, not just fruit juice. On packaging, though, the word is strictly reserved for real one hundred percent fruit juice. Other drinks have to call themselves something else. So you'll see a big gap between the label and how people talk. Typical phrases are 「オレンジジュース」, orange juice, and 「りんごジュース」, apple juice. Japan is famous for its vending machines, and you'll find rows of juices and soft drinks on almost every street corner, hot and cold. It's a sibling to other drink loanwords you know, like 「コーヒー」, which came from Dutch koffie. To recap: English juice, but in casual Japanese it stretches to cover sweet soft drinks too.",
    ja: "{朝|あさ}、オレンジ[ジュース]を{飲みます|のみます}。",
    en: "I drink orange juice in the morning." },
  "たまご|卵": {
    explain: "This is a native Japanese word, using the native reading 「たまご」. The kanji 「卵|たまご」 is used for eggs of all kinds, chicken eggs, fish eggs, frog eggs. A way to remember the shape: it looks like two rounded halves side by side, each with a little dot inside, like two eggs with yolks. That's a hook, not the kanji's history. There's a second common spelling, 「玉子|たまご」, which you'll often see on menus and food packaging for cooked eggs. Here 「玉|たま」 means a ball or something round, and 「子|ご」 is child, the same kanji as in 「子供|こども」, but softened to 「ご」. So that spelling reads as little round child, which matches the sound nicely. In grammar it works like any noun: 「卵を食べる|たまごをたべる」, to eat eggs. A fun cultural note: a very popular simple breakfast in Japan is 「卵かけご飯|たまごかけごはん」, a raw egg cracked over hot rice with a little soy sauce. Japanese eggs are produced to be safe to eat raw, so this is normal there. It sits next to 「ご飯|ごはん」, rice or meal, from your vocab. To recap: the native word for egg, written 「卵|たまご」, or as round ball child for cooked ones.",
    ja: "{毎朝|まいあさ}[卵|たまご]を{食べます|たべます}。",
    en: "I eat eggs every morning." },
  "ふく|服": {
    explain: "This kanji uses its Chinese-origin reading, 「ふく」, even standing alone, which is a little unusual for a one-kanji word. It's the general word for clothes, what you wear on your body. The verb that goes with it is 「着る|きる」, to wear on the upper body or the whole body, so you say 「服を着る|ふくをきる」, to put on clothes. Don't confuse it with 「着物|きもの」. That word is built from 「着|き」, wearing, and 「物|もの」, thing, so it originally meant simply things you wear, but today it means traditional Japanese dress, the kimono. In contrast, Western-style clothes are 「洋服|ようふく」, where 「洋|よう」 means ocean, standing for the lands across the ocean, the West. Traditional clothing in general is 「和服|わふく」, where 「和|わ」 means Japanese. Both share 「服|ふく」. A cultural note: Japanese schools often have uniforms, called 「制服|せいふく」, again with the same kanji, and many company workers wear a suit almost like a uniform too. A common mistake: 「服|ふく」 is clothing in general, so to name a specific item, use its own word, like 「シャツ」, a shirt, or 「ぼうし」, a hat. To recap: the general word for clothes, read 「ふく」, found inside lots of clothing words.",
    ja: "あたらしい[服|ふく]をかいました。",
    en: "I bought new clothes." },
  "もの|物": {
    explain: "This is the native reading, 「もの」, a thing you can touch, a physical object. Look at the left side of the kanji. That's the cow radical, the same piece that sits on the left of a lot of animal-related characters. A way to remember it: picture a cow as the most basic valuable thing a farmer owns. That's a hook, not the official history. The real anchor is the family of words you already know, because 「物|もの」 sits at the end of so many of them. 「食べ物|たべもの」 is eating things, food. 「飲み物|のみもの」 is drinking things, drinks. 「買い物|かいもの」 is buying things, shopping. 「着物|きもの」 is wearing things, a kimono. And 「果物|くだもの」, fruit, uses it too. Then with its Chinese-origin readings, you see it in 「動物園|どうぶつえん」, the zoo, a garden of moving things, and in 「荷物|にもつ」, baggage. Here's a key point for English speakers. Japanese splits thing into two words. 「もの」 is for concrete objects, while 「こと」 is for abstract things, like events, facts, or ideas. You can see 「こと」's kanji in 「用事|ようじ」, things to do. To recap: 「もの」, a concrete thing, the ending of food, drinks, and shopping.",
    ja: "{日本|にほん}でいろいろな[物|もの]をかいました。",
    en: "I bought various things in Japan." },
  "きっぷ|切符": {
    explain: "Two kanji. 「切|きっ」 is the cutting kanji, the same one as in 「切る|きる」, to cut, and here it's squeezed down to 「きっ」 with a small 「っ」. You also know it from 「親切|しんせつ」, kind, and 「締め切り|しめきり」, a deadline, literally the point where things are cut off. The second kanji, 「符|ぷ」, means a token or tally, a little marker that proves something. Its reading is 「ふ」, but after the small 「っ」 it hardens to 「ぷ」. Notice the bamboo radical on top: long ago, tallies were made from strips of bamboo. Put together, 「切符|きっぷ」 is a cut-off token, a slip of paper that proves you paid. A cultural note: for decades, station staff stood at the ticket gates and punched or clipped every passenger's ticket by hand with special clippers. Today automatic gates swallow the ticket, and many people use rechargeable IC cards instead. You'd still buy a 「切符|きっぷ」 for a long trip or the bullet train. It's mostly for train, bus, and event tickets. A related word is 「切手|きって」, a postage stamp, with the same 「切|きっ」. To recap: the cutting kanji plus a token, a cut slip that proves you paid.",
    ja: "{駅|えき}で[切符|きっぷ]をかいました。",
    en: "I bought a ticket at the station." },
  "〜だい|〜代": {
    explain: "This is a suffix, so it attaches to the end of a noun to mean the charge or fee for that thing. It uses its Chinese-origin reading, 「だい」. The pattern is very simple: the thing you pay for plus 「代|だい」. 「電話代|でんわだい」 is the phone bill, from 「電話|でんわ」, telephone. 「電気代|でんきだい」 is the electricity bill, from 「電気|でんき」. 「バス代|バスだい」 is bus fare. You can even say 「本代|ほんだい」, money spent on books. It's very handy in daily life when you talk about bills and expenses, and you can make your own combinations. The same kanji has another big meaning: generation or a span of time. You'll hear 「二十代|にじゅうだい」, in one's twenties, and 「時代|じだい」, an era. A way to remember both meanings: the native reading of this kanji is in 「代わりに|かわりに」, instead of, in exchange. A fee is what you hand over in exchange for something, and a generation is one group taking the place of another. That's a memory hook, not a history lesson. Don't confuse it with the counter 「〜台|〜だい」 for machines, which sounds the same. To recap: put 「代|だい」 after a noun, and it becomes the fee for it.",
    ja: "{電話|でんわ}[代|だい|〜だい]がたかいです。",
    en: "My phone bill is expensive." },
  "ようじ|用事": {
    explain: "Two kanji with their Chinese-origin readings. 「用|よう」 means use, purpose, or business to do. 「事|じ」 means thing or matter, the abstract kind of thing, not an object you can hold. So 「用事|ようじ」 is a matter of business, something you have to take care of: an errand, an appointment, a task. The second kanji is worth tracking, because it shows up in lots of words you know with different readings. In 「仕事|しごと」, a job, it's read 「ごと」. In 「返事|へんじ」, a reply, and in 「お大事に|おだいじに」, get well soon, it's 「じ」 again, just like here. The usual pattern is 「用事がある|ようじがある」, I have something to do. And here's the cultural part. Japanese people often turn down invitations politely by saying something vague like 「ちょっと用事があって|ちょっとようじがあって」, I have a little something to take care of, and then trailing off. Nobody asks what the errand is. It's a gentle, face-saving no, and it's useful for you too. A mistake to avoid: don't use it for a full-time job, which is 「仕事|しごと」. To recap: a matter of use, 「用|よう」, plus thing, 「事|じ」. Something you have to do.",
    ja: "あしたは[用事|ようじ]があります。",
    en: "I have things to take care of tomorrow." },
  "おてあらい|お手洗い": {
    explain: "Three pieces. First, the polite 「お」. Then 「手|て」, hand, with its native reading. Then 「洗い|あらい」, from the verb 「洗う|あらう」, to wash. Literally it's the honorable hand washing, the place where you wash your hands. It's a gentle, indirect way to name the restroom without saying what you actually do there, a lot like English speakers say bathroom or washroom. 「手|て」 is in many words you know: 「手紙|てがみ」, a letter, paper by hand, and 「手伝う|てつだう」, to help, lending a hand. The washing kanji also appears in 「洗濯する|せんたくする」, to do laundry, with its Chinese-origin reading 「せん」. On politeness: 「トイレ」, from English toilet, is the neutral everyday word and is perfectly fine. 「お手洗い|おてあらい」 is a step politer, good for asking a stranger, a shopkeeper, or your teacher. In department stores and hotels you might also see signs with an even fancier word, the powder room. The classic question is 「お手洗いはどこですか|おてあらいはどこですか」, where's the restroom. To recap: polite 「お」, hand, washing: the place where you wash your hands.",
    ja: "[お手洗い|おてあらい]はどこですか。",
    en: "Where is the restroom?" },
  "しあい|試合": {
    explain: "Two kanji, with an unusual mix of readings. 「試|し」 uses its Chinese-origin reading and means to try or test. It's the same kanji as in 「試験|しけん」, an exam, from this same lesson. 「合|あい」 uses its native reading and comes from the verb 「合う|あう」, to fit together, to match, to come together. You've seen 「合う|あう」 in 「似合う|にあう」, to look good on someone, when clothes fit you, and 「付き合う|つきあう」, to go out with someone, keeping each other company. So 「試合|しあい」 is two sides coming together to try their strength. It's used for sports and competitions with an opponent: soccer, baseball, tennis, judo. Two verbs to pair with it are 「勝つ|かつ」, to win, and 「負ける|まける」, to lose. A typical pattern is 「試合がある|しあいがある」, there's a game, or 「試合を見る|しあいをみる」, to watch a game. A common mistake for English speakers is using it for game in the sense of a video game or board game. That's 「ゲーム」. 「試合|しあい」 is a match against someone. A cultural note: Japan's high school baseball tournament at Koshien is huge, and the whole country watches. To recap: trying, 「試|し」, plus coming together, 「合|あい」. A match.",
    ja: "あした、サッカーの[試合|しあい]があります。",
    en: "There is a soccer match tomorrow." },
  "せいじ|政治": {
    explain: "Two kanji, both with Chinese-origin readings. 「政|せい」 means government or governing affairs. 「治|じ」 means to rule, to manage, to bring under control. The same kanji with a native reading also gives the verb 「治る|なおる」, to heal or get better, A way to remember it: governing a country well is a bit like keeping a body healthy. Together, 「政治|せいじ」 is the business of governing, politics. A great sibling here is 「政治家|せいじか」, a politician. You know 「家|か」 from 「漫画家|まんがか」, cartoonist, and 「作家|さっか」, writer: the person whose profession it is. So a politician is a professional of politics. You'll also see 「治|じ」 in the name of the Meiji era, 「明治|めいじ」, which means enlightened rule. That was the period when Japan modernized in the late eighteen-hundreds. The usual pattern in this lesson is 「政治にきょうみがある|せいじにきょうみがある」, to be interested in politics, with 「に」 marking what you're interested in. Politics is also connected to 「大統領|だいとうりょう」, a president of a country. To recap: government, 「政|せい」, plus rule, 「治|じ」. The business of governing.",
    ja: "[政治|せいじ]にきょうみがあります。",
    en: "I am interested in politics." },
  "せいせき|成績": {
    explain: "Two kanji with Chinese-origin readings. 「成|せい」 means to become, to accomplish, to complete. 「績|せき」 means achievement, the results you pile up. Look at its left side: that's the thread radical, the same one in many fabric and string kanji. The old meaning of this kanji was spinning thread, twisting fibers together little by little. A way to remember it: your grades are like thread you spin bit by bit all semester, and at the end you have a whole spool of results. So 「成績|せいせき」 is accomplished results, your grades or overall performance. It's often your record over a term or a year, not just a single score on one test, though people use it for test results too. The patterns are 「成績がいい|せいせきがいい」, good grades, and 「成績が悪い|せいせきがわるい」, bad grades. Notice it uses 「が」, because it's describing the grades. A cultural note: Japanese students get a report card at the end of each term, and some kids dread bringing it home before summer vacation. Be careful: 「せき」 at the end sounds like 「せき」, cough, from this lesson, but it's a totally different word. To recap: accomplished results, spun up bit by bit. Your grades.",
    ja: "[成績|せいせき]がよかったです。",
    en: "My grades were good." },
  "かのじょ|彼女": {
    explain: "Two kanji. 「彼|かの」 is an old word for that, the far-away that, just like the modern 「あの」. 「女|じょ」 means woman, using its Chinese-origin reading here. You know the native reading in 「女の人|おんなのひと」. So 「彼女|かのじょ」 is literally that woman. Here's a neat bit of history. Before the late eighteen-hundreds, Japanese didn't really have a word for she. When Japanese writers began translating European novels, they needed one, so this word was put to use for she. It took a while to feel natural in everyday speech. Today it has two meanings. It can be she, a woman being talked about, or girlfriend. In conversation, girlfriend is extremely common: 「彼女がいる|かのじょがいる」 means I have a girlfriend. A common mistake for English speakers is using it all the time for she, like in English. Japanese usually just uses the person's name plus 「さん」, or skips the subject entirely. Saying 「彼女|かのじょ」 about your boss or teacher can sound distant or odd. Its partner word is 「彼|かれ」, he or boyfriend. To recap: that woman, she, and very often your girlfriend.",
    ja: "[彼女|かのじょ]はやさしいです。",
    en: "She is kind." },
  "かれ|彼": {
    explain: "This uses the native reading 「かれ」. Long ago, 「かれ」 meant that one over there, pointing at a person or thing far away, and it could be used for anyone, man or woman. It's part of the same far-away family as 「あれ」, that over there. When Japanese writers began translating European languages in the late eighteen-hundreds, they used 「彼|かれ」 for he, and the separate word 「彼女|かのじょ」, that woman, was used for she. So now 「彼|かれ」 is mainly for men. Like its partner, it has two meanings: he, and boyfriend. In conversation, 「彼|かれ」 alone is often heard as my boyfriend, though 「彼氏|かれし」 is clearer. Here's the big tip for English speakers. Japanese doesn't use he nearly as much as English does. It's normal to just use the person's name, 「田中さん|たなかさん」, or leave the subject out when everyone knows who you mean. Using 「彼|かれ」 for someone older or higher in status, like your teacher, sounds too casual and distant. The left side of the kanji is the step radical, the one for going or walking somewhere. A way to remember it: he's the guy who walked over there. That's a hook. To recap: that one over there, now he or boyfriend.",
    ja: "[彼|かれ]は{大学生|だいがくせい}です。",
    en: "He is a college student." },
  "かれし|彼氏": {
    explain: "Two kanji. 「彼|かれ」 is he or that one over there. 「氏|し」 is a title used after a person's name, a lot like Mister in formal writing. You'll see it in newspapers, where someone is called their family name plus 「氏|し」. Put them together, and 「彼氏|かれし」 is like Mister He. It started as a playful, jokey word in the early twentieth century and stuck. Today it's the clear, everyday word for boyfriend. Why is it useful? 「彼|かれ」 alone can mean he or boyfriend, so it can be ambiguous. 「彼氏|かれし」 only means boyfriend, never just he. Its partner is 「彼女|かのじょ」, which does double duty for she and girlfriend. The usual patterns are 「彼氏がいる|かれしがいる」, to have a boyfriend, and in this lesson 「彼氏と別れる|かれしとわかれる」, to break up with a boyfriend, using 「と」 for with. To recap: he plus a Mister title. Mister He is your boyfriend.",
    ja: "[彼氏|かれし]とえいがを{見ました|みました}。",
    en: "I watched a movie with my boyfriend." },
  "いみ|意味": {
    explain: "Two kanji with Chinese-origin readings. Look at the first one, 「意|い」. It's built from two pieces you can see: 「音|おと」, sound, stacked on top of 「心|こころ」, heart or mind. A way to remember it: the sound of your heart, what you really have in mind. Its meaning is intention, will, what's in your mind. You'll see it again in 「注意する|ちゅういする」, to watch out, literally to pour your mind onto something. The second kanji is 「味|み」, taste or flavor. With its native reading it's 「味|あじ」, the flavor of food, and it has the mouth radical on the left. It's also in 「興味|きょうみ」, interest, from this same lesson. So 「意味|いみ」 is the flavor of what's in someone's mind, the meaning behind their words. The handiest question you can learn is 「どういう意味ですか|どういういみですか」, what does that mean, or 「この言葉の意味は何ですか|このことばのいみはなんですか」, what does this word mean. Another useful phrase is 「意味がない|いみがない」, it's pointless, literally there's no meaning. To recap: the mind's intention, 「意|い」, plus taste, 「味|み」. The flavor of what someone means.",
    ja: "このことばの[意味|いみ]はなんですか。",
    en: "What is the meaning of this word?" },
  "せまい|狭い": {
    explain: "This is an i-adjective with the native reading 「せまい」. It means a space is cramped, tight, narrow, not roomy. Its opposite is 「広い|ひろい」, wide or spacious, also in this lesson. Look at the right side of the kanji. It's the same piece found in 「挟む|はさむ」, to squeeze something between two things. That's a good picture: a narrow space squeezes you in on both sides. Here's the important tip for English speakers. When a room or an apartment is small, Japanese usually says 「狭い|せまい」, not 「小さい|ちいさい」. 「小さい|ちいさい」 is about the size of an object, like a small box or a small dog. 「狭い|せまい」 is about how little space there is to move around in. So 「部屋が狭い|へやがせまい」, my room is cramped, is the natural thing to say. It also works for roads, 「道が狭い|みちがせまい」, a narrow street, which you'll see a lot in older Japanese neighborhoods. A cultural note: apartments in big Japanese cities like Tokyo are famously compact, so you'll hear this word often. Some one-room places are so tight you can almost touch both walls. There's also a phrase for narrow-minded: a narrow heart. To recap: squeezed in on both sides. Cramped, not roomy.",
    ja: "わたしのへやは[狭い|せまい]です。",
    en: "My room is small." },
  "ひろい|広い": {
    explain: "An i-adjective with the native reading 「ひろい」. It means wide or spacious, lots of room to move around. Its opposite is 「狭い|せまい」, cramped, from this same lesson. Look at the kanji. The outer part, the dot and the line with a long sweep down the left, is a radical that represents a building with a roof. You'll see it in other kanji for buildings and shops. A way to remember it: a big building with a wide roof, plenty of room inside. That's a hook built from the shape. With its Chinese-origin reading 「こう」, the same kanji appears in 「広告|こうこく」, an advertisement, which you know from your vocab: an announcement spread out widely to everyone. The city name 「広島|ひろしま」, Hiroshima, also uses it, meaning wide island. Like 「狭い|せまい」, it's used for spaces, not for the size of objects. So 「部屋が広い|へやがひろい」 is a roomy room, and 「この公園は広い|このこうえんはひろい」 is a big, spacious park. It also works for wide streets and broad knowledge. There's even a phrase for generous: a wide heart. A common mistake is using 「大きい|おおきい」, big, for a spacious room. That sounds odd. To recap: a wide roof, lots of room. Spacious.",
    ja: "このこうえんは[広い|ひろい]です。",
    en: "This park is spacious." },
  "わるい|悪い": {
    explain: "An i-adjective with the native reading 「わるい」, and the opposite of 「いい」, good. Look at the kanji. The bottom is 「心|こころ」, heart. A way to remember it: something sitting on top of your heart and weighing it down, a bad feeling. That's a hook from the shape. You'll see 「悪い|わるい」 in lots of everyday phrases. 「天気が悪い|てんきがわるい」 is bad weather. 「成績が悪い|せいせきがわるい」 is bad grades. And 「気分が悪い|きぶんがわるい」 means to feel sick, literally my feeling is bad, which is a great phrase for this lesson about illness. Here's a cool usage English speakers don't expect. In casual speech, 「悪い|わるい」 or 「悪いね|わるいね」 can mean sorry, my bad, or thanks for the trouble. It's a quick, friendly apology among friends, mostly used by men, and too casual for your teacher. The negative 「悪くない|わるくない」, not bad, works much like in English. Conjugation is the regular i-adjective pattern: 「悪かった|わるかった」, it was bad. Note that unlike 「いい」, which becomes 「よかった」, 「悪い|わるい」 has no irregular forms. To recap: a weight on the heart, the opposite of good. Bad.",
    ja: "{天気|てんき}が[悪い|わるい]です。",
    en: "The weather is bad." },
  "いたい|痛い": {
    explain: "An i-adjective with the native reading 「いたい」, for something that hurts. Look at the kanji. The outer frame, leaning like a bed on its side with dots on the left, is the sickness radical. You know it from 「病気|びょうき」, illness, and 「病院|びょういん」, hospital. So this kanji lives in the family of sickness and pain words. The key grammar pattern is body part plus 「が」 plus 「痛い|いたい」. 「頭が痛い|あたまがいたい」 is a headache, my head hurts. 「おなかが痛い|おなかがいたい」 is a stomachache. 「歯が痛い|はがいたい」 is a toothache. 「のどが痛い|のどがいたい」 is a sore throat. A common mistake for English speakers is trying to say I have a pain. Japanese just says the body part hurts. In real life, when you stub your toe or bump your head, people shout it as a reflex, often chopped short to 「いたっ」, ouch. There's also a modern slang use: calling someone or something 「いたい」 means cringe, painfully embarrassing to watch, and it's often written in katakana for that meaning. To recap: the sickness radical, and body part plus 「が痛い|がいたい」. It hurts.",
    ja: "{頭|あたま}が[痛い|いたい]です。",
    en: "I have a headache." },
  "あまい|甘い": {
    explain: "An i-adjective with the native reading 「あまい」. Look at the kanji: it's traditionally explained as a mouth with something held inside it, a line in the middle of an open shape, like a tasty thing you keep in your mouth to enjoy. Its core meaning is sweet, the taste of sugar, like 「お菓子|おかし」, snacks and sweets, and 「ケーキ」. 「甘い物|あまいもの」 is sweet stuff, desserts. You know 「物|もの」, thing, from this lesson. Someone with a sweet tooth is called 「甘党|あまとう」, a member of the sweet party. Then there's the meaning that surprises English speakers. 「甘い|あまい」 can also mean too lenient, too soft on someone. A parent who spoils their kids is 「子供に甘い|こどもにあまい」, sweet toward the children. And if your plan is naive or your guess is too optimistic, someone might say it's 「甘い|あまい」, you're being too easy on yourself. There's a related verb 「甘える|あまえる」, to act like a spoiled child and depend on someone's kindness, a very Japanese idea about relationships. It can also describe a sweet voice or a sweet smell. To recap: something tasty held in the mouth. Sweet, and sometimes too soft.",
    ja: "このケーキは[甘い|あまい]です。",
    en: "This cake is sweet." },
  "おおい|多い": {
    explain: "An i-adjective with the native reading 「おおい」. Look at the kanji. A way to remember it: it looks like two copies of 「夕|ゆう」, evening, stacked on top of each other, as if evenings were piling up into many. That's a hook from the shape, not the kanji's real history. With its Chinese-origin reading 「た」, the same kanji is in 「多分|たぶん」, probably, from this lesson: a large share, so most likely. Here's the big grammar tip, and it trips up almost every English speaker. 「多い|おおい」 is used as a predicate, at the end of a sentence: 「東京は人が多い|とうきょうはひとがおおい」, Tokyo has a lot of people, literally in Tokyo, people are many. But you usually can't put it straight in front of a noun the way you'd say many people in English. Saying 「多い人|おおいひと」 sounds wrong. Instead, use 「たくさんの」, as in 「たくさんの人|たくさんのひと」, many people. The pattern is place or topic plus 「は」, then thing plus 「が多い|がおおい」. You can say 「宿題が多い|しゅくだいがおおい」, there's a lot of homework. Its opposite is 「少ない|すくない」, few. To recap: many, but used at the end, in the pattern something 「が多い|がおおい」.",
    ja: "{東京|とうきょう}は{人|ひと}が[多い|おおい]です。",
    en: "There are many people in Tokyo." },
  "すてき|素敵": {
    explain: "This is a na-adjective, a warm, slightly elegant compliment. You'll often hear it as 「すてきですね」, how lovely, or 「すてきな服|すてきなふく」, lovely clothes. The kanji are interesting. 「素|す」 means plain or natural, and 「敵|てき」 actually means enemy. Obviously nice has nothing to do with an enemy. These kanji were chosen mainly for their sounds, not their meanings, a practice Japanese uses for some words. So don't try to build the meaning from the pieces. That's also why the word is very often written in kana. A way to remember it: picture someone saying it with stars in their eyes, looking at a beautiful dress or a sweet gift. That's a hook. How does it differ from 「いい」? 「いい」 is plain good. 「すてき」 adds a touch of charm and admiration, like lovely or wonderful. It's great for complimenting someone's clothes, a nice café, a beautiful view, or a person's personality. A common mistake is to use it for something merely functional, like a good price. That's just 「いい」 or 「安い|やすい」. You'll hear it used by everyone, though it has a slightly soft, refined feel. To recap: written with sound-only kanji, used to praise something lovely.",
    ja: "[素敵|すてき]な{服|ふく}ですね。",
    en: "What nice clothes!" },
  "あるく|歩く": {
    explain: "A verb with the native reading 「あるく」. It's a u-verb, so the forms are 「歩きます|あるきます」 and the te-form 「歩いて|あるいて」. You already know 「歩いて|あるいて」 as on foot, as in 「歩いて行く|あるいていく」, to go on foot. Look at the kanji. The top part, 「止|し」, is an old drawing of a foot. The bottom part is also a foot, turned around. So the kanji shows two footprints, one stepping in front of the other: walking. Feet show up in other kanji too, like 「足|あし」, leg or foot, from this same lesson. Its faster sibling verb is 「走る|はしる」, to run. With its Chinese-origin reading 「ほ」 or 「ぽ」, the same kanji is in 「散歩|さんぽ」, a stroll, like walking the dog. Grammar tip: when you walk along a path, use 「を」, not 「に」. So 「道を歩く|みちをあるく」, to walk along the road, or 「公園を歩く|こうえんをあるく」, to walk through the park. The 「を」 marks the space you move through. A cultural note: Japanese cities are very walkable, and it's common to walk ten or fifteen minutes to the station every day. To recap: two footprints, one in front of the other. To walk.",
    ja: "{駅|えき}まで[歩きます|あるきます|あるく]。",
    en: "I walk to the station." },
  "ねつがある|熱がある": {
    explain: "This is a set phrase built from two parts you know. 「熱|ねつ」 is heat or fever, the kanji with the fire dots at the bottom. 「ある」 is the verb for things existing, there is. So literally, there is heat. That's how Japanese says I have a fever. The pattern is the same one you use for lots of things in this lesson. 「用事がある|ようじがある」, there's an errand, I have something to do. 「興味がある|きょうみがある」, there's interest, I'm interested. 「アレルギーがある」, I have an allergy. Japanese often uses 「ある」 for having things, especially abstract ones. A common mistake for English speakers is trying to translate have directly with the verb for holding. Just remember: there is heat. You'll also hear 「熱が出る|ねつがでる」, a fever comes out, for when a fever starts, and 「熱が下がる|ねつがさがる」, the fever goes down. To ask someone, say 「熱がありますか|ねつがありますか」, do you have a fever. In Japan, a temperature of thirty-seven point five degrees Celsius or higher is often the line for staying home from school or work. To recap: fever plus 「ある」. There is heat, so you have a fever.",
    ja: "{今日|きょう}は[熱があります|ねつがあります|ねつがある]。",
    en: "I have a fever today." },
  "のどがかわく|喉が渇く": {
    explain: "A phrase with two pieces. 「喉|のど」 is throat, written with the mouth radical on the left. 「渇く|かわく」 is to become dry, especially from thirst. Look at its left side: those three short strokes are the water radical. So it's a water kanji about water running out. Together, my throat becomes dry, which is how Japanese says I'm thirsty. Here's the grammar twist. Because 「渇く|かわく」 describes a change, becoming dry, you usually put it in the past to say you're thirsty right now: 「のどがかわきました」 or casually 「のどがかわいた」. It means my throat has gotten dry, so I'm thirsty now. Saying the present form 「かわきます」 sounds like it will get dry later. English speakers often make that mistake. It's just like 「おなかがすく」, to get hungry, where you say 「おなかがすきました」 to mean I'm hungry. These two phrases are a matched pair. One more thing: there's another kanji for the same verb, 「乾く|かわく」, used for things drying out, like laundry. Don't confuse them in writing; the thirsty one is the water radical version. To recap: the throat dries out, and you say it in the past to mean you're thirsty now.",
    ja: "[喉が渇きました|のどがかわきました|のどがかわく]。みずをください。",
    en: "I am thirsty. Water, please." },
  "はらう|払う": {
    explain: "A u-verb with the native reading 「はらう」. Look at the kanji. The left side is the hand radical, the same one in tons of action kanji. A way to remember it: picture your hand sweeping money across the counter. That's a hook. In fact the verb's broader meaning is to sweep away or brush off, like brushing dust off your clothes, and you can think of paying as clearing away what you owe. Watch the forms: 「払います|はらいます」, polite, and 「払って|はらって」, te-form. The usual patterns are 「お金を払う|おかねをはらう」, to pay money, with 「を」 for what you pay, and 「カードで払う|カードではらう」, to pay by card, with 「で」 for the means. You'll also hear 「現金で払う|げんきんではらう」, to pay in cash. A cultural note: Japan has long been a cash-heavy country, though cards and phone payments are now common. And there's no tipping. In shops you often put your money on a little tray instead of handing it over directly. A useful related word is 「〜代|〜だい」, the fee, from this lesson: 「電話代を払う|でんわだいをはらう」, to pay the phone bill. To recap: a hand sweeping money over. To pay.",
    ja: "カードで[払います|はらいます|はらう]。",
    en: "I will pay by card." },
  "なくす|": {
    explain: "A u-verb, usually written in kana. It means to lose something you had, like a wallet, keys, or a ticket. Look at the sound: it starts with 「ない」, not exist. It's related to that idea: you make something not be there anymore. That makes it easy to remember. It's the active, transitive verb, meaning someone loses something, so it takes 「を」: 「さいふをなくす」, to lose your wallet, or 「切符をなくしました|きっぷをなくしました」, I lost my ticket. There's a matching verb 「なくなる」, to disappear or run out, where the thing itself goes missing. For example, 「お金がなくなった|おかねがなくなった」, the money ran out. Here's a big mistake for English speakers. In English, lose also means losing a game. In Japanese, that's a totally different verb, 「負ける|まける」. You'd never use 「なくす」 for losing a match or 「試合|しあい」. Also, for getting lost on the way somewhere, use 「道に迷う|みちにまよう」, which you know. A cultural note: Japan is famous for returning lost items. People hand in lost wallets at the police box, often with all the cash still inside. To recap: make something not be there. To lose an item.",
    ja: "さいふを[なくしました|なくしました|なくす]。",
    en: "I lost my wallet." },
  "きょうみがある|興味がある": {
    explain: "Two pieces. 「興味|きょうみ」 is interest, and 「ある」 is there is. So literally, there is interest. Let's break 「興味|きょうみ」 apart. 「興|きょう」 means to rise up, to get excited or stirred up. 「味|み」 means taste, the same kanji as 「味|あじ」, flavor, and the one in 「意味|いみ」, meaning, from this lesson. So interest is a taste for something rising up in you. That's a nice way to picture it. The grammar pattern is very important: the thing you're interested in takes 「に」. So 「日本に興味がある|にほんにきょうみがある」, I'm interested in Japan, or 「政治に興味があります|せいじにきょうみがあります」, I'm interested in politics. A common mistake for English speakers is using 「が」 or 「を」 for the topic of interest. It's always 「に」. To say not interested, use 「興味がない|きょうみがない」. It's in the same family of 「ある」 phrases as 「熱がある|ねつがある」, have a fever, and 「用事がある|ようじがある」, have something to do. It's a slightly more serious, thoughtful phrase than 「好き|すき」, to like. You might be interested in history without loving it. To recap: a taste rising up, and you put the topic before 「に」.",
    ja: "{政治|せいじ}に[興味があります|きょうみがあります|きょうみがある]。",
    en: "I am interested in politics." },
  "せきがでる|せきが出る": {
    explain: "A set phrase with two parts. 「せき」 is a cough, the native word usually written in kana. 「出る|でる」 is to come out, the same verb you know from 「出かける|でかける」, to go out, and its partner 「出す|だす」, to take something out or hand it in. So literally, a cough comes out. That's the natural Japanese way to say I'm coughing. Notice the cough is the subject, marked with 「が」, and it comes out on its own. You're not doing the coughing on purpose, it just happens to you. Japanese often describes symptoms this way. Compare 「熱が出る|ねつがでる」, a fever comes out, meaning a fever starts. Since 「出る|でる」 is a ru-verb, the forms are easy: 「せきが出ます|せきがでます」 and 「せきが出て|せきがでて」. A typical sentence to a doctor would be 「せきが出て、のどが痛いです|せきがでて、のどがいたいです」, I'm coughing and my throat hurts. A common mistake for English speakers is trying to turn cough into a verb with 「する」. You may hear that sometimes, but 「せきが出る|せきがでる」 is much more natural. A quick cultural note: if you cough in public in Japan, it's polite to wear a mask. To recap: the cough comes out on its own.",
    ja: "かぜで[せきが出ます|せきがでます|せきがでる]。",
    en: "I am coughing because of a cold." },
  "わかれる|別れる": {
    explain: "A ru-verb with the native reading 「わかれる」. The kanji 「別|べつ」 means separate or different. With its Chinese-origin reading 「べつ」, you know it from 「別に|べつに」, not particularly, nothing special, which is a separate matter. You may also know 「別々|べつべつ」, separately, like when you split the bill. So 「別れる|わかれる」 is to become separate. It has two main uses. Two people parting ways after meeting, like saying goodbye at a station. And couples breaking up. The partner is marked with 「と」: 「彼氏と別れた|かれしとわかれた」, I broke up with my boyfriend. A common mistake: English says broke up with, but Japanese uses 「と」, together with, not 「を」. Both people separate from each other. There's a sound-alike to watch out for. 「分かれる|わかれる」, written with the dividing kanji, means a road or a group splits into parts. Same sound, different kanji. A way to remember it: 「分かる|わかる」, to understand, sounds the same at the start. Picture understanding as splitting a problem apart into clear pieces. That's a hook. And the polite goodbye 「さようなら」 is often said at a parting. To recap: the separate kanji, two people becoming separate.",
    ja: "{彼氏|かれし}と[別れました|わかれました|わかれる]。",
    en: "I broke up with my boyfriend." },
  "きんちょうする|緊張する": {
    explain: "Two kanji with Chinese-origin readings, plus 「する」. 「緊|きん」 means tight or tense. Look at the bottom of it: that's the thread radical, like a string pulled tight. 「張|ちょう」 means to stretch, to pull out. Its left side is the bow radical, as in a bow and arrow. Picture drawing back a bowstring until it's stretched taut. So 「緊張|きんちょう」 is pulled tight and stretched: tension. When you're nervous, your body and mind feel exactly like that string. A great sibling word is 「頑張る|がんばる」, to do your best, which uses the same stretching kanji with a native reading. When you 「頑張る|がんばる」, you stretch yourself. The verb is 「緊張する|きんちょうする」, and it's often used in the past for how you felt: 「緊張しました|きんちょうしました」, I was nervous. It fits right before a 「試験|しけん」, an exam, a 「試合|しあい」, a match, a speech, or a first date. A common mistake: Japanese doesn't use the word for worried here; 「心配する|しんぱいする」 is about worrying over something, while 「緊張する|きんちょうする」 is the jittery, tense feeling in the moment. A cultural note: people often encourage each other with 「頑張って|がんばって」 right before something nerve-wracking. To recap: tight plus stretched. Tense, like a bowstring.",
    ja: "{試験|しけん}のまえに[緊張しました|きんちょうしました|きんちょうする]。",
    en: "I got nervous before the exam." },
  "しんぱいする|心配する": {
    explain: "Two kanji with Chinese-origin readings, plus 「する」. 「心|しん」 is heart or mind. With its native reading it's 「心|こころ」, which you'll hear in songs and stories. 「配|ぱい」 means to distribute, to hand out, to pay attention to. On its own its reading is 「はい」, but after the 「ん」 it hardens to 「ぱい」. So 「心配|しんぱい」 is spreading your heart out over something, giving your attention and feelings to it, which is what worrying is. The person or thing you worry about is marked with 「を」: 「母を心配する|ははをしんぱいする」, to worry about my mother. Or use 「が心配です|がしんぱいです」 to say something is a worry: 「試験が心配です|しけんがしんぱいです」, I'm worried about the exam. Two phrases you'll use constantly are 「心配しないで|しんぱいしないで」, don't worry, and the more formal 「ご心配なく|ごしんぱいなく」, please don't worry. A common mix-up is with 「緊張する|きんちょうする」, to get nervous. That's the tense feeling in the moment. 「心配する|しんぱいする」 is worrying about something that might go wrong. And remember 「大丈夫|だいじょうぶ」, it's okay, which is the natural answer when someone worries about you. To recap: heart, 「心|しん」, spread out over something. To worry.",
    ja: "{母|はは}はいつも[心配します|しんぱいします|しんぱいする]。",
    en: "My mother always worries." },
  "おだいじに|お大事に": {
    explain: "A set phrase. The core is 「大事|だいじ」, important or precious. Its pieces are 「大|だい」, big, like in 「大学|だいがく」 and 「大丈夫|だいじょうぶ」, and 「事|じ」, matter or thing, like in 「用事|ようじ」 and 「返事|へんじ」. So 「大事|だいじ」 is a big matter, something important. Add polite 「お」 in front and the particle 「に」 at the end, which turns it into how to treat something. The full idea is please treat yourself as precious, please take good care. It's what you say to someone who is sick or injured. In English we'd say get well soon or take care. You'll hear it everywhere around illness. Doctors and pharmacists in Japan say it at the end of every visit, as you leave with your medicine. Friends say it when you mention a cold. It's polite enough for anyone, and you can add 「どうぞ」 in front for extra warmth. A common mistake for English speakers is to use it as a general goodbye, like take care on any normal day. It's only for when someone is unwell. Also, you don't say it about yourself. Typical exchange: 「風邪をひきました|かぜをひきました」, I caught a cold, and the reply is 「お大事に|おだいじに」. To recap: treat yourself as precious. Get well soon.",
    ja: "かぜですか。[お大事に|おだいじに]。",
    en: "You have a cold? Get well soon." },
  "げんきがない|元気がない": {
    explain: "A phrase made of two pieces. 「元気|げんき」 is health and energy, the word you know from 「お元気ですか|おげんきですか」, how are you. Let's break it apart. 「元|げん」 means origin or source. 「気|き」 is spirit or energy, the same kanji as in 「天気|てんき」, weather, and 「病気|びょうき」, sickness. So 「元気|げんき」 is the source of your energy, your vitality. Then 「ない」 is there isn't. So 「元気がない|げんきがない」 is there's no energy. It describes someone who seems low, down, or tired, not their usual self. It's often about mood as much as health. You'd say it when a friend is quiet and gloomy: 「元気がないですね|げんきがないですね」, you don't look so good, or the casual 「どうしたの、元気ないね|どうしたの、げんきないね」, what's up, you seem down. A common mistake: 「元気がない|げんきがない」 isn't a diagnosis. For actual illness use 「病気|びょうき」, sick. And note the sentence pattern, 「元気|げんき」 plus 「が」 plus 「ない」, just like 「熱がある|ねつがある」 uses 「が」 plus 「ある」. It's a gentle, caring thing to notice and say. To recap: the source of energy, and there isn't any. You seem down.",
    ja: "{今日|きょう}は[元気がない|げんきがない|げんきがない]ですね。",
    en: "You don't look well today." },
  "できるだけ|": {
    explain: "Two pieces you know. 「できる」 is can, be able to. 「だけ」 is only or just, as in 「〜だけ」. Together, it's only as much as you can, which means as much as possible. Put it right before what you're trying to do. 「できるだけ早く|できるだけはやく」 is as soon as possible. 「できるだけ毎日運動します|できるだけまいにちうんどうします」 is I exercise every day as much as I can. You'll hear it a lot in instructions from teachers and doctors, like 「できるだけ休んでください|できるだけやすんでください」, please rest as much as possible, which fits right in with this lesson about being sick. It's a great phrase for making plans or promises without overpromising: you're saying you'll do your best, within your ability. It's a little like 「頑張る|がんばる」, to try hard, in spirit. A common mistake for English speakers is putting it at the end of the sentence, like in English, as possible. In Japanese, it goes before the action or the adverb it modifies. Remember the order: can, only, then the thing. It's polite enough for any situation. A way to remember it: only as far as you can go, and not one step less. That's a hook. To recap: can, only. As much as you're able.",
    ja: "[できるだけ]{毎日|まいにち}{運動|うんどう}します。",
    en: "I exercise every day as much as possible." },
  "たぶん|多分": {
    explain: "Two kanji with Chinese-origin readings. 「多|た」 means many or a lot, the same kanji as in 「多い|おおい」, there are many, from this lesson, but here using its 「た」 reading. 「分|ぶん」 means part or portion. You see it in 「気分|きぶん」, mood, and 「自分|じぶん」, oneself. So 「多分|たぶん」 is a large portion, which turned into most likely or probably. Picture most of the chances pointing one way. In real life it's very often written in kana. The usual position is at the start of the sentence, and it pairs naturally with 「でしょう」 or 「と思います|とおもいます」 at the end. 「たぶん雨でしょう|たぶんあめでしょう」, it'll probably rain. 「たぶん来ると思います|たぶんくるとおもいます」, I think he'll probably come. The ending reinforces the guess. How sure is it? It's somewhere between maybe and probably, a reasonable guess, not certain. A cultural note: Japanese speakers often soften statements to avoid sounding too pushy, and 「たぶん」 is one of the handiest softeners. It can even be a gentle, polite way to say I'm not sure. A common mistake is using it alone with a firm statement that's actually certain. To recap: a large portion of the chances. Probably.",
    ja: "あしたは[多分|たぶん]{雨|あめ}でしょう。",
    en: "It will probably rain tomorrow." },
  "もうすぐ|": {
    explain: "Two pieces you know. 「もう」 means already, and 「すぐ」 means right away. Put them together and you get it's almost already here, coming right up. It means very soon, in a few moments, or even in a few days or weeks, depending on what's coming. The usual patterns are 「もうすぐ」 plus a noun plus 「です」: 「もうすぐ夏休みです|もうすぐなつやすみです」, summer vacation is coming soon. Or 「もうすぐ」 plus a verb: 「もうすぐ来ます|もうすぐきます」, they'll be here soon. You can also use it for time and events: 「もうすぐ誕生日です|もうすぐたんじょうびです」, my birthday is coming up. Here's a tip for English speakers. 「すぐ」 alone is immediately, often used for actions: 「すぐ行きます|すぐいきます」, I'll go right now. 「もうすぐ」 is more about something approaching on its own. Something is about to happen, rather than you doing it right now. Watch out for 「もう」 in other combinations, like 「もう一度|もういちど」, one more time, where it means more instead of already. Context tells you which. A way to remember it: already, and right away, so it's practically here. That's a hook. To recap: already plus right away. Very soon.",
    ja: "[もうすぐ]{夏休み|なつやすみ}です。",
    en: "Summer vacation is coming soon." },
  "はじめて|初めて": {
    explain: "The native reading here is 「はじめて」. Look at the kanji. The left side is the clothing radical, and the right side is 「刀|かたな」, a knife or blade. The traditional explanation is that cutting the cloth is the first step in making clothes. That's a lovely picture for beginnings. You already know this kanji from a phrase you say all the time: 「はじめまして」, nice to meet you, literally this is the first time. The 「はじめ」 part is the same word. It's also in 「初詣|はつもうで」, with the reading 「はつ」, the first shrine visit of the new year, a big cultural tradition in early January. There's a sound-alike: 「始める|はじめる」, to begin, uses a different kanji. 「初めて|はじめて」 is about doing something for the first time in your life, while 「始める|はじめる」 is about starting an activity. So 「初めて日本に行きました|はじめてにほんにいきました」 means I went to Japan for the first time. A common mistake is using it to mean first, as in first of all, in a list of steps. That's 「最初に|さいしょに」 or 「まず」. To recap: cutting the cloth, the very first step. For the first time.",
    ja: "[初めて|はじめて]{日本|にほん}にいきました。",
    en: "I went to Japan for the first time." },
  "にさんにち|二三日": {
    explain: "This is simple once you see it. 「二|に」 is two, 「三|さん」 is three, and 「日|にち」 is the counter for days. Put them side by side and you get two or three days, a couple of days. Notice it uses the Chinese-origin readings for the numbers, 「に」 and 「さん」, and 「にち」 for day. Compare the special native reading for two days, 「二日|ふつか」, and three days, 「三日|みっか」, from your vocab, or 「二日酔い|ふつかよい」, hangover. Those are the precise counts, while this one is a rough estimate. That's an important difference. A common mistake for English speakers is to try to say two to three days with something like a to between them. Japanese simply puts the numbers side by side, no extra word needed. The same trick works with other counters too. 「二三人|にさんにん」, two or three people. 「二三回|にさんかい」, two or three times. You'll hear this a lot at the doctor: 「二三日休んでください|にさんにちやすんでください」, please rest for a couple of days, which fits this lesson about being sick. It's also used in everyday plans, like being away for a couple of days. To recap: two, three, days. A couple of days, as a rough guess.",
    ja: "[二三日|にさんにち]やすんでください。",
    en: "Please rest for two or three days." },
  "それに|": {
    explain: "Two pieces. 「それ」 is that, the same word as in 「それから」, and then, which you know. 「に」 here works like onto or on top of. So 「それに」 is on top of that, which means moreover or besides. It's a conjunction that starts a new sentence, and it's used for stacking up one more reason or point in the same direction. For example, 「このみせはやすいです。それに、おいしいです。」, this shop is cheap, and on top of that, it's tasty. Both points support the same idea, that it's a good shop. A common mistake for English speakers is to use 「それに」 for and then, in time order. That's 「それから」. 「それから」 is about what happens next, while 「それに」 is about adding another reason. It's also great for excuses. In this lesson, someone might say they can't go out: they have a cold, and besides, they have an exam tomorrow. 「それに」 lets you pile up reasons naturally. It's neutral and polite enough for most situations. In casual speech, you might hear it at the start of an extra complaint too. A way to remember it: picture placing one more brick on top of a stack. That's a hook. To recap: that, plus on top of. Moreover.",
    ja: "このみせはやすいです。[それに]、おいしいです。",
    en: "This shop is cheap. Moreover, it is tasty." },
  "おなじ|同じ": {
    explain: "This uses the native reading 「おなじ」. It's a special word grammatically, and that's the most important thing to learn. It acts like an adjective, but when it comes directly before a noun, you add nothing, no 「な」 and no 「の」. So 「同じクラス|おなじクラス」, the same class, and 「同じ大学|おなじだいがく」, the same college. A very common mistake for English speakers is to say 「同じなクラス|おなじなクラス」 or 「同じのクラス|おなじのクラス」. Both are wrong. Just put the noun right after it. At the end of a sentence, you use 「です」: 「同じです|おなじです」, they're the same. To compare, use 「と」: 「これとそれは同じです|これとそれはおなじです」, this and that are the same, or 「兄と同じ|あにとおなじ」, the same as my older brother. You can also say 「同じ物|おなじもの」, the same thing, with 「物|もの」 from this lesson. Its opposite is 「違う|ちがう」, to be different. Look at the kanji: a frame with a single 「口|くち」, mouth, inside, under a line. A way to remember it: everyone under one roof speaking with one mouth, all saying the same thing. That's a hook. To recap: the same, and it goes straight before a noun with nothing in between.",
    ja: "わたしと{兄|あに}は[同じ|おなじ]{大学|だいがく}です。",
    en: "My older brother and I go to the same college." },
  "おとな|大人": {
    explain: "Look at the two kanji. The first is the big from 「大きい|おおきい」 and 「大学|だいがく」. The second is the person from 「人|ひと」 and 「外国人|がいこくじん」. Put them together and you get a big person, a grown-up. That part is easy. The tricky part is the sound. Neither kanji is read the way you would expect. Normally the big kanji is read 「だい」 or 「おお」, and the person kanji is 「ひと」, 「じん」 or 「にん」. But this word is an old native Japanese word, 「おとな」, that was simply given these two kanji because they fit the meaning. The reading belongs to the pair as a whole, not to each kanji. You already know another word like this: 「一人|ひとり」, one person, where the reading also belongs to the whole word. So when you see these two kanji side by side, do not try to build the sound from the parts. Just remember the pair. You will see it on ticket machines and price boards, for example 「大人|おとな」 next to 「子供|こども」, adult price and child price. So, a big person is a grown-up, and the pair has its own special reading.",
    ja: "[大人|おとな]は{千円|せんえん}です。",
    en: "Adults are one thousand yen." },
  "べんごし|弁護士": {
    explain: "This is a three kanji job word, and all three readings are the Chinese-origin ones. The first, 「弁|べん」, has to do with speech and arguing a case, being able to talk your way through something. The second, 「護|ご」, means to protect or defend. The third, 「士|し」, marks a trained professional, someone with a qualification. Add them up: a qualified professional who speaks up to protect you. That is exactly what a lawyer does in court. Now the family. You already know 「看護師|かんごし」, nurse. It has the same 「護|ご」, protect, in the middle. A nurse watches over and protects patients, a lawyer protects clients with words. And the 「士|し」 at the end shows up in other job words you know, like 「消防士|しょうぼうし」, firefighter, and 「宇宙飛行士|うちゅうひこうし」, astronaut. Careful, though: the 「し」 in 「看護師|かんごし」 is a different kanji, 「師|し」, used for teachers and experts. Both sound the same, so listen for the meaning. So, speak, protect, professional: the one who argues your case.",
    ja: "{母|はは}は[弁護士|べんごし]です。",
    en: "My mother is a lawyer." },
  "わたくし|私": {
    explain: "This is the very same kanji as 「私|わたし」, the everyday word for I. The difference is only the reading. 「わたくし」 is the older, fuller form, and 「わたし」 is a shortened version of it that became the normal word. Because the long form sounds more careful and proper, it is now the formal way to say I. Use it when you need to be at your most polite. Think of a job interview, a speech, talking to a customer, or calling a company on the phone. It pairs naturally with the humble phrase 「と申します|ともうします」, so you might say 「わたくしは山田と申します|わたくしはやまだともうします」, my name is Yamada. With friends, it would sound stiff and a little funny, so stay with 「わたし」 or, for men, 「僕|ぼく」. The kanji also carries a sense of private or personal, the opposite of public. You see it in 「私たち|わたしたち」, we. A way to remember it: the extra 「く」 is like putting on a tie. Same person, dressed up. So, one kanji, two readings, and the longer one is the formal one.",
    ja: "[私|わたくし]は{田中|たなか}ともうします。",
    en: "My name is Tanaka." },
  "カレー|": {
    explain: "This comes from the English word curry, which itself came into English from India. To fit Japanese sounds, the r becomes the Japanese r sound, and the final y turns into a long vowel, written with the long dash. So curry becomes 「カレー」. The interesting part is how it arrived. Curry did not come to Japan straight from India. It came from Britain in the late 1800s, as a British style curry made with curry powder and thickened with flour. That is why Japanese curry is so different from Indian curry. It is a thick, mild, slightly sweet stew with potatoes, carrots and onions, poured over rice. That dish is called 「カレーライス」. The Japanese navy adopted it early, and even today Japan's navy is famous for eating curry on Fridays. Now it is one of the most common home meals and school lunches in Japan. Families buy blocks of curry roux in the supermarket, labeled mild, medium or hot. A handy link: a hot one is 「辛い|からい」, spicy, a word in this same lesson. So, an English word for an Indian dish, reshaped by Britain, and made Japan's comfort food.",
    ja: "この[カレー]はからいです。",
    en: "This curry is spicy." },
  "こうちゃ|紅茶": {
    explain: "Here is a fun difference between languages. English calls it black tea, but Japanese calls it red tea. The first kanji, 「紅|こう」, means deep red or crimson, the color of the brewed tea in the cup. Notice the thread radical on its left side, the same one you see in 「約束|やくそく」 and 「手紙|てがみ」. It hints at dyed thread and cloth. The second kanji, 「茶|ちゃ」, is tea. It has the grass radical on top, because tea is made from leaves. Both readings here are Chinese-origin readings. Now the family. You already know 「お茶|おちゃ」, which in Japan means green tea by default. If you just ask for tea, you will get green tea. If you want the British style, you ask for this word. The same tea kanji also hides inside 「喫茶店|きっさてん」, a cafe, where it is read 「さ」 instead. Chinese also calls this kind of tea red tea, so the name came along with the kanji. So, black tea in English is red tea in Japanese, named for the color in your cup.",
    ja: "{朝|あさ}[紅茶|こうちゃ]を{飲みます|のみます}。",
    en: "I drink black tea in the morning." },
  "きもの|着物": {
    explain: "This word is built from two native readings, and it is very literal. The first kanji, 「着|き」, comes from the verb 「着る|きる」, to wear. The second, 「物|もの」, means thing. So the word is just a thing to wear. Long ago it meant any clothes at all. Over time, as Western clothes became normal, the word narrowed to mean the traditional Japanese robe. Now look at the family. The ending 「物|もの」 is everywhere: 「食べ物|たべもの」, a thing to eat, food, 「飲み物|のみもの」, a thing to drink, and 「買い物|かいもの」, shopping. This word fits the same pattern. And the first kanji also appears in 「着く|つく」, to arrive, a word you will meet soon. Today most people wear a kimono only on special days, like New Year's, weddings, graduation, or the Coming of Age Day when twenty year olds dress up. In summer there is a light cotton version for festivals called 「ゆかた」. Putting on a formal kimono is so complicated that many people pay a professional to help. So, a thing to wear, which became the traditional robe.",
    ja: "{お正月|おしょうがつ}に[着物|きもの]を{着ました|きました}。",
    en: "I wore a kimono at New Year's." },
  "セーター|": {
    explain: "This is from the English word sweater. Watch how the sounds get squeezed. Japanese does not like the sw cluster at the start, so the w simply drops out and you get 「セ」. The t sound stays. Then the er at the end, which English barely pronounces, turns into a long vowel, written with the long dash. That same habit of making er into a long vowel shows up in lots of loanwords you know, like 「コンピューター」, computer, and 「スーパー」, supermarket. In Japanese this word is used for knitted tops, the kind made from wool or yarn. Be careful with a related false friend. A sweatshirt, the cotton kind with a fleece inside, is not called this. It is 「トレーナー」, from the English word trainer. So if you want a cozy knit, say this word. If you want the gym style top, say 「トレーナー」. This word also fits nicely with the verb 「編む|あむ」, to knit, from this same lesson. A handmade knitted sweater is a classic gift in Japanese stories and dramas. So, sweater with the w dropped and the ending stretched out.",
    ja: "{母|はは}が[セーター]をあみました。",
    en: "My mother knitted a sweater." },
  "がっき|楽器": {
    explain: "The first kanji, 「楽|がく」, is the music kanji. You know it from 「音楽|おんがく」, music. The same kanji also means fun or comfort, as in 「楽しみです|たのしみです」, I can't wait, because music and joy go together. The second kanji, 「器|き」, means a tool, a vessel, or a container. Both readings here are Chinese-origin. So the word is a music tool, a thing for making music. Now listen to the sound. 「がく」 plus 「き」 should give 「がくき」, but Japanese squeezes the 「く」 into a small pause, giving 「がっき」. The same squeeze happens in 「学校|がっこう」, where 「がく」 plus 「こう」 becomes 「がっこう」. Here is a fun trap. You already know 「今学期|こんがっき」, this semester. That 「がっき」 is a different word, written with the learning kanji, but it sounds exactly the same. So 「がっき」 can be a semester or an instrument. Context makes it clear. You play string or keyboard instruments with the verb 「ひく」, like 「ピアノをひく」 or 「ギターをひく」. So, the music kanji plus the tool kanji: a music tool.",
    ja: "なにか[楽器|がっき]をひけますか。",
    en: "Can you play any musical instrument?" },
  "からて|空手": {
    explain: "Two simple kanji, both with native readings. The first, 「空|から」, means empty. The same kanji can also be read 「そら」, sky, and 「くう」 in 「空港|くうこう」, airport. The second, 「手|て」, is hand, as in 「手紙|てがみ」 and 「上手|じょうず」. So the word is empty hand: fighting with your bare hands, no weapons. There is a nice bit of history here. Karate grew up in Okinawa, and it was once written with a different first kanji meaning China, because of its Chinese roots. In the 1930s the name was changed to the empty kanji, which sounds the same and gives the meaning of fighting unarmed. Here is another member of the family you already know. 「カラオケ」 starts with the same empty, 「から」, plus a short form of orchestra. Karaoke is an empty orchestra, the music with the singer missing. So karate and karaoke share the very same empty. So, empty plus hand: the art of fighting with nothing in your hands.",
    ja: "{毎日|まいにち}[空手|からて]をれんしゅうします。",
    en: "I practice karate every day." },
  "ゴルフ|": {
    explain: "Straight from the English word golf. Watch what happens to the sounds. Japanese syllables almost always end in a vowel, so English consonants that sit alone need a vowel added. The l in the middle has no vowel after it, so it becomes 「ル」, using the Japanese r sound, since Japanese does not have a separate l. The f at the end also stands alone, so it becomes 「フ」. The result is three beats where English has one. You can hear the same pattern in other sport words you know, like 「テニス」 and 「サッカー」. In Japan golf has a strong image as a business sport. Office workers and company bosses traditionally played it with clients and coworkers on weekends, and courses can be expensive. There are also many driving ranges in cities, often with tall green nets you can see from the train. To say you play, use 「する」: 「ゴルフをします」. So, golf, stretched out to fit Japanese, with a vowel after every consonant.",
    ja: "{父|ちち}は{日曜日|にちようび}に[ゴルフ]をします。",
    en: "My father plays golf on Sundays." },
  "バイク|": {
    explain: "This comes from the English word bike, but there is a big meaning shift. In English, bike often means a bicycle. In Japanese, it means a motorbike or motorcycle. The English word was short for motorbike, and Japanese kept that meaning. The sounds come through nicely: the ai sound stays, and the k at the end gets a vowel, becoming 「ク」. Now, for a pedal bicycle, you use a word you already know, 「自転車|じてんしゃ」. Its kanji mean self, turning, and vehicle: a vehicle whose wheels you turn yourself. And 「車|くるま」, car, shares that last kanji. A way to remember it: in Japanese, if it has an engine, it is this loanword. If it needs your legs, it is 「自転車|じてんしゃ」. Small scooters are also usually called by this word. For riding, use the verb 「のる」, to ride, with 「に」: 「バイクにのります」. To say you go somewhere on one, use 「で」, like 「バイクで行きます|バイクでいきます」. So, a borrowed bike, but in Japan it always has a motor.",
    ja: "[バイク]で{大学|だいがく}に{行きます|いきます}。",
    en: "I go to college by motorcycle." },
  "ぞう|象": {
    explain: "The kanji is one of the classic picture characters. In its oldest form it was a drawing of an elephant standing on end, with the trunk at the top, the body in the middle, and legs and tail below. Over the centuries the drawing became squared off, but you can still imagine a long creature stacked vertically. The reading 「ぞう」 is the Chinese-origin reading. Later, the same kanji took on the meaning of shape or image, so you will meet it in advanced words about impressions and appearances. For now, just keep the elephant. A way to remember it: you go to the zoo to see one, and 「ぞう」 sounds like zoo. The zoo itself is 「動物園|どうぶつえん」. A cute fact: every Japanese child knows the song 「ぞうさん」, where a little elephant is told what a long nose it has, and it answers that its mother has a long nose too. In Japanese, an elephant's trunk is called its nose, 「はな」. So, an ancient drawing of an elephant, and a word that sounds like the place you see one.",
    ja: "[象|ぞう]はとても{大きい|おおきい}です。",
    en: "Elephants are very big." },
  "からだ|体": {
    explain: "Look at the kanji. On the left is the person radical, the same one in 「休む|やすむ」, to rest. On the right is 「本|ほん」, the kanji for book, which originally means root or origin. A way to remember it: the person part plus the root part, the foundation of a person, which is the body. That is a hook, not the full history. The kanji you see is a simplified form of an older, more complicated one. In this word it has its native reading, 「からだ」. In other words it is read 「たい」, the Chinese-origin reading, as in words for physical education and body weight you will meet later. This word is used in very common phrases. 「体にいい|からだにいい」 means good for your body, healthy. 「体に悪い|からだにわるい」 means bad for your health, using 「悪い|わるい」, bad. And when someone is sick, you might ask 「体はだいじょうぶですか|からだはだいじょうぶですか」, is your body okay. So, a person plus a root, the body you live in.",
    ja: "やさいは[体|からだ]にいいです。",
    en: "Vegetables are good for your body." },
  "がいこくご|外国語": {
    explain: "This is a three kanji word, and it is a great one, because you already know every piece. The first kanji, 「外|がい」, means outside. The second, 「国|こく」, means country, the same kanji as 「国|くに」. Together they make 「外国|がいこく」, foreign country, literally an outside country. Add the third kanji, 「語|ご」, language, and you get the language of an outside country. All the readings here are Chinese-origin. Now the family. You know 「外国人|がいこくじん」, foreigner, a person from an outside country. You know 「日本語|にほんご」, Japanese language, which uses the same 「語|ご」. And English, 「英語|えいご」, uses it too. Look at the left side of 「語|ご」. It is the speech radical, also found in 「言う|いう」, to say, and 「言葉|ことば」, word. So it makes sense that it means language. You can stick 「語|ご」 after almost any country name to name its language. A common question is 「外国語を話しますか|がいこくごをはなしますか」, do you speak a foreign language. So, outside, country, language: the language of another land.",
    ja: "なにか[外国語|がいこくご]を{話します|はなします}か。",
    en: "Do you speak any foreign language?" },
  "ことば|言葉": {
    explain: "The first kanji is the speech kanji from 「言う|いう」, to say. Here it is read 「こと」, a native reading. The second kanji is leaf, with the grass radical on top. On its own it is 「は」, but when it follows another sound, it softens to 「ば」, a common sound change in Japanese compounds. So the word is literally saying leaves. Why leaves? There is a famous line from about eleven hundred years ago, in the preface to an old poetry collection. It says that Japanese poetry takes the human heart as its seed and grows into countless leaves of words. That image of words as leaves growing from the heart is a lovely way to remember it. This word covers both a single word and language in general, depending on context. You might ask 「この言葉はどういう意味ですか|このことばはどういういみですか」, what does this word mean. Compare 「外国語|がいこくご」, foreign language, which uses another kanji with the same speech radical on its left. So, speech plus leaves: words that grow from the heart like leaves.",
    ja: "この[言葉|ことば]は{英語|えいご}で{何|なん}ですか。",
    en: "What is this word in English?" },
  "ぶんぽう|文法": {
    explain: "The first kanji, 「文|ぶん」, means writing, a sentence, or text. You know it from 「文化|ぶんか」, culture, and you also have 「ぶんがく」, literature, which uses the same kanji. The second kanji, 「法|ほう」, means law, rule, or method. It has the water radical on its left. Both readings are Chinese-origin. Put them together and you get the rules of sentences: grammar. Now listen to the sound. 「法|ほう」 is normally 「ほう」, but after the 「ん」 of 「ぶん」, it changes to 「ぽう」. Japanese often turns an h sound into a p sound after 「ん」 or a small pause. You can hear the same thing in counters, like 「一本|いっぽん」, where the h sound of 「本|ほん」 becomes a p. So if you ever hear 「ぽう」 in the middle of a word, think of 「ほう」 in disguise. You might say 「文法はむずかしいです|ぶんぽうはむずかしいです」, grammar is difficult. A way to remember it: grammar is the law of writing. So, sentence plus rule, with the sound hardened to 「ぽう」 after 「ん」.",
    ja: "{日本語|にほんご}の[文法|ぶんぽう]はむずかしいです。",
    en: "Japanese grammar is difficult." },
  "アプリ|": {
    explain: "This is short for 「アプリケーション」, from the English word application. Japanese loves to take long loanwords and cut them down to the first few sounds. Here the long word keeps only its first three beats. You already know several words made the same way. 「パソコン」 is short for personal computer, cutting both words. 「エアコン」 is short for air conditioner. And 「スーパー」 is short for supermarket. Once you notice the pattern, many loanwords become easier to guess. Watch the sounds too. The p in application gets a vowel, becoming 「プ」, and the l becomes the Japanese r sound, giving 「リ」. In everyday Japanese this word means a phone or computer app. You download one, use one, delete one. People also say 「スマホ」 for smartphone, which is another chopped word, from smart and phone. A useful phrase is 「このアプリはべんりです」, this app is convenient. A way to remember it: Japanese takes the first bite of a long English word and keeps it. So, application cut down to three beats.",
    ja: "この[アプリ]はべんりです。",
    en: "This app is convenient." },
  "アパート|": {
    explain: "This is from the English word apartment, cut short. The ending ment is dropped, and the ar sound turns into a long vowel, written with the long dash. You already know a perfect twin: 「デパート」, department store, is from department, cut in exactly the same place. A way to remember it: 「アパート」 and 「デパート」 are both English words with the ment chopped off. In Japan, though, this word has a specific image. It usually means a small, cheaper building of two or three floors, often made of wood or light steel, with outdoor stairs and thin walls. Many students and young workers live in one. A bigger, sturdier concrete building with many floors is called 「マンション」, from this same lesson. So Japanese splits English apartment into two words by building type. To say you live in one, use 「すむ」: 「アパートにすんでいます」. When you rent one, you deal with the 「大家さん|おおやさん」, landlord. So, apartment with its tail cut off, meaning a small, simple building.",
    ja: "{私|わたし}は[アパート]にすんでいます。",
    en: "I live in an apartment." },
  "マンション|": {
    explain: "This comes from the English word mansion, but do not picture a huge house with a pool. In Japanese it means a larger, sturdier apartment building, usually made of reinforced concrete, with many floors, an elevator, and often an automatic locked entrance. Individual units can be rented or bought, so it also covers what English calls a condominium. The grand sounding name was a selling point when these newer, nicer buildings first appeared. Watch the sounds. The ending sion becomes 「ション」, the same way station becomes 「ステーション」. Compare it with 「アパート」, from this same lesson. That one is smaller, cheaper, often wood, with fewer floors. If you tell a Japanese friend you live in a mansion, they will think of a modern apartment, not a palace. A way to remember it: in Japan, a mansion is just a nice apartment block. To say you live in one, use 「すむ」, like 「マンションにすんでいます」. So, an English word for a grand house, scaled down to mean a solid apartment building.",
    ja: "{友だち|ともだち}は[マンション]にすんでいます。",
    en: "My friend lives in a condominium." },
  "くうこう|空港": {
    explain: "Two kanji, both with their Chinese-origin readings. The first, 「空|くう」, means sky or air. On its own, sky is 「そら」, the native reading. The second, 「港|こう」, means port or harbor. Look at its left side: the water radical, because a harbor is where ships meet the water. On its own, harbor is 「みなと」. Put them together: a sky port, a harbor for planes instead of ships. English airport works the very same way, air plus port. Now the family. The same first kanji appears in 「空手|からて」, karate, but there it is read 「から」 and means empty. Sky and empty are linked in the kanji: the sky is the big empty space above you. And you have 「カラオケ」, empty orchestra, which uses that same 「から」, written in katakana. To get to the airport, you might take a train or bus, and then board a 「飛行機|ひこうき」, airplane. A useful phrase is 「空港まで行きます|くうこうまでいきます」, I'm going as far as the airport. So, sky plus harbor: a port for the sky.",
    ja: "[空港|くうこう]まで{車|くるま}で{行きます|いきます}。",
    en: "I go to the airport by car." },
  "みせ|店": {
    explain: "Look at the kanji. The outer part, a dot and a line with a long stroke sweeping down on the left, is a radical that shows a building with a roof. Shops are buildings, so that fits. Here the word has its native reading, 「みせ」. Some say the word comes from the verb 「見せる|みせる」, to show, because a shop shows its goods to people passing by. That link is widely given, and it makes a great hook either way: a shop is where things are shown. The kanji's Chinese-origin reading is 「てん」, and you already know it at the end of 「喫茶店|きっさてん」, cafe, literally a tea drinking shop. Many shop words end in that 「てん」. Another way to name a shop is with 「屋|や」, as in 「本屋|ほんや」, bookstore. When you walk into a Japanese shop, staff will greet you with 「いらっしゃいませ」, welcome. You do not need to answer, a small nod is fine. A useful sentence is 「この店はやすいです|このみせはやすいです」, this store is cheap. So, a building with a roof, where goods are shown.",
    ja: "この[店|みせ]はやすいです。",
    en: "This store is cheap." },
  "ぶっか|物価": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「物|ぶつ」, is the thing kanji. You know it with its native reading 「もの」 in 「食べ物|たべもの」 and 「着物|きもの」. With the Chinese-origin reading it shows up in 「動物園|どうぶつえん」, zoo, the garden of moving things, animals. The second kanji, 「価|か」, means value or price. It has the person radical on the left. A way to picture it: people decide what things are worth. Put them together: the price of things. Listen to the sound change. 「ぶつ」 plus 「か」 should be 「ぶつか」, but the 「つ」 squeezes into a small pause, giving 「ぶっか」. That is the same squeeze you hear in 「学校|がっこう」. Now the meaning. This is not the price of one item. It is the general level of prices in a place, the cost of living. So you say a city's prices are high, 「物価が高い|ぶっかがたかい」, or low, 「物価が安い|ぶっかがやすい」. Tokyo is famous for high prices, while the countryside is cheaper. So, things plus value: how much things cost in general.",
    ja: "{東京|とうきょう}は[物価|ぶっか]が{高い|たかい}です。",
    en: "Prices are high in Tokyo." },
  "こうこく|広告": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「広|こう」, means wide or broad. You know it with its native reading in 「広い|ひろい」, wide, spacious. Its outer part is the same roof radical you see in 「店|みせ」, a building with a roof. The second kanji, 「告|こく」, means to announce or tell. It has 「口|くち」, mouth, at the bottom, which fits, since you announce things with your mouth. Put them together: to announce widely. An advertisement spreads a message out to as many people as possible. That is a nice clean picture. Listen to the rhythm too: two very similar sounds, 「こう」 and 「こく」, back to back. A way to remember it: an ad is a loud mouth that speaks wide. You will see this word for ads in newspapers, magazines, on trains, and online. Trains in Japan are famous for being packed with hanging paper ads. You might say 「新聞で広告を見ました|しんぶんでこうこくをみました」, I saw an ad in the newspaper. Another common word for a TV ad is 「コマーシャル」, from English commercial, or just 「シーエム」. So, wide plus announce: telling everyone.",
    ja: "{新聞|しんぶん}で[広告|こうこく]を{見ました|みました}。",
    en: "I saw an advertisement in the newspaper." },
  "ぼしゅう|募集": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「募|ぼ」, means to call for, to invite people to come forward. Look at the bottom of it: it is 「力|ちから」, power or effort. The second kanji, 「集|しゅう」, means to gather. This one has a lovely real picture. The top part is a bird, and the bottom part is 「木|き」, tree. Birds gathering on a tree. You already know this kanji in 「集める|あつめる」, to collect, with its native reading. Put them together: calling people in and gathering them, which is recruitment. In daily life, you see this word on signs in shop windows, like 「アルバイト募集|アルバイトぼしゅう」, part-timers wanted. It is also used for clubs looking for members, companies hiring staff, and contests looking for entries. It works as a noun and as a verb with 「する」, as in 「募集しています|ぼしゅうしています」, they are recruiting. A way to remember it: picture a manager calling out with all their power, and new workers flocking in like birds to a tree. So, call for plus gather: bringing people in.",
    ja: "あの{店|みせ}はアルバイトを[募集|ぼしゅう]しています。",
    en: "That shop is recruiting part-time workers." },
  "やくそく|約束": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「約|やく」, means an agreement or a promise. It has the thread radical on the left, like 「紅茶|こうちゃ」 and 「手紙|てがみ」. A promise is something that ties people together, like thread. The second kanji, 「束|そく」, means a bundle. Its shape is a tree, 「木|き」, with a band around its middle, sticks tied together into a bundle. Put them together: an agreement tied up tight. You already know the first kanji from 「予約|よやく」, reservation. A reservation is an agreement made in advance. So both words are about tying down a plan. Now the meaning. This word covers two English ideas: a promise and an appointment, a plan to meet. 「約束があります|やくそくがあります」 means I have plans, I'm meeting someone. Keeping a promise is 「約束を守る|やくそくをまもる」, literally guarding it, also in this lesson. Japanese kids seal promises with a pinky swear song. So, agreement plus bundle: a promise tied up tight between two people.",
    ja: "{友だち|ともだち}と[約束|やくそく]があります。",
    en: "I have an appointment with a friend." },
  "うれしい|": {
    explain: "This is a native Japanese word, and it is almost always written in hiragana. It is the bright, happy feeling you get when something good happens to you. A present, a good test score, a message from a friend, good news. It is about a moment, a reaction. Compare 「幸せ|しあわせ」, happy, also in this lesson, which is a deeper, lasting happiness about your life. You feel 「うれしい」 when you get a gift. You feel 「幸せ|しあわせ」 when your life is good. Here is a common mistake. Feeling words like this one are used for your own feelings. You can say 「うれしいです」, I am glad. But saying another person is glad sounds odd, because you cannot see inside their heart. For others, Japanese uses a form like 「うれしそう」, looks glad, which you meet in this same lesson. The opposite feeling is 「悲しい|かなしい」, sad. A way to remember it: picture shouting hooray when good news comes, and hear the 「うれ」 hiding in hooray. So, a quick burst of gladness, for your own feelings.",
    ja: "プレゼントをもらって、[うれしい]です。",
    en: "I got a present, so I'm glad." },
  "かなしい|悲しい": {
    explain: "Look at the kanji, because it tells a clear story. At the bottom is 「心|こころ」, heart. On top is a part that means not or wrong. A heart that is not right: sadness. That bottom heart is a real and useful pattern. Many feeling kanji have a heart at the bottom or on the left. You know 「心配する|しんぱいする」, to worry, which starts with the heart kanji itself. And in 「感動する|かんどうする」, to be moved, from this same lesson, the first kanji also has a heart at the bottom. Here the reading is native, 「かな」, with 「しい」 written in hiragana, the ending many feeling adjectives have, like 「うれしい」 and 「さびしい」. Just like 「うれしい」, it describes your own feelings directly. For someone else, you say they look sad, 「悲しそう|かなしそう」. This is the opposite of 「うれしい」, glad. A way to remember it: when something sad happens, your heart is not right. So, a heart marked wrong: sadness.",
    ja: "{友だち|ともだち}が{帰って|かえって}、[悲しい|かなしい]です。",
    en: "My friend went home, so I'm sad." },
  "きびしい|厳しい": {
    explain: "The kanji is a complicated one, and its history is not simple, so let's focus on how the word is used. Here it has its native reading, 「きび」, plus the adjective ending 「しい」. Its main use is for people and rules that are strict. A strict teacher, strict parents, strict school rules. You might say 「父はとても厳しいです|ちちはとてもきびしいです」, my father is very strict. But it goes beyond people. It also means harsh or severe. Very harsh cold weather is 「厳しい寒さ|きびしいさむさ」. A tough business situation, a hard schedule, or a tough competition can all be called this. Think of it as anything that does not let you off easy. It is a little different from 「むずかしい」, difficult. Something difficult is hard to understand or do. Something with this word is hard on you, demanding. The opposite for people is 「やさしい」, kind or gentle. A way to remember it: the strict teacher holds the key, and her words sting like a bee, key and bee. So, strict, harsh, and severe: something that does not go easy on you.",
    ja: "{父|ちち}はとても[厳しい|きびしい]です。",
    en: "My father is very strict." },
  "きぶんがわるい|気分が悪い": {
    explain: "This is a short phrase, so let's open it up. The first word, 「気分|きぶん」, means mood or how you feel inside. It has two kanji with Chinese-origin readings. 「気|き」 is spirit, energy, or air. You know it from many words: 「元気|げんき」, healthy, 「天気|てんき」, weather, 「病気|びょうき」, sickness, and 「電気|でんき」, electricity. All of them are about some kind of invisible energy. The second kanji, 「分|ぶん」, means part or portion. You know it in 「自分|じぶん」, oneself, and 「多分|たぶん」, probably. Then 「が」, and 「悪い|わるい」, bad, which you already know. So the phrase is literally your inner feeling is bad. In practice it usually means you feel sick, often a bit queasy, like you might throw up, or just unwell. It can also mean you are in a bad mood, upset by something. Context makes it clear. The opposite, 「気分がいい|きぶんがいい」, means you feel good or refreshed. Compare 「元気がない|げんきがない」, don't look well, which is about low energy. So, your inner spirit is bad: you feel sick.",
    ja: "{今日|きょう}は[気分が悪い|きぶんがわるい]です。",
    en: "I feel sick today." },
  "からい|辛い": {
    explain: "This is a native word, written with a kanji plus 「い」. Its main meaning is hot and spicy, like chili, wasabi, or a hot curry. In some regions it is also used for salty, though people in the Tokyo area usually say 「しょっぱい」 for that. Here is something interesting about the kanji. The very same kanji, with a different native reading, is 「辛い|つらい」, which means painful or hard to bear. Food that is too spicy is painful, so the two meanings fit together. Just remember that the reading changes the meaning, so listen carefully. There is another fun link. Look at the kanji for 「幸せ|しあわせ」, happiness, also in this lesson. It looks almost the same, but it has one extra horizontal line on top. People in Japan love to point this out: add one line to pain, and you get happiness. The opposite of spicy is 「甘い|あまい」, sweet. And a mild curry is 「あまくち」, a sweet mouth. A way to remember it: 「カレー」 is 「からい」, the two even sound alike. So, spicy, sometimes salty, and the same kanji as painful.",
    ja: "このカレーは[辛い|からい]です。",
    en: "This curry is spicy." },
  "すごい|": {
    explain: "This is a native word, normally written in hiragana. It is the all-purpose wow word, for anything amazing, impressive, or intense. A great view, a friend's skill, a huge crowd, a surprising price. Here is an interesting history. In older Japanese, this word meant something eerie, frightening, or chilling, the kind of thing that makes your skin crawl. Over time, it shifted from scary intense to impressive intense, and now it is mostly positive. English did something similar with awesome and terrific, which once meant scary too. Two useful forms. First, before an adjective or verb, it becomes 「すごく」, meaning very or really, as in 「すごくおいしい」, really delicious. You learned that form back in lesson five. Second, people in casual speech often stretch it out for feeling, like 「すごーい」. In polite speech, 「すごいですね」 is a nice way to compliment someone. Careful: in formal writing, use 「とても」 instead of 「すごく」, since it sounds more proper. A way to remember it: your jaw drops, wow. So, from eerie to awesome, the go-to word for amazing.",
    ja: "{山田|やまだ}さんの{日本語|にほんご}は[すごい]です。",
    en: "Mr. Yamada's Japanese is amazing." },
  "ちかい|近い": {
    explain: "Look at the kanji. The stroke that wraps along the bottom left is a radical for moving along a road. You see it in lots of kanji about movement or distance. You know it from 「週|しゅう」, as in 「今週|こんしゅう」, this week, from 「遅い|おそい」, slow or late, and from 「遊ぶ|あそぶ」, to play. Inside sits a part that also appears in other kanji, but the key piece is the road. A way to remember it: something just a short walk down the road. Here the reading is native, 「ちか」, plus 「い」. The Chinese-origin reading is 「きん」. You will meet that soon in 「最近|さいきん」, recently, meaning near in time instead of space. Here is a grammar point people often miss. To say near something, use 「の近く|のちかく」, as in 「駅の近く|えきのちかく」, near the station. And to say A is close to B, use 「に」 or 「から」, like 「駅から近い|えきからちかい」, close to the station. The opposite is 「遠い|とおい」, far, which has the same road radical. So, a short way down the road: close.",
    ja: "{駅|えき}は[近い|ちかい]です。",
    en: "The station is close." },
  "いろいろ|": {
    explain: "This is usually written in hiragana, but it comes from 「色|いろ」, color, said twice. When written with kanji, the second half uses the repeat mark, the same mark you see in 「時々|ときどき」, sometimes. So the word is literally colors, colors. Many colors means many kinds, a variety. That is a lovely picture: a world full of different colors. Japanese has many words that repeat a sound like this to show plurality or variety. 「時々|ときどき」 is times, times, sometimes. And people, 「人々|ひとびと」, is person, person. Here is how to use it. Before a noun, add 「な」, as a na-adjective: 「いろいろな所|いろいろなところ」, various places. You can also use it as an adverb with 「と」 or alone, like 「いろいろとありがとう」, thanks for everything. A very common use is when someone asks what you did, and you answer 「いろいろ」, all sorts of things. A way to remember it: picture a box of crayons, every color a different kind of thing. So, colors repeated: all kinds of things.",
    ja: "[いろいろ]な{所|ところ}に{行きました|いきました}。",
    en: "I went to various places." },
  "しあわせ|幸せ": {
    explain: "The kanji means good fortune or blessing. Here it has the native reading, 「しあわせ」, with 「せ」 written in hiragana. The Chinese-origin reading is 「こう」, which you will meet in more formal words later. A bit of history: long ago, this word was written differently and meant how things come together, your circumstances or luck, good or bad. Over time it came to mean only good luck, and then the happy state that comes from it. Now look at the kanji next to 「辛い|からい」, spicy, from this same lesson, which also means painful. The happiness kanji has one extra horizontal line at the top. Japanese people love this: one more line turns pain into happiness. It is a coincidence of shape, but a great hook. Now the meaning. This is deep, lasting happiness, not a quick moment. Compare 「うれしい」, glad, which is a reaction to a good thing. You are 「うれしい」 when you get a gift. You are 「幸せ|しあわせ」 when your life, family, or relationship is good. It is a na-adjective, so 「幸せな家族|しあわせなかぞく」, a happy family. So, good fortune, and a kanji one stroke away from pain.",
    ja: "{私|わたし}は{今|いま}とても[幸せ|しあわせ]です。",
    en: "I am very happy now." },
  "だめ|": {
    explain: "This is usually written in hiragana or katakana. It is often said to come from the board game of Go. In Go, there are points between the two players' territories that count for neither side, useless spaces. Those were called by this word, and from there it spread to mean useless, no good. That is why the kanji used for it mean something like useless eye, and they are only a spelling for the sound. You will hear this word constantly in Japan. Parents say it to kids when something is not allowed, often doubled: 「だめだめ」. It covers several English ideas: no good, not allowed, does not work, hopeless. For not allowed, there is a key grammar pattern: verb te form plus 「は」 plus this word. For example, 「ここでたべてはだめです」, you can't eat here. It is a bit softer and more casual than 「いけません」. You can also say 「だめです」 to turn down an idea, or 「だめですか」 to ask if something is okay. A way to remember it: a useless spot on the game board, a dead end. So, from a useless Go point to the everyday word for no good.",
    ja: "ここでしゃしんをとっては[だめ]です。",
    en: "You can't take pictures here." },
  "あむ|編む": {
    explain: "Look at the left side of the kanji. It is the thread radical, a little twisted strand of silk. You have already seen it in 「紅茶|こうちゃ」, 「約束|やくそく」, and 「手紙|てがみ」. Here it makes perfect sense, because you knit with yarn. The right side helps give the sound in other words, so focus on the thread. In this verb the reading is native, 「あ」, with 「む」 in hiragana. It is a regular u verb, so the polite form is 「編みます|あみます」, and the te form is 「編んで|あんで」, just like 「読む|よむ」 becomes 「読んで|よんで」. The Chinese-origin reading, 「へん」, shows up later in words about editing, which is a kind of knitting together of writing. The objects that go with it are what you would expect: a 「セーター」, sweater, from this same lesson, a 「マフラー」, scarf, or gloves, 「手袋|てぶくろ」. Hand-knitting a scarf for someone you love is a classic romantic gesture in Japanese dramas and manga, especially in winter. A way to remember it: picture your hands looping thread, over and over. So, the thread radical, and the verb for making things out of yarn.",
    ja: "{母|はは}はマフラーを[編みました|あみました|あむ]。",
    en: "My mother knitted a scarf." },
  "がんばる|頑張る": {
    explain: "This might be the most Japanese word in the book. Let's look at the kanji first. 「頑|がん」 means stubborn or firm, with a Chinese-origin reading. 「張る|はる」 is a native verb meaning to stretch something tight, like a tent or a rope. Together you can picture it as stretching yourself tight and holding on stubbornly. That picture is a great memory aid, but be aware that the kanji spelling may have been fitted to the word, and scholars disagree about its exact origin. So treat the picture as a hook. Now the use. You say it all the time. Before an exam or a game, friends cheer you on with 「がんばって」, good luck, do your best. Politely, 「がんばってください」. When you promise to try hard, you say 「がんばります」. Teams and fans shout it at sports events. It is less about winning and more about effort and not giving up, which is a value Japanese culture honors. A common mistake: English speakers use good luck, which is about chance. Japanese focuses on your effort instead. So, stretch yourself tight and hang on: do your best.",
    ja: "{明日|あした}のしけん、[頑張ります|がんばります|がんばる]。",
    en: "I'll do my best on tomorrow's exam." },
  "なく|泣く": {
    explain: "Look at the kanji. On the left are three drops of water, the water radical. On the right is 「立|た」, from 「立つ|たつ」, to stand. A way to remember it: a person standing there with water running down their face, tears. That is a hook, but the water part really does fit, since crying is all about tears. The reading here is native, 「な」, with 「く」 in hiragana. It is a regular u verb, so it becomes 「泣きます|なきます」, and the te form is 「泣いて|ないて」, just like 「書く|かく」 becomes 「書いて|かいて」. A crying baby is 「赤ちゃんが泣いています|あかちゃんがないています」. Here is a common mistake. Animal sounds use the same sound, 「なく」, but a different kanji, 「鳴く|なく」, a mouth next to a bird. So a cat meowing, a bird singing, or an insect chirping, all use the bird one. People crying use the water one. Japanese also has a nice word for a crybaby, 「泣き虫|なきむし」, a crying bug. So, water plus standing: a person in tears.",
    ja: "{赤ちゃん|あかちゃん}が[泣いています|ないています|なく]。",
    en: "The baby is crying." },
  "みがく|磨く": {
    explain: "Look at the bottom of the kanji. It is 「石|いし」, stone. A way to remember it: polishing something by rubbing it with a stone, the way people once ground and smoothed things. The top part is a building shape with hemp plants inside, but the stone at the bottom is the piece to remember. The reading here is native, 「みが」, with 「く」 in hiragana. It is a regular u verb: 「磨きます|みがきます」, and the te form 「磨いて|みがいて」. In English, this word splits into two ideas. For teeth, it means to brush. For shoes, glass, or a car, it means to polish. In Japanese, it is the same verb, because both are about scrubbing a surface clean and shiny. The most common phrase is 「歯を磨く|はをみがく」, to brush your teeth, using 「歯|は」, tooth, which you learned in lesson twelve. A common mistake: English speakers sometimes use 「あらう」, to wash, for teeth. That sounds strange. Teeth get brushed, not washed. The verb is also used for polishing a skill, like practicing a lot. So, stone at the bottom, rubbing something until it shines.",
    ja: "{毎晩|まいばん}{歯|は}を[磨きます|みがきます|みがく]。",
    en: "I brush my teeth every night." },
  "やくそくをまもる|約束を守る": {
    explain: "This phrase has three parts. First, 「約束|やくそく」, a promise, from this same lesson, an agreement tied up like a bundle. Then 「を」, the object marker. Then the verb 「守る|まもる」, which on its own means to protect, to defend, or to guard. So the phrase is literally to guard a promise, keeping it safe so it does not break. Look at the kanji for guard. On top is a roof, the same roof you see in 「家|いえ」, house. Below is a part that is often linked to the hand. So a hand keeping things safe under a roof. That is a helpful picture, but treat it as a hook. The verb also shows up in a well-known cultural item: 「お守り|おまもり」, the little charms you buy at shrines and temples. They are meant to protect you, for safe travel, good health, or passing exams. The opposite phrase is 「約束をやぶる|やくそくをやぶる」, to break a promise, which literally means to tear it. You also use 「守る|まもる」 for rules: 「ルールを守る|ルールをまもる」, to follow the rules. So, guarding a promise so it stays whole: keeping your word.",
    ja: "{田中|たなか}さんはいつも[約束を守ります|やくそくをまもります|やくそくをまもる]。",
    en: "Mr. Tanaka always keeps his promises." },
  "かんどうする|感動する": {
    explain: "Two kanji, both with Chinese-origin readings, plus 「する」. The first, 「感|かん」, means feeling or sense. Look at its bottom: 「心|こころ」, heart. Like 「悲しい|かなしい」 from this same lesson, a feeling kanji with a heart underneath. The second kanji, 「動|どう」, means to move. On the right is 「力|ちから」, power. A way to picture it: moving things takes strength. You know this kanji from 「動物園|どうぶつえん」, zoo, a garden of moving things, animals, and from 「活動|かつどう」, activity. Put them together: your feelings move. English says the very same thing: to be moved or touched. It is a strong word, for when something really affects your heart. A great movie, a beautiful piece of music, a speech, a kind act, or a sports victory. Use 「に」 for the thing that moved you: 「その映画に感動しました|そのえいがにかんどうしました」, I was moved by that movie. Japanese TV and ads use this word a lot, promising a moving story. So, feeling plus moving: your heart is moved.",
    ja: "その{映画|えいが}に[感動しました|かんどうしました|かんどうする]。",
    en: "I was moved by that movie." },
  "〜かい|〜回": {
    explain: "This is a counter for the number of times something happens. Look at the kanji: a small box inside a bigger box. It is often described as something going around and around, and that matches its meaning of turning or circling. The native verb with this kanji is 「回る|まわる」, to go around. So each time is one round. The reading as a counter is the Chinese-origin 「かい」. Here are the numbers, with the sound changes to watch. One time is 「一回|いっかい」, with a small pause. Two times is 「二回|にかい」. Three is 「三回|さんかい」. Six becomes 「六回|ろっかい」, and ten becomes 「十回|じゅっかい」. How many times is 「何回|なんかい」. To say how often in a period, use 「に」: 「一日に三回|いちにちにさんかい」, three times a day, or 「一週間に二回|いっしゅうかんににかい」, twice a week. A common mistake is mixing this up with 「〜ど」, which you learned for degrees of temperature. That one can also count times, but this counter is the everyday choice. You may also hear 「今回|こんかい」, this time. So, a box going around, one round each time.",
    ja: "{一週間|いっしゅうかん}に[三回|さんかい|〜かい]{運動|うんどう}します。",
    en: "I exercise three times a week." },
  "〜キロ|": {
    explain: "This comes from kilo, a word part meaning one thousand. It was created for the metric system in France, built from a Greek word for thousand. A kilogram is a thousand grams, and a kilometer is a thousand meters. In everyday speech, both English and Japanese shorten them. English says kilos for weight. Japanese goes further and uses this one short word for both weight and distance. So 「五キロ|ごキロ」 can mean five kilometers or five kilograms. How do you know which? Context does the work. If you are talking about running, walking, or how far a place is, it is distance. If you are talking about your weight, a bag of rice, or luggage, it is weight. The sounds are simple: the k gets its vowel, the l becomes the Japanese r sound, and you get 「キロ」. Other metric words come through the same way, like 「メートル」, meter, and 「グラム」, gram. Japan uses metric, so you will hear this a lot. Distances on road signs and weights at the supermarket are all metric. So, kilo means a thousand, and context tells you if it is meters or grams.",
    ja: "{毎日|まいにち}[五キロ|ごキロ|〜キロ]はしります。",
    en: "I run five kilometers every day." },
  "ぜんぶ|全部": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「全|ぜん」, means whole or complete. You know it from 「全然|ぜんぜん」, not at all, which is literally wholly, completely, used with a negative. The second kanji, 「部|ぶ」, means part, section, or department. You know it hidden in 「部屋|へや」, room, where it has an unusual reading. Rooms are parts of a house. Put them together: the whole of the parts, every single part, all of it. A nice clear picture. You use this word for things, not usually for people. For all the people, Japanese prefers 「みんな」. That is a common mistake for English speakers. For example, 「全部食べました|ぜんぶたべました」, I ate all of it. Add 「で」 and it means in total. At a shop, the clerk might tell you the total by starting with 「全部で|ぜんぶで」, all together it comes to. You might also hear 「全部でいくらですか|ぜんぶでいくらですか」, how much is it all together. So, whole plus part: every part, the whole thing.",
    ja: "[全部|ぜんぶ]{食べました|たべました}。",
    en: "I ate all of it." },
  "〜ともうします|〜と申します": {
    explain: "This is a humble way to give your name. It is made of three parts. First, 「と」, the quoting particle, the same one you use with 「言う|いう」 to report what someone said. Then 「申します|もうします」, the polite form of 「申す|もうす」, which is a humble verb for to say. Humble means you lower yourself to show respect to the listener. So the phrase is literally I am humbly called, and it is a step more polite than 「といいます」. It shows up in specific situations: job interviews, business meetings, calling a company, speeches, or meeting your partner's parents. A typical line is 「わたくしは田中と申します|わたくしはたなかともうします」, my name is Tanaka. Notice it pairs naturally with 「わたくし」, the formal I, from this same lesson. Here is a common mistake. Never use this verb for someone else's name or words, because humble words are only for yourself and your own group. For other people you would use a respectful form instead. With friends, just say your name with 「です」. So, humbly saying your name, for your most polite moments.",
    ja: "{私|わたし}は{山田|やまだ}[と申します|ともうします|〜ともうします]。",
    en: "My name is Yamada." },
  "とくに|特に": {
    explain: "The kanji, 「特|とく」, means special or particular, with a Chinese-origin reading. Look at its parts. On the left is the cow radical, the same piece you see in 「牛乳|ぎゅうにゅう」, milk. On the right is 「寺|てら」, temple, the same kanji as in 「お寺|おてら」. A way to remember it: a special cow at the temple, standing out from the rest. That is a hook, not history. Then 「に」 makes the word an adverb, so it modifies a verb or a sentence. You use it to pick one thing out of a group. 「すしが好きです。特にまぐろが好きです|すしがすきです。とくにまぐろがすきです」. I like sushi, especially tuna. It also has a very useful negative use. When someone asks if you have a question or a request, you can answer 「特にないです|とくにないです」, nothing in particular. Compare 「別に|べつに」, from lesson seven, which can also mean nothing in particular. But 「別に|べつに」 can sound a little cold or uninterested, while this word sounds neutral and polite. So, a special cow at the temple: especially.",
    ja: "すしが{好き|すき}です。[特に|とくに]まぐろが{好き|すき}です。",
    en: "I like sushi. I especially like tuna." },
  "いちにち|一日": {
    explain: "Two simple kanji, both with Chinese-origin readings: 「一|いち」, one, and 「日|にち」, day. Together: one day, as a length of time. You use it for durations and rates, like 「一日に三回|いちにちにさんかい」, three times a day, or 「一日中|いちにちじゅう」, all day long, a word you will meet soon. Here is the big trap. The same two kanji, written exactly the same way, are also read 「ついたち」, which means the first day of the month, a date. That reading is very old. It is often traced to the idea of the moon rising, since old calendars started each month with the new moon. So when you see these two kanji, ask yourself: is this one day of time, or the first of the month? Listen and look at the context. The day kanji, 「日|にち」, is in many words you know: 「毎日|まいにち」, every day, 「日曜日|にちようび」, Sunday, and on its own as 「日|ひ」, day. A way to remember the split: counting one day is the plain number word, while the date has its own special name. So, one plus day: one day long.",
    ja: "[一日|いちにち]{三時間|さんじかん}べんきょうします。",
    en: "I study three hours a day." },
  "ふつか|二日": {
    explain: "From two to ten, Japanese uses old native numbers for days, not the Chinese-origin ones you use for counting money or time. The native two is 「ふた」. You know it from 「二つ|ふたつ」, two things, and 「二人|ふたり」, two people. Add 「か」, an old native word for days, and the sound shortens a little to 「ふつか」. This word has two jobs. It means two days, a length of time, and also the second day of the month, a date. Context tells you which. 「京都に二日いました|きょうとにふつかいました」 means I was in Kyoto for two days. Here is a family member you already know: 「二日酔い|ふつかよい」, hangover. It is literally drunk into the second day, the morning after. And you know 「二三日|にさんにち」, two or three days, which switches back to the Chinese-origin numbers. That is because it is a rough range, not one of the fixed day words. A way to remember it: the native two that gives you 「二つ|ふたつ」 also gives you two days. So, native two, plus the old day sound.",
    ja: "{京都|きょうと}に[二日|ふつか]いました。",
    en: "I was in Kyoto for two days." },
  "みっか|三日": {
    explain: "This uses the native Japanese three, 「み」. You know it from 「三つ|みっつ」, three things. Add the old native day sound 「か」, and a little pause slips in between, giving 「みっか」. That pause is the same one you hear in 「三つ|みっつ」. Like the other day words, it does double duty. It means three days, a length of time, and also the third day of the month, a date. Context will tell you which. Here is a fun expression with it: 「三日坊主|みっかぼうず」, a three day monk. It means someone who starts something, like a diet, a diary, or studying, and gives up after just three days. It comes from the idea of someone who becomes a monk but cannot stand the strict life and quits after three days. If you start a new habit, you can joke, I hope I don't become a three day monk. A way to remember it: three days is just long enough to quit. A related word for New Year: the first three days of January are a big holiday period in Japan, called 「三が日|さんがにち」, which uses the Chinese-origin three instead. So, native three plus the day sound.",
    ja: "かぜで[三日|みっか]{休みました|やすみました}。",
    en: "I was off for three days with a cold." },
  "よっか|四日": {
    explain: "This uses the native Japanese four, 「よ」. You know it from 「四つ|よっつ」, four things. Add the old native day sound 「か」, and a little pause slips in, giving 「よっか」, just like 「よっつ」. Like the other day words, it means four days as a length of time, and also the fourth day of the month as a date. Here is the big trap. It sounds a lot like 「八日|ようか」, eight days, or the eighth of the month. The difference is tiny but important. Four has a short 「よ」 and then a small pause, 「よっか」. Eight has a long vowel, 「よう」, and no pause, 「ようか」. If you make a date with a friend and mix them up, you will show up four days off. So when you hear it, listen for the pause or the long vowel. A way to remember it: four is short and choppy, with a little stop in it, while eight is stretched out long and smooth. So, native four, with a pause, not to be confused with eight.",
    ja: "{旅行|りょこう}は[四日|よっか]です。",
    en: "The trip is four days." },
  "いつか|五日": {
    explain: "This uses the native Japanese five, 「いつ」. You know it from 「五つ|いつつ」, five things. Add the old native day sound 「か」, and you get 「いつか」. Like the other day words, it means five days as a length of time, and also the fifth day of the month as a date. Now here is a fun coincidence. 「いつか」 also means someday, sometime, built from 「いつ」, when, plus 「か」, the question particle. So the same sound means the fifth day and someday. They are different words that happen to sound the same. In writing, the date one uses kanji, while someday is usually in hiragana. You can tell them apart from the sentence. 「五日に会いましょう|いつかにあいましょう」 is let's meet on the fifth. But 「いつか行きたいです|いつかいきたいです」 is I want to go someday. A way to remember it: someday, you will remember the fifth. Also note the native counting pattern: 「一つ|ひとつ」, 「二つ|ふたつ」, 「三つ|みっつ」, 「四つ|よっつ」, 「五つ|いつつ」. The day words follow those same native numbers. So, native five, and it sounds just like someday.",
    ja: "[五日|いつか]{東京|とうきょう}にいました。",
    en: "I was in Tokyo for five days." },
  "むいか|六日": {
    explain: "This uses the native Japanese six, 「む」. You know it from 「六つ|むっつ」, six things. Then comes 「いか」 instead of the plain 「か」 you heard in the earlier days. That extra 「い」 is just part of how this word settled over time, so learn it as a set. Like the other day words, it means six days as a length of time, and also the sixth day of the month as a date. Here is the full native pattern so far: 「二日|ふつか」, 「三日|みっか」, 「四日|よっか」, 「五日|いつか」, 「六日|むいか」. Notice how each one starts with the native number from the counting set 「ふたつ」, 「みっつ」, 「よっつ」, 「いつつ」, 「むっつ」. The day words are like cousins of those numbers. A way to remember the odd 「い」: the ending 「いか」 sounds just like the Japanese word for squid. Picture a squid waiting patiently for six days. It is a silly picture, but it holds the sound. So, native six, with an extra 「い」 before the day sound.",
    ja: "[六日|むいか]{雨|あめ}がふりました。",
    en: "It rained for six days." },
  "なのか|七日": {
    explain: "This uses the native Japanese seven, 「なな」, which you know from 「七つ|ななつ」, seven things. In the day word, the second sound softens to 「なの」, and then the day sound 「か」 is added, giving 「なのか」. You may sometimes hear an older form, 「なぬか」, but 「なのか」 is the standard one today. Like the other day words, it means seven days as a length of time, and also the seventh day of the month as a date. Seven days, of course, make a week, 「一週間|いっしゅうかん」. Here is a nice cultural note. In Japan, the seventh of July is the star festival, 「七夕|たなばた」, when people write wishes on strips of paper and hang them on bamboo. It celebrates two star lovers who can meet only once a year. It is written with the seven kanji, but has its own special reading. Now look at the whole set you are learning: 「ふつか」, 「みっか」, 「よっか」, 「いつか」, 「むいか」, 「なのか」, and then 「ようか」, 「ここのか」, and 「とおか」. All native numbers. A way to remember it: seven days, one full week, 「なのか」. So, native seven, softened to 「なの」, plus the day sound.",
    ja: "{一週間|いっしゅうかん}は[七日|なのか]です。",
    en: "One week is seven days." },
  "ようか|八日": {
    explain: "Look at the two kanji first. 「八|はち」 is eight, and 「日|ひ」 is day or sun. But neither kanji uses its usual reading here. Instead, the word is built from the old native Japanese way of counting. The native eight is 「や」, the same sound you hear in 「八つ|やっつ」, eight things. Long ago this word was something like 「やうか」, and over time that 「やう」 smoothed out into the long 「よう」 sound you hear today. The 「か」 at the end is the native word for days, the same 「か」 you find in 「三日|みっか」 and 「五日|いつか」. This one word does two jobs. It can mean a length of time, eight days, or a date, the eighth of the month. The big trap is its neighbor four days, 「四日|よっか」. They sound very close, so listen for the long 「よう」 in eight versus the short, clipped 「よっ」 in four. A way to remember it: eight is the bigger number, so it gets the longer, stretched-out sound. To recap, native eight plus native days, with a long vowel that keeps it apart from four.",
    ja: "[八日|ようか]{旅行|りょこう}しました。",
    en: "I traveled for eight days." },
  "ここのか|九日": {
    explain: "The kanji are 「九|く」 nine and 「日|ひ」 day, but the word skips their usual readings and uses the old native Japanese count instead. The native nine is 「ここの」, which you already know from 「九つ|ここのつ」, nine things. Drop the 「つ」, add 「か」, the native word for days, and you get this word. That same 「か」 shows up all through the set: 「二日|ふつか」, 「三日|みっか」, 「八日|ようか」. Like the others, it works two ways. It can be a length of time, nine days, or a date, the ninth of the month. It is the longest of the native day words, four full beats, so give each beat its time. Do not confuse it with the Chinese-origin nine, 「九|きゅう」 or 「く」, which you use for clock times like 「九時|くじ」, nine o'clock. Those readings never appear in this word. A way to remember it: 「ここの」 sounds a bit like the word for here, 「ここ」, so picture yourself staying right here for nine days. To recap, native nine plus native days, four beats long.",
    ja: "{手紙|てがみ}は[九日|ここのか]かかりました。",
    en: "The letter took nine days." },
  "とおか|十日": {
    explain: "「十|じゅう」 is ten and 「日|ひ」 is day, but again the word uses the old native count. The native ten is 「とお」, the word you use for ten things. So when you count objects, one through ten, you finish with 「とお」, and this word is just that ten plus 「か」 for days. Spell it with 「お」, a long 「とお」, not a short one. This is where the native day words stop. From eleven on, you switch to the Chinese-origin numbers plus 「日|にち」, as in 「十一日|じゅういちにち」, eleven days or the eleventh. There are just a few leftovers from the native set. The fourteenth is 「十四日|じゅうよっか」, which reuses the native four days. And the twentieth is the special word 「二十日|はつか」. Like the other day words, it works for both a length of time and a date, so 「十日|とおか」 is ten days or the tenth of the month. A way to remember it: 「とお」 sounds a little like toe, and you have ten toes. To recap, native ten plus days, and the last stop on the native day train.",
    ja: "[十日|とおか]{日本|にほん}にいます。",
    en: "I will be in Japan for ten days." },
  "おくさん|奥さん": {
    explain: "The kanji 「奥|おく」, with its native reading, means the deep inside, the far back of a space. You can say the back of a room or the depths of a forest with the same kanji. In old Japan, the wife of a samurai or a lord lived and ran the household in the inner rooms at the back of the home, and people came to call her by that place, the one in the back. Add polite 「さん」 and you get the everyday word for someone else's wife. Here is the key rule. Use this word for other people's wives, like 「田中さんの奥さん|たなかさんのおくさん」, Mr. Tanaka's wife. When you talk about your own wife, you humble her, and say 「妻|つま」. There is an even more formal version, 「奥様|おくさま」, which you will hear in shops and on TV. Many people today find the idea of the wife in the back a bit old fashioned, so you may also hear neutral words like 「パートナー」. A way to remember it: think of the inner rooms, the heart of the home. To recap, the person of the inner house, for someone else's wife.",
    ja: "{山田|やまだ}さんの[奥さん|おくさん]は{先生|せんせい}です。",
    en: "Mr. Yamada's wife is a teacher." },
  "ごしゅじん|ご主人": {
    explain: "Break it into three pieces. First, the polite 「ご」 that goes in front of Chinese-origin words, as in 「ご飯|ごはん」. Then 「主|しゅ」, with its Chinese-origin reading, which means master, owner, or main. The kanji looks like a lamp with a flame on top, and you can picture the head of the house as the light at the center. That part is a hook, not a history. Last is 「人|じん」, person, read the same way as in 「外国人|がいこくじん」, foreigner, and 「有名人|ゆうめいじん」, celebrity. Put together, the master of the house. With 「ご」, it means someone else's husband: 「ご主人はお元気ですか|ごしゅじんはおげんきですか」, how is your husband. Without the 「ご」, 「主人|しゅじん」 is what many women still say for their own husband, though younger people often prefer 「夫|おっと」, which has no master idea in it. It pairs naturally with 「奥さん|おくさん」, someone else's wife. You may also hear 「主人|しゅじん」 used for the owner of a shop or an inn. To recap, polite 「ご」, plus master, plus person: the master of someone else's house.",
    ja: "[ご主人|ごしゅじん]はお{元気|げんき}ですか。",
    en: "How is your husband?" },
  "パートナー|": {
    explain: "This comes straight from English partner, and it is a nice example of how English gets squeezed into Japanese sounds. English has an r sound after the vowel in both halves, part and ner. Japanese drops those r sounds and stretches the vowel instead, which is what the long marks 「ー」 are doing. So part becomes 「パー」, and the ending ner becomes 「ナー」. The t in the middle cannot sit on its own, so it picks up an extra vowel and becomes 「ト」. You will see the same pattern in 「セーター」, sweater, where the r ending also turns into a long vowel. In meaning, it is a lot like English. It can be a business partner, a dance partner, or the person you share your life with, married or not. In recent years many people use it as a neutral, modern way to talk about a spouse, instead of 「主人|しゅじん」 or 「奥さん|おくさん」, which carry old ideas of master and inner house. It works for any gender. To recap, English partner, with the r sounds turned into long vowels, and a nice neutral word for your other half.",
    ja: "{私|わたし}の[パートナー]はアメリカ{人|じん}です。",
    en: "My partner is American." },
  "おじさん|": {
    explain: "This word has two jobs. In the family, it is your uncle, your mother's or father's brother, or an aunt's husband. Outside the family, it is what children and young people call any man who looks middle aged, a bit like saying mister. A kid might point at a stranger and say 「あのおじさん」, that man over there. The big trap for English speakers is vowel length. With a short 「じ」, it is uncle. Stretch it to 「おじいさん」, and you have just called him grandfather, or an old man, which he will not enjoy. The same pattern shows up in its partner word: 「おばさん」, aunt, and 「おばあさん」, grandmother. When you write it in kanji, there are actually two spellings, depending on whether the uncle is older or younger than your parent, but in speech it is all the same word. Like other family words, add 「さん」 when talking about him politely. A way to remember it: short vowel, younger man; long vowel, older man. The longer the sound, the longer he has lived. To recap, uncle or a middle aged man, and keep that vowel short.",
    ja: "[おじさん]は{東京|とうきょう}にすんでいます。",
    en: "My uncle lives in Tokyo." },
  "おばさん|": {
    explain: "This is the female partner of 「おじさん」. In the family, it is your aunt, your mother's or father's sister, or an uncle's wife. Outside the family, it is what children call any woman who looks middle aged, like ma'am or lady. A child in a shop might say 「おばさん、これください」. The trap is the same as with uncle: vowel length. With a short 「ば」, it means aunt. Stretch it to 「おばあさん」, and you have just called her grandmother, or an old woman. Be a little careful with this word in real life. For a woman who is not a relative, being called this by an adult can sting, a bit like being told she looks old, so many adults avoid it and use polite words like 「すみません」 to get attention instead. With children, though, it is perfectly normal and warm. You might also hear it in a funny way, when a woman jokes that she is already 「おばさん」. A way to remember it: short vowel, younger woman; long vowel, older woman. To recap, aunt or a middle aged woman, with a short 「ば」 and a bit of care when you use it.",
    ja: "[おばさん]がセーターをあんでくれました。",
    en: "My aunt knitted me a sweater." },
  "りょうしん|両親": {
    explain: "Two kanji, both read with their Chinese-origin readings. 「両|りょう」 means both, a pair, the two sides. 「親|しん」 means parent, and also close or intimate. You already know that kanji by itself with its native reading, 「親|おや」, parent. You also know it in 「親切|しんせつ」, kind, which is about being close and warm to someone, and in 「親せき|しんせき」, relatives, the people close to you by blood. So the word is literally both parents, mother and father together. Use it plain like this for your own parents when you talk to other people: 「両親は東京にいます|りょうしんはとうきょうにいます」, my parents are in Tokyo. For someone else's parents, add the polite 「ご」 and say 「ご両親|ごりょうしん」. Note that this word is a bit formal and written in feel. In casual chat with friends, people often just say 「親|おや」. And when you talk about each parent separately, you use 「父|ちち」 and 「母|はは」. A way to remember it: picture a pair of scales with mother on one side and father on the other. To recap, both plus parent: your mom and dad as a pair.",
    ja: "[両親|りょうしん]に{電話|でんわ}をかけました。",
    en: "I called my parents." },
  "おおやさん|大家さん": {
    explain: "Both kanji use their native readings here, which is the trick. 「大|おお」 is big, as in 「大きい|おおきい」. 「家|や」 is house or home. You know that kanji with other readings too: 「家|いえ」 as house by itself, and 「か」 in 「家族|かぞく」, family, and 「家具|かぐ」, furniture. Here it takes the short native 「や」. The same 「や」 sound shows up in shop words like 「本屋|ほんや」, bookstore, though that one is written with a different kanji. Put together, the big house, meaning the person who owns the building you live in. Add polite 「さん」, because this is someone you deal with face to face. In Japan, a landlord or landlady may live right next door to the apartment, and renting often involves a cultural surprise for foreigners: some places ask for a thank-you gift of money to the owner when you move in, called key money. A small gift of sweets when you first meet your landlord is also a nice gesture. A way to remember it: picture the owner living in the big house, while you rent the little room. To recap, big plus house, read the native way, plus 「さん」: the owner of your home.",
    ja: "[大家さん|おおやさん]はやさしいです。",
    en: "My landlord is kind." },
  "みなさん|皆さん": {
    explain: "The kanji 「皆|みな」, with its native reading, means all or everybody. Add polite 「さん」, the same one you put after names, and you get a respectful way to address a whole group at once. You hear it at the start of almost every speech, class, or announcement: 「皆さん、こんにちは|みなさん、こんにちは」, hello, everyone. You already know its casual cousin, 「みんな」, from 「みんなで」, all together. 「みんな」 is simply a relaxed form of 「みな」, so the two are really the same word wearing different clothes. Use 「みんな」 with friends, 「みなさん」 with a group you want to be polite to, and the even more formal 「皆様|みなさま」 in very polite settings, like an airline announcement. One common mistake: English speakers sometimes put 「さん」 on themselves or their own group. You never include yourself when you say 「みなさん」. It always means all of you, the people you are speaking to. A way to remember it: 「さん」 makes it a polite word aimed outward, at the audience. To recap, all plus polite 「さん」, the go-to greeting for a whole room.",
    ja: "[皆さん|みなさん]、おはようございます。",
    en: "Good morning, everyone." },
  "チョコレート|": {
    explain: "This is English chocolate, run through Japanese sounds. English squeezes chocolate into two or three quick syllables, but Japanese gives each consonant its own vowel. So choc becomes 「チョコ」, and the ending late becomes 「レート」, with a long vowel and an extra o sound after the t, since a t cannot sit alone. That turns a short English word into six beats. In daily life, people very often cut it back down to just 「チョコ」. The big cultural note is Valentine's Day. In Japan, women traditionally give chocolate to men. There is 「本命|ほんめい」 chocolate, for the person you really like, and 「義理|ぎり」 chocolate, obligation chocolate, for coworkers and classmates. You may also hear about friend chocolate given between girls. Then a month later, on 「ホワイトデー」, men are expected to give a return gift. Department stores have huge chocolate fairs every February. A way to remember it: the word is long and luxurious, like a big box of chocolates, but in a hurry you just grab a 「チョコ」. To recap, English chocolate with extra vowels, the star of February in Japan.",
    ja: "バレンタインデーに[チョコレート]をあげました。",
    en: "I gave chocolate on Valentine's Day." },
  "みかん|": {
    explain: "This is usually written in kana, but it does have kanji: 「蜜柑|みかん」. The first kanji means honey, and the second means citrus fruit. So the name is basically honey citrus, which suits this small, sweet, easy-to-peel orange. In English it is often called a satsuma, after Satsuma, an old province in the south of Japan, which shows how closely the fruit is linked to the country. It is the classic Japanese winter fruit. The famous picture is a family sitting at a 「こたつ」, a low table with a heater under it and a blanket over it, with a basket of these oranges on top. People eat so many in winter that some say their fingers turn a little yellow. You also see them at New Year's, in 「お正月|おしょうがつ」 decorations. They are counted with 「〜こ」 as small items: 「みかんを三個|みかんをさんこ」, three oranges. A way to remember it: picture a cozy winter night, the heater on, and a sweet orange in your hand. To recap, honey citrus, the sweet orange of a Japanese winter at the 「こたつ」.",
    ja: "{冬|ふゆ}は[みかん]がおいしいです。",
    en: "Mandarin oranges are tasty in winter." },
  "シャツ|": {
    explain: "This comes from English shirt, and the changes are easy to hear. English has an r sound in the middle, as in sh-ir-t. Japanese simply drops that r. The sh sound is fine, so it becomes 「シャ」. The final t cannot stand on its own in Japanese, and English t sounds before a u vowel turn into 「ツ」, so the ending is 「ツ」. Two short beats, and you have the word. In Japanese, it is a broad word for shirts in general, and you will see it in compounds. Put the letter T in front and you get a T-shirt, 「ティーシャツ」. There is also a word you might not guess: 「ワイシャツ」, a dress shirt, which comes from white shirt, because office shirts used to be white. A shirt is something you wear on your upper body, so you use the verb for upper-body clothes, 「着る|きる」, to put it on, not 「はく」, which is for pants and shoes. A way to remember it: the word is just as short and plain as a basic shirt. To recap, English shirt, with the r dropped and the t turned into 「ツ」.",
    ja: "{白い|しろい}[シャツ]を{買いました|かいました}。",
    en: "I bought a white shirt." },
  "ネクタイ|": {
    explain: "This is English necktie, and you can hear both halves clearly. Neck becomes 「ネク」, with an extra vowel after the k, since a k cannot stand alone at the end of a syllable in Japanese. Tie becomes 「タイ」. Stick them together and you get four short beats. Note that Japanese keeps the full word necktie, where English speakers mostly just say tie today. That is common with loanwords: Japanese often keeps an older or fuller form of the English word. You put it on with the verb 「する」, as in 「ネクタイをする」, wear a tie. In Japan, the necktie is part of the classic salaryman look with a dark suit, though in summer many offices now follow a cool business style, with no jacket and no tie, to save air conditioning. It is also a very common gift for fathers, bosses, and on Father's Day, a bit like in the West. A way to remember it: neck plus tie, the thing you tie around your neck. To recap, English necktie, kept whole, with an extra vowel after neck.",
    ja: "{父|ちち}に[ネクタイ]をあげました。",
    en: "I gave my father a necktie." },
  "マフラー|": {
    explain: "This comes from the English word muffler. In English today, a muffler usually means the part of a car that quiets the engine, but it is also an old word for a warm scarf that muffles your neck against the cold. Japanese uses it in both senses, but in daily life it is almost always the winter scarf. Here is how the sounds shift. The English uh vowel becomes 「ア」, so muff becomes 「マフ」. The ending ler has an l and an r, and Japanese uses its r family sound for both, 「ラ」, and then stretches the vowel because of that final r, giving 「ラー」. A lighter summer or fashion scarf is a different word, 「スカーフ」, so this one is specifically the thick, cozy kind. You put it on with 「する」, as in 「マフラーをする」. Another nice cultural note: hand-knitting a scarf for someone you love is a classic romantic gift in Japanese dramas and manga. A way to remember it: the scarf muffles the cold wind. To recap, English muffler, l and r both turned into 「ラ」, meaning your winter scarf.",
    ja: "{寒い|さむい}から、[マフラー]をします。",
    en: "It's cold, so I'll wear a scarf." },
  "ゆびわ|指輪": {
    explain: "Both kanji use their native readings, and the meaning is easy to see once you split it. 「指|ゆび」 means finger. Look at the left side of the kanji: it has the hand shape, the same piece you see in many action kanji like 「持つ|もつ」, to hold. 「輪|わ」 means ring, loop, or wheel. Look at its left side, and you will find the kanji 「車|くるま」, car, which reminds you of a wheel going round. So the word is literally finger loop, a ring for your finger. The 「輪|わ」 kanji also shows up in other round things, like the Olympic rings. This is a real word for jewelry, so it is often a gift: an engagement ring after a 「プロポーズ」, or a wedding ring at a 「結婚式|けっこんしき」, wedding. To wear a ring, you use 「する」, as in 「指輪をする|ゆびわをする」. A way to remember it: picture your finger, 「ゆび」, poking through a little wheel, 「わ」. To recap, finger plus loop: a ring on your hand, with both parts read the native way.",
    ja: "プロポーズのとき、[指輪|ゆびわ]をもらいました。",
    en: "I got a ring when he proposed." },
  "えんぴつ|鉛筆": {
    explain: "Both kanji use Chinese-origin readings. 「鉛|えん」 means lead, the soft gray metal. Look at the left side: it is the metal piece, the same one you see in 「お金|おかね」, money, and in 「銀行|ぎんこう」, bank. 「筆|ひつ」 means writing brush. Look at the top: it has the bamboo piece, because traditional brushes have bamboo handles. So the word is literally a lead brush, a writing tool with lead inside. Fun fact: modern pencils actually contain graphite, not lead, but the name stuck in both English and Japanese. Notice the sound change. On its own, brush is 「ひつ」, but after the 「ん」 sound it becomes 「ぴつ」. Japanese often does this, turning an h sound into a p sound after 「ん」 or a small 「っ」. You can see the same pattern with the counter for long things: 「一本|いっぽん」, one pencil, which is exactly how you count these. A way to remember it: the metal piece on the left of the first kanji, and the bamboo hat on top of the second. To recap, lead plus brush, with 「ひつ」 popping into 「ぴつ」 after 「ん」.",
    ja: "[鉛筆|えんぴつ]で{名前|なまえ}を{書いて|かいて}ください。",
    en: "Please write your name with a pencil." },
  "ぬいぐるみ|": {
    explain: "This is a native Japanese word, and it is built from two verbs. The first is 「ぬう」, to sew, which turns into 「ぬい」 when it joins another word. The second is 「くるむ」, to wrap something up, which softens into 「ぐるみ」. So the word is literally sewn and wrapped, a soft toy made by sewing fabric around stuffing. It is sometimes written with the kanji for sew, but kana is far more common. The same 「ぐるみ」 ending shows up in a fun related word, 「着ぐるみ|きぐるみ」, the big mascot costumes that people wear at theme parks and events, literally a wrap you wear. Japan loves mascot characters, and you will see their stuffed versions everywhere, from game centers to train station shops. Claw crane machines full of these toys are a classic sight in Japanese arcades. It is a common gift for children, and also for adults, especially as a cute souvenir. A way to remember it: picture someone sewing, 「ぬい」, and then wrapping a bear up snugly, 「ぐるみ」. To recap, sew plus wrap: a soft toy sewn up around its stuffing.",
    ja: "{妹|いもうと}に[ぬいぐるみ]をあげました。",
    en: "I gave my little sister a stuffed animal." },
  "まんが|漫画": {
    explain: "Both kanji use Chinese-origin readings. 「画|が」 means picture or drawing, and you already know it from 「映画|えいが」, a movie, which is literally a projected picture. 「漫|まん」 means loose, casual, wandering, going wherever it likes. Look at its left side, the water piece, which suits something that spreads and flows freely. So the word is something like free, rambling pictures, drawings done for fun rather than serious art. The famous woodblock artist Hokusai used this word for his sketchbooks in the early 1800s, full of people, animals, and funny scenes. Today it means comics, from children's books to huge adventure series read by adults on the train. You also know 「漫画家|まんがか」, cartoonist, which adds 「家|か」, an expert or professional, as in 「作家|さっか」, writer. In English, the word manga has become a loanword itself, meaning Japanese style comics specifically. In Japanese it covers comics from any country. A way to remember it: water flowing freely, and pictures flowing freely across the page. To recap, free, rambling plus picture: comics.",
    ja: "{毎晩|まいばん}[漫画|まんが]を{読みます|よみます}。",
    en: "I read comic books every night." },
  "けしょうひん|化粧品": {
    explain: "Three kanji, all with Chinese-origin readings. 「化|け」 means change or transform. Its usual reading is 「か」, as in 「文化|ぶんか」, culture, but in this word it takes the less common reading 「け」. The same kanji appears in 「お化け|おばけ」, a ghost, something that has transformed. 「粧|しょう」 means to adorn or dress up. Together, 「化粧|けしょう」 means makeup, literally transform and adorn yourself. You will hear it on its own too: 「化粧をする|けしょうをする」, to put on makeup. Then 「品|ひん」 means goods or products. The kanji is three little boxes stacked up, which is a nice hook for a pile of goods. You will see it in many shopping words, like food products or electronic products on store signs. So the whole word is makeup goods, everything from lipstick to skin cream. Japanese drugstores have huge cosmetics sections, and Japanese skin care is very popular with visitors, so this is a useful word for shopping. A way to remember it: picture a ghost, 「お化け|おばけ」, transforming into a beauty with a pile of products. To recap, transform plus adorn plus goods: cosmetics.",
    ja: "{母|はは}に[化粧品|けしょうひん]を{買いました|かいました}。",
    en: "I bought cosmetics for my mother." },
  "ラジオ|": {
    explain: "This is from English radio, and the vowels tell the story. English says ray-dee-oh. Japanese does not use the ray sound here, and keeps a simple short 「ラ」. The d sound before an ee vowel turns into 「ジ」, the way 「ディ」 used to be hard for older Japanese to say. So you get three short beats. Japanese also uses the English l and r sounds the same, as one r family sound, which is why this starts with 「ラ」. Japan has a famous radio tradition called 「ラジオ体操|ラジオたいそう」, radio exercises. It began in 1928. Every morning, a simple piano tune plays on the radio, and people all over the country do the same set of stretches. In summer vacation, many children gather in a local park early in the morning to do them together and get a stamp on a card. Many companies and older people still do them every day. A way to remember it: hear that cheerful morning piano and picture a whole park stretching in time. To recap, English radio, with a short 「ラ」 and 「ジ」 in the middle, and a country that exercises to it.",
    ja: "{毎朝|まいあさ}[ラジオ]を{聞きます|ききます}。",
    en: "I listen to the radio every morning." },
  "おさら|お皿": {
    explain: "「皿|さら」 is a native reading, and the kanji is a picture you can still see. It looks like a dish or bowl seen from the side, sitting on a low stand. Put the polite 「お」 in front, the same one you see in 「お茶|おちゃ」, tea, and 「お酒|おさけ」, alcohol. Food and kitchen words often take this 「お」, and it makes the word sound softer and nicer. Without the 「お」, you will still hear 「皿|さら」 in compounds and in casual speech. The word covers plates, dishes, and saucers, and it can also mean a serving of food, a plateful. You can count dishes with native numbers, like 「一皿|ひとさら」, one plate. A useful phrase from daily life is 「お皿を洗う|おさらをあらう」, to wash the dishes. In Japanese homes, each person often has their own rice bowl and chopsticks, but plates are shared for side dishes. A way to remember it: look at the kanji and see the flat dish sitting on its little stand, ready for food. To recap, a picture of a dish, plus polite 「お」: plates and dishes.",
    ja: "[お皿|おさら]を{洗いました|あらいました}。",
    en: "I washed the dishes." },
  "おかえし|お返し": {
    explain: "This comes from a verb you already know, 「返す|かえす」, to return something. Take its stem, 「返し|かえし」, and add the polite 「お」, and you get a noun, the thing you give back. The kanji has the road piece along the bottom left, the same one you see in 「送る|おくる」, to send. Both are about something moving along a road, sent out or sent back. You also know the same kanji with its Chinese-origin reading in 「返事|へんじ」, a reply, an answer sent back. In Japanese culture, gift giving is a two way street. When someone gives you a present, it is polite to give something back later, an 「お返し|おかえし」, to show thanks. The famous example is 「ホワイトデー」, when men return Valentine's chocolates. For gifts at weddings or funerals, there is even a custom of returning something worth about half the original gift. It is also used for revenge in a joking way: getting someone back. A way to remember it: what goes down the road comes back up the road. To recap, polite 「お」 plus return: a thank-you gift sent back.",
    ja: "ホワイトデーに[お返し|おかえし]をあげました。",
    en: "I gave a return gift on White Day." },
  "りれきしょ|履歴書": {
    explain: "Three kanji, all Chinese-origin readings. 「履|り」 means to step on, or to put on footwear. You know a related native word, 「はく」, to put on items below your waist, which is often written with this kanji when it means shoes. Then 「歴|れき」 means history, things that have passed, as in the word for history, 「歴史|れきし」. Together, 「履歴|りれき」 is the path you have walked, your personal history. It is also used for things like your browser history. Last, 「書|しょ」 is writing or document, the same kanji as in 「辞書|じしょ」, dictionary, 「教科書|きょうかしょ」, textbook, and 「書く|かく」, to write. So the whole word is a document of the path you have walked. Japanese résumés are a bit different from Western ones. They usually follow a fixed form you can buy at a convenience store, with boxes for your education and work history, and a small ID photo glued in the corner. Some companies still prefer them handwritten. A way to remember it: picture footprints walking across a page. To recap, footsteps plus history plus document: your résumé.",
    ja: "[履歴書|りれきしょ]を{送りました|おくりました}。",
    en: "I sent my résumé." },
  "クリスマス|": {
    explain: "This is English Christmas, and the changes are clear. English starts with a cluster, chr, and Japanese splits it up with an extra vowel, giving 「クリ」. The t in the middle is silent in English too, so it disappears. Then mas becomes 「マス」, with an extra vowel at the end, since Japanese words do not end in s. Five short beats in total. The holiday itself took on a very different shape in Japan. It is not a religious or family holiday for most people, and it is not a day off work. Instead, Christmas Eve is a romantic night for couples, a bit like Valentine's Day in the West. Families often eat a Christmas cake, usually a white sponge cake with whipped cream and strawberries. And since the 1970s, a fried chicken chain made eating fried chicken a Christmas tradition, so people order buckets weeks in advance. The big family holiday comes a week later, with 「お正月|おしょうがつ」, New Year's. A way to remember it: picture a strawberry cake and a bucket of chicken under the lights. To recap, English Christmas with extra vowels, and a date night in Japan.",
    ja: "[クリスマス]にケーキを{食べます|たべます}。",
    en: "I eat cake at Christmas." },
  "バレンタインデー|": {
    explain: "This is English Valentine's Day, and it shows several sound changes at once. Japanese has no v sound in its basic set, so v becomes b: 「バ」. The l becomes Japanese r: 「レ」. Then tine becomes 「タイン」, and day becomes 「デー」, with a long vowel instead of the English glide. You can see the same day ending in 「ホワイトデー」. The custom is Japan's own twist. On February 14, women give chocolate to men. There is 「本命|ほんめい」 chocolate, often handmade, for someone you truly love, and 「義理|ぎり」 chocolate, obligation chocolate, for coworkers, bosses, and classmates. Friends also swap chocolates with each other. Chocolate companies promoted the day heavily from the 1950s onward, and it became a huge season for sweet shops. Then, one month later, men return the favor. Some offices have started banning obligation chocolate, since buying for everyone gets expensive. A way to remember it: in Japan, the arrow of love flies from women to men on this day, and comes back a month later. To recap, English Valentine's Day, v to b and l to r, and women give the chocolate.",
    ja: "[バレンタインデー]にチョコレートをあげました。",
    en: "I gave chocolate on Valentine's Day." },
  "ホワイトデー|": {
    explain: "This looks English, but it was made in Japan. English speakers do not have a White Day. It is built from English white, squeezed into 「ホワイト」, and day, 「デー」, with a long vowel, the same ending as in 「バレンタインデー」. Notice how white becomes 「ホワイト」: the w sound gets a 「ホ」 before it, and the final t gets an extra vowel. On March 14, exactly one month after Valentine's Day, men give a return gift, an 「お返し|おかえし」, to the women who gave them chocolate. Japanese candy and sweet makers started promoting it around 1980, and the name may come from white sweets like marshmallows and white chocolate. Popular gifts are cookies, candy, or white chocolate. There is a joking rule called three times return, meaning a man should give back something worth about three times the chocolate he got. The day has spread to some other countries in East Asia. A way to remember it: Valentine's is dark chocolate going out, and a month later the white sweets come back. To recap, made in Japan from white plus day, the day men give back.",
    ja: "[ホワイトデー]は{三月|さんがつ}{十四日|じゅうよっか}です。",
    en: "White Day is March fourteenth." },
  "ほしい|欲しい": {
    explain: "The kanji 「欲|よく」 means desire or greed, and here it is read with its native reading, 「ほ」, plus 「しい」. The word works like an i-adjective, not a verb, even though the English is to want. That is the key to using it. The thing you want is marked with 「が」, because you are describing it as wanted: 「車が欲しいです|くるまがほしいです」, I want a car. You can also see the same pattern in other feelings words, like 「好き|すき」, where the thing you like takes 「が」. It changes like any i-adjective: 「欲しくない|ほしくない」, I do not want it, and 「欲しかった|ほしかった」, I wanted it. Two common mistakes. First, this is for wanting things, nouns. For wanting to do something, use the 「たい」 form instead, like 「食べたい|たべたい」, I want to eat. Second, it describes your own feelings. Japanese avoids stating what is inside someone else's head, so for others you use other forms you will learn later. Also, asking a teacher if they want something with this word can sound too direct. To recap, desire as an adjective: the thing you want takes 「が」.",
    ja: "{新しい|あたらしい}{車|くるま}が[欲しい|ほしい]です。",
    en: "I want a new car." },
  "おしゃれ|": {
    explain: "This is a 「な」-adjective. Put 「な」 before a noun, as in 「おしゃれなシャツ」, a stylish shirt, or 「おしゃれな店|おしゃれなみせ」, a trendy shop. You can also use it on its own: 「山田さんはおしゃれです|やまださんはおしゃれです」, Ms. Yamada is stylish. It works for people, clothes, cafes, rooms, even a well designed website. It can also be a noun meaning dressing up, as in 「おしゃれをする」, to dress up for something. The word comes from 「お」 plus 「洒落|しゃれ」, an older word for being stylish or witty. That 「しゃれ」 also means a clever play on words, and lives on in 「だじゃれ」, a bad pun, the Japanese version of a dad joke. So being stylish and being witty come from the same root, the idea of something clever and well done. You will hear young people use it constantly as praise, a bit like English cool or chic. A way to remember it: picture someone so stylish they also tell clever jokes. To recap, a 「な」-adjective for stylish, from the same root as a clever pun.",
    ja: "{山田|やまだ}さんはいつも[おしゃれ]です。",
    en: "Ms. Yamada is always stylish." },
  "けち|": {
    explain: "Call someone this and you are saying they hate spending money or sharing. It is a bit rude, so use it about friends in a joking way, not to your boss. It works both as a noun, a stingy person, and as a 「な」-adjective: 「けちな人|けちなひと」, a stingy person. Kids shout 「けち」 at a friend who will not share their snacks, a bit like an English child saying meanie. You also hear it in the phrase about not being petty, like a small, cheap complaint. You might see it written in katakana as 「ケチ」 in manga or ads, which makes it feel more punchy. The opposite idea is someone who happily treats others, and you know a verb for that: 「おごる」, to treat someone to a meal. So the friend who never 「おごる」 might get called 「けち」. A way to remember it: it sounds like the noise of a tight purse snapping shut, ketch. Short and sharp, just like the stingy person who will not open their wallet. To recap, a short, cheeky word for stingy, best used in fun among friends.",
    ja: "{兄|あに}は[けち]です。",
    en: "My older brother is stingy." },
  "おくる|送る": {
    explain: "The kanji 「送|そう」 is read here with its native reading, 「おく」, plus 「る」. Look at the bottom left of the kanji. That curving piece is the road or movement piece, and you see it in many words about going places, like 「返す|かえす」, to return, and 「近い|ちかい」, near. So you can picture something moving off down the road. The word has two big meanings. First, to send things: 「手紙を送る|てがみをおくる」, to send a letter, or to send an email or a package. Second, to see someone off or take someone somewhere: 「駅まで送ります|えきまでおくります」, I will take you to the station. In Japan, it is polite to walk a guest to the door, or even to the station, rather than saying goodbye inside. The person you send to takes 「に」: 「母に送る|ははにおくる」, send to my mother. It is a regular u-verb, so 「送ります|おくります」 and 「送って|おくって」. Do not mix it up with 「おくれる」, to be late. A way to remember it: things travel down the road in the kanji, letters or people. To recap, sending things or people off down the road.",
    ja: "{母|はは}に{手紙|てがみ}を[送りました|おくりました|おくる]。",
    en: "I sent a letter to my mother." },
  "にあう|似合う": {
    explain: "Two pieces, both native readings. 「似|に」 means to resemble. Look at the left side, the person piece, as in 「休む|やすむ」, to rest. Then 「合う|あう」 means to fit or match. You know that kanji from 「試合|しあい」, a match or game, where two sides meet, and 「付き合う|つきあう」, to date or keep company. Do not mix it up with 「会う|あう」, to meet, which sounds the same but uses a different kanji. So the word is something like resemble and fit: the clothes and the person match each other so well that they seem made for each other. The pattern is: the item takes 「が」, and the person takes 「に」: 「その色が田中さんに似合う|そのいろがたなかさんににあう」. Most often, though, people just say it as a compliment to someone's face: 「よく似合いますね|よくにあいますね」, that really suits you. It is a great phrase to use when a friend shows you new clothes or a new haircut. A way to remember it: the person and the outfit resemble each other and fit together. To recap, resemble plus fit: something looks good on someone.",
    ja: "そのセーター、よく[似合います|にあいます|にあう]ね。",
    en: "That sweater looks good on you." },
  "あきらめる|": {
    explain: "This is a 「る」-verb, so 「あきらめます」, 「あきらめて」, 「あきらめない」. It has kanji, but they are hard, so kana is common. The thing you give up takes 「を」: 「ゆめをあきらめる」, to give up on a dream. You will hear the negative request a lot as encouragement: 「あきらめないで」, do not give up. Japanese sports anime and manga use that line constantly. Its opposite in spirit is 「頑張る|がんばる」, to keep trying, do your best. One interesting note: dictionaries link this verb to an older verb meaning to make something clear. The idea is that giving up comes from seeing the situation clearly and accepting it. So in Japanese, giving up can sound less like a failure and more like accepting reality calmly. Related to this, you will hear the phrase that it cannot be helped, which expresses the same calm acceptance. A common mistake: English speakers sometimes use it for quitting a habit, like smoking. For that, people usually say they stop it. This word is more about letting go of a hope or goal. A way to remember it: picture someone sighing, ah, and letting the dream float away. To recap, letting go of a goal, with the thing you drop marked by 「を」.",
    ja: "[あきらめないで|あきらめないで|あきらめる]ください。",
    en: "Please don't give up." },
  "あげる|": {
    explain: "This is a giving verb, and the key is direction. It is for giving that moves outward, from you or someone on your side to someone else, or between two other people. The pattern is: giver 「は」 or 「が」, receiver 「に」, thing 「を」. So 「私は友だちに本をあげました|わたしはともだちにほんをあげました」, I gave my friend a book. The same verb also means to raise or lift, so a nice image is lifting a gift up and handing it out to someone. The big rule is that you never use it for something coming to you. If your friend gives you something, you must use 「くれる」. A very common mistake for English speakers is to say a friend 「あげました」 something to me. That sounds wrong in Japanese. A third verb, 「もらう」, is for receiving. Note one politeness point: offering to give something to a superior with this word can sound like you are doing them a favor, so be careful with teachers. For plants and pets, you will often hear the casual 「やる」 instead. A way to remember it: 「あげる」 goes up and away from me. To recap, giving outward, never toward me.",
    ja: "{友だち|ともだち}にプレゼントを[あげました|あげました|あげる]。",
    en: "I gave a present to my friend." },
  "くれる|": {
    explain: "This is the other half of 「あげる」. It is giving that comes toward you, or toward someone in your group, like your family. Someone else is the giver, and you are the receiver. The pattern is: giver 「が」, receiver 「に」, thing 「を」, and often the receiver is just left out, because it is obviously you. 「友だちが本をくれました|ともだちがほんをくれました」, my friend gave me a book. You can include it too: 「私にくれました|わたしにくれました」. The most common mistake for English speakers is to use 「あげる」 for everything, because English uses give in both directions. In Japanese, it sounds odd and a bit cold to use 「あげる」 for something you received, as if you were an outsider. Using 「くれる」 shows that you see the gift as a kindness coming to you. Your in-group counts too, so if a friend gave something to your little sister, you can still use 「くれる」. It is a 「る」-verb: 「くれます」, 「くれて」. A way to remember it: the gift comes to my side. Picture an arrow pointing at you. To recap, giving toward me and my side, the opposite direction from 「あげる」.",
    ja: "{友だち|ともだち}が{本|ほん}を[くれました|くれました|くれる]。",
    en: "My friend gave me a book." },
  "できる|": {
    explain: "You already know this verb as can do, as in 「日本語ができる|にほんごができる」, I can speak Japanese. Here is its other big job: something comes into being. A new shop opens, a building goes up, or 「友だちができる|ともだちができる」, you make a friend. It is sometimes written with the kanji for come out and come, 「出来る|できる」, which fits this meaning nicely: something comes out into the world. The thing that appears is marked with 「が」, not 「を」, because nobody is doing it to an object. It just happens: 「駅の前にカフェができました|えきのまえにカフェができました」, a cafe opened in front of the station. You will also hear it in the kitchen. When food is ready, people say 「できた」, it is done, or 「ご飯ができましたよ|ごはんができましたよ」, dinner is ready. And with relationships: getting a boyfriend or girlfriend is also said with this verb. A common mistake for English speakers is to use 「を」 here, as if someone made the shop. Remember that the shop simply comes to exist. A way to remember it: picture something popping out into the world, ta-da. To recap, the same verb as can do, but with 「が」 it means something new appears.",
    ja: "{駅|えき}のそばに{新しい|あたらしい}{店|みせ}が[できました|できました|できる]。",
    en: "A new store opened near the station." },
  "そうだんする|相談する": {
    explain: "Two kanji, both Chinese-origin readings. 「相|そう」 means mutual, each other, together. 「談|だん」 means talk or conversation. Look at its left side: the speech piece, the same one you see in 「話す|はなす」, to speak, and in 「電話|でんわ」, telephone. Words with that piece are usually about words and talking. So the word is literally talking together, sitting down and working through a problem with someone. That is why it covers both to consult and to discuss. Add 「する」 and it becomes a verb. The person you consult takes 「に」, and the topic often comes with about: 「先生に相談する|せんせいにそうだんする」, to talk it over with my teacher. You can also use it as a noun, as in having a little consultation. In Japan, talking things over before acting is very important. Before a big decision at work, people quietly consult everyone involved first, so no one is surprised. A nice phrase to know is asking someone if you can consult them about something, a polite way to ask for advice. A way to remember it: two people facing each other, talking. To recap, mutual plus talk: talking a problem over together.",
    ja: "{先生|せんせい}に[相談しました|そうだんしました|そうだんする]。",
    en: "I consulted my teacher." },
  "ちゅういする|注意する": {
    explain: "Two kanji, both Chinese-origin readings. 「注|ちゅう」 means to pour. Look at its left side, the three drops of the water piece, which fits pouring. 「意|い」 means mind, intention, or meaning, the same kanji you know from 「意味|いみ」, meaning. So the word is literally pour your mind into something: pay close attention, be careful. Add 「する」 and it becomes a verb. The thing you watch out for takes 「に」: 「車に注意する|くるまにちゅういする」, watch out for cars. You will see this word all over Japanese signs, sometimes with a single word in front, warning you to mind your step or watch for falling objects. The second meaning comes from pointing that attention at someone else: you warn them, or give them a light scolding. If a teacher 「注意する|ちゅういする」 a student, it means they told them off or cautioned them. A close cousin is 「気をつける|きをつける」, be careful, which is softer and used more in daily speech, as in take care. A way to remember it: picture pouring water carefully into a cup, eyes fixed on it, so you do not spill. To recap, pour plus mind: watch out, or warn someone.",
    ja: "{車|くるま}に[注意して|ちゅういして|ちゅういする]ください。",
    en: "Please watch out for cars." },
  "プロポーズする|": {
    explain: "This is English propose, plus 「する」, the do verb that turns loanwords into verbs. Listen to the sounds. The pr cluster gets split with an extra vowel, 「プロ」. The po part becomes 「ポー」, with a long vowel for the English oh glide. And the se at the end, with its z sound, becomes 「ズ」, again with an extra vowel. The big thing to know is the meaning shift. In English, you can propose an idea at a meeting, a plan, or a toast. In Japanese, this word almost only means proposing marriage. For suggesting an idea, Japanese uses a different word. You can also use it as a noun, as in getting a proposal. The person you propose to takes 「に」: 「彼女にプロポーズした|かのじょにプロポーズした」, he proposed to his girlfriend. Japanese dramas love a big proposal scene, often with a ring, a 「指輪|ゆびわ」, in a fancy restaurant or with a city view at night. A way to remember it: in Japan, only one kind of proposal comes with a ring. To recap, English propose with extra vowels, used only for asking someone to marry you.",
    ja: "{山下|やました}さんは{恋人|こいびと}に[プロポーズしました|プロポーズしました|プロポーズする]。",
    en: "Mr. Yamashita proposed to his girlfriend." },
  "〜くん|〜君": {
    explain: "The kanji 「君|くん」 is read here with its Chinese-origin reading. Its native reading is 「きみ」, which means you, a casual word a man might use to a friend, a younger person, or a partner. Long ago, the kanji meant a lord or ruler, but over time it became a friendly, casual title. Put it after a name, like 「たけし君|たけしくん」, and it is a casual version of 「さん」. It is used mostly for boys and young men, by friends, classmates, older people, and teachers talking to students. Girls usually get 「ちゃん」 instead when they are young. At some Japanese companies, a boss may use it for younger staff of any gender, and in the Japanese parliament it is used for all members, so it is not strictly a boy word. The big rules: never use it for your boss, a teacher, or anyone older than you, because it would sound like talking down. And never use it for yourself, just like 「さん」. A common mistake is using it with someone you have just met, which can feel too familiar. A way to remember it: think of a friendly older classmate calling out to a younger boy. To recap, a casual name ender for boys and juniors.",
    ja: "[たけし君|たけしくん|〜くん]はわたしの{友だち|ともだち}です。",
    en: "Takeshi is my friend." },
  "〜たち|": {
    explain: "Stick this on words for people to make them plural: 「子どもたち|こどもたち」, children, 「学生たち|がくせいたち」, students. It is sometimes written with the kanji 「達|たち」, but kana is common. Here is a fun connection: the word you already know for friend, 「友だち|ともだち」, is actually friend plus this very ending, with the sound softened to 「だち」. Long ago it meant friends, but today it is just one friend, and the ending lost its plural feel. A few points to know. First, it is mostly for people and sometimes animals, not things. You do not say books plus this ending. Japanese nouns usually do not need a plural at all, so 「本|ほん」 can be one book or many. Second, after a name, it means that person and their group: 「田中さんたち|たなかさんたち」, Tanaka and the others. So it is more like and company than a strict plural. Third, you can add it to pronouns: 「私たち|わたしたち」, we, and 「あなたたち」, you all. A way to remember it: picture a little crowd of people gathered behind the word. To recap, a plural ender for people, also hiding inside 「友だち|ともだち」.",
    ja: "[子どもたち|こどもたち|〜たち]は{公園|こうえん}であそんでいます。",
    en: "The children are playing in the park." },
  "わたしたち|私たち": {
    explain: "Just 「私|わたし」 plus the plural ender 「たち」, so it is literally I and my group. 「私|わたし」 uses its native reading here. You also know its more formal reading, 「わたくし」, and the kanji has a Chinese-origin reading, 「し」, used in words for private things, like private schools. So the kanji is about the self and personal matters. You can make other we words the same way. Boys and men often say 「僕たち|ぼくたち」, we, in casual speech. And for you all, people say 「あなたたち」. The plural can mean two people or a whole nation, depending on context, a bit like English. One cultural point: Japanese often leaves the subject out completely when it is obvious. So in conversation, you will hear this word less than English speakers use we. When you do hear it, it often stresses the group, as in we, as opposed to them. In formal speeches, you may hear 「私たち|わたしたち」 or the old formal word for we. A way to remember it: one 「私|わたし」, then a little crowd of 「たち」 standing behind it. To recap, I plus the people plural: we.",
    ja: "[私たち|わたしたち]は{学生|がくせい}です。",
    en: "We are students." },
  "こんな〜|": {
    explain: "This is part of the 「こ」「そ」「あ」「ど」 family you already know from 「これ」, 「それ」, 「あれ」, 「どれ」, and 「ここ」, 「そこ」, 「あそこ」, 「どこ」. The 「こ」 words point to things close to you. So 「こんな」 is this kind of, something near you or just mentioned by you. 「そんな」 is that kind, near the listener, 「あんな」 is that kind over there, and 「どんな」, which you learned already, asks what kind. They always need a noun right after them: 「こんな本|こんなほん」, a book like this. You cannot use them alone like 「これ」. You will also hear 「こんなに」, so much, like this, as in I did not know it was this hard. Watch the tone. Depending on context, it can sound excited, like I wanted something like this, or annoyed, like what is this kind of thing. A common mistake is mixing it up with 「この」. 「この本|このほん」 is this specific book. 「こんな本|こんなほん」 is a book of this kind. A way to remember it: 「この」 points at one thing, 「こんな」 points at the type. To recap, the 「こ」 word for this kind of, always followed by a noun.",
    ja: "[こんな]{本|ほん}が{欲しい|ほしい}です。",
    en: "I want a book like this." },
  "きゅうに|急に": {
    explain: "The kanji 「急|きゅう」 uses its Chinese-origin reading here, and it means hurry, sudden, or steep. You already know it with its native reading in 「急ぐ|いそぐ」, to hurry. Look at the bottom of the kanji: it has the heart piece, the same one at the bottom of 「思う|おもう」, to think. A way to remember it: a racing heart, the feeling when something rushes at you. Add 「に」 and it turns into an adverb describing how something happens: suddenly, all of a sudden. 「急に雨が降りました|きゅうにあめがふりました」, it suddenly rained. 「急に|きゅうに」 is great for any surprise: someone suddenly stops, a plan suddenly changes, a person suddenly calls. The same kanji shows up in express trains, the ones in a hurry that skip stations, which you will see at train stations all over Japan. Another useful phrase is something being urgent, which uses the same kanji. A common mistake is using 「急に|きゅうに」 for things that are just fast. It is about something being sudden and unexpected, not quick. For fast, use 「早く|はやく」. To recap, hurry or sudden, plus 「に」: all of a sudden.",
    ja: "[急に|きゅうに]{雨|あめ}がふりました。",
    en: "It suddenly rained." },
  "ちょうど|": {
    explain: "This means right on the mark, nothing more, nothing less. It is usually written in kana, though you may see the kanji 「丁度|ちょうど」. Use it for times and amounts: 「ちょうど三時です|ちょうどさんじです」, it is exactly three o'clock, or 「ちょうど千円|ちょうどせんえん」, exactly a thousand yen. When you pay with the exact amount at a shop, the clerk often says the amount is exactly right, using this word. It also works for timing. 「ちょうどいい」 means just right, not too much, not too little, like a room at the perfect temperature or shoes that fit. And you can say something happened just as something else was happening: I was just about to call you. A common mistake for English speakers is using it for strong agreement, the way English says exactly. In Japanese, for that you would say 「そうですね」 instead. 「ちょうど」 is about a precise fit. A way to remember it: it sounds a bit like a little drum hit, cho-do, landing right on the beat. To recap, right on the dot, for times, amounts, and things that fit just right.",
    ja: "{今|いま}[ちょうど]{三時|さんじ}です。",
    en: "It's exactly three o'clock now." },
  "さあ|": {
    explain: "This little sound has two main jobs, and the tone tells you which one. The first, from this lesson, is a thinking sound when you do not know. Said slowly, low, often with a little head tilt, 「さあ」 means hmm, I am not sure. You can follow it with 「わかりません」, I do not know: 「さあ、わかりません」. The second job is completely different. Said brightly, with energy, it means come on, or well then, let's go, as in 「さあ、行こう|さあ、いこう」, come on, let's go. You will hear that one when someone is starting something, like a meal or a trip. For the not sure meaning, be careful with politeness. On its own, 「さあ」 can sound a bit dismissive, like I don't know and I don't care. To a teacher or boss, it is safer to add something softer, like 「ちょっとわかりません」. It is a casual, natural word, so it is great in conversation with friends. A way to remember it: picture a long, slow breath out, like a shrug turned into sound. To recap, a shrug word for I'm not sure, or, said brightly, come on.",
    ja: "[さあ]、わかりません。",
    en: "Hmm, I don't know." },
  "どうしたらいい|": {
    explain: "This is a little phrase built from pieces you know. 「どう」 is how. 「したら」 is the if or when form of 「する」, to do. And 「いい」 is good. So it is literally how, if I do it, would it be good? In plain English: what should I do? You will learn the 「たら」 form properly a bit later, but you can use this whole phrase now as a set expression. Add 「ですか」 to make it polite: 「どうしたらいいですか」, what should I do. In casual speech, people just say 「どうしたらいい」 with a rising tone, or sigh it to themselves when they are stuck. It is great for asking for advice, which links nicely to 「相談する|そうだんする」, to consult. You can also put an action in front, like what should I do about this problem, or how should I say it. You will also hear the close cousin 「どうすればいい」, which means almost the same thing. A common mistake is translating should word for word, which Japanese does not need here. The 「いい」 does that job. A way to remember it: how plus do plus good, three little words for being stuck. To recap, how, if I do, is it good: what should I do?",
    ja: "{財布|さいふ}をなくしました。[どうしたらいい]ですか。",
    en: "I lost my wallet. What should I do?" },
  "〜こ|〜個": {
    explain: "The kanji 「個|こ」 uses its Chinese-origin reading, and it means individual, one single item. Look at the left side: it has the person piece, and you will see it in the word for individual person. As a counter, it is for smallish, often roundish or chunky things: apples, eggs, candies, 「みかん」, erasers, even ice cubes. It is also a handy fallback when you do not know the proper counter. Watch the sound changes, because this counter starts with a k sound and gets the small 「っ」 with certain numbers. One is 「一個|いっこ」, six is 「六個|ろっこ」, eight is often 「八個|はっこ」, and ten is 「十個|じゅっこ」. The others are regular: 「二個|にこ」, 「三個|さんこ」. To ask how many, say 「何個|なんこ」. You also know a native way to count things, 「ひとつ」, 「ふたつ」, and so on, and for small items both systems work. The native one stops at ten, though, and this one keeps going. A way to remember it: picture a pile of single, individual candies, each one its own little 「こ」. To recap, individual item, a counter for small things, with small 「っ」 for one, six, eight, and ten.",
    ja: "みかんを[三個|さんこ|〜こ]{買いました|かいました}。",
    en: "I bought three mandarin oranges." },
  "〜さつ|〜冊": {
    explain: "The kanji 「冊|さつ」 is a picture you can still see. It shows strips of bamboo or wood, standing side by side, with a string tied through them. That is how books were bound in ancient China, before paper was common. So it makes perfect sense as the counter for bound volumes: books, notebooks, magazines, dictionaries like 「辞書|じしょ」, and textbooks like 「教科書|きょうかしょ」. It uses its Chinese-origin reading. Watch the sound changes. One is 「一冊|いっさつ」, eight is 「八冊|はっさつ」, and ten is 「十冊|じゅっさつ」, each with a small 「っ」. The rest are regular, like 「二冊|にさつ」 and 「三冊|さんさつ」. To ask how many, say 「何冊|なんさつ」. A common mistake is to use the general counter for things for books. That sounds off to Japanese ears. Note that flat sheets, like single pages or tickets, use a different counter, 「〜まい」, for thin flat things. Only bound items with pages get 「さつ」. A way to remember it: look at the kanji and see the bamboo strips tied together, an old book. To recap, a picture of bound strips, used to count books and notebooks.",
    ja: "{本|ほん}を[二冊|にさつ|〜さつ]{読みました|よみました}。",
    en: "I read two books." },
  "〜だい|〜台": {
    explain: "The kanji 「台|だい」 uses its Chinese-origin reading, and it means a stand, platform, or base, something that holds things up. As a counter, it is for machines and vehicles: cars, bicycles, computers, TVs, washing machines, pianos. The idea is that each machine sits on its own stand or base, like a unit. The good news is that the numbers are regular, with no sound changes: 「一台|いちだい」, 「二台|にだい」, 「三台|さんだい」, and so on. To ask how many, say 「何台|なんだい」. You know the same kanji with a different reading in 「台風|たいふう」, typhoon. Different reading, different job, so do not go looking for a stand inside the typhoon. A useful example: 「車が二台あります|くるまがにだいあります」, there are two cars. Note that people riding in the car are counted with 「〜人|にん」, not this counter. A common mistake is to count cars or bikes with the general counter for small things. For machines, 「台|だい」 always sounds right. A way to remember it: picture each machine on its own little stand, like a display in an electronics store. To recap, a stand or base, the counter for machines and vehicles.",
    ja: "うちに{車|くるま}が[二台|にだい|〜だい]あります。",
    en: "We have two cars at home." },
  "〜ひき|〜匹": {
    explain: "The kanji 「匹|ひき」 uses its native reading as a counter, and it is for small animals: cats, dogs, fish, insects, mice. The kanji itself is simple, and its origin is not something to rely on, so use a hook. A way to remember it: picture a little box with something wriggling inside. The sound changes are the big thing to learn, because this counter starts with an h sound. One is 「一匹|いっぴき」, with a p sound. Three is 「三匹|さんびき」, with a b sound. Six is 「六匹|ろっぴき」, eight is 「八匹|はっぴき」, and ten is 「十匹|じゅっぴき」. To ask how many, say 「何匹|なんびき」, again with a b sound. It is the same pattern as the long-object counter, 「本|ほん」: 「いっぽん」, 「さんぼん」, 「ろっぽん」. If you learn one, you get the other free. Big animals like horses, cows, and elephants use a different counter, 「頭|とう」, literally heads. So a 「猫|ねこ」, cat, is counted with 「ひき」, but an elephant is not. Medium dogs can go either way. To recap, the counter for small animals, with the same p and b sound changes as 「ほん」.",
    ja: "{猫|ねこ}が[三匹|さんびき|〜ひき]います。",
    en: "There are three cats." },
  "〜ほん|〜本": {
    explain: "You know this kanji as book, 「本|ほん」, and in 「日本|にほん」, Japan. Its shape is a tree, 「木|き」, with an extra line near the bottom marking the root. So its core meaning is root or origin, which is why Japan is the origin of the sun. As a counter, it uses the long, straight shape of a tree trunk: pencils like 「鉛筆|えんぴつ」, bottles, umbrellas, trees, bananas, even roads and rivers. It also counts some things you might not expect, like movies and phone calls, which are worth just memorizing. The sound changes are important. One is 「一本|いっぽん」, three is 「三本|さんぼん」, six is 「六本|ろっぽん」, eight is 「八本|はっぽん」, and ten is 「十本|じゅっぽん」. To ask how many, say 「何本|なんぼん」. The others stay 「ほん」. It is the same pattern as 「匹|ひき」 for small animals, so learn them together. A common mistake is saying 「さんほん」 instead of 「さんぼん」. A way to remember it: a tree with its root, long and straight. To recap, the root-of-a-tree kanji, counting long thin things with p and b sound changes.",
    ja: "{鉛筆|えんぴつ}を[三本|さんぼん|〜ほん]ください。",
    en: "Three pencils, please." },
  "がいこくじん|外国人": {
    explain: "Three kanji, all read with their Chinese-origin readings. The first is 「外|がい」, outside. On its own, with the native reading, it is 「外|そと」, the outdoors. The second is 「国|こく」, country. Alone it is 「国|くに」. A way to remember its shape: a border box with a jewel inside, a country guarding its treasure. The last is 「人|じん」, person, the same piece that turns a country into its people, as in 「日本人|にほんじん」 or 「アメリカ人|アメリカじん」. So, a person from outside the country. You already know the first two together as 「外国|がいこく」, a foreign country, and you have seen 「外国語|がいこくご」, foreign language. Swap the last kanji and you change the meaning: country, language, person. A cultural note. People sometimes shorten this to 「外人|がいじん」. That short form is very common, but it can sound blunt or a bit excluding, so 「外国人|がいこくじん」 is the safe, neutral word to use yourself. To recap: outside, country, person, a person from a foreign land.",
    ja: "[外国人|がいこくじん]の{友だち|ともだち}がいます。",
    en: "I have a friend who is a foreigner." },
  "そば|": {
    explain: "These are thin noodles made from buckwheat flour, usually grayish brown, with a nutty taste. Japanese normally writes them in kana, though there is a kanji spelling you may see on shop signs, 「蕎麦|そば」. You can eat them two main ways. Hot, in a soy based broth, or cold, piled on a bamboo tray and dipped into a cool sauce, which is called 「ざるそば」. Slurping loudly is perfectly polite. It cools the noodles and shows you are enjoying them. Two customs make this word stick. On New Year's Eve, many families eat 「年越しそば|としこしそば」, year crossing soba. The long noodles stand for a long life, and because they break easily, they also stand for cutting off the troubles of the old year. And when people move into a new home, there is an old custom of giving neighbors soba. One trap. 「焼きそば|やきそば」, fried noodles, is actually made with wheat noodles, not buckwheat, even though it carries the name. Also, a different word that sounds the same, 「そば」, means right next to something. Recap: buckwheat noodles, hot or cold, and the noodle of New Year's Eve.",
    ja: "{昼ごはん|ひるごはん}に[そば]を{食べました|たべました}。",
    en: "I ate soba for lunch." },
  "え|絵": {
    explain: "A single sound, and a surprise. It looks like a native word, but this 「え」 is actually a Chinese-origin reading. Look at the kanji in two parts. On the left is the thread part, the same one found in 「糸|いと」, thread. On the right is 「会|かい」, the kanji from 「会う|あう」, to meet or gather. A way to remember it: threads of many colors gathered together into one picture, like embroidery. It covers any kind of picture made by hand, paintings, drawings, sketches, even a child's crayon doodle. A photo is not this word. A photo is 「写真|しゃしん」. Its partner verb is 「描く|かく」, to draw or paint, so you say 「絵を描く|えをかく」. You will also meet it inside other words, like 「絵本|えほん」, a picture book, with 「本|ほん」, book, and 「絵はがき|えはがき」, a picture postcard. If you want to say someone is good at art, the natural phrase is 「絵が上手です|えがじょうずです」. Recap: colored threads gathered together, a hand made picture.",
    ja: "{兄|あに}は[絵|え]がじょうずです。",
    en: "My older brother is good at drawing pictures." },
  "ちず|地図": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「地|ち」, ground or land. Look at its left side and you will see the earth part, 「土|つち」, soil. You already know it in 「地下鉄|ちかてつ」, the subway, which is literally underground iron. The second is 「図|ず」, a drawing, a diagram or a plan. It is the same kanji that starts 「図書館|としょかん」, the library, but notice the reading changes. There it is 「と」, here it is 「ず」. Both are Chinese-origin readings of the same kanji, and each word just uses one. Put them together and you get a drawing of the land. Simple. Fun detail. The kanji 「地|ち」 and 「池|ち」, the pond in 「電池|でんち」, share the same right side and the same reading, so they are easy to mix up. Just check the left side. Earth for land, water drops for a pond. Useful phrases are 「地図を見る|ちずをみる」, to look at a map, and 「地図アプリ|ちずアプリ」, a map app on your phone. Recap: a drawing of the land, a map.",
    ja: "この[地図|ちず]を{見て|みて}ください。",
    en: "Please look at this map." },
  "じしょ|辞書": {
    explain: "Two kanji, both read with their Chinese-origin readings. The first is 「辞|じ」, which is about words and expressions. The second is 「書|しょ」, writing or a written book. A book of words. You have seen 「書|しょ」 in lots of places. It is in 「図書館|としょかん」, the library, in 「教科書|きょうかしょ」, the textbook, and in 「履歴書|りれきしょ」, a resume. With its native reading it becomes the verb 「書く|かく」, to write. Notice that the learner list first gave you this word in kana only, back in the early lessons. Now you get the kanji too. A nice idiom. In Japanese you do not just use a dictionary, you pull it. The phrase is 「辞書を引く|じしょをひく」, to pull the dictionary, which comes from flipping and pulling pages to find a word. You can also say 「辞書で調べる|じしょでしらべる」, to look something up in the dictionary. A related word is 「電子辞書|でんしじしょ」, an electronic dictionary, which Japanese students used for years before phones took over. Recap: a written book of words.",
    ja: "{漢字|かんじ}を[辞書|じしょ]でしらべます。",
    en: "I look up kanji in the dictionary." },
  "かぐ|家具": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「家|か」, house or family. With its native reading it is 「家|いえ」, house, and you know it in 「家族|かぞく」, family. A way to remember the shape: a roof on top, and under it the old kanji for a pig, as if the most precious thing in an old farmhouse was kept indoors. The second is 「具|ぐ」, tools, equipment, or the fillings in a dish. Japanese people even call the ingredients floating in a soup the 「具|ぐ」. So the equipment of a house. Tables, chairs, beds, shelves and sofas. Like English furniture, it is a general, uncountable feeling word. You would not use it for small things like cups or a phone. A related word is 「道具|どうぐ」, tools, which shares the same 「具|ぐ」. Cultural note. Many Japanese apartments come completely empty, sometimes without even a light fixture, so buying 「家具|かぐ」 is a big part of moving. Recap: house plus equipment, everything that fills a home.",
    ja: "{新しい|あたらしい}[家具|かぐ]を{買いました|かいました}。",
    en: "I bought new furniture." },
  "でんち|電池": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「電|でん」, electricity. Look at the top and you will see the rain part, 「雨|あめ」. The kanji began as a picture of lightning in a storm, the first electricity people ever saw. You know it from a whole family of words. 「電話|でんわ」, telephone, 「電車|でんしゃ」, train, and 「電気|でんき」, electricity or lights. The second kanji is 「池|ち」, a pond. Its left side is the water part, three drops. With the native reading, it is 「池|いけ」, a pond in a garden or park. So a battery is a pond of electricity, a little pool where power is stored until you need it. That is a lovely, accurate picture. A sharp eye will notice that 「池|ち」, pond, and 「地|ち」, land, as in 「地図|ちず」, share the same right side and the same sound. Water on the left for pond, earth on the left for land. A handy phrase: 「電池が切れました|でんちがきれました」, the battery ran out, literally the battery got cut. Recap: lightning plus pond, stored electricity.",
    ja: "[電池|でんち]を{買いに|かいに}{行きます|いきます}。",
    en: "I'm going to buy batteries." },
  "ジャケット|": {
    explain: "A loanword from English, jacket. Look at how the sounds were squeezed to fit Japanese. The ja sound becomes 「ジャ」. The ck in the middle turns into a small 「ッ」, which is a tiny pause, a held breath before the next sound. Then the final t cannot stand alone in Japanese, because almost every syllable has to end in a vowel, so it gets an o sound added and becomes 「ト」. You will see the same pattern in 「ペット」 and 「ポケット」, pocket. Since a jacket goes on your upper body, the verb is 「着る|きる」, to wear, the same one you use for a shirt or a sweater: 「ジャケットを着る|ジャケットをきる」. Meaning shift. In Japanese, this word also means the cover of a record or CD. Music fans talk about the cover art as the 「ジャケット」. For a heavy winter coat, people more often say 「コート」. Recap: an English word with a small pause and an extra vowel, the thing you put on when it gets cool.",
    ja: "さむいですから、[ジャケット]をきます。",
    en: "It's cold, so I'll wear a jacket." },
  "ペット|": {
    explain: "A loanword from English, pet. The short e stays as 「ペ」. The final t, which Japanese cannot leave hanging, becomes a small 「ッ」 pause plus 「ト」, adding a little o sound at the end. It is the same squeeze you hear in 「ジャケット」. Grammar tip. Pets are alive, so they take 「いる」 not 「ある」: 「ペットがいます」, I have a pet. The verb for keeping an animal is 「飼う|かう」, which sounds like 「買う|かう」, to buy, but uses a different kanji. And small animals like dogs and cats are counted with 「匹|ひき」. A common trap. When you see 「ペットボトル」, it has nothing to do with animals. That is a plastic drink bottle, named after the plastic it is made of, called P E T. Many people in Japan live in apartments that ban pets, so finding a pet friendly apartment can be a real search. Recap: an English word with a clipped ending, and it lives with you, so use 「いる」.",
    ja: "うちには[ペット]がいません。",
    en: "We don't have any pets at home." },
  "わりびきけん|割引券": {
    explain: "Three kanji, and the first two come from native verbs. 「割|わり」 comes from 「割る|わる」, to split or divide. 「引|びき」 comes from 「引く|ひく」, to pull, or in math, to subtract. The 「ひ」 turns into 「び」 here because it is joined onto the word before it. Together, 「割引|わりびき」 means a discount, splitting off a part of the price and pulling it away. The last kanji uses its Chinese-origin reading, 「券|けん」, a ticket or voucher. It appears on all kinds of tickets, like the meal tickets you buy from machines at noodle shops, called 「食券|しょっけん」. So a ticket that takes some off the price. A useful bonus. 「割|わり」 on its own also means ten percent. So 「二割引|にわりびき」 means twenty percent off, and 「三割引|さんわりびき」 means thirty percent off. You will see these signs in supermarkets in the evening, stuck on bento and sushi. You know 「引|ひく」 from other places too, like 「辞書を引く|じしょをひく」, to look up a word. Recap: split, pull off, ticket, a coupon.",
    ja: "[割引券|わりびきけん]がありますか。",
    en: "Do you have a discount coupon?" },
  "インターネット|": {
    explain: "A loanword from English, internet. Watch how it gets squeezed. The in becomes 「イン」. The ter loses its r sound, because Japanese usually drops an r at the end of a syllable, and becomes 「ター」 with a long vowel. Then net becomes 「ネット」, with a small 「ッ」 pause and an o sound added to the final t. In everyday talk, people almost always cut it down to just 「ネット」. They say 「ネットで買う|ネットでかう」, to buy online, and 「ネットで調べる|ネットでしらべる」, to look something up online. Notice the particle. You do things on the internet with 「で」, the particle for the means or place of an action. Japanese loves to shorten long loanwords this way. 「パソコン」 is a shortened personal computer, and 「エアコン」 is a shortened air conditioner. Words for online life are mostly loanwords too, like 「アプリ」, app, and 「メール」, email. Recap: an English word with a dropped r and an extra vowel, and most people just say 「ネット」.",
    ja: "[インターネット]で{調べました|しらべました}。",
    en: "I looked it up on the internet." },
  "じしん|地震": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「地|じ」, ground or earth. Look closely at the reading. In 「地図|ちず」, map, and 「地下鉄|ちかてつ」, subway, it is 「ち」. Here it is 「じ」. Both are real readings of the same kanji, and this word simply uses 「じ」. The second kanji is 「震|しん」, to shake or tremble. It has the rain part on top, like 「電|でん」 and 「雪|ゆき」, a reminder of thunder shaking the sky. So the ground shakes. A cultural note. Japan sits on several tectonic plates and feels many small earthquakes every year. There is an old saying listing the four scariest things in life: 「地震|じしん」, 「雷|かみなり」, thunder, 「火事|かじ」, fire, and 「親父|おやじ」, the old man, meaning a strict father. Schools hold earthquake drills where children hide under their desks. A sound alike to watch for. 「自信|じしん」, with different kanji, means self confidence. Context tells them apart. Recap: earth plus shake.",
    ja: "きのう[地震|じしん]がありました。",
    en: "There was an earthquake yesterday." },
  "ほけん|保険": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「保|ほ」, to protect, keep or maintain. Its left side is the person part, a person who looks after something. The second is 「険|けん」, steep, dangerous or risky. Its left side is the hill part, so you can picture a steep, risky slope. You see it in 「危険|きけん」, danger. Together, protection against danger. That is exactly what insurance is, a way of keeping yourself safe from risks you cannot see coming. In Japan, everyone who lives there, including foreign students, is expected to join the national health insurance. You get a card called 「保険証|ほけんしょう」, and you show it at every clinic visit. With it you usually pay only about thirty percent of the cost. The verb is a little unusual. You do not buy insurance in Japanese, you enter it: 「保険に入る|ほけんにはいる」. Travelers often get 「旅行保険|りょこうほけん」, travel insurance. Recap: protect plus danger, protection against risk.",
    ja: "[保険|ほけん]はたかいです。",
    en: "Insurance is expensive." },
  "ぜいきん|税金": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「税|ぜい」, tax. Look at its left side and you will see the grain part, the stalk of a rice plant. That fits history well. For centuries in Japan, taxes were paid in rice, not coins. The second is 「金|きん」, gold or money. You know it with its native reading in 「お金|おかね」, money, and in 「お金持ち|おかねもち」, a rich person. With the same Chinese-origin reading as here, it gives you 「金曜日|きんようび」, Friday, gold day. So tax money. The verb you use is 「払う|はらう」, to pay: 「税金を払う|ぜいきんをはらう」. A practical note for shopping. Japan has a consumption tax, which is the sales tax added to prices. Price tags often show two numbers, one before tax and one including tax, so look for the label that says 「税込|ぜいこみ」, tax included. Recap: grain on the left, money on the right, the money you owe the government.",
    ja: "{毎年|まいとし}[税金|ぜいきん]をはらいます。",
    en: "I pay taxes every year." },
  "きょうしつ|教室": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「教|きょう」, to teach. With its native reading it becomes the verb 「教える|おしえる」, to teach, which you already know. It also starts 「教科書|きょうかしょ」, textbook, and 「教師|きょうし」, teacher. The second is 「室|しつ」, a room. It has the roof part on top, a covered space. So a teaching room. Two uses worth knowing. The first is the plain classroom at a school. The second is a class or lesson school outside regular education. A cooking class is 「料理教室|りょうりきょうしつ」, and a place for English lessons can be called 「英会話教室|えいかいわきょうしつ」. A cultural note. In most Japanese schools, there are no janitors for the classrooms. The students clean their own classrooms every day, sweeping, wiping desks and even washing floors. It is seen as part of learning to care for shared spaces. Recap: teach plus room, a place where teaching happens.",
    ja: "[教室|きょうしつ]に{学生|がくせい}がいます。",
    en: "There are students in the classroom." },
  "たてもの|建物": {
    explain: "Two kanji, and here both use their native readings, which is a little unusual for a compound. The first is 「建|たて」, from the verb 「建てる|たてる」, to build or put up a structure. The second is 「物|もの」, thing. So a built thing, a building. You already know 「物|もの」 from a big family of everyday words. 「食べ物|たべもの」 is an eaten thing, food. 「飲み物|のみもの」 is a drunk thing, a drink. 「買い物|かいもの」 is a bought thing, shopping. And 「着物|きもの」 is a worn thing, the kimono. In each one, a verb plus 「物|もの」 makes a thing. Careful, though. The same kanji switches to its Chinese-origin reading in other words, like 「動物園|どうぶつえん」, the zoo, and 「物価|ぶっか」, prices. This word is general. It covers houses, temples, schools and towers. For a modern multi story office or shopping building, people often say 「ビル」, short for the English word building. Recap: build plus thing, anything that was built.",
    ja: "あの[建物|たてもの]は{大きい|おおきい}です。",
    en: "That building is big." },
  "プール|": {
    explain: "A loanword from English, pool. The long oo sound is shown by the long mark 「ー」, which stretches the vowel. The final l becomes 「ル」, because Japanese has no separate l sound and uses its r sound instead, with an extra vowel on the end. You hear the same thing in 「ホテル」, hotel. Meaning shift. In Japanese this word only means a swimming pool. The game you play with cues and balls is called 「ビリヤード」, billiards. And a pool of water on the ground after rain is a different word again. The verb that goes with it is 「泳ぐ|およぐ」, to swim: 「プールで泳ぐ|プールでおよぐ」, swim at the pool, with 「で」 for the place of the action. A cultural note. Most Japanese elementary and junior high schools have an outdoor pool, and swimming lessons are a normal part of summer classes. Many towns also run cheap public pools that open in July and August. Recap: the English word pool with a long vowel and an l turned into r, and only for swimming.",
    ja: "なつは[プール]で{泳ぎます|およぎます}。",
    en: "In summer I swim in the pool." },
  "えいがかん|映画館": {
    explain: "Three kanji, all with Chinese-origin readings. The first two you already know together as 「映画|えいが」, movie. 「映|えい」 means to reflect or project. It has the sun part on the left, light shining on something. 「画|が」 means a picture. It is the same kanji in 「漫画|まんが」, comics. So a movie is a projected picture. Then comes 「館|かん」, a large building or hall. Its left side is the food part, because the kanji first meant a guesthouse where travelers were fed. That ending gives you a whole family of public buildings you have met. 「図書館|としょかん」, the library, a hall of books. 「美術館|びじゅつかん」, the art museum, a hall of fine art. And 「旅館|りょかん」, a Japanese inn, a hall for travelers. So here, a hall for projected pictures. A cultural note. Movie tickets in Japan are fairly expensive, so many theaters offer cheaper days, often a ladies' day or a discount on the first day of each month. Recap: projected picture plus hall.",
    ja: "{友だち|ともだち}と[映画館|えいがかん]に{行きました|いきました}。",
    en: "I went to the movie theater with a friend." },
  "りょかん|旅館": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「旅|りょ」, travel or a journey. You know it from 「旅行|りょこう」, a trip, and with its native reading it is 「旅|たび」, a journey, a slightly poetic word. The second is 「館|かん」, a hall or building, the same ending as 「図書館|としょかん」, 「美術館|びじゅつかん」 and 「映画館|えいがかん」. So a hall for travelers. But this word means something more specific than a hotel. A 「旅館|りょかん」 is a traditional Japanese inn. You take off your shoes at the entrance. Rooms have tatami mats, and staff lay out futons for you in the evening. Guests wear a light cotton robe called a 「浴衣|ゆかた」, and many inns have a large shared bath, often a hot spring, an 「温泉|おんせん」. Dinner is usually a long, beautiful set meal of many small dishes. A Western style place is a 「ホテル」. The verb for staying overnight is 「泊まる|とまる」: 「旅館に泊まる|りょかんにとまる」. Recap: travel plus hall, the traditional inn.",
    ja: "{京都|きょうと}の[旅館|りょかん]に{泊まりました|とまりました}。",
    en: "I stayed at a Japanese inn in Kyoto." },
  "にわ|庭": {
    explain: "Here the kanji uses its native reading, a Japanese word that existed long before writing arrived. The kanji has the building part on top and to the left, a roof with one side open, and the rest sits underneath it. A way to remember it: the open space that belongs to a house. The Chinese-origin reading of this kanji is 「てい」, and you hear it in 「日本庭園|にほんていえん」, a formal Japanese garden. Notice that this word is about the yard or garden attached to a home or temple, not a vegetable plot or a public park. A park is 「公園|こうえん」. A cultural note. Japanese gardens are famous. Some temples in Kyoto have dry rock gardens, where raked white gravel stands for water and stones stand for islands or mountains. Many city homes have only a tiny garden, but people still fit in a small tree, a few stones and some moss. A memory hook, clearly just a hook: it sounds a bit like knee wah, so picture plants growing knee high in your garden. Recap: the open space by a house, a garden or yard.",
    ja: "うちの[庭|にわ]にねこがいます。",
    en: "There is a cat in our garden." },
  "ボランティア|": {
    explain: "A loanword from English, volunteer. Watch the squeeze. Japanese has no v sound, so the v becomes a b, giving 「ボ」. The l becomes the Japanese r sound in 「ラン」. Then the teer part needs a sound that Japanese did not traditionally have. The plain 「チ」 would sound like chee, so a small 「ィ」 is added to 「テ」 to make a tee sound, 「ティ」. The ending r is dropped and becomes 「ア」. Meaning shift. In English, volunteer is mainly the person. In Japanese it is very often the activity itself, so you say 「ボランティアをする」, to do volunteering. You can also say 「ボランティア活動|ボランティアかつどう」, volunteer activities. A cultural note. The year 1995, after the great Kobe earthquake, is often called the first year of volunteering in Japan, because so many ordinary people came to help. Since then, volunteering after disasters has become a familiar part of Japanese life. Recap: v to b, a small vowel trick for tee, and it names the activity.",
    ja: "{週末|しゅうまつ}に[ボランティア]をします。",
    en: "I do volunteer work on weekends." },
  "かつどう|活動": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「活|かつ」, lively, active, full of life. It has the water part on the left, like a flowing stream. You already know it in 「生活|せいかつ」, daily life, literally living and being lively. The second is 「動|どう」, to move. A way to remember its shape: on the left is 「重い|おもい」, heavy, and on the right is 「力|ちから」, strength, so you use strength to move something heavy. You know it from 「動物園|どうぶつえん」, the zoo, where 「動物|どうぶつ」 is a moving thing, an animal. Together, lively moving, activity. It is used for organized activities, rarely for something small like reading a book. School club activities are called 「部活動|ぶかつどう」, usually shortened to 「部活|ぶかつ」, a huge part of Japanese school life. Japanese also loves this kind of shortcut. Job hunting is 「就活|しゅうかつ」, a job activity. Recap: lively plus move, organized activity.",
    ja: "ボランティア[活動|かつどう]をしています。",
    en: "I do volunteer activities." },
  "けいけん|経験": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「経|けい」. Its left side is the thread part, and it originally meant the long threads stretched on a loom, the ones everything else is woven through. From there it came to mean passing through, and also managing. You know it from 「経済|けいざい」, economics, from the very first lesson. The second is 「験|けん」, to test or check. Its left side is the horse part. You know it from 「試験|しけん」, an exam. So, things you have passed through and been tested by. That is experience. The key pattern is 「経験がある|けいけんがある」, to have experience. For example, work experience, or experience living abroad. This links to a grammar point you know: verb in the past plus 「ことがある」 means you have done something before. The noun says it in one word. In job interviews you will hear this a lot, and job ads often say experience is not needed, using this word. Recap: passed through and tested, experience.",
    ja: "{日本|にほん}で{働いた|はたらいた}[経験|けいけん]があります。",
    en: "I have experience working in Japan." },
  "しゅうかん|習慣": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「習|しゅう」, to learn by practice. With its native reading it is the verb 「習う|ならう」, to learn from someone, and you know it in 「練習|れんしゅう」, practice. Look at the top. It is 「羽|はね」, feathers or wings. A way to remember it: a young bird flapping its wings again and again until it can fly. The second is 「慣|かん」, to get used to something. Its left side is the heart part, and with its native reading it gives 「慣れる|なれる」, to get used to. So, something practiced so often that you are used to it. This word covers both a personal habit, like jogging every morning, and a custom shared by a whole society. Some Japanese customs: taking your shoes off indoors, saying 「いただきます」 before meals, bowing when you greet people, and giving 「お土産|おみやげ」 after a trip. Recap: learned by practice plus got used to, a habit or custom.",
    ja: "{日本|にほん}の[習慣|しゅうかん]はおもしろいです。",
    en: "Japanese customs are interesting." },
  "しめきり|締め切り": {
    explain: "Two parts, both from native verbs, so both use native readings. The first is 「締め|しめ」, from 「締める|しめる」, to tighten, fasten or close up. It has the thread part on the left, like tying a cord tight. The second is 「切り|きり」, from 「切る|きる」, to cut. You know that kanji in 「切符|きっぷ」, a ticket, and in 「切手|きって」, a stamp. So, the point where things are closed up and cut off. After this moment, no more entries. It is used for homework, reports, job applications and work projects. Useful patterns. 「締め切りはいつですか|しめきりはいつですか」, when is the deadline. And 「締め切りを守る|しめきりをまもる」, to keep a deadline, which uses the same verb as 「約束を守る|やくそくをまもる」, to keep a promise. Writers and comic artists in Japan are famous for racing against their deadlines, and editors sometimes wait at their homes for the pages. Recap: close up plus cut off, the deadline.",
    ja: "[締め切り|しめきり]はあしたです。",
    en: "The deadline is tomorrow." },
  "よてい|予定": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「予|よ」, beforehand, in advance. It is in a nice little family you know. 「予約|よやく」, a reservation, a promise made in advance. And 「天気予報|てんきよほう」, the weather forecast, a report made in advance. The second is 「定|てい」, to fix or decide. It has the roof part on top, like something settled firmly in place. So, something fixed in advance. That is a plan or a schedule. Two very useful patterns. First, 「予定がある|よていがある」, to have plans. If someone invites you and you are busy, you can say 「その日は予定があります|そのひはよていがあります」, I have plans that day. Second, a plain verb plus 「予定です|よていです」 means I plan to, or it is scheduled. For example, 「来年日本に行く予定です|らいねんにほんにいくよていです」, I plan to go to Japan next year. It sounds a bit firmer than just wanting to. Recap: in advance plus fixed, a plan.",
    ja: "{週末|しゅうまつ}の[予定|よてい]はなんですか。",
    en: "What are your plans for the weekend?" },
  "そつぎょうしき|卒業式": {
    explain: "Three kanji, all with Chinese-origin readings. The first two make 「卒業|そつぎょう」, graduation. 「卒|そつ」 means to finish, and 「業|ぎょう」 means work or studies. You know 「業|ぎょう」 from 「授業|じゅぎょう」, a class, literally giving studies. So finishing your studies. Then comes 「式|しき」, a ceremony. That ending makes other ceremony words too, like 「結婚式|けっこんしき」, a wedding. And the opposite of this one is 「入学式|にゅうがくしき」, the entrance ceremony when you start school. A cultural note. The Japanese school year starts in April, so graduation ceremonies happen in March, just as the cherry blossoms are about to bloom. They are formal and emotional. Students sing together, receive their diplomas one by one, and many cry. At university graduations, many women wear a 「袴|はかま」, a traditional pleated skirt over a kimono, which makes the day very colorful. Recap: finish studies plus ceremony, the graduation ceremony.",
    ja: "きょうは[卒業式|そつぎょうしき]です。",
    en: "Today is the graduation ceremony." },
  "けっこんしき|結婚式": {
    explain: "Three kanji, all with Chinese-origin readings. The first two make 「結婚|けっこん」, marriage, which you know from 「結婚する|けっこんする」. 「結|けつ」 means to tie or bind, and it has the thread part on the left. Its sound shrinks to 「けっ」 here, a small pause before the next sound. 「婚|こん」 means marriage, and it has the woman part on the left. So two people tied together in marriage. Then comes 「式|しき」, a ceremony, the same ending as 「卒業式|そつぎょうしき」, the graduation ceremony. Notice the difference in use. 「結婚|けっこん」 is the marriage itself. This word is the wedding event. A cultural note. Many Japanese couples have a Western style chapel wedding, while others choose a Shinto ceremony at a shrine, a 「神社|じんじゃ」. Guests do not usually bring gifts from a registry. Instead they bring crisp new bills in a special decorated envelope, often around thirty thousand yen. Then there is a reception with speeches. Recap: tie, marriage, ceremony.",
    ja: "{来月|らいげつ}{姉|あね}の[結婚式|けっこんしき]があります。",
    en: "My older sister's wedding is next month." },
  "うる|売る": {
    explain: "This is a native Japanese verb, so the kanji takes its native reading. It is the opposite of 「買う|かう」, to buy, and they make a perfect pair. The kanji's Chinese-origin reading is 「ばい」, and you can see both partners in the word 「売買|ばいばい」, buying and selling. It is a regular u verb, so the te form is 「売って|うって」, with a small pause. To say a store sells something, use the te form plus 「いる」: 「あの店で本を売っています|あのみせでほんをうっています」, they sell books at that store. A neat shape detail. In modern kanji, this exact kanji forms the right side of 「読む|よむ」, to read, next to the words part. A way to remember it: a seller calling out in words, reading off the goods. Related everyday words. 「売り場|うりば」 is a sales floor in a department store, and 「売り切れ|うりきれ」, sold out, is the sad sign you see on a vending machine, with 「切る|きる」, to cut. Recap: the opposite of buy, the right side of read.",
    ja: "あのみせはくつを[売っています|うっています|うる]。",
    en: "That store sells shoes." },
  "おろす|下ろす": {
    explain: "This is a native verb using the native reading of 「下|した」, down, below. You know that kanji from 「下手|へた」, unskilled, and 「地下鉄|ちかてつ」, the subway. The verb means to bring something down or lower it. You take luggage down from a shelf, 「荷物を下ろす|にもつをおろす」. And you bring money down out of the bank: 「お金を下ろす|おかねをおろす」, to withdraw cash. A helpful cousin. You learned 「降りる|おりる」, to get off a train or bus. The sounds are close, because these native words are related, going down and bringing down. Notice that this verb takes 「を」 for the thing you are lowering. It is a regular u verb, so the past is 「下ろした|おろした」. A cultural note. Japan still uses a lot of cash, and many people withdraw money not at banks but at ATMs in convenience stores, which are open all night. Recap: down, so bring down, and with money it means withdraw.",
    ja: "ぎんこうでお{金|かね}を[下ろしました|おろしました|おろす]。",
    en: "I withdrew money at the bank." },
  "かく|描く": {
    explain: "This is a native verb, and it sounds exactly like 「書く|かく」, to write, which you learned early on. Japanese uses different kanji to show which kind of marks you are making. 「書く|かく」 is for writing letters and words. This kanji is for pictures. Its left side is the hand part, the same one in 「持つ|もつ」, to hold, a hand moving across paper. So the natural pair is 「絵を描く|えをかく」, to draw or paint a picture. You can also draw a map, 「地図を描く|ちずをかく」. In speech the two verbs sound identical, so context does the work. If you hear about a picture, it is this one. If you hear about a letter or a report, it is writing. Both are regular u verbs that change the same way, so the te form is 「描いて|かいて」. You may also see this kanji read 「えがく」, a more literary word for depicting something. A good related word is 「漫画家|まんがか」, a comic artist, someone whose job is drawing. Recap: same sound as write, but the hand is making pictures.",
    ja: "{子ども|こども}が{絵|え}を[描いています|かいています|かく]。",
    en: "The child is drawing a picture." },
  "さがす|探す": {
    explain: "This is a native verb, using the native reading. The kanji has the hand part on the left, the same one in 「持つ|もつ」, to hold, a hand reaching and feeling around for something. A memory hook, just a hook: it sounds like saga, and looking for your lost keys can turn into a long saga. The pattern is simple. The thing you are looking for takes 「を」. You can look for an apartment, 「アパートを探す|アパートをさがす」, a job, 「仕事を探す|しごとをさがす」, or a lost wallet. A common mistake for English speakers. To look up information, like a word or a train time, Japanese uses a different verb, 「調べる|しらべる」. Use this one for finding a thing or a person. Also watch the difference between searching and finding. This verb is the search. When the thing turns up, Japanese uses 「見つかる|みつかる」, to be found. So you search with this verb, and with luck, it is found. Recap: a hand feeling around, to look for something.",
    ja: "アパートを[探しています|さがしています|さがす]。",
    en: "I'm looking for an apartment." },
  "さそう|誘う": {
    explain: "This is a native verb using its native reading. Look at the left side of the kanji. It is the words part, the same piece on the left of 「話す|はなす」, to speak, and 「読む|よむ」, to read. A way to remember it: you use words to draw someone along. The pattern is: the person takes 「を」, and the event takes 「に」. So, to invite a friend to a movie is 「友だちを映画に誘う|ともだちをえいがにさそう」. A note on how it feels. This verb is about casually asking someone to join you, like going for a meal or a party. It is less formal than a printed invitation. In actual conversation, the invitation itself usually sounds like 「〜ませんか」, won't you, as in 「いっしょに行きませんか|いっしょにいきませんか」. A cultural note. When Japanese people turn down an invitation, they often avoid a direct no. They may just say 「ちょっと」, and let it trail off. Recap: words on the left, using words to draw someone along, to invite.",
    ja: "{友だち|ともだち}を{映画|えいが}に[誘いました|さそいました|さそう]。",
    en: "I invited my friend to a movie." },
  "しゃべる|": {
    explain: "A native verb, nearly always written in kana. There is a kanji spelling, 「喋る|しゃべる」, but you rarely need it. It is a casual, everyday word for talking and chatting, the easy flow of conversation between friends. Compare it with 「話す|はなす」, which is neutral, good for any situation, from a speech to a phone call. This verb is more relaxed, and it can hint at talking a lot. You would not use it for a formal speech. It is a regular u verb, so the te form is 「しゃべって」. You will also hear it for languages in casual speech, as in 「日本語がしゃべれる|にほんごがしゃべれる」, I can speak Japanese. A very common related word is 「おしゃべり」. As a noun it means a chat, and describing a person, it means a chatterbox. A way to remember it, as a hook: picture a group of friends at a café, chattering so much their coffee gets cold. Recap: casual talk, the chatty cousin of 「話す|はなす」.",
    ja: "{友だち|ともだち}と{一時間|いちじかん}[しゃべりました|しゃべりました|しゃべる]。",
    en: "I chatted with a friend for an hour." },
  "つきあう|付き合う": {
    explain: "Two native verbs joined together. The first is 「付く|つく」, to stick to or be attached. You know the same sound in 「気をつける|きをつける」, where you attach your attention, and in 「つける」, to turn on. The second is 「合う|あう」, to fit together or match. You know it in 「似合う|にあう」, to suit someone, where clothes fit you well. So, to stick together and fit with someone. It has two meanings. The first is to date someone, to be in a relationship. The pattern is 「〜と付き合う|〜とつきあう」, to go out with someone, often in the te form, 「付き合っています|つきあっています」, we are going out. The second is to keep someone company. If a friend says 「ちょっと付き合って|ちょっとつきあって」, they mean come along with me for a bit, maybe to a shop. A cultural note. In Japan, dating often begins with a clear confession of feelings, after which the couple officially starts going out. Recap: stick plus fit, to stay close to someone.",
    ja: "{二人|ふたり}は{去年|きょねん}から[付き合っています|つきあっています|つきあう]。",
    en: "The two of them have been dating since last year." },
  "つく|着く": {
    explain: "A native verb with the native reading. The kanji is the same one in 「着る|きる」, to wear, and 「着物|きもの」, kimono. The core idea of this kanji is to reach or attach to something. A way to remember the link, just a hook: clothes arrive on your body, and you arrive at a place. The pattern is: the destination takes 「に」. So 「駅に着く|えきにつく」, to arrive at the station, and 「家に着きました|いえにつきました」, I got home. A common mistake. English speakers sometimes use 「来る|くる」 or 「行く|いく」 when they mean the moment of arrival. Those two talk about the movement. This one is the moment you actually reach the place. Another tip. Several different verbs sound like 「つく」, including 「付く|つく」, to stick, which you see in 「付き合う|つきあう」. In speech, context sorts them out. It is a regular u verb, so the te form is 「着いて|ついて」. A handy line: 「着いたら電話します|ついたらでんわします」, I will call when I arrive. Recap: same kanji as wearing, reaching a place.",
    ja: "{駅|えき}に[着きました|つきました|つく]。",
    en: "I arrived at the station." },
  "ほけんにはいる|保険に入る": {
    explain: "This is a set phrase built from pieces you know. 「保険|ほけん」 is insurance, protection against danger. Then 「入る|はいる」, to enter, with the particle 「に」 marking what you go into. So, literally, to enter insurance. Where English says buy insurance or get insurance, Japanese thinks of it as joining something, like joining a group. You see the same idea in other phrases you know. 「お風呂に入る|おふろにはいる」, to take a bath, is literally to enter the bath. And people say 「大学に入る|だいがくにはいる」, to enter a university, or 「サークルに入る|サークルにはいる」, to join a club. A useful sentence: 「旅行の前に保険に入りました|りょこうのまえにほけんにはいりました」, I got insurance before the trip. Remember that 「入る|はいる」 is an u verb even though it ends in 「る」, so the past is 「入った|はいった」, with a small pause, just like 「帰った|かえった」. A cultural note. In Japan, residents, including foreign students, are expected to join the national health insurance system. Recap: enter insurance, you join it like a club.",
    ja: "りょこうの{前|まえ}に[保険に入りました|ほけんにはいりました|ほけんにはいる]。",
    en: "I bought insurance before the trip." },
  "きをつける|気をつける": {
    explain: "A set phrase. The first part is 「気|き」, one of the most useful kanji in Japanese. It means spirit, energy, mind or attention. It is in a big family you already know. 「元気|げんき」 is healthy, full of energy. 「天気|てんき」 is the weather, the energy of the sky. 「電気|でんき」 is electricity. 「気温|きおん」 is air temperature. And 「気分が悪い|きぶんがわるい」 means feeling sick. Then comes 「つける」, to attach or put on. So, to attach your mind to something, to pay attention. The thing you watch out for takes 「に」. For example, 「車に気をつけて|くるまにきをつけて」, watch out for cars. The most common form is 「気をつけて|きをつけて」, take care, which people say when someone leaves on a trip or heads home late. A memory tip: imagine pinning your attention onto something, like a magnet that will not let go. Recap: attach your mind, be careful.",
    ja: "{車|くるま}に[気をつけて|きをつけて|きをつける]ください。",
    en: "Please watch out for cars." },
  "しらべる|調べる": {
    explain: "A native verb using the native reading of the kanji. The kanji has the words part on the left, the same one in 「話す|はなす」, to speak, 「読む|よむ」, to read, and 「誘う|さそう」, to invite. Words are a good clue here, because this verb is about checking and investigating information. The thing you look into takes 「を」. You look up a word in a dictionary, 「辞書で調べる|じしょでしらべる」, or look up something online, 「ネットで調べる|ネットでしらべる」, with 「で」 for the tool you use. It also works for bigger things, like researching a topic for a report, or the police investigating a case. A common mistake. English uses look for and look up as if they were similar. Japanese splits them. When you are searching for a physical thing, like keys or an apartment, use 「探す|さがす」. When you are finding out facts, use this one. It is a ru verb, so the te form is 「調べて|しらべて」 and the polite form is 「調べます|しらべます」. Recap: words on the left, investigating information.",
    ja: "{電車|でんしゃ}の{時間|じかん}を[調べます|しらべます|しらべる]。",
    en: "I'll look up the train times." },
  "みえる|見える": {
    explain: "A native verb built on 「見る|みる」, to look or watch. The difference is about intention. 「見る|みる」 is when you choose to look at something. This verb is when something comes into view on its own, whether you are trying or not. So the thing you can see becomes the subject, marked with 「が」. For example, 「山が見えます|やまがみえます」, the mountains are visible. A great sentence for a hotel room with a view. A common mistake is to say 「山を見えます|やまをみえます」 with 「を」. Use 「が」. Its sound partner is 「聞こえる|きこえる」, to be audible, from 「聞く|きく」, to listen. Another trap. 「見られる|みられる」 means you are able to see something, like a movie that is available to watch. This verb is about things physically appearing in your sight. It is a ru verb, so the negative is 「見えない|みえない」, I cannot see it. A cultural note. On clear winter days you can see Mount Fuji from Tokyo. Recap: seeing without trying, things come into view.",
    ja: "へやから{山|やま}が[見えます|みえます|みえる]。",
    en: "You can see the mountains from the room." },
  "かんこうする|観光する": {
    explain: "Two kanji, both with Chinese-origin readings, plus 「する」, to do. The first is 「観|かん」, to view or observe carefully. It has the seeing part, 「見|み」, on the right. The second is 「光|こう」, light. With its native reading it is 「光|ひかり」, light, and the town of 「日光|にっこう」, sunlight, is a famous place for sightseeing. The word is usually traced to an old Chinese classic, which spoke of observing the light of a country, meaning its glory and culture. So, sightseeing is going to look at the bright sights of a place. The place you tour takes 「を」: 「京都を観光する|きょうとをかんこうする」, to sightsee in Kyoto. Related words are 「観光客|かんこうきゃく」, tourists, and 「観光地|かんこうち」, a tourist spot. A small contrast. 「旅行|りょこう」 is the whole trip, travel. This word is the looking around once you are there, visiting temples, shrines and famous views. Recap: view the light, sightseeing.",
    ja: "{京都|きょうと}を[観光しました|かんこうしました|かんこうする]。",
    en: "I went sightseeing in Kyoto." },
  "よやくする|予約する": {
    explain: "Two kanji, both with Chinese-origin readings, plus 「する」, to do. You met the noun 「予約|よやく」 before, and now it becomes a verb. The first kanji is 「予|よ」, beforehand. It is the same one in 「予定|よてい」, a plan, and 「天気予報|てんきよほう」, the weather forecast. The second is 「約|やく」, a promise or agreement. It has the thread part on the left, like tying a knot to seal a deal. You know it from 「約束|やくそく」, a promise. So, a promise made in advance. That is exactly what a reservation is. You promise to come, and they promise to hold your place. The thing you reserve takes 「を」: 「レストランを予約する|レストランをよやくする」, to book a restaurant. You can also reserve a hotel, a train seat on the 「新幹線|しんかんせん」, or a haircut at the 「美容院|びよういん」. A handy phrase on the phone is 「予約したいんですが|よやくしたいんですが」, I would like to make a reservation. Recap: in advance plus promise, to book.",
    ja: "レストランを[予約しました|よやくしました|よやくする]。",
    en: "I reserved a restaurant." },
  "さんかする|参加する": {
    explain: "Two kanji, both with Chinese-origin readings, plus 「する」, to do. The first is 「参|さん」, to go and join, or to visit respectfully. You may hear it in 「お参り|おまいり」, a visit to a shrine or temple to pray, with a different reading. The second is 「加|か」, to add. So, to go and add yourself to something. You join in and become one of the people taking part. The key grammar point is the particle. The event takes 「に」, because you are adding yourself to it. So 「パーティーに参加する|パーティーにさんかする」, to take part in a party, and 「ボランティア活動に参加する|ボランティアかつどうにさんかする」, to take part in volunteer activities. A common mistake is to use 「を」. Use 「に」. This word sounds a little more formal than just going. For a casual party with friends, people often just say 「行く|いく」 or 「出る|でる」. For events, tours, classes and meetings, this word fits well. Someone who participates is a 「参加者|さんかしゃ」. Recap: go and add yourself, to participate.",
    ja: "パーティーに[参加します|さんかします|さんかする]。",
    en: "I will take part in the party." },
  "そつぎょうする|卒業する": {
    explain: "Two kanji, both with Chinese-origin readings, plus 「する」, to do. The first is 「卒|そつ」, to finish or complete. The second is 「業|ぎょう」, work or studies. You know it from 「授業|じゅぎょう」, a class. So, to finish your studies. The ceremony for it is 「卒業式|そつぎょうしき」. The grammar is the interesting part. The school you graduate from takes 「を」, because you are leaving it behind. So 「大学を卒業する|だいがくをそつぎょうする」, to graduate from college. English says from, so learners often want a different particle, but Japanese uses 「を」, the same as when you leave a place, like getting off a train. A cultural note. Japanese uses this word in a fun extended way. When a member leaves a pop idol group, they do not quit, they graduate. People also joke about graduating from a habit, like finally quitting junk food. It makes leaving sound like a proud step forward. Recap: finish plus studies, and the school takes 「を」.",
    ja: "{来年|らいねん}{大学|だいがく}を[卒業します|そつぎょうします|そつぎょうする]。",
    en: "I will graduate from college next year." },
  "はっぴょうする|発表する": {
    explain: "Two kanji, both with Chinese-origin readings, plus 「する」, to do. The first is 「発|はつ」, to send out, to set off or to start. The second is 「表|ひょう」, to show or express. With its native reading it is 「表|おもて」, the surface or front side. Now watch the sounds change when they join. 「はつ」 shrinks to 「はっ」, a small pause, and 「ひょう」 turns into 「ぴょう」. So you get 「はっぴょう」. This kind of sound change is common when two Chinese-origin readings meet. So, to send something out and show it to people. That covers two uses. One is a presentation, like the talks students give in class. The other is making something public, like announcing news or results. A cultural note. In Japan, university entrance exam results are announced on a set day, and the moment when students check whether their number appears on the list is a big, emotional scene. Recap: send out plus show, to present or announce.",
    ja: "{授業|じゅぎょう}で[発表しました|はっぴょうしました|はっぴょうする]。",
    en: "I gave a presentation in class." },
  "〜けど|": {
    explain: "A small connecting word added to the end of a clause. It is the casual, conversational version of 「けれども」, and it means but, just like 「が」. For example, 「高いけど、おいしい|たかいけど、おいしい」, it is expensive, but tasty. It can follow plain forms or polite forms, so 「高いですけど|たかいですけど」 works too. 「が」 sounds a bit more formal and written, while this one feels softer and very natural in speech. Its second job is the tricky one. It often just gives background, more like and so, or leaves the rest of the sentence unsaid. For example, 「すみません、ちょっと聞きたいんですけど|すみません、ちょっとききたいんですけど」, excuse me, I have a quick question, and then the speaker waits. The listener fills in the rest. Stopping a sentence here sounds polite and gentle, because you are not pushing your point all the way. A common mistake is to think it always means but. Listen for whether there is a contrast. Recap: but, and also a soft way to set things up or leave them hanging.",
    ja: "{高い|たかい}です[けど]、{買います|かいます}。",
    en: "It's expensive, but I'll buy it." },
  "〜め|〜目": {
    explain: "This ending turns a number into an order, like first, second, third. The kanji is 「目|め」, eye, the same as the body part you learned, with its native reading. A way to remember it, just a hook: picture your eye moving along a row of things, counting one, two, three. It attaches to a number with a counter. So 「一つ目|ひとつめ」 is the first one, 「二回目|にかいめ」 is the second time, 「三日目|みっかめ」 is the third day, and 「一年目|いちねんめ」 is the first year. For order in a line or a ranking, you will often hear 「〜番目|〜ばんめ」, so 「二番目|にばんめ」 is the second. A common mistake. 「一番|いちばん」 on its own means number one, the best. Add this ending, 「一番目|いちばんめ」, and it just means first in order, with no idea of being the best. Directions use it a lot: 「二つ目の角|ふたつめのかど」, the second corner. Recap: number plus counter plus eye, the order of things.",
    ja: "{三つ|みっつ}[目|め]の{駅|えき}でおります。",
    en: "I get off at the third station." },
  "いちにちめ|一日目": {
    explain: "This is 「一日|いちにち」, one day, plus the order ending 「目|め」, the eye kanji, which turns a count into first, second, third. So day number one of something, a trip, a course, a festival or a new job. Be careful, because Japanese has three similar words. 「一日|いちにち」 means one day, a length of time. 「一日|ついたち」, the same kanji, means the first day of the month, the date. And this word means the first day in a sequence. You can keep counting with the day words you learned. 「二日目|ふつかめ」 is the second day, and 「三日目|みっかめ」 is the third day. Notice they use the special date readings, 「ふつか」 and 「みっか」, before the ending. A typical sentence: 「旅行の一日目は京都でした|りょこうのいちにちめはきょうとでした」, the first day of the trip was in Kyoto. You will hear this a lot when someone starts a new job and talks about how their first day went. Recap: one day plus the order ending, day one.",
    ja: "りょこうの[一日目|いちにちめ]は{東京|とうきょう}でした。",
    en: "The first day of the trip was in Tokyo." },
  "いちにちじゅう|一日中": {
    explain: "This is 「一日|いちにち」, one day, plus 「中|じゅう」. You know 「中|なか」 with its native reading, inside, and the Chinese-origin reading is usually 「ちゅう」. But after a word of time or place, it often turns into 「じゅう」 and means all through, the whole of it. So, all through the day, all day long. Compare the two sounds, because they mean different things. 「授業中に|じゅぎょうちゅうに」, with 「ちゅう」, means during class. 「今日中に|きょうじゅうに」, with 「じゅう」, means by the end of today, within the whole day. Here are more with the same ending: 「一年中|いちねんじゅう」, all year round, and 「世界中|せかいじゅう」, all over the world. Grammar tip. It works like an adverb, so it goes right before the verb with no particle: 「一日中寝ていました|いちにちじゅうねていました」, I slept all day. It often carries a feeling of too much, a whole day of work or rain. Recap: one day plus all through, all day long.",
    ja: "[一日中|いちにちじゅう]べんきょうしました。",
    en: "I studied all day long." },
  "さいきん|最近": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「最|さい」, the most. It makes superlatives, like 「最高|さいこう」, the best, literally the highest. The second is 「近|きん」, near. With its native reading it is 「近い|ちかい」, close by. Look at its bottom left, the moving along a road part, the same one in 「週|しゅう」, week. So the nearest stretch of time, recently, lately. A grammar tip. It often goes with a verb in the te form plus 「いる」, for something that has been going on: 「最近、日本語を勉強しています|さいきん、にほんごをべんきょうしています」, lately I have been studying Japanese. It also works with adjectives, like 「最近いそがしいです|さいきんいそがしいです」, I have been busy lately. And it can be used with the past for a single recent event. A related word you know is 「このごろ」, these days, which feels similar. The opposite idea would be long ago. Recap: the most plus near, the nearest stretch of time.",
    ja: "[最近|さいきん]いそがしいです。",
    en: "I've been busy recently." },
  "もういちど|もう一度": {
    explain: "Two pieces. The first is 「もう」. You may know it as already, but before a number or an amount, it means more or another. For example, 「もう少し|もうすこし」, a little more, and 「もう一つ|もうひとつ」, one more. The second piece is 「一度|いちど」, one time. The kanji 「度|ど」 is the counter for times. It is the same counter you learned for degrees of temperature, so it does double duty. 「二度|にど」 is twice, or two degrees. So, one more time. It is perfect for class. If you did not catch something, say 「もう一度お願いします|もういちどおねがいします」, once more, please. Or 「もう一度言ってください|もういちどいってください」, please say it again. A related word is 「〜回|〜かい」, which also counts times, so 「もう一回|もういっかい」 means the same and sounds a little more casual. Kids shout it constantly when they want to play a game again. Recap: more plus one time, one more time.",
    ja: "[もう一度|もういちど]{言って|いって}ください。",
    en: "Please say it one more time." },
  "たのしみです|楽しみです": {
    explain: "This comes from 「楽しい|たのしい」, fun or enjoyable, using the native reading of the kanji. Drop the adjective ending, add 「み」, and you get a noun, 「楽しみ|たのしみ」, something to enjoy, a pleasure still ahead of you. Add 「です」, and you are saying, this is something I am looking forward to. The thing you look forward to takes 「が」: 「旅行が楽しみです|りょこうがたのしみです」, I cannot wait for the trip. A longer form is 「楽しみにしています|たのしみにしています」, I am looking forward to it. A common mistake is to use it for something fun happening now. For right now, say 「楽しいです|たのしいです」. This one points to the future. Family of words. The same kanji, read with its Chinese-origin reading 「がく」, gives 「音楽|おんがく」, music, sound plus enjoyment, and with 「がっ」, 「楽器|がっき」, a musical instrument. Recap: the fun that is still coming, I cannot wait.",
    ja: "{旅行|りょこう}が[楽しみです|たのしみです]。",
    en: "I'm really looking forward to the trip." },
  "えきいん|駅員": {
    explain: "Two kanji, both read with their Chinese-origin readings. The first is 「駅|えき」, station. Look at its left side and you'll find the horse part, 「馬|うま」. That's real history. Long before trains, a station was a relay post on the road where riders swapped tired horses for fresh ones. The word stayed when the railways came. The second kanji is 「員|いん」, a member or staff person. You already know it from 「会社員|かいしゃいん」, a company person, an office worker. So the pattern is simple. Place plus 「員|いん」 means a person who works there as staff. A station plus staff gives you the people in uniforms at the ticket gates. In Japan they're the ones to ask when you're lost, when your ticket won't go through the gate, or when you need to know which platform to use. They're famous for being polite and precise, and at big stations they even help push commuters onto packed trains at rush hour. To recap: 「駅|えき」, the old horse relay station, plus 「員|いん」, staff member, gives station staff.",
    ja: "[駅員|えきいん]に{道|みち}を{聞きました|ききました}。",
    en: "I asked the station attendant for directions." },
  "おや|親": {
    explain: "Here the kanji is read with its native reading, 「おや」. In other words it switches to the Chinese-origin reading 「しん」, and that's where its family lives. In 「両親|りょうしん」 it's parents, both of them, since 「両|りょう」 means both. In 「親切|しんせつ」, kind, and in 「親せき|しんせき」, relatives, the same kanji carries the idea of closeness, being dear and intimate. That's a nice way to hold it together. A parent is the closest person of all. Now the shape. A popular memory hook, and it is a hook, not the real history, splits the kanji into three parts. 「立|た」, stand, 「木|き」, tree, and 「見|み」, see. Picture a parent standing up on a tree, watching over their child from above. One usage note. When you talk about your own parents politely, 「両親|りょうしん」 is the usual word. 「親|おや」 by itself is a bit more general and plain, like saying parent or parents in a broad sense, as in 「親にでんわします|おやにでんわします」. Recap: native 「おや」 for parent, Chinese-origin 「しん」 for closeness in 「両親|りょうしん」 and 「親切|しんせつ」.",
    ja: "[親|おや]に{電話|でんわ}をかけました。",
    en: "I called my parents." },
  "しんせき|親せき": {
    explain: "The first part is 「親|しん」, the same kanji as 「親|おや」, parent, but here it takes its Chinese-origin reading. It carries the idea of being close and dear, the same as in 「親切|しんせつ」, kind, which is literally close and caring, and 「両親|りょうしん」, parents. The second part, 「せき」, has its own kanji that also means relatives, but it's not on the everyday kanji list, so you'll usually see it written in kana, just like here. So the whole word is close family people. It covers your aunts, uncles, cousins, grandparents' side, everyone related to you beyond your own household. A cultural note that helps it stick. In Japan, the big times for seeing 「親せき|しんせき」 are 「お正月|おしょうがつ」, New Year's, and 「お盆|おぼん」 in summer, when people travel back to their hometowns. Kids often receive little envelopes of New Year's money from all their relatives, so for children, a big family means a good New Year. Recap: 「親|しん」, closeness, plus 「せき」, kin, gives your relatives.",
    ja: "お{正月|しょうがつ}に[親せき|しんせき]が{来ます|きます}。",
    en: "Relatives come over at New Year's." },
  "ごみ|": {
    explain: "This one is a native word, and in daily life it's written in kana, often in katakana too, so you'll see it both ways on signs. There is an old kanji spelling, but you won't need it. What matters more is how much this word comes up in Japanese life. Japan sorts its garbage very carefully. Each neighborhood has a schedule with set days for burnable trash, plastics, cans and bottles, and big items. You put the right bag out on the right morning, at the collection spot, and neighbors really do notice if you get it wrong. You'll also notice that public trash cans are rare, so people often carry their 「ごみ」 home. The verbs to pair with it are 「すてる」, to throw away, as in 「ごみをすてる」, and 「出す|だす」, which is what you say for putting the garbage out for collection, 「ごみを出す|ごみをだす」. Recap: 「ごみ」 is garbage, it goes out on the right day, and you 「出す|だす」 it or 「すてる」 it.",
    ja: "{朝|あさ}[ごみ]を{捨てます|すてます}。",
    en: "I take out the garbage in the morning." },
  "さとう|砂糖": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「砂|さ」, sand. Its shape is a nice one. On the left is the stone part, and on the right is the kanji for little or few. Little bits of stone. That's sand. On its own, sand is the native word 「すな」, but in this word it's read 「さ」. The second kanji is 「糖|とう」, sugar itself, and you can spot the rice part on its left side, a part that shows up in lots of food and grain kanji. Put them together and you get grainy sugar, sugar that looks like sand. Think of how white granulated sugar pours just like fine sand. 「糖|とう」 also appears in science and health words, for example in words about blood sugar, so it's a useful one to recognize. Pair this word with 「甘い|あまい」, sweet, which you already know, and with the verb 「入れる|いれる」, to put in, as in putting 「砂糖|さとう」 in your coffee. In Japanese cooking, sugar goes into many savory dishes, like sukiyaki and teriyaki sauce, which is why lots of Japanese food has that sweet and salty balance. Recap: sand plus sugar gives sand-like sugar.",
    ja: "コーヒーに[砂糖|さとう]を{入れます|いれます}。",
    en: "I put sugar in my coffee." },
  "ファイル|": {
    explain: "A loanword from the English word file. Japanese has no f sound of its own, so it uses 「フ」 with a small 「ァ」 to get close to fa. The English l sound becomes an r sound, and since Japanese words like to end in a vowel, an extra u is added at the end, giving the 「ル」. That's how file turns into this word. The meaning stretched a little in Japan. Yes, it means a computer file. But in everyday life it often means a physical folder or binder for papers. The most famous one is the 「クリアファイル」, the clear plastic sleeve folder that every Japanese student and office worker carries. Shops and anime stores sell them with characters printed on them, and companies give them away as free gifts. So if someone in Japan says they put a handout in their 「ファイル」, picture a plastic folder, not a computer. It's a cousin of other loanwords with the same squeeze, like 「ホテル」 from hotel, where the l also turns into r and gets a vowel. Recap: file, squeezed into Japanese sounds, meaning both a document folder and a computer file.",
    ja: "この[ファイル]は{私|わたし}のです。",
    en: "This folder is mine." },
  "おおきさ|大きさ": {
    explain: "This word is built with a handy bit of grammar. Start with the adjective 「大きい|おおきい」, big. Drop the final 「い」 and add 「さ」. The 「さ」 turns an adjective into a noun meaning how much of that quality something has. So big becomes bigness, which in English we'd just call size. The kanji 「大|おお」 here uses its native reading, the same as in 「大きい|おおきい」. Compare 「大学|だいがく」, college, where the same kanji takes its Chinese-origin reading 「だい」. The 「さ」 pattern works on many adjectives. 「長い|ながい」, long, becomes 「長さ|ながさ」, length. 「高い|たかい」, high, becomes 「高さ|たかさ」, height. 「おもい」, heavy, becomes 「おもさ」, weight. Once you know the trick, you can make a whole set of measurement words on your own. To ask about size, combine it with 「どのぐらい」, as in 「大きさはどのぐらいですか|おおきさはどのぐらいですか」, about how big is it. Recap: 「大きい|おおきい」 minus 「い」 plus 「さ」 gives size.",
    ja: "[大きさ|おおきさ]はどのぐらいですか。",
    en: "About how big is it?" },
  "みち|道": {
    explain: "Here the kanji takes its native reading, 「みち」. Look at the shape. Along the left and bottom runs a part that means moving along a road. You already know it from many words. It's in 「近い|ちかい」, near, in 「週|しゅう」, week, which moves on and on, in 「返事|へんじ」, reply, and in 「遅れる|おくれる」, to be late. Whenever you see that sweeping road part, think motion. The top right of 「道|みち」 is the kanji for head, 「首|くび」, which on its own actually means neck. A way to picture it: a person going forward, head first, down a path. The word's meaning is broad. It's a road or street, the way to somewhere, and directions, as in asking someone the way, 「道を聞く|みちをきく」. With its Chinese-origin reading 「どう」, the same kanji means a way of life or discipline. That's the 「どう」 in judo, kendo, and the tea ceremony, which literally means the way of tea. Recap: the moving part plus head gives a path you travel, read 「みち」 for road, and 「どう」 for a discipline.",
    ja: "[道|みち]がわかりません。",
    en: "I don't know the way." },
  "きまつしけん|期末試験": {
    explain: "Four kanji, all with Chinese-origin readings, and you know pieces of every one. 「期|き」 is a set period of time, a term. You've seen it in 「今学期|こんがっき」, this semester, where it's squeezed to 「き」 after a small 「っ」. 「末|まつ」 is the end, the tip. It's in 「週末|しゅうまつ」, weekend, the end of the week. So 「期末|きまつ」 is the end of the term. Then 「試験|しけん」, exam. 「試|し」 means to try or test, as in 「試合|しあい」, a match where teams test each other. It has the speech part on the left. 「験|けん」 means to check or verify, as in 「経験|けいけん」, experience. And look at its left side. That's the horse part, the same one you see in 「駅|えき」, station. So end of term plus exam gives the final exam. A note on Japanese school life. Most schools also have a mid-term exam, 「中間試験|ちゅうかんしけん」, the in-the-middle exam, and students cram hard for both. Recap: 「期|き」 term, 「末|まつ」 end, 「試験|しけん」 exam, so the end of term exam.",
    ja: "[期末試験|きまつしけん]はむずかしかったです。",
    en: "The final exam was difficult." },
  "けんきゅう|研究": {
    explain: "Two kanji, both with Chinese-origin readings. The first, 「研|けん」, has the stone part on its left side, and its core meaning is to grind or polish, like sharpening a blade on a whetstone. The second, 「究|きゅう」, has the hole or cave part on top, and it means to get to the bottom of something, to investigate all the way to the end. Put them together and research becomes polishing a question and digging down to its bottom. That's a nice picture of what scholars actually do, over and over, until the answer shines. You can grow the word easily. Add 「者|しゃ」, person, and you get 「研究者|けんきゅうしゃ」, researcher, which you also know. Add 「する」 and it becomes a verb, 「研究する|けんきゅうする」, to do research. A common pattern is the subject plus 「を研究しています|をけんきゅうしています」, I'm researching something. In Japanese universities, students in their final years join a professor's research group, often called a seminar or lab, and much of their life centers on it. Recap: grind and polish, then dig to the bottom, gives research.",
    ja: "{日本|にほん}の{文化|ぶんか}を[研究|けんきゅう]しています。",
    en: "I'm doing research on Japanese culture." },
  "だいがくいん|大学院": {
    explain: "Start with a word you know well, 「大学|だいがく」, college. Both kanji use Chinese-origin readings. 「大|だい」 is big, and 「学|がく」 is learning, so a big place of learning. Then add 「院|いん」. This kanji means an institution, a large formal building or establishment. You've met it in 「病院|びょういん」, hospital, the sickness institution, and in 「美容院|びよういん」, beauty parlor, the beauty institution. So 「大学院|だいがくいん」 is the institution attached to the university, the higher level you enter after finishing college. That's graduate school, for master's and doctoral degrees. Students there are called 「大学院生|だいがくいんせい」, adding 「生|せい」, the same as in 「学生|がくせい」, student. A cultural note. In Japan, far fewer people go on to graduate school than in the United States, especially outside science and engineering. Many companies traditionally hire students right after college and train them on the job. So saying you want to go to 「大学院|だいがくいん」 often means you're aiming for research or a specialist career. Recap: college plus institution gives graduate school.",
    ja: "[大学院|だいがくいん]に{行きたい|いきたい}です。",
    en: "I want to go to graduate school." },
  "しょうがくきん|奨学金": {
    explain: "Three kanji, all with Chinese-origin readings. The first, 「奨|しょう」, means to encourage or urge on. It's not a common kanji on its own, but it's the key to this word. The second is 「学|がく」, learning, the same one in 「学生|がくせい」, student, and 「大学|だいがく」, college. The third is 「金|きん」, money or gold. You know it from 「金曜日|きんようび」, Friday, and 「税金|ぜいきん」, tax. Notice that in 「お金|おかね」, money, the same kanji uses its native reading 「かね」, but in compound words it usually switches to 「きん」. Now put it together: encourage, learning, money. Money given to encourage study. That's a scholarship. One thing to know about Japan. Many things called 「奨学金|しょうがくきん」 there are actually student loans that you have to pay back after you graduate, and only some are true grants that you don't repay. So when a Japanese friend says they're paying back their 「奨学金|しょうがくきん」, that's why. The verb that goes with it is 「もらう」, to receive. Recap: encourage plus study plus money gives scholarship.",
    ja: "[奨学金|しょうがくきん]をもらいました。",
    en: "I received a scholarship." },
  "すいせんじょう|推薦状": {
    explain: "This word has two parts, all read with Chinese-origin readings. First, 「推薦|すいせん」, recommendation. 「推|すい」 has the hand part on its left, and it means to push forward. 「薦|せん」 is a rare kanji that also means to recommend. So you're pushing someone forward, putting them up for something. That's what a recommendation is. Then 「状|じょう」, a formal letter or written document. You'll meet it in 「年賀状|ねんがじょう」, the New Year's cards that people in Japan mail to friends, family, and coworkers so they all arrive on New Year's Day. So the whole word is a written push forward, a letter of recommendation. You'll need one for applying to 「大学院|だいがくいん」, graduate school, or for a 「奨学金|しょうがくきん」, a scholarship, so these three words come as a set in this lesson. The usual pattern is asking a teacher to write it for you, using the giving and receiving grammar, 「先生に推薦状を書いてもらいました|せんせいにすいせんじょうをかいてもらいました」. Recap: push forward plus recommend plus letter gives a letter of recommendation.",
    ja: "{先生|せんせい}に[推薦状|すいせんじょう]を{書いて|かいて}もらいました。",
    en: "I had my teacher write me a letter of recommendation." },
  "たいふう|台風": {
    explain: "Two kanji, both with Chinese-origin readings. The second, 「風|ふう」, is wind. You know this kanji in its other readings too. In 「風邪|かぜ」, a cold, it's the native reading 「かぜ」, the same sound as the word for wind, as if a cold is something the wind blows in. And in 「お風呂|おふろ」, bath, it's read 「ふ」. The first kanji, 「台|たい」, usually means a stand or platform, and you know it as the counter for machines, 「〜台|〜だい」. In this word it's read 「たい」 and it's mostly there for its sound. The word sounds very much like the English typhoon, and that's a perfect hook. The history of which language borrowed from which is tangled, so just enjoy the match. Typhoons hit Japan mostly from late summer into fall. Japan numbers them each year in order, so the news says typhoon number one, number two, and so on. When one comes, trains stop, schools may close, and people stock up and stay home. Weather forecasts, 「天気予報|てんきよほう」, track them closely. Recap: stand plus wind, sounds like typhoon, comes in late summer and fall.",
    ja: "[台風|たいふう]が{来ます|きます}から、{気をつけて|きをつけて}ください。",
    en: "A typhoon is coming, so please be careful." },
  "ぶんか|文化": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「文|ぶん」, writing, letters, sentences, the written arts. You've seen it in 「文法|ぶんぽう」, grammar, which is literally the rules of writing. The second is 「化|か」, to change or transform. It shows up in 「化粧品|けしょうひん」, cosmetics, things that change how you look. The left side of 「化|か」 is the person part, and its whole idea is turning into something else. So writing plus change. In old Chinese, this pairing meant changing and refining people through learning and the written word rather than by force. Later, when Japan needed a word for the Western idea of culture, this was the word it chose. It fits nicely. Culture is what people become through learning, art, and shared ways of life. You'll see it a lot in phrases like 「日本の文化|にほんのぶんか」, Japanese culture, and there's even a national holiday called Culture Day in early November. Recap: writing plus transformation, people shaped by learning, gives culture.",
    ja: "{日本|にほん}の[文化|ぶんか]がすきです。",
    en: "I like Japanese culture." },
  "へんじ|返事": {
    explain: "Two kanji, both with Chinese-origin readings. The first is 「返|へん」, to return or send back. It has the moving-along-a-road part on its left and bottom, which fits, because something travels back. You already know this kanji with its native reading in 「返す|かえす」, to return a thing, and in 「お返し|おかえし」, a return gift. The second is 「事|じ」, a thing or a matter. You know it from 「用事|ようじ」, business to take care of, and in 「仕事|しごと」, work, it takes its native reading 「こと」 with the sound softened to 「ごと」. So the whole word is the thing you send back. A reply. It's used for replying to letters, invitations and messages, and also for answering when someone calls your name. In Japanese classrooms, when the teacher calls roll, students answer 「はい」, and that is called giving a 「返事|へんじ」. A common pattern is 「返事をする|へんじをする」, to reply, or 「返事を書く|へんじをかく」, to write a reply. For email you may also hear a more technical word, but this one works everywhere. Recap: send back plus thing gives reply.",
    ja: "メールの[返事|へんじ]を{書きました|かきました}。",
    en: "I wrote a reply to the email." },
  "ひ|日": {
    explain: "This kanji began as a picture of the sun, a circle with a dot in the middle, which got squared off over time into the box with a line you see now. Since one trip of the sun across the sky is one day, the kanji means both sun and day. Here it's the native reading 「ひ」, used on its own as the word for a day. You know this kanji in many other readings. It's 「にち」 in 「毎日|まいにち」, every day, and 「日本|にほん」, Japan, the land where the sun comes from. It's 「び」 in 「誕生日|たんじょうび」, birthday, and in the days of the week, like 「日曜日|にちようび」, Sunday, the sun day. With so many readings, the bare 「ひ」 shows up mainly in phrases where you describe what kind of day it was. For example 「雨の日|あめのひ」, a rainy day, 「休みの日|やすみのひ」, a day off, or 「その日|そのひ」, that day. One mistake to avoid. For dates like the fifth of the month, use the date words, not this one. Recap: a picture of the sun, one sun is one day, read 「ひ」 when it stands alone.",
    ja: "{雨|あめ}の[日|ひ]は{家|いえ}にいます。",
    en: "On rainy days I stay home." },
  "きたない|汚い": {
    explain: "The kanji 「汚|きた」 here uses its native reading, followed by 「ない」 written in kana. Don't be fooled by that ending. It is not the negative 「ない」. This whole word is just a regular 「い」 adjective that happens to end in those sounds. So 「汚くない|きたなくない」 means not dirty. Now the kanji. On its left side is the three-drop water part, the same one you'll see in many kanji about water and liquids. A way to picture it: muddy, dirty water. The opposite is 「きれい」, which means both beautiful and clean. That makes a handy pair, a dirty room versus a clean room. The word has some useful stretches too. 「字が汚い|じがきたない」 means messy handwriting. And for a person or behavior, it can mean dirty in the sense of unfair, like a dirty trick, so be careful about saying it to people. In Japan, cleanliness matters a lot. Students clean their own classrooms every day, so a 「汚い|きたない」 classroom is the students' own fault. Recap: the water part, dirty water, an 「い」 adjective, opposite of 「きれい」.",
    ja: "へやが[汚い|きたない]です。",
    en: "The room is dirty." },
  "おこす|起こす": {
    explain: "This verb is the partner of one you know, 「起きる|おきる」, to get up or wake up. They share the kanji 「起|お」 with its native reading, and the shape is fun. On its left, wrapping underneath, is 「走|はし」, the kanji from 「走る|はしる」, to run. Getting up and getting going. The two verbs are a classic Japanese pair. 「起きる|おきる」 is something that happens to you. You wake up. 「起こす|おこす」 is something you do to someone or something else. You wake someone up. So 「私は七時に起きます|わたしはしちじにおきます」, I get up at seven, but 「母を起こします|ははをおこします」, I wake my mother. You'll see this kind of pairing again and again. One verb takes 「を」 and acts on something, the other just happens. A useful request is 「起こしてください|おこしてください」, please wake me up. Later you'll also meet it with the meaning to cause something, like causing an accident, which comes from the same idea of raising something up. Recap: 「起きる|おきる」 you wake, 「起こす|おこす」 you wake someone else.",
    ja: "あした{七時|しちじ}に[起こして|おこして|おこす]ください。",
    en: "Please wake me up at seven tomorrow." },
  "おごる|": {
    explain: "There is a kanji for this verb, but it's rarely used, so it's normally written in kana. It's a casual, friendly word for paying for someone else's food or drinks. Who pays is a real social topic in Japan. Among friends, splitting the bill evenly is very common, and there's even a word for it, 「わりかん」. But senior people often pay for juniors. A boss treating the team, or an older student treating younger club members, is a familiar scene, and the younger ones are expected to thank them warmly, often with 「ごちそうさまでした」. The grammar is worth getting right. The person you treat takes 「に」, and the food takes 「を」, as in 「友だちに昼ごはんをおごる|ともだちにひるごはんをおごる」. To say someone treated you, use 「おごってもらう」, I received the treat. To offer, say 「今日は私がおごります|きょうはわたしがおごります」, today it's on me. A way to remember it: oh, go ahead, I'll get this. Recap: a casual verb for treating someone, person with 「に」, meal with 「を」.",
    ja: "{友だち|ともだち}に{昼ごはん|ひるごはん}を[おごりました|おごりました|おごる]。",
    en: "I treated my friend to lunch." },
  "わらう|笑う": {
    explain: "The kanji is read with its native reading, 「わら」, followed by 「う」. Look at the top of the kanji. Those two little shapes are the bamboo part, the same top you see on many kanji for bamboo things. The origin of the bottom part is debated, so here's a memory hook instead. A way to remember it: picture bamboo bending and swaying in the wind, like a person doubled over, shaking with laughter. The verb covers laughing and also smiling. A smiling face is 「笑顔|えがお」, with 「顔|かお」, face, which you know. Here's a fun modern note. In Japanese online chat, people type the letter w after a message to mean lol. It comes from the first sound of this very word. Several w's in a row look like grass, so laughing online is jokingly called grass. If you see a Japanese comment full of w's, someone is laughing. One grammar point. To laugh at someone or something, use 「を」. Recap: bamboo top, bending with laughter, 「笑う|わらう」 for laughing and 「笑顔|えがお」 for a smiling face.",
    ja: "みんなが[笑いました|わらいました|わらう]。",
    en: "Everyone laughed." },
  "おちこむ|落ち込む": {
    explain: "This is a compound verb, two verbs glued together, both with native readings. The first is 「落ちる|おちる」, to fall or drop. You'll know it from things falling off a desk, or failing an exam, which in Japanese is falling off it too. The second is 「込む|こむ」, which means to go into, to get packed in. On its own, it's the verb for a train being crowded. When it's attached after another verb, it adds the sense of going deep inside. So falling plus going in means sinking down into a hole. Literally, that's what it can mean, like ground caving in. But most often it's about feelings. You sink into a low mood. To feel down, to get depressed after something goes wrong. Note it's not usually a medical word. It's what you'd say after a bad test, a breakup, or a failed job interview. People commonly use the 「ている」 form, as in 「落ち込んでいる|おちこんでいる」, to say someone is feeling down right now. If a friend is 「落ち込んでいる|おちこんでいる」, you might cheer them up and say 「げんきを出して|げんきをだして」. Recap: fall plus sink in gives getting down in the dumps.",
    ja: "{試験|しけん}がだめで、[落ち込みました|おちこみました|おちこむ]。",
    en: "The exam went badly, so I got depressed." },
  "こまる|困る": {
    explain: "The kanji is read with its native reading, 「こま」, plus 「る」. Its shape is easy to see. It's 「木|き」, tree, inside a closed box. The real origin of the kanji is debated, so take this as a memory hook. A way to remember it: a tree boxed in on every side has no room to grow. It's stuck. It's in trouble. That's the feeling of this verb. Having a problem, being at a loss, not knowing what to do. The grammar has a twist for English speakers. To say you're in trouble right now, Japanese uses the 「ている」 form, 「困っています|こまっています」, because it's an ongoing state. And the thing causing trouble usually comes first with a reason form, as in 「お金がなくて困っています|おかねがなくてこまっています」, I'm stuck because I have no money. A very common little phrase is 「困ったな|こまったな」, said to yourself when something goes wrong, like oh no, what now. You'll also hear 「困ったときは|こまったときは」, when you're in trouble, as in come to me anytime. Recap: a tree stuck in a box, stuck and in trouble, usually 「困っています|こまっています」.",
    ja: "お{金|かね}がなくて、[困っています|こまっています|こまる]。",
    en: "I have no money, so I'm in trouble." },
  "だす|出す": {
    explain: "This verb is the partner of one you know, 「出る|でる」, to go out or come out. The kanji 「出|だ」 is the same, using its native reading. 「出る|でる」 is something that goes out by itself. You leave a room. 「出す|だす」 is you sending something out. You take it out, put it out, or hand it in. That's why the meanings look like a mixed bag in English, but they're all one idea: something moves out because you made it. You hand in homework, 「宿題を出す|しゅくだいをだす」. You mail a letter, 「手紙を出す|てがみをだす」. You put the garbage out, 「ごみを出す|ごみをだす」. You take something out of your bag. The same kanji also appears with its Chinese-origin reading 「しゅつ」 in 「出身|しゅっしん」, where you come from, and as 「で」 in 「出かける|でかける」, to go out. A nice phrase to know is 「げんきを出して|げんきをだして」, cheer up, which is literally put your energy out. Recap: 「出る|でる」 something goes out, 「出す|だす」 you send it out, homework, letters and garbage included.",
    ja: "{宿題|しゅくだい}を[出しました|だしました|だす]。",
    en: "I handed in my homework." },
  "なおす|直す": {
    explain: "The kanji uses its native reading, 「なお」. Its core meaning is straight, direct, honest. To fix something is to make it straight again, so that it's right. That one idea covers many uses. You fix a broken bike. You correct mistakes in a paper. A teacher corrects your Japanese. The thing you fix takes 「を」. There's a related kanji to know about. When you cure an illness, the same sound 「なおす」 is usually written with a different kanji that means to govern or heal. Same sound, different spelling, so don't be surprised to see both. A very handy pattern comes later. 「直す|なおす」 can be added to the stem of another verb to mean redo it, do it again properly. For example, 「書き直す|かきなおす」, to rewrite, and 「やり直す|やりなおす」, to do over. It keeps the same idea of making it straight and right. Pair it with the intransitive partner 「直る|なおる」, which means something gets fixed by itself or is fixed. Recap: straight and right, so 「直す|なおす」 is to make something right again, fixing or correcting it.",
    ja: "{先生|せんせい}が{私|わたし}の{日本語|にほんご}を[直しました|なおしました|なおす]。",
    en: "The teacher corrected my Japanese." },
  "みつかる|見つかる": {
    explain: "This verb is built on the kanji 「見|み」, to see, with its native reading, the same as in 「見る|みる」, to see, and 「見える|みえる」, to be visible. The word means to be found, or to turn up. Think of it as the thing becoming seen. It's the partner of 「見つける|みつける」, to find. Here's how they divide the job. With 「見つける|みつける」, a person does the finding, and the thing found takes 「を」. With 「見つかる|みつかる」, the thing just turns up, and it takes 「が」. So 「さいふが見つかりました|さいふがみつかりました」, my wallet was found, or my wallet turned up. Japanese often prefers this way of speaking, focusing on what happened rather than who did it. A common mistake for English speakers is using 「を」 with this verb. Don't. It also gets used in job hunting and housing. If you finally found a job or an apartment, you'd say it was found, using this verb. And the 「ない」 form, 「見つからない|みつからない」, is the go-to way to say I can't find it. Recap: something becomes seen, turns up, with 「が」. Partner of 「見つける|みつける」.",
    ja: "さいふが[見つかりました|みつかりました|みつかる]。",
    en: "My wallet was found." },
  "やくす|訳す": {
    explain: "The kanji uses its native reading, 「やく」, plus 「す」. Look at its left side. That's the speech or words part. It's the same part you see on 「話す|はなす」, to speak, 「言う|いう」, to say, 「読む|よむ」, to read, and 「語|ご」 in 「外国語|がいこくご」, foreign language. Whenever you see it, think words. So this verb is about doing something with words, turning them from one language into another. The grammar: the language you translate into takes 「に」, as in 「英語に訳す|えいごにやくす」, to translate into English. The language you translate from takes 「から」. The same kanji appears in words you'll meet later. Translation as a noun is 「翻訳|ほんやく」, and an interpreter is 「通訳|つうやく」. And here's a surprise. It also shows up in 「言い訳|いいわけ」, which means an excuse. There, the kanji means reason. You can think of an excuse as explaining yourself in other words. Recap: the words part on the left, turning words into another language, into with 「に」.",
    ja: "{英語|えいご}に[訳して|やくして|やくす]ください。",
    en: "Please translate it into English." },
  "かす|貸す": {
    explain: "The kanji uses its native reading, 「か」, plus 「す」. Look at the bottom part of it. That's 「貝|かい」, shell. In ancient China, shells were used as money, so this shell part shows up in lots of kanji connected to money and value. Lending things, money especially, fits right in. This verb is the opposite partner of 「借りる|かりる」, to borrow. Notice they even start with the same sound, which makes them easy to mix up. The key is the direction. With 「貸す|かす」, the thing goes away from you. With 「借りる|かりる」, it comes to you. A very common mistake: when you want to ask a friend for their pen, you can say 「貸してください|かしてください」, which literally means please lend it to me. That's correct and very natural. Or you can say 「借りてもいいですか|かりてもいいですか」, may I borrow it. Both work, as long as the verb matches who is acting. The person you lend to takes 「に」, as in 「友だちにかさを貸す|ともだちにかさをかす」, to lend a friend an umbrella. Recap: shell money underneath, things going away from you, opposite of 「借りる|かりる」.",
    ja: "{友だち|ともだち}にかさを[貸しました|かしました|かす]。",
    en: "I lent my umbrella to a friend." },
  "つれていく|連れていく": {
    explain: "This is the te form of 「連れる|つれる」, to bring someone along, plus 「いく」, to go. The kanji 「連|つ」 uses its native reading. It has the moving-along-a-road part on the left and bottom, and 「車|くるま」, car or cart, in the middle. Its core meaning is to link up or accompany. A way to remember it: carts traveling together in a line. So the whole phrase means to go somewhere with a person in tow. You take your child to the park, or take a friend to a restaurant. Here's the key point for English speakers. Japanese splits take by what you're taking. For people and animals, use this verb. For things, use 「持っていく|もっていく」, take a thing, which you already know. So you don't 「持っていく|もっていく」 your little brother. The direction works the same as with things too. Its partner 「連れてくる|つれてくる」 means to bring someone here, toward where you are. Going away uses 「いく」, coming toward uses 「くる」. The place you take them takes 「に」. Recap: accompany plus go, for people only, while things use 「持っていく|もっていく」.",
    ja: "{子ども|こども}を{公園|こうえん}に[連れていきました|つれていきました|つれていく]。",
    en: "I took my child to the park." },
  "みちにまよう|道に迷う": {
    explain: "Three pieces, all native readings. 「道|みち」 is the road or way. 「に」 marks where the problem happens. And 「迷う|まよう」 means to be lost, to wander, or to be unsure which way to go. So it's literally to be lost on the road. Look at the kanji 「迷|まよ」. Like 「道|みち」 itself, it has the moving-along-a-road part on the left and bottom. Two road kanji in one phrase, which fits a phrase about wandering. The middle of 「迷|まよ」 is the rice shape, but don't read too much into that. The verb 「迷う|まよう」 also has a second use, being unable to make up your mind. If you can't choose between two dishes on a menu, you're 「迷っている|まよっている」. A lost child is 「迷子|まいご」, which you'll hear in announcements at department stores and amusement parks. A note on Japan. Most streets there don't have names, and addresses go by blocks, so even locals get lost. The little police boxes called 「こうばん」 often help with directions. Recap: road plus wander, two road kanji, to get lost.",
    ja: "きのう[道に迷いました|みちにまよいました|みちにまよう]。",
    en: "I got lost yesterday." },
  "むかえにいく|迎えに行く": {
    explain: "This phrase uses a pattern you know from 「買い物に行く|かいものにいく」, to go shopping. A verb stem or action noun, plus 「に」, plus a motion verb, means going in order to do that. Here the action is 「迎え|むかえ」, from the verb 「迎える|むかえる」, to meet, greet or welcome someone who is arriving. The kanji uses its native reading, and it has the moving-along-a-road part on the left and bottom, like in 「近い|ちかい」, near, and 「道|みち」, road. Someone is traveling toward you, and you go out to meet them. So the whole phrase means to go to welcome someone, which in daily life means to go pick them up. Going to the station to get your mother, going to the airport for a friend, going to school to pick up your kid. The place takes 「に」 and the person takes 「を」, as in 「駅に母を迎えに行きます|えきにははをむかえにいきます」. Its partner is 「迎えに来る|むかえにくる」, to come to pick up, for when someone comes to where you are. Recap: welcome plus go for that purpose, going out to get someone.",
    ja: "{駅|えき}に{母|はは}を[迎えに行きます|むかえにいきます|むかえにいく]。",
    en: "I'll go to the station to pick up my mother." },
  "あつめる|集める": {
    explain: "The kanji uses its native reading, 「あつ」, plus 「める」. This is one of those kanji whose picture is real. On top is a bird part, the one used for short-tailed birds, and underneath is 「木|き」, tree. In older forms, there were even several birds on the tree. Birds flocking together on a branch, that's gathering. The verb means to gather things or people together, to collect. You collect stamps, gather information, or call people together for a meeting. The thing collected takes 「を」, and for a hobby you'd use the 「ている」 form, as in 「切手を集めています|きってをあつめています」, I collect stamps. It has an intransitive partner, 「集まる|あつまる」, which means to gather by themselves, like people gathering at a park. You'll find the same kanji with its Chinese-origin reading 「しゅう」 in 「募集|ぼしゅう」, recruitment, gathering people for a job or a club. A cultural note: collecting is a big hobby in Japan, from train station stamps that travelers stamp in little notebooks to temple seals. Recap: birds gathering on a tree, collecting things together.",
    ja: "{古い|ふるい}{本|ほん}を[集めています|あつめています|あつめる]。",
    en: "I collect old books." },
  "いれる|入れる": {
    explain: "The kanji 「入|い」 uses its native reading here. Its shape is simple, two strokes leaning into each other, and it means to enter or go in. You know it from 「入る|はいる」, to enter, as in 「お風呂に入る|おふろにはいる」, to take a bath, which is literally to enter the bath, and 「保険に入る|ほけんにはいる」, to buy insurance, which is to enter an insurance plan. Notice the same kanji is read 「はい」 there and 「い」 here. These two verbs are a classic pair. 「入る|はいる」 is something going in by itself. You enter a room. 「入れる|いれる」 is you putting something in. You put milk in coffee, or a book in your bag. The thing goes with 「を」 and the place with 「に」, as in 「かばんに本を入れる|かばんにほんをいれる」. A bonus use: 「お茶を入れる|おちゃをいれる」 means to make tea, because you're putting the tea into the pot and the hot water in. And when you get into a group or a club, someone lets you in, which is also this verb. Recap: 「入る|はいる」 you go in, 「入れる|いれる」 you put something in.",
    ja: "コーヒーにミルクを[入れます|いれます|いれる]。",
    en: "I put milk in my coffee." },
  "みせる|見せる": {
    explain: "Built on the kanji 「見|み」, to see, with its native reading, the same one in 「見る|みる」, to see, 「見える|みえる」, to be visible, and 「見つかる|みつかる」, to be found. This verb flips the seeing around. Instead of you seeing, you make someone else see. That's showing. You show your photos, your passport, your homework. The person you show it to takes 「に」, and the thing shown takes 「を」, as in 「友だちに写真を見せる|ともだちにしゃしんをみせる」. The most useful phrase by far is 「見せてください|みせてください」, please show me. Use it in a shop when you want to see an item behind the counter, as in 「それを見せてください|それをみせてください」, please show me that one. A common mistake is mixing it up with 「見る|みる」. If you say 「見てください|みてください」, you're asking someone to look at something. If you say 「見せてください|みせてください」, you're asking them to let you look. Here's a fun fact. The word for a shop, 「店|みせ」, has the same sound, and one common explanation links it to a place where goods are shown. Recap: 「見る|みる」 you look, 「見せる|みせる」 you make someone look, show.",
    ja: "{写真|しゃしん}を[見せて|みせて|みせる]ください。",
    en: "Please show me the photos." },
  "のりおくれる|乗り遅れる": {
    explain: "This is a compound verb, two verbs joined, both with native readings. The first is 「乗る|のる」, to ride or get on, which you know from riding trains and buses. Notice that 「乗る|のる」 marks the vehicle with 「に」, as in 「電車に乗る|でんしゃにのる」. That 「に」 carries over into this verb too. The second part is 「遅れる|おくれる」, to be late. Its kanji 「遅|おく」 has the moving-along-a-road part on its left and bottom, and you know it from 「遅い|おそい」, slow or late, 「遅く|おそく」, late, and 「遅刻する|ちこくする」, to be late for an appointment. Put them together: ride plus be late. Too late to ride. You missed it. So 「電車に乗り遅れました|でんしゃにのりおくれました」, I missed the train. Japanese trains are famous for leaving right on time, to the second, so if you're even a moment late, the doors close and you're left on the platform. The worst one to miss is the last train of the night, which might mean an expensive taxi or a night in a karaoke box. Recap: ride plus late, too late to ride, missing the train with 「に」.",
    ja: "{朝|あさ}、{電車|でんしゃ}に[乗り遅れました|のりおくれました|のりおくれる]。",
    en: "I missed the train this morning." },
  "アイロンをかける|": {
    explain: "Two parts. 「アイロン」 is a loanword from the English word iron, the tool for pressing clothes. It follows the English spelling more than the English pronunciation. In English we hardly say the r, but Japanese reads it letter by letter, with the r sound clearly in the middle, and adds the 「ン」 at the end. The second part is the very handy verb 「かける」. It's a verb for hanging or putting something onto something else, and you already know several of its uses. 「めがねをかける」 is to put on glasses, onto your face. 「電話をかける|でんわをかける」 is to make a phone call. And here, 「アイロンをかける」 is to run the iron over clothes. The clothes take 「に」, because you put the iron onto them, as in 「シャツにアイロンをかける」, to iron a shirt. A way to remember it: whenever something gets put onto something else, think 「かける」. Glasses onto your face, the iron onto your shirt. Recap: the iron, borrowed from English with a clear r, put onto the clothes with 「かける」.",
    ja: "シャツに[アイロンをかけました|アイロンをかけました|アイロンをかける]。",
    en: "I ironed my shirt." },
  "あさねぼうする|朝寝坊する": {
    explain: "Three kanji with mixed readings, plus 「する」. 「朝|あさ」, morning, uses its native reading, as in 「朝ご飯|あさごはん」, breakfast. 「寝|ね」, sleep, also uses its native reading, as in 「寝る|ねる」, to sleep. And 「坊|ぼう」 uses its Chinese-origin reading. That kanji originally meant a monk's lodging, and later came to be used for monks and then for little boys, as in 「赤ん坊|あかんぼう」, a baby. Added after another word, it can mean a person who's like that, a little affectionately. So 「寝坊|ねぼう」 is a sleepyhead, someone who sleeps late. Add 「朝|あさ」 and it's a morning sleepyhead. With 「する」, it becomes the verb, to oversleep. You'll often hear just 「寝坊する|ねぼうする」, and it means the same thing. It's the classic excuse for being late, so it pairs naturally with 「遅れる|おくれる」, as in 「寝坊して遅れました|ねぼうしておくれました」, I overslept and was late. A note on Japan: it's polite to apologize directly for this rather than make excuses. Recap: morning plus sleep plus little boy, a morning sleepyhead, to oversleep.",
    ja: "きょうは[朝寝坊しました|あさねぼうしました|あさねぼうする]。",
    en: "I overslept today." },
  "あんないする|案内する": {
    explain: "Two kanji, both with Chinese-origin readings, plus 「する」. The first, 「案|あん」, means a plan or an idea. You can see 「木|き」, tree, at the bottom, and it's more common in words about plans and proposals. The second, 「内|ない」, means inside or within. On its own, with its native reading, it's 「うち」, inside, home. So together it's like planning a route through the inside of a place. Leading someone around somewhere you know, as their guide. That covers giving someone a tour of your town or school, showing a guest to their seat, or guiding visitors through a building. The place takes 「を」 and the person you guide takes 「に」, as in 「友だちに町を案内しました|ともだちにまちをあんないしました」, I showed my friend around town. You'll also see the noun a lot on signs. An information desk at a station or department store is called 「案内所|あんないじょ」, and a store guide or directory board uses it too. When you visit Japan, look for it whenever you need help. Recap: plan plus inside, guiding someone through a place.",
    ja: "{友だち|ともだち}に{町|まち}を[案内しました|あんないしました|あんないする]。",
    en: "I showed my friend around town." },
  "せつめいする|説明する": {
    explain: "Two kanji, both with Chinese-origin readings, plus 「する」. The first is 「説|せつ」, to explain or put forward an idea. On its left side is the speech or words part, the same one in 「話す|はなす」, to speak, 「言う|いう」, to say, and 「読む|よむ」, to read. So it's about using words. The second is 「明|めい」, bright or clear. Its shape is famous: 「日|ひ」, the sun, beside 「月|つき」, the moon. Two lights side by side make it bright. You know it from 「明日|あした」, tomorrow, the next bright day. So the whole word means to use words to make something clear. That's explaining. Things being explained take 「を」, and the person you explain to takes 「に」, as in 「先生が文法を説明しました|せんせいがぶんぽうをせつめいしました」. You'll also see it in 「説明書|せつめいしょ」, the instruction manual that comes with a product, with 「書|しょ」, writing, as in 「辞書|じしょ」. A handy request is 「説明してください|せつめいしてください」, please explain. Recap: words plus bright, making things clear with words, to explain.",
    ja: "{先生|せんせい}が{文法|ぶんぽう}を[説明しました|せつめいしました|せつめいする]。",
    en: "The teacher explained the grammar." },
  "むかえにくる|迎えに来る": {
    explain: "This is the partner of 「迎えに行く|むかえにいく」, to go to pick up. The first part, 「迎え|むかえ」, comes from 「迎える|むかえる」, to meet or welcome someone who's arriving. Its kanji uses the native reading and has the moving-along-a-road part on the left and bottom. Then comes the purpose pattern you know: 「に」 plus a motion verb, meaning coming in order to do something, like 「あそびに来る|あそびにくる」, to come to hang out. Here the motion verb is 「来る|くる」, to come. So someone comes to meet you and takes you back with them. The whole difference between the two phrases is the direction, the same as with 「連れていく|つれていく」 and 「連れてくる|つれてくる」. If you go out to get someone, use 「行く|いく」. If someone comes to where you are, use 「来る|くる」. So 「父が駅に迎えに来ました|ちちがえきにむかえにきました」 means my father came to the station to pick me up. A very natural request is 「迎えに来てください|むかえにきてください」, please come pick me up. In Japan, parents picking kids up from cram school late at night is a common sight. Recap: welcome plus come for that purpose, someone comes to get you.",
    ja: "{父|ちち}が{駅|えき}に[迎えに来ました|むかえにきました|むかえにくる]。",
    en: "My father came to the station to pick me up." },
  "きょうじゅうに|今日中に": {
    explain: "Three pieces. 「今日|きょう」, today, has a special reading that doesn't follow the usual sounds of its kanji, so learn it as a whole. Then 「中|じゅう」. This kanji means middle or inside, and its shape shows a line going right through the middle of a box. Here it takes the sound 「じゅう」, which after a time word means all through, the whole span. You know it from 「一日中|いちにちじゅう」, all day long. Finally 「に」 marks a point in time. So within the whole of today, before it ends. By the end of today. It's a deadline phrase. You'll hear it at work and school, as in 「今日中に出してください|きょうじゅうにだしてください」, please hand it in by the end of today. You can swap in other time words too. 「今週中に|こんしゅうちゅうに」, usually said that way, means by the end of this week. Notice that one says 「ちゅう」, which brings up the tricky point. The same kanji is sometimes 「じゅう」 and sometimes 「ちゅう」, and the reading just has to be learned per word. Compare 「授業中に|じゅぎょうちゅうに」, during class. Recap: today plus all through, within today, a deadline.",
    ja: "[今日中に|きょうじゅうに]{宿題|しゅくだい}を{出します|だします}。",
    en: "I'll hand in my homework by the end of today." },
  "じゅぎょうちゅうに|授業中に": {
    explain: "Three pieces. 「授業|じゅぎょう」, class, uses Chinese-origin readings. 「授|じゅ」 means to give or confer, and it has the hand part on its left. 「業|ぎょう」 means work, studies, or a course of learning, and you know it from 「卒業する|そつぎょうする」, to graduate, to finish your studies. So a class is giving out learning. Next is 「中|ちゅう」. This kanji means middle or inside, and its shape is a line going right through the middle of a box. After an activity, with the reading 「ちゅう」, it means in the middle of doing it, during. And 「に」 marks the time. So in the middle of class. You can use the same 「ちゅう」 after many activity words, like a meeting or a phone call. That's why a sign on a door might say that someone is in a meeting, or a phone call is in progress. Be careful with the reading. In 「今日中に|きょうじゅうに」 and 「一日中|いちにちじゅう」, the same kanji says 「じゅう」 and means all through a time period. Here it says 「ちゅう」, during an activity. A typical classroom rule is 「授業中に寝ないでください|じゅぎょうちゅうにねないでください」. Recap: class plus in the middle of, during class.",
    ja: "[授業中に|じゅぎょうちゅうに]{寝ないで|ねないで}ください。",
    en: "Please don't sleep during class." },
  "このあいだ|この間": {
    explain: "Two pieces with native readings. 「この」 is this, the same as in 「この本|このほん」, this book. 「間|あいだ」 is the space between two things, a gap, or a span of time. Look at the shape of the kanji. It's 「門|もん」, a gate, with 「日|ひ」, the sun, inside. The traditional picture is sunlight shining through a gap in the gate. You know this kanji with its Chinese-origin reading 「かん」 in 「時間|じかん」, time, and 「一時間|いちじかん」, one hour, and 「〜週間|〜しゅうかん」, for some weeks. So 「この間|このあいだ」 is this recent stretch of time. It points back to something that happened recently, a few days or a few weeks ago. In English, the other day, or recently. A common mistake is to use it for the future. It only points back. It's casual and very common in conversation, especially to bring up something you both remember, as in 「この間はありがとうございました|このあいだはありがとうございました」, thanks for the other day. In Japan, people say that a lot, thanking someone again for a meal or a favor the next time they meet. Recap: this plus gap in time, the other day, always in the past.",
    ja: "[この間|このあいだ]、{友だち|ともだち}に{会いました|あいました}。",
    en: "I met a friend the other day." },
  "これから|": {
    explain: "Two pieces you know well. 「これ」 means this, the thing close to me, and here it points to this moment, right now. 「から」 means from, as in from a starting point. So from this point. From now on. It's part of a family you know. 「それから」, and then, is literally from that, moving on from what was just said. In fact, 「これから」 has two common uses. One is from now on, for changes going forward, like resolutions. 「これから毎日勉強します|これからまいにちべんきょうします」, from now on I'll study every day. The other is right after this, about to, as in 「これから出かけます|これからでかけます」, I'm about to go out. You'll hear it all the time on the phone or in messages, telling someone what you're doing next. It also shows up in a classic greeting when you start working with someone new, 「これからよろしくおねがいします」, which is like saying I look forward to working with you from now on. A way to remember it: this, then from, starting at this moment. Recap: 「これ」 plus 「から」, from this point forward.",
    ja: "[これから]{毎日|まいにち}べんきょうします。",
    en: "From now on I'll study every day." },
  "このぐらい|": {
    explain: "Two pieces. 「この」 means this, near me. 「ぐらい」 means about or approximately, and you know it from 「〜ぐらい」 after amounts, as in 「一時間ぐらい|いちじかんぐらい」, about an hour. It can also be said as 「くらい」, without the extra sound mark, and both are fine. So the phrase means about this much, this amount, this size. It's really a phrase for gestures. You say it while holding your hands apart to show a size, or while pointing to an amount. It's part of the 「こそあど」 family you know, the this, that, that over there, which set. 「このぐらい」 is about this much, near me. 「そのぐらい」 is about that much, near you. 「あのぐらい」 is about that much, over there. And 「どのぐらい」 is the question, how much or how long, which you already know. So a typical exchange is 「どのぐらいですか」, about how big is it, and the answer, 「このぐらいです」, with your hands showing it. A way to remember it: point to your own hands and say this much. Recap: this plus about, said with a gesture, part of the question family with 「どのぐらい」.",
    ja: "[このぐらい]の{大きさ|おおきさ}です。",
    en: "It's about this big." },
  "じぶんで|自分で": {
    explain: "Two kanji, both with Chinese-origin readings, plus 「で」. The first, 「自|じ」, means self. It started as a picture of a nose, and that connects to a lovely cultural habit. When Japanese people mean me, they often point to their own nose, not their chest. You know this kanji from 「自転車|じてんしゃ」, bicycle, the thing that turns its wheels by itself. The second, 「分|ぶん」, means a part or a share, and you know it from 「気分|きぶん」, mood, and 「多分|たぶん」, probably. So 「自分|じぶん」 is one's own part, oneself. Then 「で」 marks the means, how you do something, as in 「バスで行く|バスでいく」, to go by bus. So by oneself. Doing it on your own, without help. Compare a similar word, 「一人で|ひとりで」, alone. 「一人で|ひとりで」 is about being alone, with no one around. 「自分で|じぶんで」 is about doing it yourself, with no one helping. You could cook dinner 「自分で|じぶんで」 even with your family in the room. Recap: self plus part, oneself, plus 「で」, doing it by yourself without help.",
    ja: "[自分で|じぶんで]{料理|りょうり}をします。",
    en: "I cook by myself." },
  "ほかの|他の": {
    explain: "The kanji 「他|ほか」 uses its native reading here. On its left is the person part, the same one you see in many kanji for people, and the whole kanji means other, as in other people, others. With its Chinese-origin reading 「た」 it appears in words like 「他人|たにん」, a stranger, literally an other person. The 「の」 links it to a noun, just like 「私の本|わたしのほん」, my book. So 「他の人|ほかのひと」, other people, 「他の店|ほかのみせ」, another shop. A common mistake is to drop the 「の」. You always need it before the noun. The word 「ほか」 also works without 「の」 in other patterns. 「ほかに」 means besides, else, as in a server asking if you'd like anything else, 「ほかに何かありますか|ほかになにかありますか」. You may also see 「ほか」 written with the kanji for outside, 「外|ほか」, the same kanji as in 「外国|がいこく」, so don't be thrown by that. A way to remember it: a person standing to one side, someone other than you. Recap: other, with the person part, always add 「の」 before a noun.",
    ja: "[他の|ほかの]{人|ひと}はどこですか。",
    en: "Where are the other people?" },
  "ええと|": {
    explain: "This is a filler word, the sound you make while you're thinking of what to say, like um, uh, or let me see. It has no kanji. You'll also see it written 「えーと」 or shortened to 「えと」, and stretched out in speech, 「ええーと」, as long as you need. It's casual but perfectly fine in polite conversation, for example when someone asks you a question and you need a second. A common mix-up: don't confuse it with 「ええ」 by itself, which means yes, a softer form of 「はい」. The 「と」 at the end is what makes it a thinking sound. Another filler you know, 「あのう」, is a little different. 「あのう」 is mostly used to get someone's attention politely, or before saying something a bit awkward. 「ええと」 is for searching your memory, like looking for a word or a number. Using Japanese fillers instead of English ums makes you sound much more natural, so it's worth practicing. A way to remember it: say um with a little hesitating eh at the start, and stretch it out while you look up at the ceiling. Recap: a thinking sound, not yes, stretch it as long as you need.",
    ja: "[ええと]、ちょっとわかりません。",
    en: "Let me see, I'm not quite sure." },
  "じつは|実は": {
    explain: "The kanji 「実|じつ」 uses its Chinese-origin reading. Its core meaning is fruit, and from there, substance, the real content of something, truth. With its native reading, 「み」, it means a fruit or nut on a tree. So think of the fruit as the real thing inside, the true part. Then 「は」, the topic particle, the same as in 「私は|わたしは」. So literally, as for the truth. That's what it means: actually, to tell the truth, in fact. It's the phrase you use right before you reveal something. A confession, a surprise, a request, or bad news. It softens what comes next and signals that you're about to say something real. It often pairs with the 「んです」 pattern, which explains a situation, as in 「実は、あした行けないんです|じつは、あしたいけないんです」, actually, I can't go tomorrow. Japanese speakers often say it before asking a favor, to set up the situation politely. If you hear it, get ready, something important is coming. Recap: fruit, the real content, truth, plus 「は」. As for the truth, actually.",
    ja: "[実は|じつは]、あした{行けません|いけません}。",
    en: "Actually, I can't go tomorrow." },
  "〜いがい|〜以外": {
    explain: "Two kanji, both with Chinese-origin readings. 「以|い」 marks a point of reference, a starting line that you measure from. It shows up in useful words you'll meet later, like 「以上|いじょう」, that point and above, and 「以下|いか」, that point and below. The second kanji, 「外|がい」, means outside. You know it from 「外国|がいこく」, foreign country, the country outside, and 「外国人|がいこくじん」, foreigner. With its native reading, it's 「そと」, outside. So 「以外|いがい」 is everything outside of that point. Put it right after a noun to mean other than that, except that. 「肉以外|にくいがい」, anything other than meat. 「日曜日以外|にちようびいがい」, any day except Sunday. It's often followed by a word for all or anything, as in 「肉以外は何でも食べます|にくいがいはなんでもたべます」, I eat anything other than meat. Or by a negative, meaning only that, as in no one other than me knows. Watch out for a word with the same sound, 「意外|いがい」, which means unexpected. Recap: reference point plus outside, everything outside of that, other than.",
    ja: "にく[以外|いがい]はなんでも{食べます|たべます}。",
    en: "I eat anything other than meat." },
  "ごめん|": {
    explain: "This is a casual apology, used with friends and family. It's written in kana nowadays, but it comes from a kanji phrase meaning your honorable pardon. The 「ご」 is the polite prefix, like in 「ご飯|ごはん」, and 「めん」 comes from a kanji meaning pardon or exemption. So it was originally a way of asking forgiveness or permission. That's why you'll also hear the old visiting phrase 「ごめんください」, said at someone's door when you arrive, like asking pardon for intruding. Now, the apology family by level. 「ごめん」 is the casual one, for people close to you. 「ごめんなさい」 is a bit softer and fuller, still for friends and family, and also what kids say. 「すみません」 is the polite, all-purpose one for strangers, teachers, and coworkers. A common mistake is using 「ごめん」 with a teacher or a boss. It sounds too casual. Young people often stretch it, like 「ごめんね」, which feels gentler, or 「ごめんごめん」, a quick, light sorry for something small. Recap: from asking pardon, the casual sorry for close friends and family.",
    ja: "[ごめん]、ちょっとおくれる。",
    en: "Sorry, I'll be a little late." },
  "しつれいします|失礼します": {
    explain: "Two kanji, both with Chinese-origin readings, plus 「します」. 「失|しつ」 means to lose or to fail at something. 「礼|れい」 means manners, courtesy, a bow. You'll meet it in 「お礼|おれい」, thanks, a gesture of gratitude. So 「失礼|しつれい」 is literally losing your manners, being rude. Add 「します」 and you're saying I'm about to do something rude. That sounds strange in English, but it's a humble way of excusing yourself. You're admitting that walking in or leaving bothers the other person a little. You say it when knocking and entering a teacher's office, when hanging up a phone call, or when leaving a room. When leaving, many people use the past form, 「失礼しました|しつれいしました」, I was rude, as in sorry for the interruption. In an office, people leaving work before their coworkers say 「お先に失礼します|おさきにしつれいします」, excuse me for leaving ahead of you. And 「失礼ですが|しつれいですが」, it may be rude but, comes before a personal question, like asking someone's name. Recap: lose plus manners, a humble excuse me for entering, leaving or interrupting.",
    ja: "{先生|せんせい}、[失礼します|しつれいします]。",
    en: "Excuse me, professor." }
});
